INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b5c53bf-05b8-4c71-aa60-960d0db64d10', '送友人入蜀', '送友人入蜀', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["遠路接天末，怪君與我違。","客程千嶂裏，鳥道片雲飛。","樹色連青漢，泉聲出翠微。","錦城花月下，才子定忘歸。","（見《全蜀藝文志》卷二十）。"]', '["远路接天末，怪君與我違。","客程千嶂裏，鸟道片云飞。","樹色連青漢，泉声出翠微。","錦城花月下，才子定忘归。","（见《全蜀藝文志》卷二十）。"]', '诗', 'shi', '', NULL, '送友人入蜀 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bd6e892-cfff-45c6-bd9b-88e9d1543eb9', '送歸客', '送归客', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["京口三秋衰葉落，潯陽千里暮潮生。","（《千載佳句》卷下《別離部·行旅》）。"]', '["京口三秋衰葉落，潯陽千里暮潮生。","（《千載佳句》卷下《別離部·行旅》）。"]', '诗', 'shi', '', NULL, '送歸客 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceb6de3c-e926-4870-9338-010e17057af6', '贈錢起（題擬）', '贈錢起（題擬）', '293bbb3b-9117-45b0-8b1f-7eade37d735e', '唐', '["黃卷讀來今已老，白頭受屈不曾言。","（見《錢考功集》卷八《酬考功楊員外見贈佳句》自注引）（按：《郎官石柱題名》考功員外郎一欄殘泐過甚，存名僅五十二人，無楊姓者。","勞《考》卷十復自羣書採摭補遺，有楊於陵貞元八年後曾任此職，其時已較後。","頗此人即與錢起有過往之楊綰，然兩《唐書》本傳皆不云其任考外事。","姑存疑以俟考詳。","）。"]', '["黄卷读来今已老，白头受屈不曾言。","（见《錢考功集》卷八《酬考功楊員外见贈佳句》自注引）（按：《郎官石柱題名》考功員外郎一欄殘泐過甚，存名僅五十二人，無楊姓者。","勞《考》卷十复自羣书採摭補遺，有楊於陵貞元八年後曾任此職，其时已較後。","頗此人即與錢起有過往之楊綰，然兩《唐书》本傳皆不云其任考外事。","姑存疑以俟考詳。","）。"]', '诗', 'shi', '', NULL, '贈錢起（題擬） 楊員外 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38d01423-e62a-4473-8f9b-4f10f6c0aa1b', '遊荆溪', '游荆溪', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["銅官之山溪水南，周處廟前多夕嵐。","看捲雲帆歌白苧，勸嘗春酒破黃柑。","長林獨往誰能覓，幽事相關性所耽。","若欲避喧那畏虎，尚從地主結松龕。","（見嘉慶二年刊寧楷等纂《宜興縣志》卷十）。"]', '["銅官之山溪水南，周处廟前多夕嵐。","看捲云帆歌白苧，勸嘗春酒破黄柑。","长林独往誰能覓，幽事相关性所耽。","若欲避喧那畏虎，尚從地主結松龕。","（见嘉慶二年刊寧楷等纂《宜兴縣志》卷十）。"]', '诗', 'shi', '', NULL, '遊荆溪 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a5ef821-6aab-4773-9c33-0bf715b24bd1', '劍詩', '劍诗', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["舞揮秦日月，爲整漢山河。","（見《吟窗雜錄》卷十四正字王玄《詩中旨格》）。"]', '["舞揮秦日月，爲整漢山河。","（见《吟窗杂錄》卷十四正字王玄《诗中旨格》）。"]', '诗', 'shi', '', NULL, '劍詩 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcbdf61c-2e67-4241-9fec-e88280cc4207', '句', '句', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["觀身岸額離根草，論命江頭不繫舟。","（見《日本古典文學大系》七三冊藤原公任《和漢朗詠集》卷下《無常》）（〖1〗川口久雄校注《和漢朗詠集》云：「底本注作者爲『羅維』，柿村氏以爲『羅維當係嚴維之誤』。","」其說是。","《全唐詩》卷七七○收羅維《水精環》，即爲嚴維之誤。","）。"]', '["观身岸額離根草，論命江头不繫舟。","（见《日本古典文学大系》七三冊藤原公任《和漢朗詠集》卷下《無常》）（〖1〗川口久雄校注《和漢朗詠集》云：「底本注作者爲『羅維』，柿村氏以爲『羅維當係嚴維之誤』。","」其说是。","《全唐诗》卷七七○收羅維《水精环》，即爲嚴維之誤。","）。"]', '诗', 'shi', '', NULL, '句 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce7c2bed-34fe-49d3-a68f-bc3361099686', '贈王叔雅兄弟（題擬）', '贈王叔雅兄弟（題擬）', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["萬里天連水，孤舟弟與兄。","（見《古刻叢抄》收唐許志雍撰《唐故江南西道觀察判官監察御史裏行太原王公墓誌銘》引）。"]', '["万里天連水，孤舟弟與兄。","（见《古刻叢抄》收唐許志雍撰《唐故江南西道观察判官監察御史裏行太原王公墓誌銘》引）。"]', '诗', 'shi', '', NULL, '贈王叔雅兄弟（題擬） 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a10962a4-cc5c-4994-8c13-7e0f61b43abe', '頌鮮于叔明（題擬）', '頌鲜于叔明（題擬）', '3b5cea84-6192-4390-91c2-0204b5c89f4b', '唐', '["三院四人簪白筆，一門三鎮擁朱幡。","（見《輿地紀勝》卷一五四《潼川軍》引《潼川舊記》引《鮮于叔明神道碑》載）（按：《舊唐書》卷一二二《李叔明傳》謂「大曆末，有閬州嚴氏子上疏」云云，因知此二句詩作者，爲大曆末人。","）。"]', '["三院四人簪白笔，一门三鎮擁朱幡。","（见《輿地紀勝》卷一五四《潼川軍》引《潼川旧記》引《鲜于叔明神道碑》載）（按：《旧唐书》卷一二二《李叔明傳》謂「大曆末，有閬州嚴氏子上疏」云云，因知此二句诗作者，爲大曆末人。","）。"]', '诗', 'shi', '', NULL, '頌鮮于叔明（題擬） 嚴氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04b5990c-8295-49ec-94fd-c03e691d2d44', '珮賦附歌', '珮賦附歌', '8e8f478c-9a82-4ddd-904d-c4094afd2d0a', '唐', '["佩玉蘂兮德音發，中規矩兮聲不歇。","馳畋獵兮思敬慎，壽考不亡兮長歲月。","端法服兮臨魏闕，羣后覲兮萬方謁。","（見《文苑英華》卷一一一）。"]', '["佩玉蘂兮德音發，中規矩兮声不歇。","驰畋獵兮思敬慎，壽考不亡兮长歲月。","端法服兮臨魏闕，羣后覲兮万方謁。","（见《文苑英华》卷一一一）。"]', '诗', 'shi', '', NULL, '珮賦附歌 胡運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d3c39ee-61c7-423e-9e11-f3658fcbc74e', '', '', '6a974042-560b-40d5-8e80-a90f41ee3a62', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 崔生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('253393f9-badf-4fb0-9345-b13b5ca48a2c', '思紅綃妓詩（題擬）', '思紅綃妓诗（題擬）', '6a974042-560b-40d5-8e80-a90f41ee3a62', '唐', '["誤到蓬山頂上遊，明璫玉女動星眸。","朱扉半掩深宮月，應照璚芝雪豔愁。","（見《太平廣記》卷一九四引《傳奇》）。"]', '["誤到蓬山頂上游，明璫玉女动星眸。","朱扉半掩深宮月，應照璚芝雪豔愁。","（见《太平廣記》卷一九四引《傳奇》）。"]', '诗', 'shi', '', NULL, '思紅綃妓詩（題擬） 崔生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb06f985-3a45-400d-8c7d-1bddd1598345', '同李使君渭遊等慈寺（題擬）', '同李使君渭游等慈寺（題擬）', '084d29c5-d744-429f-93a0-f7454b9dc876', '唐', '["淮陽清靜理，永嘉山水心。","（見《輿地紀勝》卷一五七《資州》）（〖1〗《輿地紀勝》云：「李渭爲本州刺史，有詩刻留等慈寺。","時與前進士崔公輔同遊，崔有詩略曰：『淮陽清靜理，永嘉山水心。","』」二句爲公輔頌渭之作。","《全唐詩續補遺》卷十九據《蜀中名勝記》收作李渭詩，誤。","又《杜少陵集》卷十五有《贈崔十三評事公輔》）。"]', '["淮陽清静理，永嘉山水心。","（见《輿地紀勝》卷一五七《資州》）（〖1〗《輿地紀勝》云：「李渭爲本州刺史，有诗刻留等慈寺。","时與前進士崔公輔同游，崔有诗略曰：『淮陽清静理，永嘉山水心。","』」二句爲公輔頌渭之作。","《全唐诗續補遺》卷十九據《蜀中名勝記》收作李渭诗，誤。","又《杜少陵集》卷十五有《贈崔十三評事公輔》）。"]', '诗', 'shi', '', NULL, '同李使君渭遊等慈寺（題擬） 崔公輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7744bc5-b9a7-4211-ba29-0054f8e2905c', '', '', '8b2ea6c1-3953-4879-8aa7-75a36edbd429', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 路應 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('276d593e-07af-4711-b847-5fa0b6aa0c69', '游南雁蕩', '游南雁蕩', '8b2ea6c1-3953-4879-8aa7-75a36edbd429', '唐', '["雁蕩峯高豈易梯，筇鞋極處與天齊。","蟾宮隱隱步將到，日駕亭亭手可提。","織女支機堪索石，仙翁花雨不霑泥。","詩懷到此清如許，欲向銀河蘸筆題。","（見周喟《南雁蕩山志》卷七《詩外編》引陳玭《嘉靖南雁蕩山志》）（按：路應詩及小傳皆承張靖同志錄示。","）。"]', '["雁蕩峯高豈易梯，筇鞋極处與天齊。","蟾宮隐隐步將到，日駕亭亭手可提。","织女支機堪索石，仙翁花雨不霑泥。","诗懷到此清如許，欲向銀河蘸笔題。","（见周喟《南雁蕩山志》卷七《诗外編》引陳玭《嘉靖南雁蕩山志》）（按：路應诗及小傳皆承張靖同志錄示。","）。"]', '诗', 'shi', '', NULL, '游南雁蕩 路應 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76274435-8ce2-4204-af1a-1b2fbb28c51f', '贈饒州韋之晉別駕', '贈饒州韋之晉別駕', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["天道不可問，問天天杳冥。","如何正月霜，百卉皆凋零。","爝火亂白日，夜光雜飛螢。","賈生賢大夫，所以離漢庭。","河色本異洛，渭流頗殊涇。","清濁共朝宗，滔滔曾莫停。","巨川用舟楫，傅說匡武丁。","大船膠潢洿，不使濟滄溟。","中夜擊唾壺，仰頭望天庚。","三台位尚闕，羣象徒熒熒。","鸞翮時暫鎩，龍門晝常扃。","心傾下士盡，眼顧貧交青。","幽室養虛白，香茶陶性靈。","應將混榮辱，詎肯甘羶腥。","至道是吾本，浮雲勞我形。","手中菩提子，身外《蓮花經》。","興來步出門，長嘯臨江亭。","毫端灑垂露，賦裏搖文星。","大音比呌鐘，大智同挈缾。","巴歌利節曲，布鼓隨雷霆。","陋巷一簟食，在原雙鶺[鴒]（領）。","每懷受施恩，長記座右銘。","食惠飽復飯，飲仁醉還醒。","綿綿寄生葉，泛泛無根萍。","萍豈不隨流，愛君水清泠。","葉豈不戀本。","愛君樹芳馨。","彷徨竊三省，感激終百齡。","開閤眷已重，掃門心匪寧。","鉛刀冀效割，鈍刃思發鉶。","危絃託在茲，實願知音聽。","（影印本《詩淵》第一冊第四七九至四八○頁）。"]', '["天道不可问，问天天杳冥。","如何正月霜，百卉皆凋零。","爝火亂白日，夜光杂飞螢。","賈生賢大夫，所以離漢庭。","河色本異洛，渭流頗殊涇。","清濁共朝宗，滔滔曾莫停。","巨川用舟楫，傅说匡武丁。","大船膠潢洿，不使濟滄溟。","中夜擊唾壺，仰头望天庚。","三台位尚闕，羣象徒熒熒。","鸾翮时暫鎩，龙门晝常扃。","心傾下士尽，眼顧貧交青。","幽室養虛白，香茶陶性靈。","應將混榮辱，詎肯甘羶腥。","至道是吾本，浮云勞我形。","手中菩提子，身外《蓮花經》。","兴来步出门，长嘯臨江亭。","毫端灑垂露，賦裏搖文星。","大音比呌鐘，大智同挈缾。","巴歌利節曲，布鼓隨雷霆。","陋巷一簟食，在原雙鶺[鴒]（領）。","每懷受施恩，长記座右銘。","食惠飽复飯，饮仁醉還醒。","綿綿寄生葉，泛泛無根萍。","萍豈不隨流，愛君水清泠。","葉豈不戀本。","愛君樹芳馨。","彷徨竊三省，感激終百齡。","开閤眷已重，掃门心匪寧。","鉛刀冀效割，鈍刃思發鉶。","危絃託在茲，實願知音听。","（影印本《诗淵》第一冊第四七九至四八○頁）。"]', '诗', 'shi', '', NULL, '贈饒州韋之晉別駕 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c462775-1484-40d4-b373-c2959effbefb', '韋使君席詠拗籠籌得茲字', '韋使君席詠拗籠籌得茲字', 'd226be94-a2b8-4495-b15d-9b254def896e', '唐', '["幸得陪樽俎，良籌復在茲。","獻酬君有禮，賞罰我無私。","莫怪斜相向，還將正自持。","一朝權入手，看取令行時。","（同前第二冊第一三二○頁）。"]', '["幸得陪樽俎，良籌复在茲。","獻酬君有禮，賞罰我無私。","莫怪斜相向，還將正自持。","一朝權入手，看取令行时。","（同前第二冊第一三二○頁）。"]', '诗', 'shi', '', NULL, '韋使君席詠拗籠籌得茲字 朱灣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a13c4fc7-78fe-4427-9a63-49b6b30c115a', '題潘岳六城南莊莊是源贊善處', '題潘岳六城南莊莊是源贊善处', '4a46e16e-e82a-4911-972b-39e2a75408ad', '唐', '["原公舊路唯三徑，潘岳新年已二毛。","（《千載佳句》卷上《人事部·閑居》）（按：《全唐詩逸》卷中誤收此詩爲溫達作，今移正。","又《全唐詩逸》卷中據《文鏡秘府論》天卷錄陳閏《罷官後却歸舊居詩》，別作一人，實誤。","陳閏應即陳潤，《文苑英華》卷一五七、卷二九八錄潤詩皆作陳閏，可證。","）。"]', '["原公旧路唯三徑，潘岳新年已二毛。","（《千載佳句》卷上《人事部·闲居》）（按：《全唐诗逸》卷中誤收此诗爲溫達作，今移正。","又《全唐诗逸》卷中據《文镜秘府論》天卷錄陳閏《罷官後却归旧居诗》，別作一人，實誤。","陳閏應即陳潤，《文苑英华》卷一五七、卷二九八錄潤诗皆作陳閏，可證。","）。"]', '诗', 'shi', '', NULL, '題潘岳六城南莊莊是源贊善處 陳潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7d2356a-0ac3-429b-a110-616e94e4d3d7', '呈史君（名巖） 一', '呈史君（名巖） 一', '1fc21b2a-4375-4b6e-92ab-e9d38cd03450', '唐', '["夔郡楊椿作狀元，爲文司權四十年。","推情貸活人無數，累積陰功感上天。"]', '["夔郡楊椿作狀元，爲文司權四十年。","推情貸活人無數，累積陰功感上天。"]', '诗', 'shi', '', NULL, '呈史君（名巖） 一 楊旬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bdd082e-17df-4824-b4c1-313cf3f2d3f3', '呈史君（名巖） 二', '呈史君（名巖） 二', '1fc21b2a-4375-4b6e-92ab-e9d38cd03450', '唐', '["人道公門不可入，我道公門好修行。","若使曲直無顛倒，脚踏蓮花步步生。","（《卐續藏經》本宋佚名《金剛經感應傳》）（按：《金剛經感應傳》云楊旬常持《金剛》、《般若》，感動上天，其子楊椿省試得九十六名，殿試魁天下。","所述科舉之事，顯爲宋制，疑詩亦爲宋人依託。","）。"]', '["人道公门不可入，我道公门好修行。","若使曲直無顛倒，脚踏蓮花步步生。","（《卐續藏經》本宋佚名《金剛經感應傳》）（按：《金剛經感應傳》云楊旬常持《金剛》、《般若》，感动上天，其子楊椿省試得九十六名，殿試魁天下。","所述科舉之事，显爲宋制，疑诗亦爲宋人依託。","）。"]', '诗', 'shi', '', NULL, '呈史君（名巖） 二 楊旬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4adaef0a-5fa6-4781-9f55-0b852991cfd1', '寄姜窈窕詩', '寄姜窈窕诗', 'f2ece9d7-e6cb-40c0-a437-0b1e335b3d80', '唐', '["几上博山靜不焚，匡牀愁臥對斜曛。","犀梳寶鏡人何處？半枕蘭香空綠雲。","（《瑯嬛記》卷上引《本傳》）。"]', '["几上博山静不焚，匡牀愁臥对斜曛。","犀梳寶镜人何处？半枕蘭香空綠云。","（《瑯嬛記》卷上引《本傳》）。"]', '诗', 'shi', '', NULL, '寄姜窈窕詩 張叔良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e1a962-1ac9-4248-8374-4ab7a457f6d5', '詩', '诗', 'f6b3ee51-c9b9-4362-bb3a-3df81bc79276', '唐', '["數行心因鯉魚傳，輕放金鈎繡帳懸。","不是嬌慵貪晝臥，衆中無處看花牋。","（同前卷下引《本傳》）（按：《瑯嬛記》云「張叔良字房卿，大曆中與姜窈窕相悅」。","錄二人詩三首。","今檢《唐詩紀事》卷三一載，張叔良爲廣德二年登進士第，與此云大曆相合。","姜窈窕詩二首，其中《春思》「門前梅柳爛春輝」一首，《全唐詩》卷八○二作張窈窕詩。","張、姜故事，或出後人附會，而詩作則似別有依據，故仍錄存之。","）。"]', '["數行心因鯉鱼傳，轻放金鈎繡帳懸。","不是嬌慵貪晝臥，衆中無处看花牋。","（同前卷下引《本傳》）（按：《瑯嬛記》云「張叔良字房卿，大曆中與姜窈窕相悅」。","錄二人诗三首。","今檢《唐诗紀事》卷三一載，張叔良爲廣德二年登進士第，與此云大曆相合。","姜窈窕诗二首，其中《春思》「门前梅柳爛春輝」一首，《全唐诗》卷八○二作張窈窕诗。","張、姜故事，或出後人附會，而诗作則似別有依據，故仍錄存之。","）。"]', '诗', 'shi', '', NULL, '詩 姜窈窕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06b02b4d-d426-4035-aa63-38d3db703d8d', '', '', '287d01ca-30c0-41e3-8a2e-be022ff6697c', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 張翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00a801a4-e0ed-4d90-bfc1-549d2be20266', '經羅淵弔屈原', '經羅淵弔屈原', '287d01ca-30c0-41e3-8a2e-be022ff6697c', '唐', '["讜言忠諫阻春霄，放逐南荒澤國遙。","五夢楚蘭香易染，一魂香水渺難招。","風聲落日心逾壯，魚腹終天恨未消。","却借微香薦蘋藻，海門何處問漁樵？","（光緒《湘陰縣圖志》卷四。","此詩及張翔事跡，皆從陶敏先生所告）。"]', '["讜言忠諫阻春霄，放逐南荒澤国遙。","五梦楚蘭香易染，一魂香水渺难招。","风声落日心逾壯，鱼腹終天恨未消。","却借微香薦蘋藻，海门何处问漁樵？","（光緒《湘陰縣圖志》卷四。","此诗及張翔事跡，皆從陶敏先生所告）。"]', '诗', 'shi', '', NULL, '經羅淵弔屈原 張翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07856e1d-7b5a-45d6-b4d4-5400925efb14', '浮萍賦附歌', '浮萍賦附歌', 'b3961a41-e769-47be-a3dd-1410bb78ecda', '唐', '["大江之水東西流，別有孤萍朝夕浮。","莫言此中長汎汎，終當結實觸王舟。","（見《文苑英華》卷一四九）。"]', '["大江之水东西流，別有孤萍朝夕浮。","莫言此中长汎汎，終當結實觸王舟。","（见《文苑英华》卷一四九）。"]', '诗', 'shi', '', NULL, '浮萍賦附歌 常袞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13885a73-2f4a-4027-acea-0b225b5034b1', '太原進鐵鏡賦附歌', '太原進鐵镜賦附歌', '0e9710df-0310-4650-b440-23f911189c45', '唐', '["金之精兮衆寶所參，鏡之明兮羣象所含。","清至瑩兮氛埃不雜，明至察兮醜類相慙。","（見《文苑英華》卷一○五）。"]', '["金之精兮衆寶所參，镜之明兮羣象所含。","清至瑩兮氛埃不杂，明至察兮醜類相慙。","（见《文苑英华》卷一○五）。"]', '诗', 'shi', '', NULL, '太原進鐵鏡賦附歌 喬琳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61833461-f5c3-40d8-b7bf-b5ece0f9207c', '大曆年浙東聯唱集 松花壇茶宴聯句（元本不注名姓於聯句下）', '大曆年浙东聯唱集 松花壇茶宴聯句（元本不注名姓於聯句下）', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["幾歲松花下，今來草色平。","衣冠遊佛剎，鼓角望軍城。","亂竹邊溪暗，孤雲向嶺明。","遶壇煙樹老，入殿雨花輕。","山磬入天界，風泉遠近聲。","夜禪三世晤，朝梵一章清。","上砌莓苔遍，緣窗薜荔生。","焚香忘世慮，啜茗長幽情。","聚土何年置，修心此地成。","道緣雲起滅，人世月虧盈。","蟬噪林當曉，虹生澗欲晴。","水流驚歲序，塵網悟簪纓。","池上蓮無著，籬間槿自榮。","因知性不染，更識理常精。","從此應貪味，非惟悔近名。","山棲多自愜，林臥欲無營。","已接追凉處，仍陪問法行。","賞心殊未遍，惆悵暮鐘鳴。"]', '["幾歲松花下，今来草色平。","衣冠游佛剎，鼓角望軍城。","亂竹邊溪暗，孤云向嶺明。","遶壇煙樹老，入殿雨花轻。","山磬入天界，风泉远近声。","夜禪三世晤，朝梵一章清。","上砌莓苔遍，緣窗薜荔生。","焚香忘世慮，啜茗长幽情。","聚土何年置，修心此地成。","道緣云起滅，人世月虧盈。","蟬噪林當晓，虹生澗欲晴。","水流驚歲序，塵網悟簪纓。","池上蓮無著，籬间槿自榮。","因知性不染，更識理常精。","從此應貪味，非惟悔近名。","山棲多自愜，林臥欲無營。","已接追凉处，仍陪问法行。","賞心殊未遍，惆悵暮鐘鳴。"]', '诗', 'shi', '', NULL, '大曆年浙東聯唱集 松花壇茶宴聯句（元本不注名姓於聯句下） 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a51031fd-0f94-4ba2-a7ce-afc85fee7bc2', '大曆年浙東聯唱集 尋法華寺西溪聯句', '大曆年浙东聯唱集 尋法华寺西溪聯句', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["（賈弇陳允初呂渭張叔政〖肅代間人，《全唐文》卷四三六存《對棄農判》一篇〗鮑防周頌〖京兆人，天寶進士，永泰中爲慈溪令，官至大理寺司直。","據《元和姓纂》卷五、《太平廣記》卷三八二、《登科記考》卷二七〗□成用〖不詳〗鄭槩嚴維）常願山水遊，靈奇賞皆遍。","（賈弇）雲端訪潭洞，林下徵茂彥。","（允初）枕石愛閑眠，尋源樂清宴。","（呂渭）探幽漸有趣，憑險恣流眄。","（張叔政）竹影思挂冠，湍聲忘搖扇。","（鮑防）旁登樵子徑，却望金人殿。","（周頌）蘿葉朝架煙，松花暮飛霰。","（□成用）蟬聲掩清管，雲色緣素練。","（鄭槩）從事暮澄清，看以得方便。","（嚴維）攀崖屢迴互，絕迹無健羨。","（允初）野客歸路逢，山僧入林見。","（賈弇）雲林會獨往，世道從交戰。","（鮑防）塔廟年代深，雲霞朝夕變。","（周頌）潛流注隈隩，觸石乍踐濺。","（□用）逸興發山林，道情忘貴賤。","（鄭槩）臨流日復夕，應接空無倦。","（嚴維）。"]', '["（賈弇陳允初呂渭張叔政〖肅代间人，《全唐文》卷四三六存《对棄農判》一篇〗鲍防周頌〖京兆人，天寶進士，永泰中爲慈溪令，官至大理寺司直。","據《元和姓纂》卷五、《太平廣記》卷三八二、《登科記考》卷二七〗□成用〖不詳〗鄭槩嚴維）常願山水游，靈奇賞皆遍。","（賈弇）云端訪潭洞，林下徵茂彥。","（允初）枕石愛闲眠，尋源乐清宴。","（呂渭）探幽漸有趣，憑險恣流眄。","（張叔政）竹影思挂冠，湍声忘搖扇。","（鲍防）旁登樵子徑，却望金人殿。","（周頌）蘿葉朝架煙，松花暮飞霰。","（□成用）蟬声掩清管，云色緣素練。","（鄭槩）從事暮澄清，看以得方便。","（嚴維）攀崖屢迴互，絕迹無健羨。","（允初）野客归路逢，山僧入林见。","（賈弇）云林會独往，世道從交戰。","（鲍防）塔廟年代深，云霞朝夕变。","（周頌）潛流注隈隩，觸石乍踐濺。","（□用）逸兴發山林，道情忘貴賤。","（鄭槩）臨流日复夕，應接空無倦。","（嚴維）。"]', '诗', 'shi', '', NULL, '大曆年浙東聯唱集 尋法華寺西溪聯句 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('068726af-a513-4549-a172-4e0cb3edf698', '大曆年浙東聯唱集 雲門寺小溪茶宴懷院中諸公', '大曆年浙东聯唱集 云门寺小溪茶宴懷院中諸公', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["（嚴維謝良弼〖謝良輔之昆仲，曾任中書舍人。","據顧況《禮部員外郎陶氏集序》〗裴晃〖不詳〗呂渭鄭槩陳允初庾騤〖不詳〗賈肅〖不詳〗）喜從林下會，還憶府中賢。","（嚴維）石門雲路裏，花宮玉笥前。","（謝良弼）日移侵岸竹，溪引出山泉。","（裴晃）猨飲無人處，琴聽淺溜邊。","（呂渭）黃粱誰共飯，香茗憶同煎。","（鄭槩）暫與真僧對，遙知靜者便。","（允初）清言皆亹亹，佳句又翩翩。","（庾騤）竟日懷君子，沉吟對暮天。","（賈肅）。"]', '["（嚴維謝良弼〖謝良輔之昆仲，曾任中书舍人。","據顧況《禮部員外郎陶氏集序》〗裴晃〖不詳〗呂渭鄭槩陳允初庾騤〖不詳〗賈肅〖不詳〗）喜從林下會，還憶府中賢。","（嚴維）石门云路裏，花宮玉笥前。","（謝良弼）日移侵岸竹，溪引出山泉。","（裴晃）猨饮無人处，琴听淺溜邊。","（呂渭）黄粱誰共飯，香茗憶同煎。","（鄭槩）暫與真僧对，遙知静者便。","（允初）清言皆亹亹，佳句又翩翩。","（庾騤）竟日懷君子，沉吟对暮天。","（賈肅）。"]', '诗', 'shi', '', NULL, '大曆年浙東聯唱集 雲門寺小溪茶宴懷院中諸公 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f32b3e1b-9802-41ff-aa6e-f9df924eec2e', '大曆年浙東聯唱集 徵鏡湖故事', '大曆年浙东聯唱集 徵镜湖故事', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["將尋[煉]（練）（從《緯略》卷十改，《剡溪》卷六作「鍊」）藥井，更逐賣樵風。","（允初。","《剡溪》誤作「凡初」）刻石秦（《剡溪》作「泰」）山上，探書禹穴中。","（呂渭）溪邊尋五老，橋上覓雙童。","（嚴維）梅市西陵近，蘭亭上道通。","（謝良弼）雷門驚鶴去，射的驗年豐。","（賈肅）古寺思王令，孤潭憶謝公。","（鄭槩）帆開巖上石，劍出浦間銅。","（庾騤）興裏還尋戴，東山更向東。","（裴晃。","《歷代詩話》本《韻語陽秋》卷五引作「裴勉」，《類編》本作「裴冕」，均誤。","影宋本《韻語陽秋》及《剡錄》均作「裴晃」，不誤。","）。"]', '["將尋[煉]（練）（從《緯略》卷十改，《剡溪》卷六作「鍊」）藥井，更逐賣樵风。","（允初。","《剡溪》誤作「凡初」）刻石秦（《剡溪》作「泰」）山上，探书禹穴中。","（呂渭）溪邊尋五老，橋上覓雙童。","（嚴維）梅市西陵近，蘭亭上道通。","（謝良弼）雷门驚鹤去，射的驗年豐。","（賈肅）古寺思王令，孤潭憶謝公。","（鄭槩）帆开巖上石，劍出浦间銅。","（庾騤）兴裏還尋戴，东山更向东。","（裴晃。","《歷代诗話》本《韻語陽秋》卷五引作「裴勉」，《類編》本作「裴冕」，均誤。","影宋本《韻語陽秋》及《剡錄》均作「裴晃」，不誤。","）。"]', '诗', 'shi', '', NULL, '大曆年浙東聯唱集 徵鏡湖故事 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce800899-3b4a-4256-9245-09c3dc21b5cd', '大曆年浙東聯唱集 自雲門還泛若耶入鏡湖寄院中諸公', '大曆年浙东聯唱集 自云门還泛若耶入镜湖寄院中諸公', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["（謝良弼呂渭鄭槩嚴維裴晃陳允初蕭幼和〖不詳〗）山中秋賞罷，溪上晚歸時。","（謝良弼）出谷秦人望，經湖謝客期。","（呂渭）日斜愁路遠，風橫畏舟遲。","（鄭槩）章句懷文友，途程問檝師。","（嚴維）淺沙遊蚌蛤，危石起鸕鷀。","（裴晃）落葉飛孤戍，橫塘向古祠。","（允初）行行多興逸，無處不相思。","（蕭幼和）。"]', '["（謝良弼呂渭鄭槩嚴維裴晃陳允初蕭幼和〖不詳〗）山中秋賞罷，溪上晚归时。","（謝良弼）出谷秦人望，經湖謝客期。","（呂渭）日斜愁路远，风橫畏舟遲。","（鄭槩）章句懷文友，途程问檝師。","（嚴維）淺沙游蚌蛤，危石起鸕鷀。","（裴晃）落葉飞孤戍，橫塘向古祠。","（允初）行行多兴逸，無处不相思。","（蕭幼和）。"]', '诗', 'shi', '', NULL, '大曆年浙東聯唱集 自雲門還泛若耶入鏡湖寄院中諸公 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dd34820-9738-49f0-9e61-2225e9359fa8', '大曆年浙東聯唱集 秋日宴嚴長史宅', '大曆年浙东聯唱集 秋日宴嚴长史宅', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["（鄭槩裴晃嚴維徐嶷〖東海人。","《宋高僧傳》卷十五〗張著〖字處晦，常山人。","鷟孫，任剡尉，著《翰林盛事》一卷。","據《直齋書錄解題》卷五〗范絳〖不詳〗劉全白沈仲昌闕名）北客來江外，秋山到越中。","（鄭槩）故交多此見，清興復能同。","（裴晃）落木秦山近，衡門鏡水通。","（嚴維）簷前苔繞砌，籬下菊成叢。","（徐嶷）泫泫花承露，泠泠葉動風。","（鄭槩）卷簾看彩翠，對酒命絲桐。","（張著）戊日辭巢燕，商天向浦鴻。","（范絳）騫開通細雨，笑語望秋空。","（劉全白）嬾竹霜天綠，殘花醉裏紅。","（仲昌）客遊驚落葉，更使恨風蓬。","（闕名）。"]', '["（鄭槩裴晃嚴維徐嶷〖东海人。","《宋高僧傳》卷十五〗張著〖字处晦，常山人。","鷟孫，任剡尉，著《翰林盛事》一卷。","據《直斋书錄解題》卷五〗范絳〖不詳〗劉全白沈仲昌闕名）北客来江外，秋山到越中。","（鄭槩）故交多此见，清兴复能同。","（裴晃）落木秦山近，衡门镜水通。","（嚴維）簷前苔繞砌，籬下菊成叢。","（徐嶷）泫泫花承露，泠泠葉动风。","（鄭槩）卷簾看彩翠，对酒命絲桐。","（張著）戊日辞巢燕，商天向浦鴻。","（范絳）騫开通細雨，笑語望秋空。","（劉全白）嬾竹霜天綠，殘花醉裏紅。","（仲昌）客游驚落葉，更使恨风蓬。","（闕名）。"]', '诗', 'shi', '', NULL, '大曆年浙東聯唱集 秋日宴嚴長史宅 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b950f6df-7efe-456c-906e-54fd855c5732', '大曆年浙東聯唱集 嚴氏園林（六言）', '大曆年浙东聯唱集 嚴氏园林（六言）', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["（嚴維鄭槩王綱〖大曆九年以大理司直充崑山縣令，首建縣學。","據《玉峯志》卷上《學校》、卷中《名宦》〗沈仲昌賈全〖長樂人，弇弟。","大曆四年進士。","歷任咸陽縣令、戶部員外郎、常州刺史、浙東觀察使，永貞元年卒。","據《柳河東集》卷十二《先友記》、《陸宣公翰苑集》卷四、《郎官石柱題名考》卷十二、《會稽掇英總集》卷十八、《舊唐書·憲宗紀》〗段格〖不詳〗劉題〖不詳〗）策杖山橫綠野，乘舟水入衡門。","（嚴維）客來多從業縣，僧去還指煙村。","（鄭槩）春韭青青耐剪，香粳日日宜飧。","（王綱）自愧薄霑冠冕，何如樂在丘園。","（沈仲昌）鳥散紛紛花落，人行處處苔痕。","（賈全）水池偏多白鷺，畦隔半是芳蓀。","（段格）柳徑共知歸郭，暮雲誰使當軒。","（劉題）。"]', '["（嚴維鄭槩王綱〖大曆九年以大理司直充崑山縣令，首建縣学。","據《玉峯志》卷上《学校》、卷中《名宦》〗沈仲昌賈全〖长乐人，弇弟。","大曆四年進士。","歷任咸陽縣令、戶部員外郎、常州刺史、浙东观察使，永貞元年卒。","據《柳河东集》卷十二《先友記》、《陸宣公翰苑集》卷四、《郎官石柱題名考》卷十二、《會稽掇英總集》卷十八、《旧唐书·憲宗紀》〗段格〖不詳〗劉題〖不詳〗）策杖山橫綠野，乘舟水入衡门。","（嚴維）客来多從業縣，僧去還指煙村。","（鄭槩）春韭青青耐剪，香粳日日宜飧。","（王綱）自愧薄霑冠冕，何如乐在丘园。","（沈仲昌）鸟散紛紛花落，人行处处苔痕。","（賈全）水池偏多白鷺，畦隔半是芳蓀。","（段格）柳徑共知归郭，暮云誰使當軒。","（劉題）。"]', '诗', 'shi', '', NULL, '大曆年浙東聯唱集 嚴氏園林（六言） 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13519bf5-6b64-4ca1-b714-858a0da4b8c3', '大曆年浙東聯唱集 柏梁體狀雲門山物（幷序）', '大曆年浙东聯唱集 柏梁體狀云门山物（幷序）', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["（秦瑀〖不詳〗鮑防李聿〖玄宗時清漳令，遷尚書郎。","據《全唐文》卷四三五〗李清杜奕袁邕呂渭崔泌〖不詳。","《新唐書·宰相世系表》博陵安平崔氏有刑部員外郎崔泌，爲湜弟，時代稍早，非是。","〗陳允初鄭槩杜倚〖京兆人，淹玄孫，左衛將軍。","據《元和姓纂》卷六〗）。"]', '["（秦瑀〖不詳〗鲍防李聿〖玄宗时清漳令，遷尚书郎。","據《全唐文》卷四三五〗李清杜奕袁邕呂渭崔泌〖不詳。","《新唐书·宰相世系表》博陵安平崔氏有刑部員外郎崔泌，爲湜弟，时代稍早，非是。","〗陳允初鄭槩杜倚〖京兆人，淹玄孫，左衛將軍。","據《元和姓纂》卷六〗）。"]', '诗', 'shi', '', NULL, '大曆年浙東聯唱集 柏梁體狀雲門山物（幷序） 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ccbcd88-4b92-4ceb-9f76-76566f37da35', '大曆年浙東聯唱集', '大曆年浙东聯唱集', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["幡竿映水出蒲檣。","（秦瑀）榴花向陽臨鏡妝。","（鮑防）子規一聲猿斷腸。","（李聿）殘雲入戶起爐香。","（李清）晴虹夭矯架危梁。","（杜奕）輕蘿縹緲挂霓裳。","（袁邕）月臨影殿玉毫光。","（呂渭）粉帶新篁白簡霜。","（崔泌）玲瓏珠綴魚網張。","（陳允初）高枝反舌巧如簧。","（鄭槩）風搖寶鐸佩鏘鏘。","（秦瑀）古松擁腫懸如囊。","（杜倚）雨垂珠箔映迴廊。","（李聿）薔薇綠刺半緘長。","（鮑防）五粒松英大麥芒。","（李清）古藤蚴蟉毒龍驤。","（杜奕）深林怪石猛虎藏。","（袁邕）古碑勒字棋局方。","（呂渭）山僧行道鴻鴈行（崔泌）亭亭孤筍綠沉鎗。","（鄭槩）蜂窼倒掛枯蓮房。","（允初）燃燈幽殿星煌煌。","（杜倚）。"]', '["幡竿映水出蒲檣。","（秦瑀）榴花向陽臨镜妝。","（鲍防）子規一声猿斷腸。","（李聿）殘云入戶起爐香。","（李清）晴虹夭矯架危梁。","（杜奕）轻蘿縹緲挂霓裳。","（袁邕）月臨影殿玉毫光。","（呂渭）粉带新篁白簡霜。","（崔泌）玲瓏珠綴鱼網張。","（陳允初）高枝反舌巧如簧。","（鄭槩）风搖寶鐸佩鏘鏘。","（秦瑀）古松擁腫懸如囊。","（杜倚）雨垂珠箔映迴廊。","（李聿）薔薇綠刺半緘长。","（鲍防）五粒松英大麦芒。","（李清）古藤蚴蟉毒龙驤。","（杜奕）深林怪石猛虎藏。","（袁邕）古碑勒字棋局方。","（呂渭）山僧行道鴻鴈行（崔泌）亭亭孤筍綠沉鎗。","（鄭槩）蜂窼倒掛枯蓮房。","（允初）燃灯幽殿星煌煌。","（杜倚）。"]', '诗', 'shi', '', NULL, '大曆年浙東聯唱集 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0df0b203-3179-4218-aa6f-43621cea65a8', '大曆年浙東聯唱集 花巖寺松潭', '大曆年浙东聯唱集 花巖寺松潭', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["（張叔政嚴維呂渭賈弇周頌鄭槩陳允初□成用）山下花巖會，松間水積深。","（張叔政）晚荷交亂影，疎竹引輕陰。","（嚴維）雲散千巖暮，風生萬木吟。","（呂渭）循涯通妙理，步勝獲幽尋。","（賈弇）望鳥知無迹，看猿欲學心。","（周頌）浮榮指西景，微尚寄東岑。","（鄭槩）待月開山閤，聞鐘出石林。","（允初）波文搖翠壁，蟬響續幽琴。","（張叔政）永日陪霜簡，通宵聽梵音。","（賈弇）機閑任情性，道勝等浮沉。","（□成用）賞異方終古，佳遊幾度今。","（嚴維）自然輕執簡，寧敢忘抽簪。","（允初）過見心皆妄，驅馳力未任。","（呂渭）從來謝公意，山水愛登臨。","（周頌）。"]', '["（張叔政嚴維呂渭賈弇周頌鄭槩陳允初□成用）山下花巖會，松间水積深。","（張叔政）晚荷交亂影，疎竹引轻陰。","（嚴維）云散千巖暮，风生万木吟。","（呂渭）循涯通妙理，步勝獲幽尋。","（賈弇）望鸟知無迹，看猿欲学心。","（周頌）浮榮指西景，微尚寄东岑。","（鄭槩）待月开山閤，闻鐘出石林。","（允初）波文搖翠壁，蟬响續幽琴。","（張叔政）永日陪霜簡，通宵听梵音。","（賈弇）機闲任情性，道勝等浮沉。","（□成用）賞異方終古，佳游幾度今。","（嚴維）自然轻執簡，寧敢忘抽簪。","（允初）過见心皆妄，驱驰力未任。","（呂渭）從来謝公意，山水愛登臨。","（周頌）。"]', '诗', 'shi', '', NULL, '大曆年浙東聯唱集 花巖寺松潭 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d6ce67-ebf3-46ce-b98b-a36c5ee092a2', '大曆年浙東聯唱集 入五雲溪寄諸公聯句（從一字至九字）（按：《全唐詩》卷七八九收本詩，題作《一字至九字詩聯句》，爲後人擬題，原題實缺。另五言詩二句下漏書作者呂渭。今爲補題，詩不重錄。）', '大曆年浙东聯唱集 入五云溪寄諸公聯句（從一字至九字）（按：《全唐诗》卷七八九收本诗，題作《一字至九字诗聯句》，爲後人擬題，原題實缺。另五言诗二句下漏书作者呂渭。今爲補題，诗不重錄。）', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '大曆年浙東聯唱集 入五雲溪寄諸公聯句（從一字至九字）（按：《全唐詩》卷七八九收本詩，題作《一字至九字詩聯句》，爲後人擬題，原題實缺。另五言詩二句下漏書作者呂渭。今爲補題，詩不重錄。） 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('def47c59-47fd-4016-80b3-080d930a8bf9', '大曆年浙東聯唱集 登法華寺最高頂憶院中諸公（從一字至九字）', '大曆年浙东聯唱集 登法华寺最高頂憶院中諸公（從一字至九字）', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["（周頌□成用張叔政賈弇[鮑防]嚴維呂渭鄭槩陳允初）身，心。","（周頌）城郭，山林。","（□成用）望處遠，到時深。","（張叔政）雲崖杳杳，煙樹沉沉。","（賈弇）嘯侶時停策，探幽或撫琴。","[鮑防]得法小枝小葉，懷人如玉如金。","（嚴維）月色前庭清靜觀，梵聲初夜海潮音。","（呂渭）思君子山深不可見，登高頂望遠欲相尋。","（鄭槩）何事歸舟客興櫂不駛，君不見紅蓮綠荇沙禽。","（允初）（〖1〗《通志·藝文志》八著錄：「《大曆年浙東聯唱集》二卷。","」《嘉泰會稽志》卷十四《嚴維傳》云：「大曆中與鄭槩、裴晃、徐嶷、王綱等宴其園宅，聯句賦詩，世傳《浙東唱和》。","」卷十三云：「嚴長史園林，頗名於唐，大曆中有聯句者六人。","」卷十八云：「松花壇，唐大曆中嚴維、呂渭茶宴於此，聯句云〖略〗。","」〖2〗桑世昌《蘭亭考》卷十二云：「鮑防、嚴維、劉全白、宋迪，共三十五人具姓名。","大曆中唱和五十七人。","」今按：嚴維等大曆唱和原集，今已不存。","宋人引錄其詩者有：《歲時雜詠》收一首，《唐詩紀事》收一首，《會稽掇英總集》收詩十二首又偈十一首，《剡錄》收一首，《蘭亭考》收一首，《嘉泰會稽志》收片斷若干。","另宋刻唐人別集附見三首。","綜計各書所收，今存此次唱和詩凡十四首又偈十一首。","與唱者除本書前列三十人外，可考知者尚有劉蕃、樊珣、丘丹、范淹、吳筠、□迥〖疑爲劉迥〗、任逵、謝良輔、宋迪等九人，凡三十九人，已超過《蘭亭考》所舉之三十五人。","這一組詩，《全唐詩》卷七八九收《中元日鮑端公宅遇吳師聯句》、《酒語聯句各分一字》、《一字至九字詩聯句》三首，《全唐詩續補遺》卷五收《經蘭亭故池聯句》〖收嚴維名下〗，餘十首皆錄如上。","另《會稽掇英總集》卷十五收《雲門寺濟公上方偈》十一首，皆爲四言之作，《全唐文》未全收。","姑附錄於次，以存該集完貌，爲研究者提供參讀的便利。","）。"]', '["（周頌□成用張叔政賈弇[鲍防]嚴維呂渭鄭槩陳允初）身，心。","（周頌）城郭，山林。","（□成用）望处远，到时深。","（張叔政）云崖杳杳，煙樹沉沉。","（賈弇）嘯侶时停策，探幽或撫琴。","[鲍防]得法小枝小葉，懷人如玉如金。","（嚴維）月色前庭清静观，梵声初夜海潮音。","（呂渭）思君子山深不可见，登高頂望远欲相尋。","（鄭槩）何事归舟客兴櫂不駛，君不见紅蓮綠荇沙禽。","（允初）（〖1〗《通志·藝文志》八著錄：「《大曆年浙东聯唱集》二卷。","」《嘉泰會稽志》卷十四《嚴維傳》云：「大曆中與鄭槩、裴晃、徐嶷、王綱等宴其园宅，聯句賦诗，世傳《浙东唱和》。","」卷十三云：「嚴长史园林，頗名於唐，大曆中有聯句者六人。","」卷十八云：「松花壇，唐大曆中嚴維、呂渭茶宴於此，聯句云〖略〗。","」〖2〗桑世昌《蘭亭考》卷十二云：「鲍防、嚴維、劉全白、宋迪，共三十五人具姓名。","大曆中唱和五十七人。","」今按：嚴維等大曆唱和原集，今已不存。","宋人引錄其诗者有：《歲时杂詠》收一首，《唐诗紀事》收一首，《會稽掇英總集》收诗十二首又偈十一首，《剡錄》收一首，《蘭亭考》收一首，《嘉泰會稽志》收片斷若干。","另宋刻唐人別集附见三首。","綜計各书所收，今存此次唱和诗凡十四首又偈十一首。","與唱者除本书前列三十人外，可考知者尚有劉蕃、樊珣、丘丹、范淹、吳筠、□迥〖疑爲劉迥〗、任逵、謝良輔、宋迪等九人，凡三十九人，已超過《蘭亭考》所舉之三十五人。","這一組诗，《全唐诗》卷七八九收《中元日鲍端公宅遇吳師聯句》、《酒語聯句各分一字》、《一字至九字诗聯句》三首，《全唐诗續補遺》卷五收《經蘭亭故池聯句》〖收嚴維名下〗，餘十首皆錄如上。","另《會稽掇英總集》卷十五收《云门寺濟公上方偈》十一首，皆爲四言之作，《全唐文》未全收。","姑附錄於次，以存該集完貌，爲研究者提供參读的便利。","）。"]', '诗', 'shi', '', NULL, '大曆年浙東聯唱集 登法華寺最高頂憶院中諸公（從一字至九字） 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c687d524-01bf-45bf-bdb2-c7c92d7bd56e', '鮑防《雲門寺濟公上方偈序》 同人《護戒刀偈》', '鲍防《云门寺濟公上方偈序》 同人《護戒刀偈》', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["剖妄妄絕，決機機壞。","彼堅鋼刀，護身聞戒。"]', '["剖妄妄絕，決機機壞。","彼堅鋼刀，護身闻戒。"]', '诗', 'shi', '', NULL, '鮑防《雲門寺濟公上方偈序》 同人《護戒刀偈》 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f95facfe-a745-40a1-9607-f6f03ce0167f', '鮑防《雲門寺濟公上方偈序》 李聿《茗侶偈》', '鲍防《云门寺濟公上方偈序》 李聿《茗侶偈》', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["采采春渚，芳香天與。","滌慮破煩，靈芝之侶。","。"]', '["采采春渚，芳香天與。","滌慮破煩，靈芝之侶。","。"]', '诗', 'shi', '', NULL, '鮑防《雲門寺濟公上方偈序》 李聿《茗侶偈》 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62472843-7824-4990-93df-7b849ad08ae2', '鮑防《雲門寺濟公上方偈序》 杜奕《芭蕉偈》', '鲍防《云门寺濟公上方偈序》 杜奕《芭蕉偈》', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["幽山淨土，生此芭蕉。","無心起喻，覺路非遙。"]', '["幽山淨土，生此芭蕉。","無心起喻，覺路非遙。"]', '诗', 'shi', '', NULL, '鮑防《雲門寺濟公上方偈序》 杜奕《芭蕉偈》 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d784fe1-b476-4838-9119-baa03ce8be3e', '鮑防《雲門寺濟公上方偈序》 缺名《山啄木偈》', '鲍防《云门寺濟公上方偈序》 缺名《山啄木偈》', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["爾禽啄木，惡蠹傷木。","愈木無病，巢枝自足。"]', '["爾禽啄木，惡蠹傷木。","愈木無病，巢枝自足。"]', '诗', 'shi', '', NULL, '鮑防《雲門寺濟公上方偈序》 缺名《山啄木偈》 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('533c8e18-6d2d-485c-bd11-26434197960e', '鮑防《雲門寺濟公上方偈序》 缺名《澡瓶偈》', '鲍防《云门寺濟公上方偈序》 缺名《澡瓶偈》', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["靈圓取相，塵垢是澡。","定水清淨，救彼熱惱。"]', '["靈圓取相，塵垢是澡。","定水清淨，救彼熱惱。"]', '诗', 'shi', '', NULL, '鮑防《雲門寺濟公上方偈序》 缺名《澡瓶偈》 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c12c00d-9073-457a-8651-88bd54b2caa1', '鮑防《雲門寺濟公上方偈序》 鄭槩《山石榴偈》', '鲍防《云门寺濟公上方偈序》 鄭槩《山石榴偈》', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["何方而有，天上人間。","色空我性，對爾空山。"]', '["何方而有，天上人间。","色空我性，对爾空山。"]', '诗', 'shi', '', NULL, '鮑防《雲門寺濟公上方偈序》 鄭槩《山石榴偈》 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d805e212-a63c-42ac-ad48-8766a1d493dc', '鮑防《雲門寺濟公上方偈序》 杜倚《漉水囊偈》', '鲍防《云门寺濟公上方偈序》 杜倚《漉水囊偈》', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["裂素成器，給我救彼。","密淨圓靈，護生絜水。"]', '["裂素成器，給我救彼。","密淨圓靈，護生絜水。"]', '诗', 'shi', '', NULL, '鮑防《雲門寺濟公上方偈序》 杜倚《漉水囊偈》 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75c03711-35e6-46a1-bbd7-db0953fddd89', '鮑防《雲門寺濟公上方偈序》 袁邕《藤偈》', '鲍防《云门寺濟公上方偈序》 袁邕《藤偈》', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["得彼柔性，契茲佛乘。","豈無衆木，我喻垂藤。"]', '["得彼柔性，契茲佛乘。","豈無衆木，我喻垂藤。"]', '诗', 'shi', '', NULL, '鮑防《雲門寺濟公上方偈序》 袁邕《藤偈》 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4069352c-5530-4171-a51c-2ebdbcba4251', '鮑防《雲門寺濟公上方偈序》 崔泌《薔薇偈》', '鲍防《云门寺濟公上方偈序》 崔泌《薔薇偈》', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["護草木性，植彼薔薇。","眼根不染，見爾色非。"]', '["護草木性，植彼薔薇。","眼根不染，见爾色非。"]', '诗', 'shi', '', NULL, '鮑防《雲門寺濟公上方偈序》 崔泌《薔薇偈》 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b13ef034-7e61-4e0e-b301-ab24d91c51da', '鮑防《雲門寺濟公上方偈序》 缺名《斑竹杖偈》', '鲍防《云门寺濟公上方偈序》 缺名《斑竹杖偈》', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["護性維戒，扶身在杖。","動必由道，心無來往。","。"]', '["護性維戒，扶身在杖。","动必由道，心無来往。","。"]', '诗', 'shi', '', NULL, '鮑防《雲門寺濟公上方偈序》 缺名《斑竹杖偈》 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc3ab7cf-aba1-49e7-a5b1-81bad2924b62', '鮑防《雲門寺濟公上方偈序》 任逵《題天章寺偈》', '鲍防《云门寺濟公上方偈序》 任逵《題天章寺偈》', 'd3588864-d7df-4f90-b599-3393b7b0e2e1', '唐', '["降伏心住，自在心住。","有心且住，無心即住。","。"]', '["降伏心住，自在心住。","有心且住，無心即住。","。"]', '诗', 'shi', '', NULL, '鮑防《雲門寺濟公上方偈序》 任逵《題天章寺偈》 浙東衆詩人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68c5f12a-441b-4263-99d9-16919ad4c358', '早梅', '早梅', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["不知近水花先發，疑是經冬雪未銷。","（《千載佳句》卷下《草木部·梅》）。"]', '["不知近水花先發，疑是經冬雪未銷。","（《千載佳句》卷下《草木部·梅》）。"]', '诗', 'shi', '', NULL, '早梅 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcfc1e8f-29d3-47f5-b9aa-d44d63b7967f', '湖南歸夢', '湖南归梦', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["歸夢不知湖水濶，夜來還到洛陽城。","（同前《別離部·旅情》）。"]', '["归梦不知湖水濶，夜来還到洛陽城。","（同前《別離部·旅情》）。"]', '诗', 'shi', '', NULL, '湖南歸夢 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31908213-dcf6-457b-9700-cb181d2784bb', '送李使君貶郴州', '送李使君貶郴州', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["竹符辭漢守，桂酒奠湘君。","（見《十萬卷樓叢書》本皎然《詩式》卷五）。"]', '["竹符辞漢守，桂酒奠湘君。","（见《十万卷楼叢书》本皎然《诗式》卷五）。"]', '诗', 'shi', '', NULL, '送李使君貶郴州 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58cb3e15-396e-49fc-93fd-837291dfbc20', '上林白鹿賦附歌', '上林白鹿賦附歌', '754fad08-b154-45db-b210-a42efe31fe5a', '唐', '["德由庾兮羣物湊，協嘉祥兮擾靈獸。","感訢合於天符，遂充塞於君囿。","（見《文苑英華》卷八九）。"]', '["德由庾兮羣物湊，協嘉祥兮擾靈獸。","感訢合於天符，遂充塞於君囿。","（见《文苑英华》卷八九）。"]', '诗', 'shi', '', NULL, '上林白鹿賦附歌 蕭昕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d44afb3a-30ba-4e47-832d-309157ffa7e8', '奉同秘書苗丞菘陽山閑居引', '奉同秘书苗丞菘陽山闲居引', '146a4bbe-f3e3-4236-9b3f-473d28577906', '唐', '["有山𨁟兮有水潺湲，王孫獨往兮春草經年。","溪路獨行兮到時何處？","漁父相見兮水上天邊。","犬吠前村兮極浦，迴風入林兮微月映戶。","白石磷磷兮曲（小川氏疑爲「迸」字）水泥（疑）衣，哀猿啾啾兮空山半雨。","谷口蒼茫兮天陰，人間離別兮年月深。","花迷流水不知處，心憶君家難得（小川氏定爲「後」）尋。","（日本藏唐抄本《新撰類林抄》卷四）。"]', '["有山𨁟兮有水潺湲，王孫独往兮春草經年。","溪路独行兮到时何处？","漁父相见兮水上天邊。","犬吠前村兮極浦，迴风入林兮微月映戶。","白石磷磷兮曲（小川氏疑爲「迸」字）水泥（疑）衣，哀猿啾啾兮空山半雨。","谷口蒼茫兮天陰，人间離別兮年月深。","花迷流水不知处，心憶君家难得（小川氏定爲「後」）尋。","（日本藏唐抄本《新撰類林抄》卷四）。"]', '诗', 'shi', '', NULL, '奉同秘書苗丞菘陽山閑居引 吉中孚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('406814ae-e98c-46a3-b7c0-49f21b181397', '地儉', '地儉', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["地儉朝陽滿，天邊宿霧收。","風兼殘雪起，河帶斷冰流。","北闕馳心極，南圖尚旅遊。","登臨思不已，何處得銷愁？","（影印本《詩淵》第三冊第二○六二頁）。"]', '["地儉朝陽满，天邊宿霧收。","风兼殘雪起，河带斷冰流。","北闕驰心極，南圖尚旅游。","登臨思不已，何处得銷愁？","（影印本《诗淵》第三冊第二○六二頁）。"]', '诗', 'shi', '', NULL, '地儉 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('861334cc-50eb-49b3-b6bd-d4529c15def7', '五言普門上人蘭若一首', '五言普门上人蘭若一首', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["支公身欲老，常在沃[洲]（州）多。","惠力堪傳教，禪功久伏魔。","山雲隨坐夏，幽草伴頭陀。","借問迴心後，賢愚去幾何？","（按：《全唐詩》卷二四九收此詩爲皇甫冉作。","然《唐詩卷》約在元和前後書，爲時甚早，故仍存之。","）。"]', '["支公身欲老，常在沃[洲]（州）多。","惠力堪傳教，禪功久伏魔。","山云隨坐夏，幽草伴头陀。","借问迴心後，賢愚去幾何？","（按：《全唐诗》卷二四九收此诗爲皇甫冉作。","然《唐诗卷》約在元和前後书，爲时甚早，故仍存之。","）。"]', '诗', 'shi', '', NULL, '五言普門上人蘭若一首 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('381ff411-5aeb-4ef0-a895-7600d3789ac6', '五言南岳寺普上人院一首', '五言南岳寺普上人院一首', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["雲深石澗寺，樹老遠公房。","終日風□□，□秋景氣涼。","醍醐蒙□味，□□□□□。","□見無生理，空山坐道場。","（以上二首均見日本藏唐抄本《唐詩卷》）。"]', '["云深石澗寺，樹老远公房。","終日风□□，□秋景氣涼。","醍醐蒙□味，□□□□□。","□见無生理，空山坐道場。","（以上二首均见日本藏唐抄本《唐诗卷》）。"]', '诗', 'shi', '', NULL, '五言南岳寺普上人院一首 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c3d52a7-fc89-457b-b685-db9aa6358628', '寄靈一上人初還雲門', '寄靈一上人初還云门', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["寒山白雲裏，法侶自招攜。","竹徑通城下，松門隔水西。","方同沃洲去，不作武陵迷。","髣髴心知（《全唐詩》作「遙看」）處，高峰（《全唐詩》作「秋風」）是會稽。","（見《會稽掇英總集》卷七）（按：《全唐詩》卷三八四收此詩爲張籍作。","今檢《宋高僧傳》卷十五、《文苑英華》卷八六四獨孤及撰《揚州慶雲寺律師一公塔碑》，知靈一卒於寶應元年，年三十六。","張籍生年難確考，但在大曆間殆無可疑。","張籍生於靈一卒後，此詩非其作甚明。","郎士元與靈一同時，詩應爲其作。","）。"]', '["寒山白云裏，法侶自招携。","竹徑通城下，松门隔水西。","方同沃洲去，不作武陵迷。","髣髴心知（《全唐诗》作「遙看」）处，高峰（《全唐诗》作「秋风」）是會稽。","（见《會稽掇英總集》卷七）（按：《全唐诗》卷三八四收此诗爲張籍作。","今檢《宋高僧傳》卷十五、《文苑英华》卷八六四独孤及撰《揚州慶云寺律師一公塔碑》，知靈一卒於寶應元年，年三十六。","張籍生年难確考，但在大曆间殆無可疑。","張籍生於靈一卒後，此诗非其作甚明。","郎士元與靈一同时，诗應爲其作。","）。"]', '诗', 'shi', '', NULL, '寄靈一上人初還雲門 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2788c790-2114-482e-980d-0463c3c4f05e', '駐節太康', '駐節太康', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["霜葉飛紅過夏墟，金風吹鴈集荒渠。","鞭揮清渭分流外，目送烏江遠樹餘。","五子歌聲猶在耳，十旬獵迹已成畬。","天時人因堪惆悵，悶對牙旗展簿書。","（影印文淵閣《四庫全書》本《河南通志》卷七四、民國廿二年刊劉盼遂纂《太康縣志》卷六、《古今圖書集成·職方典》卷三八八《開封府部》）。"]', '["霜葉飞紅過夏墟，金风吹鴈集荒渠。","鞭揮清渭分流外，目送烏江远樹餘。","五子歌声猶在耳，十旬獵迹已成畬。","天时人因堪惆悵，悶对牙旗展簿书。","（影印文淵閣《四庫全书》本《河南通志》卷七四、民国廿二年刊劉盼遂纂《太康縣志》卷六、《古今圖书集成·職方典》卷三八八《开封府部》）。"]', '诗', 'shi', '', NULL, '駐節太康 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7733c16-3e71-418f-b09b-a1d2928bf226', '詩', '诗', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["假守昭平郡，當門桂水清。","海遙稀蚌跡，峽近足灘聲。","峽東江盤天影隨，輕船隻下幾危機。","初晴古木猿三叫，未晚陰崖日半規。","篁竹數家何處是？清清一曲幾首詩。","（《四庫》本《記纂淵海》卷十五）。"]', '["假守昭平郡，當门桂水清。","海遙稀蚌跡，峽近足灘声。","峽东江盤天影隨，轻船隻下幾危機。","初晴古木猿三叫，未晚陰崖日半規。","篁竹數家何处是？清清一曲幾首诗。","（《四庫》本《記纂淵海》卷十五）。"]', '诗', 'shi', '', NULL, '詩 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc90c4d0-66cc-4489-819b-5e4f08689dcc', '送皎[然]（照）上人歸山', '送皎[然]（照）上人归山', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["雲陰鳥道苔方合，雪映龍潭水更清。","（《千載佳句》卷上《地理部·山中》）。"]', '["云陰鸟道苔方合，雪映龙潭水更清。","（《千載佳句》卷上《地理部·山中》）。"]', '诗', 'shi', '', NULL, '送皎[然]（照）上人歸山 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b0bcabe-4322-4cc3-8681-7e11ef05e258', '句 一', '句 一', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["江山幾路分。","（《江湖小集》卷三紹嵩《江浙紀行集句詩》）。"]', '["江山幾路分。","（《江湖小集》卷三紹嵩《江浙紀行集句诗》）。"]', '诗', 'shi', '', NULL, '句 一 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('883deb88-b6c7-4ecf-89eb-9fd2fa458929', '句 二', '句 二', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["上潮吞海日。","（同前）。"]', '["上潮吞海日。","（同前）。"]', '诗', 'shi', '', NULL, '句 二 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('105f3fef-957e-421c-9d1e-f5245b4ca6a8', '句 三', '句 三', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["寂寞舟中誰供問。","（《江湖小集》卷二二李龏《剪綃集》引）。"]', '["寂寞舟中誰供问。","（《江湖小集》卷二二李龏《剪綃集》引）。"]', '诗', 'shi', '', NULL, '句 三 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b2793ea-e3db-48aa-b655-fdc4007c21fd', '句 四', '句 四', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["馬令無茶分。","（見劉克莊《後村大全集》卷一八四《詩話新集》）（〖1〗劉克莊云：「余記唐人雜書載士元嘗對客有『馬令無茶分』之戲。","北平王一日飲客，士元與焉。","坐間，北平醉飽設茗供，連沃數碗，士元老不能禁，即席吐利交下。","滿坐大笑。","今不省出處，當攷。","」）。"]', '["马令無茶分。","（见劉克莊《後村大全集》卷一八四《诗話新集》）（〖1〗劉克莊云：「余記唐人杂书載士元嘗对客有『马令無茶分』之戲。","北平王一日饮客，士元與焉。","坐间，北平醉飽設茗供，連沃數碗，士元老不能禁，即席吐利交下。","满坐大笑。","今不省出处，當攷。","」）。"]', '诗', 'shi', '', NULL, '句 四 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e38801a-1bc6-426b-88f7-9f2f25a29ca9', '白角樽歌', '白角樽歌', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["或謂輕冰盛沆瀣（海氣也。","）（見宋吳聿《觀林詩話》）。"]', '["或謂轻冰盛沆瀣（海氣也。","）（见宋吳聿《观林诗話》）。"]', '诗', 'shi', '', NULL, '白角樽歌 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e33facd3-c545-433a-8fc3-f37a2777b4ba', '建中四年十月感事（題擬）', '建中四年十月感事（題擬）', 'cf7a693d-caa4-4402-916e-df48dbb4b7d3', '唐', '["煙塵忽起犯中原，自古臨危道貴存。","手持禮器空垂淚，心憶明君不敢言。","落日胡笳吟上苑，通宵虜將醉西園。","傳烽萬里無師至，累代何人受漢恩。","（見唐趙元一撰《奉天錄》卷二）（〖1〗《奉天錄》卷二：「八日，泚于宣政殿僭即大位，愚智莫不血怒。","衛者多是軍人，周行不過數十，自稱大秦皇帝，年號應天。","僞赦書云：『幽囚之中，神器自至，豈朕薄德所能經營。","』彭偃之詞。","冊文，太常少卿樊系之撰。","文成，服藥而卒。","故嚴巨川詩曰〖詩略〗。","」〖2〗《奉天錄》卷一：「時有風情女子李季蘭上泚詩，言多悖逆，故闕而不錄。","皇帝再剋京師，召季蘭而責之曰：『汝何不學嚴巨川有詩云：「手持禮器空垂淚，心憶明君不敢言」？","』遂令撲殺之。","」今按：詳此段紀事，似巨川于朱泚亂時亦陷身賊中，至德宗收京，因此詩而得寬宥。","）。"]', '["煙塵忽起犯中原，自古臨危道貴存。","手持禮器空垂泪，心憶明君不敢言。","落日胡笳吟上苑，通宵虜將醉西园。","傳烽万里無師至，累代何人受漢恩。","（见唐趙元一撰《奉天錄》卷二）（〖1〗《奉天錄》卷二：「八日，泚于宣政殿僭即大位，愚智莫不血怒。","衛者多是軍人，周行不過數十，自稱大秦皇帝，年號應天。","僞赦书云：『幽囚之中，神器自至，豈朕薄德所能經營。","』彭偃之词。","冊文，太常少卿樊系之撰。","文成，服藥而卒。","故嚴巨川诗曰〖诗略〗。","」〖2〗《奉天錄》卷一：「时有风情女子李季蘭上泚诗，言多悖逆，故闕而不錄。","皇帝再剋京師，召季蘭而責之曰：『汝何不学嚴巨川有诗云：「手持禮器空垂泪，心憶明君不敢言」？","』遂令撲殺之。","」今按：詳此段紀事，似巨川于朱泚亂时亦陷身賊中，至德宗收京，因此诗而得寬宥。","）。"]', '诗', 'shi', '', NULL, '建中四年十月感事（題擬） 嚴巨川 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f076384-a464-464d-9921-13c7ab5fceb7', '', '', '450532aa-709d-4830-85fb-09f31a090368', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 論惟明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b80768b1-524e-4749-8e19-def89d9a9be8', '朱泚亂定後上皇帝（題擬）', '朱泚亂定後上皇帝（題擬）', '450532aa-709d-4830-85fb-09f31a090368', '唐', '["豺狼暴宮闕，拔塗凌丹墀。","花木久不芳，羣凶亦自疑。","既爲皇帝枯，亦爲皇帝滋。","艸木尚多感，報恩須及時。","（見唐趙元一《奉天錄》卷四）。"]', '["豺狼暴宮闕，拔塗凌丹墀。","花木久不芳，羣凶亦自疑。","既爲皇帝枯，亦爲皇帝滋。","艸木尚多感，報恩須及时。","（见唐趙元一《奉天錄》卷四）。"]', '诗', 'shi', '', NULL, '朱泚亂定後上皇帝（題擬） 論惟明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dae5e7a2-55be-4d08-b97f-04d1f6bcf284', '和蕭郎中遊蘭若', '和蕭郎中游蘭若', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["愛彼雲外人，來取澗底泉。","風吹芭蕉折，鳥啄梧桐穿。","（見《十萬卷樓叢書》本皎然《詩式》卷三。","同書卷四錄前二句。","）（按：《全唐詩》卷三一五錄四句，缺題，又末字「穿」作「落」，故分作二斷句，蓋沿《吟窗雜錄》刪節本《詩式》之誤所致，今重錄改正之。","）。"]', '["愛彼云外人，来取澗底泉。","风吹芭蕉折，鸟啄梧桐穿。","（见《十万卷楼叢书》本皎然《诗式》卷三。","同书卷四錄前二句。","）（按：《全唐诗》卷三一五錄四句，缺題，又末字「穿」作「落」，故分作二斷句，蓋沿《吟窗杂錄》刪節本《诗式》之誤所致，今重錄改正之。","）。"]', '诗', 'shi', '', NULL, '和蕭郎中遊蘭若 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11c90e9e-f28e-47b7-b5f2-a456a0220bda', '釣渚亭', '釣渚亭', 'bdedfcb3-43d1-4e58-bf48-73f389d5f279', '唐', '["花發多遠意，鳧鴈有閒情。","遲暉耿不暮，平江寂無聲。","（見《唐詩紀事》卷二七）。"]', '["花發多远意，鳧鴈有閒情。","遲暉耿不暮，平江寂無声。","（见《唐诗紀事》卷二七）。"]', '诗', 'shi', '', NULL, '釣渚亭 暢當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('430b58ff-909a-4698-89ff-43964378a3c5', '建寧王哀詞二首（末句）', '建寧王哀词二首（末句）', '43d47387-1ee6-4533-8ef9-68284e4e68fb', '唐', '["良弓摧折久，誰識是龍韜。","（見《吟窗雜錄》卷二四《歷代吟譜》）按：《全唐詩》卷一○九收此二句，缺題，今重錄。"]', '["良弓摧折久，誰識是龙韜。","（见《吟窗杂錄》卷二四《歷代吟譜》）按：《全唐诗》卷一○九收此二句，缺題，今重錄。"]', '诗', 'shi', '', NULL, '建寧王哀詞二首（末句） 李泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('524f0997-6462-4e6b-b8ff-18391552f67a', '句 一', '句 一', '43d47387-1ee6-4533-8ef9-68284e4e68fb', '唐', '["夷門一把平安火，定逐恒山候騎來。","（《四庫》本《記纂淵海》卷二一）。"]', '["夷门一把平安火，定逐恒山候騎来。","（《四庫》本《記纂淵海》卷二一）。"]', '诗', 'shi', '', NULL, '句 一 李泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8edeb92-cfa6-44c9-a040-1a0f632b9e39', '句 二', '句 二', '43d47387-1ee6-4533-8ef9-68284e4e68fb', '唐', '["粉容冰艷玉玲瓏。","（《江湖小集》卷二十李龏《梅花衲》）。"]', '["粉容冰艷玉玲瓏。","（《江湖小集》卷二十李龏《梅花衲》）。"]', '诗', 'shi', '', NULL, '句 二 李泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e459cc18-94d9-4365-9db9-a41e31ab51ac', '酬秦徵君徐少府春日見集', '酬秦徵君徐少府春日见集', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["終日愧無政，與君聊散（《剡錄》作「放」）襟。","城根山半腹，亭影水中心。","朗詠竹窗靜，野情花徑深。","那能有餘興，不作剡溪尋。","（見《文苑英華》卷二三○、卷三一六、高似孫《剡錄》卷六、卷十。","）（按：《全唐詩》卷一九○收作韋應物詩，誤。","宋本《韋集》無此詩。","明刻《文苑英華》卷二三○此詩前爲應物詩，此詩失署作者，後人因此致誤。","《文苑英華》卷二三○周必大等校該詩云：「集作《奉酬秦徵君系春日撫州西亭野望兼寄徐少府》。","」叔倫曾任撫州刺史。","卷三一六即題作《撫州西亭》，署「戴叔倫」作。","中華書局影印本新編目錄已糾正明刻本之誤。","）。"]', '["終日愧無政，與君聊散（《剡錄》作「放」）襟。","城根山半腹，亭影水中心。","朗詠竹窗静，野情花徑深。","那能有餘兴，不作剡溪尋。","（见《文苑英华》卷二三○、卷三一六、高似孫《剡錄》卷六、卷十。","）（按：《全唐诗》卷一九○收作韋應物诗，誤。","宋本《韋集》無此诗。","明刻《文苑英华》卷二三○此诗前爲應物诗，此诗失署作者，後人因此致誤。","《文苑英华》卷二三○周必大等校該诗云：「集作《奉酬秦徵君系春日撫州西亭野望兼寄徐少府》。","」叔倫曾任撫州刺史。","卷三一六即題作《撫州西亭》，署「戴叔倫」作。","中华书局影印本新編目錄已糾正明刻本之誤。","）。"]', '诗', 'shi', '', NULL, '酬秦徵君徐少府春日見集 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42811d28-da0e-4532-bd93-89a2b20f944d', '詩', '诗', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["雲開方見日，潮盡爐峰出。","石壁轉棠陰，鄱陽寄茅室。","（《輿地紀勝》卷二三《饒州》）。"]', '["云开方见日，潮尽爐峰出。","石壁轉棠陰，鄱陽寄茅室。","（《輿地紀勝》卷二三《饒州》）。"]', '诗', 'shi', '', NULL, '詩 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9707068d-3ceb-4c32-a81d-a9a1d902b9f2', '新池', '新池', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["鄰僧猶未起，明月早先知。","（見《吟窗雜錄》卷十四正字王玄《詩中旨格》）。"]', '["鄰僧猶未起，明月早先知。","（见《吟窗杂錄》卷十四正字王玄《诗中旨格》）。"]', '诗', 'shi', '', NULL, '新池 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('864799d0-5c04-4c68-a368-a5e11a937b79', '喜嚴侍御蜀還贈嚴秘書', '喜嚴侍御蜀還贈嚴秘书', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["（按：以上三詩，《文苑英華》卷二五五收作戴叔倫詩，卷二五六復收作清江詩。","尚難遽定誰作，姑存目俟考。","）空。"]', '["（按：以上三诗，《文苑英华》卷二五五收作戴叔倫诗，卷二五六复收作清江诗。","尚难遽定誰作，姑存目俟考。","）空。"]', '诗', 'shi', '', NULL, '喜嚴侍御蜀還贈嚴秘書 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e11087c-8de6-4ed7-8e9a-37aff277f7ce', '贈淮西賈兵馬使', '贈淮西賈兵马使', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["（按：《文苑英華》卷三○○收作戴叔倫詩，卷二五七收作清江詩。","尚難遽定誰作，姑存目。","以上四首，《全唐詩》卷八一二均收清江名下。","）空。"]', '["（按：《文苑英华》卷三○○收作戴叔倫诗，卷二五七收作清江诗。","尚难遽定誰作，姑存目。","以上四首，《全唐诗》卷八一二均收清江名下。","）空。"]', '诗', 'shi', '', NULL, '贈淮西賈兵馬使 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b0881ac-8657-4bbf-b121-7d239161bee6', '', '', 'fc385595-d756-4535-9fcd-ed3e9a23f559', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 李博士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('201b6e45-7a32-4f65-ac98-74668851976a', '問韋應物（題擬）', '问韋應物（題擬）', 'fc385595-d756-4535-9fcd-ed3e9a23f559', '唐', '["宋生昔登覽。","（中缺）那能顧蓬蓽。","（見《韋蘇州集》卷五《李博士弟以余罷官居同德精舍共有伊陸名山之期久而未去枉詩見問中云宋生昔登覽末云那能顧蓬蓽直寄鄙懷聊以爲答》）（按：韋應物另有《寄酬李博士永寧主簿叔廳見待》、《答李博士》、《同德寺雨後寄元侍御李博士》、《同德閣期元侍御李博士不至各投贈二首》，均與同人之作，唯其名不詳。","傅璇琮先生《韋應物繫年考證》定應物退居同德寺爲永泰元年棄洛陽丞後。","頗疑此人即與應物過從甚密之李儋，出姑臧大房，給事中昇期之子，官至殿中侍御史，見《新唐書·宰相世系表》。","俟得確證定之。","）。"]', '["宋生昔登覽。","（中缺）那能顧蓬蓽。","（见《韋蘇州集》卷五《李博士弟以余罷官居同德精舍共有伊陸名山之期久而未去枉诗见问中云宋生昔登覽末云那能顧蓬蓽直寄鄙懷聊以爲答》）（按：韋應物另有《寄酬李博士永寧主簿叔廳见待》、《答李博士》、《同德寺雨後寄元侍御李博士》、《同德閣期元侍御李博士不至各投贈二首》，均與同人之作，唯其名不詳。","傅璇琮先生《韋應物繫年考證》定應物退居同德寺爲永泰元年棄洛陽丞後。","頗疑此人即與應物過從甚密之李儋，出姑臧大房，給事中昇期之子，官至殿中侍御史，见《新唐书·宰相世系表》。","俟得確證定之。","）。"]', '诗', 'shi', '', NULL, '問韋應物（題擬） 李博士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e3e20c-ca90-4eb0-a146-bc858af596a8', '同姜氾水題裴司馬東齋', '同姜氾水題裴司马东斋', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["不記鄱陽郡，俱因謫官過。","白雲心已矣，滄海意如何？","蔾杖全吾道，榴花養太和。","春風騎馬醉，江月釣漁歌。","步履侵苔廨，頃冠拂薜蘿。","遠山終日在，芳草傍人多。","莫學靈均悵，愁竟楚水波。","（《新撰類林鈔》卷四，據小川環樹錄文。","）（按：《全唐詩》卷一四九收此詩，題作《同姜濬題裴式微餘干東齋》。","內容大異，今重錄。","）。"]', '["不記鄱陽郡，俱因謫官過。","白云心已矣，滄海意如何？","蔾杖全吾道，榴花養太和。","春风騎马醉，江月釣漁歌。","步履侵苔廨，頃冠拂薜蘿。","远山終日在，芳草傍人多。","莫学靈均悵，愁竟楚水波。","（《新撰類林鈔》卷四，據小川环樹錄文。","）（按：《全唐诗》卷一四九收此诗，題作《同姜濬題裴式微餘干东斋》。","內容大異，今重錄。","）。"]', '诗', 'shi', '', NULL, '同姜氾水題裴司馬東齋 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('138f861a-bd44-43a4-8fd7-4c05cb741640', '過鄭山人所居', '過鄭山人所居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["一逕人尋谷口村，春山犬吠武陵源。","青苔滿地無行處，深咲桃花獨閉門。","（同前）（按：《全唐詩》卷一五○收本詩，內容大異，今重錄。","《千載佳句》卷上《人事部·閑居》收後二句，詩題不同，《全唐詩逸》卷上已收入。","）。"]', '["一逕人尋谷口村，春山犬吠武陵源。","青苔满地無行处，深咲桃花独閉门。","（同前）（按：《全唐诗》卷一五○收本诗，內容大異，今重錄。","《千載佳句》卷上《人事部·闲居》收後二句，诗題不同，《全唐诗逸》卷上已收入。","）。"]', '诗', 'shi', '', NULL, '過鄭山人所居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('889e8b5b-d646-4f31-baf7-ad0227bef696', '將赴湖南湖上別皇甫曾', '將赴湖南湖上別皇甫曾', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["此去君何恨，南行我更遙。","東西湖渺渺，離別雨瀟瀟。","綠山通春谷，青山過板橋。","潯陽如枉棹，千里有歸潮。","（見席刻《劉隨州詩集》卷二）。"]', '["此去君何恨，南行我更遙。","东西湖渺渺，離別雨瀟瀟。","綠山通春谷，青山過板橋。","潯陽如枉棹，千里有归潮。","（见席刻《劉隨州诗集》卷二）。"]', '诗', 'shi', '', NULL, '將赴湖南湖上別皇甫曾 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('678cae0c-9856-4a1e-aab3-095caa497f55', '送靈澈遠雲門', '送靈澈远云门', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["我歡常在夢，無心解傷別。","千里萬里人，祇似眼中月。","（見《會稽掇英總集》卷七）。"]', '["我歡常在梦，無心解傷別。","千里万里人，祇似眼中月。","（见《會稽掇英總集》卷七）。"]', '诗', 'shi', '', NULL, '送靈澈遠雲門 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4354792-a786-4490-9f24-2f50fd94b450', '早春詩', '早春诗', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["南園柳色動，野塘春水生。","屢遊煩將吏，獨此守山城。","（見《能改齋漫錄》卷十一）。"]', '["南园柳色动，野塘春水生。","屢游煩將吏，独此守山城。","（见《能改斋漫錄》卷十一）。"]', '诗', 'shi', '', NULL, '早春詩 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7864286-0efc-4293-bc33-9edbc8a367bd', '芳草澗', '芳草澗', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["青青滿地鋪顏色，曲曲一灣流水聲。","總爲遊人逞風景，亂雲初捲碧天空。","（見嘉靖《六合縣志》卷八，上海圖書館據天一閣藏本所攝顯微膠卷。","原注出《嘉定志》）。"]', '["青青满地鋪顏色，曲曲一灣流水声。","總爲游人逞风景，亂云初捲碧天空。","（见嘉靖《六合縣志》卷八，上海圖书館據天一閣藏本所攝显微膠卷。","原注出《嘉定志》）。"]', '诗', 'shi', '', NULL, '芳草澗 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69abfd6f-ab7d-4349-880f-1354444d597d', '春雪（存目）', '春雪（存目）', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["（按：此詩見《文苑英華》卷一五四。","《唐詩紀事》卷七、《萬首唐人絕句》卷二五、《全唐詩》卷一百作東方虬詩。","未詳孰是，姑存目以俟考。","）空。"]', '["（按：此诗见《文苑英华》卷一五四。","《唐诗紀事》卷七、《万首唐人絕句》卷二五、《全唐诗》卷一百作东方虬诗。","未詳孰是，姑存目以俟考。","）空。"]', '诗', 'shi', '', NULL, '春雪（存目） 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5359e11f-0d36-40cf-8570-94c86cb27013', '將赴渭北對月懷晝上人（題擬）', '將赴渭北对月懷晝上人（題擬）', '47c2fadf-e292-443f-8db2-d5263012ec2c', '唐', '["悠然顧山侶。","（見《皎然集》卷一《五言酬烏程楊明府將赴渭北對月見懷》注引）。"]', '["悠然顧山侶。","（见《皎然集》卷一《五言酬烏程楊明府將赴渭北对月见懷》注引）。"]', '诗', 'shi', '', NULL, '將赴渭北對月懷晝上人（題擬） 楊華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da5fa04b-2469-4fb1-b175-1761307c7f02', '悲春', '悲春', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["青青柳色萬家春，獨掩荆扉對苦辛。","山月有時來照戶，蕃歌無夜不傷人。","荒村寂寂鷄鳴早，窮巷喧喧犬吠頻。"]', '["青青柳色万家春，独掩荆扉对苦辛。","山月有时来照戶，蕃歌無夜不傷人。","荒村寂寂鷄鳴早，窮巷喧喧犬吠頻。"]', '诗', 'shi', '', NULL, '悲春 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bd9f5fa-5244-4a5d-a91c-485856b07805', '秦閨怨 一', '秦閨怨 一', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["幽閨情自苦，何事更逢春？","萱草侵堦綠，垂楊闇戶新。","鏡中絲髮亂，窗外鳥聲頻。","對此芳菲景，長宵轉憶君。"]', '["幽閨情自苦，何事更逢春？","萱草侵堦綠，垂楊闇戶新。","镜中絲髮亂，窗外鸟声頻。","对此芳菲景，长宵轉憶君。"]', '诗', 'shi', '', NULL, '秦閨怨 一 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db67ff36-08a9-48c3-8856-3bd735fccd28', '秦閨怨 二', '秦閨怨 二', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["春至感心傷，低眉入洞房。","征夫天外別，拋妾鎮[漁]（魚）陽。","有意連新月，無情理舊妝。","長流雙瞼淚，獨恨對芬芳。"]', '["春至感心傷，低眉入洞房。","征夫天外別，拋妾鎮[漁]（鱼）陽。","有意連新月，無情理旧妝。","长流雙瞼泪，独恨对芬芳。"]', '诗', 'shi', '', NULL, '秦閨怨 二 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0783d204-3eee-4c20-9307-53ebe5dd5eaa', '憶北府弟妹（二首） 一', '憶北府弟妹（二首） 一', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["骨肉東西各一方，弟兄南北斷肝腸。","離情祇向天邊碎，壯志還隨行處傷。","不料此心分兩國，誰知翻屬二君王。","艱難少有安中土，經亂多從胡虜鄉。","獨羨春秋連影雁，每思羽翼幷成行。","題詩泣盡東流水，欲話無人問短長。"]', '["骨肉东西各一方，弟兄南北斷肝腸。","離情祇向天邊碎，壯志還隨行处傷。","不料此心分兩国，誰知翻屬二君王。","艱难少有安中土，經亂多從胡虜乡。","独羨春秋連影雁，每思羽翼幷成行。","題诗泣尽东流水，欲話無人问短长。"]', '诗', 'shi', '', NULL, '憶北府弟妹（二首） 一 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cdb4325-5806-4eb9-a0c3-7df2eefc4225', '憶北府弟妹（二首） 二', '憶北府弟妹（二首） 二', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["與爾俱成淪沒世，艱難終日各東西。","胡笳曉聽心長共，漢月[宵]（霄）看意自迷。","獨泣空房襟上血，孤眠永夜夢中啼。","何時骨肉園林會，不向天涯聞鼓鞞。"]', '["與爾俱成淪沒世，艱难終日各东西。","胡笳晓听心长共，漢月[宵]（霄）看意自迷。","独泣空房襟上血，孤眠永夜梦中啼。","何时骨肉园林會，不向天涯闻鼓鞞。"]', '诗', 'shi', '', NULL, '憶北府弟妹（二首） 二 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ec61cf0-463a-44e1-8e2a-7fcc72dbf099', '奉憶北庭楊侍御留後', '奉憶北庭楊侍御留後', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["不幸同俘縶，常悲海雁孤。","如何一朝事，流落在天隅？","永夜多寂寞，秋深獨鬱紆。","欲知相憶甚，終日淚成珠。"]', '["不幸同俘縶，常悲海雁孤。","如何一朝事，流落在天隅？","永夜多寂寞，秋深独鬱紆。","欲知相憶甚，終日泪成珠。"]', '诗', 'shi', '', NULL, '奉憶北庭楊侍御留後 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af240669-6504-4680-bb2e-ce8ce3cd49ee', '歲日送王十三判官之松州幕', '歲日送王十三判官之松州幕', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["異方新歲自然悲，三友那堪更別離。","虜酒未傾心已醉，愁容相顧懶題詩。","三邊罷戰猶長策，二國通和藉六奇。","佇聽鶯遷當此日，歸鴻莫使尺書遲。"]', '["異方新歲自然悲，三友那堪更別離。","虜酒未傾心已醉，愁容相顧懶題诗。","三邊罷戰猶长策，二国通和藉六奇。","佇听鶯遷當此日，归鴻莫使尺书遲。"]', '诗', 'shi', '', NULL, '歲日送王十三判官之松州幕 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2aafa0c-b8a2-4236-b62e-48ae043297f0', '冬[宵]（霄）感懷', '冬[宵]（霄）感懷', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["切切霜風入夜寒，微微孤燭客心難。","長[宵]（霄）獨恨流離苦，直到平明淚不乾。","。"]', '["切切霜风入夜寒，微微孤燭客心难。","长[宵]（霄）独恨流離苦，直到平明泪不乾。","。"]', '诗', 'shi', '', NULL, '冬[宵]（霄）感懷 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('268f46e6-6f68-4e6a-ba91-de0937abfc4a', '歎路傍枯骨', '歎路傍枯骨', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["行行遍歷盡沙場，只是偏教此意傷。","從來征戰皆空地，徒使驕矜掩異方。"]', '["行行遍歷尽沙場，只是偏教此意傷。","從来征戰皆空地，徒使驕矜掩異方。"]', '诗', 'shi', '', NULL, '歎路傍枯骨 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6957f845-445a-45af-b8bb-bf44fcc57645', '言懷', '言懷', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["愁緒足悲歌，離心似網羅。","二年分兩國，萬里一長河。","磧外人行少，天邊雁叫多。","懷鄉不得死，皆是惜天涯。"]', '["愁緒足悲歌，離心似網羅。","二年分兩国，万里一长河。","磧外人行少，天邊雁叫多。","懷乡不得死，皆是惜天涯。"]', '诗', 'shi', '', NULL, '言懷 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9998ee3-8c7d-4cee-9887-f8f3d867e028', '見花發有思', '见花發有思', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["花未發，增所思，及見花開轉益悲。","花開未發尚有期，獨我情懷未見時。"]', '["花未發，增所思，及见花开轉益悲。","花开未發尚有期，独我情懷未见时。"]', '诗', 'shi', '', NULL, '見花發有思 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5eeb4ab-4529-4ec8-b64c-3243e6902c72', '無名歌', '無名歌', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["天下沸騰積年歲，米到千錢人失計。","附郭種得二頃田，磨折不充十一稅。","今年苗稼看更弱，[枌]（一作「墳」）榆產業須拋却。","不知天下有幾人，但見波逃如雨脚。","去去如同不繫舟，隨波逐水泛長流。","漂泊已經千里外，誰人不帶兩鄉愁？","舞女庭前厭酒肉，不知百姓餓眠宿。","君不見城外空墻遙，將軍只是栽花竹。","君看城外恓惶處，段段茅花如柳葉（一作「{葜大=糸}」）。","海鷰銜泥欲作巢，空堂無人却飛去。","（按：此首又見伯三六二○卷，不署名，今據校。","此本末多數句：「所在君侯，不須惱亂。","發意害彼，不知自傷，此世報行惡名，當來必酬苦果。","」似與此詩無關。","又此首及下二首疑非殷濟詩。","）。"]', '["天下沸腾積年歲，米到千錢人失計。","附郭種得二頃田，磨折不充十一稅。","今年苗稼看更弱，[枌]（一作「墳」）榆產業須拋却。","不知天下有幾人，但见波逃如雨脚。","去去如同不繫舟，隨波逐水泛长流。","漂泊已經千里外，誰人不带兩乡愁？","舞女庭前厭酒肉，不知百姓餓眠宿。","君不见城外空墻遙，將軍只是栽花竹。","君看城外恓惶处，段段茅花如柳葉（一作「{葜大=糸}」）。","海鷰銜泥欲作巢，空堂無人却飞去。","（按：此首又见伯三六二○卷，不署名，今據校。","此本末多數句：「所在君侯，不須惱亂。","發意害彼，不知自傷，此世報行惡名，當来必酬苦果。","」似與此诗無关。","又此首及下二首疑非殷濟诗。","）。"]', '诗', 'shi', '', NULL, '無名歌 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70d1b756-0d50-4482-be3d-b7e83188e5ea', '夢歸還', '梦归還', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '夢歸還 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81e12072-b95f-4af6-8cda-eeccffb21a91', '夢歸還 一', '梦归還 一', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["春來相思每隨風，萬里關山想自通。","夢裏宛然歸舊國，覺來還在虜營中。"]', '["春来相思每隨风，万里关山想自通。","梦裏宛然归旧国，覺来還在虜營中。"]', '诗', 'shi', '', NULL, '夢歸還 一 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8848ad2-962d-4e1b-b891-1e5075a55f78', '夢歸還 二', '梦归還 二', 'b357fb04-fedd-4dc8-96da-e7103332ed1b', '唐', '["春來有幸却承恩，花裏含啼入殿門。","殘妝不用添紅粉，且待君王見淚痕。","（均見伯三八一二卷）。"]', '["春来有幸却承恩，花裏含啼入殿门。","殘妝不用添紅粉，且待君王见泪痕。","（均见伯三八一二卷）。"]', '诗', 'shi', '', NULL, '夢歸還 二 殷濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d945acb9-1d28-4599-9554-9b16537191bf', '草庵歌', '草庵歌', 'b7958428-86f8-4208-80a0-7236df202b50', '唐', '["吾結草庵無寶貝，飯了從容圖睡快。","成時初見茅草新，破後還將茅草蓋。","住庵人，鎮常在，不屬中間與內外。","人住處，我不住，世人愛處我不愛。","庵雖小，含法界，方丈老人相體解。","上乘菩薩信無疑，中下聞之必生怪。","問此庵，壞不壞，壞與不壞主元在。","不居南北與東西，基上堅牢以爲最。","青松下，明窗內，玉殿朱樓未爲對。","納帔幪頭萬事休，此時山僧都不會。","住此庵，休作解，誰誇鋪席圖人買。","迴光返照便歸來，廓達靈根非向背。","遇祖師，親訓誨，結草爲庵莫生退。","百年拋却任縱橫，擺手便行且無罪。","千種言，萬般解，祇要交君長不解。","欲識庵中不死人，豈離而今遮皮袋。","（見《景德傳燈錄》卷三十）。"]', '["吾結草庵無寶貝，飯了從容圖睡快。","成时初见茅草新，破後還將茅草蓋。","住庵人，鎮常在，不屬中间與內外。","人住处，我不住，世人愛处我不愛。","庵雖小，含法界，方丈老人相體解。","上乘菩薩信無疑，中下闻之必生怪。","问此庵，壞不壞，壞與不壞主元在。","不居南北與东西，基上堅牢以爲最。","青松下，明窗內，玉殿朱楼未爲对。","納帔幪头万事休，此时山僧都不會。","住此庵，休作解，誰誇鋪席圖人買。","迴光返照便归来，廓達靈根非向背。","遇祖師，親訓誨，結草爲庵莫生退。","百年拋却任縱橫，擺手便行且無罪。","千種言，万般解，祇要交君长不解。","欲識庵中不死人，豈離而今遮皮袋。","（见《景德傳灯錄》卷三十）。"]', '诗', 'shi', '', NULL, '草庵歌 希遷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a737bb26-d9cb-49ba-a129-5603f8363771', '參同契', '參同契', 'b7958428-86f8-4208-80a0-7236df202b50', '唐', '["竺土大僊心，東西密相付。","人根有利鈍，道無南北祖。","靈源明皎潔，枝派暗流注。","執事元是迷，契理亦非悟。","門門一切境，迴互不迴互。","迴而更相涉，不爾依位住。","色本殊質象，聲元異樂苦。","暗合上中言，明明清濁句。","四大性自復，如子得其母。","火熱風動搖，水濕地堅固。","眼色耳音聲，鼻香舌鹼醋。","然依一一法，依根葉分布。","本末須歸宗，尊卑用其語。","當明中有暗，勿以暗相遇。","當暗中有明，勿以明相覩。","明暗各相對，比如前後步。","萬物自有功，當言用及處。","事存函蓋合，理應箭鋒拄。","承言須會宗，勿自立規矩。","觸目不會道，運足焉知路。","進步非近遠，迷隔山河固。","謹白參玄人，光陰莫虛度。","（同前。","又見《五燈會元》卷五）。"]', '["竺土大僊心，东西密相付。","人根有利鈍，道無南北祖。","靈源明皎潔，枝派暗流注。","執事元是迷，契理亦非悟。","门门一切境，迴互不迴互。","迴而更相涉，不爾依位住。","色本殊質象，声元異乐苦。","暗合上中言，明明清濁句。","四大性自复，如子得其母。","火熱风动搖，水濕地堅固。","眼色耳音声，鼻香舌鹼醋。","然依一一法，依根葉分布。","本末須归宗，尊卑用其語。","當明中有暗，勿以暗相遇。","當暗中有明，勿以明相覩。","明暗各相对，比如前後步。","万物自有功，當言用及处。","事存函蓋合，理應箭鋒拄。","承言須會宗，勿自立規矩。","觸目不會道，運足焉知路。","進步非近远，迷隔山河固。","謹白參玄人，光陰莫虛度。","（同前。","又见《五灯會元》卷五）。"]', '诗', 'shi', '', NULL, '參同契 希遷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96a4e6db-1960-44d7-8600-19c7237a8a11', '偈', '偈', 'b7958428-86f8-4208-80a0-7236df202b50', '唐', '["從來共住不知名，任運相將作（《五燈會元》作「祇」）摩行。","自古上賢猶不識，造次常（《五燈會元》作「凡」）流豈可明。","（見《祖堂集》卷四、《五燈會元》卷五）。"]', '["從来共住不知名，任運相將作（《五灯會元》作「祇」）摩行。","自古上賢猶不識，造次常（《五灯會元》作「凡」）流豈可明。","（见《祖堂集》卷四、《五灯會元》卷五）。"]', '诗', 'shi', '', NULL, '偈 希遷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81c5ac5a-7585-4b6c-8331-019ca09435ee', '頌', '頌', 'edaf07fa-7eb8-490c-97d8-501e99dee6fc', '唐', '["十二時中那事別，子丑寅卯吾今說。","若會唯心萬法空，釋迦彌勒從茲決。","（見《五燈會元》卷五）。"]', '["十二时中那事別，子丑寅卯吾今说。","若會唯心万法空，釋迦彌勒從茲決。","（见《五灯會元》卷五）。"]', '诗', 'shi', '', NULL, '頌 大同濟禪師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dccbcc7-459f-45a1-a55c-a3f795a3f10e', '', '', '68769721-c045-466f-bc78-aaacd57abef9', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 張芬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5937ae6f-2482-4844-b5db-1777fa7d0106', '酬李端山中見期不至（題擬）', '酬李端山中见期不至（題擬）', '68769721-c045-466f-bc78-aaacd57abef9', '唐', '["君家舊林壑，寄在亂峰西。","近日春雲滿，相思路亦迷。","聞鐘投野寺，待月過前溪。","悵望成幽夢，依依識故蹊。","（見江標影宋書棚本《唐詩五十家小集·李端詩集》卷二）（按：《全唐詩》卷二八五收此詩於李端名下，題作《酬前大理寺評事張芬》。","檢影宋書棚本，此詩附於李端《山中期張芬不至》後，題作《酬前》，署「大理評事張芬」。","此爲張芬詩附收於李集，作李詩誤。","另參本書卷十一苗發詩附考。","）。"]', '["君家旧林壑，寄在亂峰西。","近日春云满，相思路亦迷。","闻鐘投野寺，待月過前溪。","悵望成幽梦，依依識故蹊。","（见江標影宋书棚本《唐诗五十家小集·李端诗集》卷二）（按：《全唐诗》卷二八五收此诗於李端名下，題作《酬前大理寺評事張芬》。","檢影宋书棚本，此诗附於李端《山中期張芬不至》後，題作《酬前》，署「大理評事張芬」。","此爲張芬诗附收於李集，作李诗誤。","另參本书卷十一苗發诗附考。","）。"]', '诗', 'shi', '', NULL, '酬李端山中見期不至（題擬） 張芬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9c7c099-e7dd-4a5f-a194-f9c8bdc527ce', '上陽春辭', '上陽春辞', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["聖皇自在（《千載佳句》卷下作「有」）長生殿，不向蓬萊王母家。","（見《日本古典文學大系》七三冊藤原公任《和漢朗詠集》卷下《帝王》）（〖1〗川口久雄校注云：架藏私注本題作《上陽春辭》，《千載佳句·禁中》作《上春詞》，柿村本作《上陽春詞》）。"]', '["聖皇自在（《千載佳句》卷下作「有」）长生殿，不向蓬萊王母家。","（见《日本古典文学大系》七三冊藤原公任《和漢朗詠集》卷下《帝王》）（〖1〗川口久雄校注云：架藏私注本題作《上陽春辞》，《千載佳句·禁中》作《上春词》，柿村本作《上陽春词》）。"]', '诗', 'shi', '', NULL, '上陽春辭 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12817f2d-0f3c-4287-94a8-da1692924462', '句', '句', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["欲問皇天天更遠。","（胡偉《宮詞》）。"]', '["欲问皇天天更远。","（胡偉《宮词》）。"]', '诗', 'shi', '', NULL, '句 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64248fd5-63e9-4c49-9d82-2a216df9a1b0', '詩', '诗', '112c4420-04c5-498a-ba29-cb5654ad7e32', '唐', '["祖德道場下，往來三十秋。","白頭方問法，朗月特相留。","（《至大金陵新志》卷十二下）。"]', '["祖德道場下，往来三十秋。","白头方问法，朗月特相留。","（《至大金陵新志》卷十二下）。"]', '诗', 'shi', '', NULL, '詩 徐浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bbc4dc9-227a-4236-91f8-b1ccfb85640e', '天台智者大師畫贊', '天台智者大師畫贊', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["天台大師俗姓陳，其名智顗華容人。","隋煬皇帝崇明因，號爲智者誠敬申。","師初孕育靈異頻，彩烟浮空光照鄰。","堯眉舜目熙若春，禪慧悲智嚴其身。","長沙佛前發弘誓，定光菩薩示冥契。","恍如登山臨海際，上指伽藍畢身世。","東謁大蘇求真諦，智同靈鷲聽法偈。","得宿命通弁無礙，旋陀羅尼華三昧。","居常西面化在東，八載瓦官闡玄風。","敷演智度發禪蒙，梁陳舊德皆仰崇。","遂入天台華頂中，因見定光符昔夢。","降魔制敵爲法雄，胡僧開道精感通。","又有聖賢垂秘旨，時平國清即名寺。","贖得魚梁五百里，其中放生講流水。","後主三禮洞庭裏，請爲菩薩戒弟子。","煬皇世鎮臨江涘，金城說會求制止。","香火事訖乃西旋，渚宮聽衆逾五千。","建立精舍名玉泉，橫亘萬里皆稟緣。","煬皇啓請回法船，非禪不智求弘宣。","遂著《淨名精義傳》，因令徐柳參其玄。","帝既西趍移象魏，師因東還遂初志。","半山忽與沙門顛，俄傾逡巡偡韜秘。","止觀大師名法源，親事左溪弘度門。","二威灌頂誦師言，同稟思文龍樹尊。","荆溪妙樂間生孫，廣述祖教補乾坤。","寫照隨形殊好存，源公瞻禮必益敦。","俾余贊述斯討論，庶幾億載垂後昆。","（《傳教大師全集·天台靈應圖本傳集》卷二，轉錄自《東南文化》一九九○年六期《天台文化專號》）。"]', '["天台大師俗姓陳，其名智顗华容人。","隋煬皇帝崇明因，號爲智者誠敬申。","師初孕育靈異頻，彩烟浮空光照鄰。","堯眉舜目熙若春，禪慧悲智嚴其身。","长沙佛前發弘誓，定光菩薩示冥契。","恍如登山臨海際，上指伽藍畢身世。","东謁大蘇求真諦，智同靈鷲听法偈。","得宿命通弁無礙，旋陀羅尼华三昧。","居常西面化在东，八載瓦官闡玄风。","敷演智度發禪蒙，梁陳旧德皆仰崇。","遂入天台华頂中，因见定光符昔梦。","降魔制敵爲法雄，胡僧开道精感通。","又有聖賢垂秘旨，时平国清即名寺。","贖得鱼梁五百里，其中放生講流水。","後主三禮洞庭裏，請爲菩薩戒弟子。","煬皇世鎮臨江涘，金城说會求制止。","香火事訖乃西旋，渚宮听衆逾五千。","建立精舍名玉泉，橫亘万里皆稟緣。","煬皇啓請回法船，非禪不智求弘宣。","遂著《淨名精義傳》，因令徐柳參其玄。","帝既西趍移象魏，師因东還遂初志。","半山忽與沙门顛，俄傾逡巡偡韜秘。","止观大師名法源，親事左溪弘度门。","二威灌頂誦師言，同稟思文龙樹尊。","荆溪妙乐间生孫，廣述祖教補乾坤。","寫照隨形殊好存，源公瞻禮必益敦。","俾余贊述斯討論，庶幾億載垂後昆。","（《傳教大師全集·天台靈應圖本傳集》卷二，轉錄自《东南文化》一九九○年六期《天台文化專號》）。"]', '诗', 'shi', '', NULL, '天台智者大師畫贊 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41e97c18-ab59-453b-b7ba-eeb6ed7862ea', '桃源（題擬）', '桃源（題擬）', '5e4dc8fa-efa2-47ad-968d-407f5b14a830', '唐', '["當時避地乾坤窄，此地安家日月長。","草色幾經壇杏改，浪花猶帶洞庭香。","（見《輿地紀勝》卷六八《常德府》）。"]', '["當时避地乾坤窄，此地安家日月长。","草色幾經壇杏改，浪花猶带洞庭香。","（见《輿地紀勝》卷六八《常德府》）。"]', '诗', 'shi', '', NULL, '桃源（題擬） 李臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ea58ecb-2db5-4e2b-8eec-138c9964d4b6', '遊南鴈詩', '游南鴈诗', '5e4dc8fa-efa2-47ad-968d-407f5b14a830', '唐', '["鴈蕩諸奇不可窮，石梁華表遠淩空。","乾坤誰道洞中小，日月曾從牖裏通。","詞客墨苔觀照耀，飛仙環佩聽玲瓏。","何當偕得緱山鶴，駕入嶙峋翠幾重。","（見同治丙寅刊齊召南纂《溫州府志》）（按：張靖龍云：「見清周喟《南雁蕩山志》卷七《詩外編》引明人陳玭《嘉靖南雁蕩志》，又見乾隆《平陽縣志》卷二，題作《游橫陽雁蕩山詩》。","」）。"]', '["鴈蕩諸奇不可窮，石梁华表远淩空。","乾坤誰道洞中小，日月曾從牖裏通。","词客墨苔观照耀，飞仙环佩听玲瓏。","何當偕得緱山鹤，駕入嶙峋翠幾重。","（见同治丙寅刊齊召南纂《溫州府志》）（按：張靖龙云：「见清周喟《南雁蕩山志》卷七《诗外編》引明人陳玭《嘉靖南雁蕩志》，又见乾隆《平陽縣志》卷二，題作《游橫陽雁蕩山诗》。","」）。"]', '诗', 'shi', '', NULL, '遊南鴈詩 李臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c81b3dbd-7e2c-4b42-90e9-163d8b74376e', '', '', '410ee5b6-9254-452b-a567-902b195807a7', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 青霞子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('723b6eee-4d46-42a2-a38a-b0ef981625bd', '龍虎元旨歌 一', '龙虎元旨歌 一', '410ee5b6-9254-452b-a567-902b195807a7', '唐', '["天地初分日月高，狀如雞子復如桃。","陰陽真氣知時節，直待三年脫戰袍。"]', '["天地初分日月高，狀如雞子复如桃。","陰陽真氣知时節，直待三年脫戰袍。"]', '诗', 'shi', '', NULL, '龍虎元旨歌 一 青霞子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d4ceb5e-5f2d-4b6f-825c-2d8b3cf0c0fc', '龍虎元旨歌 二', '龙虎元旨歌 二', '410ee5b6-9254-452b-a567-902b195807a7', '唐', '["大道分明在眼前，時人不會誤歸泉。","黃芽本是乾坤氣，神水根基與汞連。"]', '["大道分明在眼前，时人不會誤归泉。","黄芽本是乾坤氣，神水根基與汞連。"]', '诗', 'shi', '', NULL, '龍虎元旨歌 二 青霞子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a9b2173-dd5f-4d84-b99b-d7bcbf31df91', '龍虎元旨歌 三', '龙虎元旨歌 三', '410ee5b6-9254-452b-a567-902b195807a7', '唐', '["龍虎丹砂義最幽，五神金內汞鉛流。","千朝變紫雲飛去，直至大羅天上頭。"]', '["龙虎丹砂義最幽，五神金內汞鉛流。","千朝变紫云飞去，直至大羅天上头。"]', '诗', 'shi', '', NULL, '龍虎元旨歌 三 青霞子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c789bdf0-6fea-46ed-8e8a-0e56cb91ceca', '龍虎元旨歌 四', '龙虎元旨歌 四', '410ee5b6-9254-452b-a567-902b195807a7', '唐', '["認得根源不用忙，三三合九有純陽。","潛通變化神光見，從此朝天近玉皇。"]', '["認得根源不用忙，三三合九有純陽。","潛通变化神光见，從此朝天近玉皇。"]', '诗', 'shi', '', NULL, '龍虎元旨歌 四 青霞子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45dfdbed-c0da-4810-b0b8-2e9d9cc24ecf', '龍虎元旨歌 五', '龙虎元旨歌 五', '410ee5b6-9254-452b-a567-902b195807a7', '唐', '["用鉛須得汞相和，二性爲親女唱歌。","鍊到紫河車地動，白雲相伴鶴來過。"]', '["用鉛須得汞相和，二性爲親女唱歌。","鍊到紫河车地动，白云相伴鹤来過。"]', '诗', 'shi', '', NULL, '龍虎元旨歌 五 青霞子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33b42804-6dee-4650-98bc-674ad6129d9e', '龍虎元旨歌 六', '龙虎元旨歌 六', '410ee5b6-9254-452b-a567-902b195807a7', '唐', '["合其天地合其元，子母相逢不敢言。","先汞後鉛真道大，莫教失伴鶴歸天。"]', '["合其天地合其元，子母相逢不敢言。","先汞後鉛真道大，莫教失伴鹤归天。"]', '诗', 'shi', '', NULL, '龍虎元旨歌 六 青霞子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7d9589d-806e-454a-8083-a9ccbfb6abb2', '龍虎元旨歌 七', '龙虎元旨歌 七', '410ee5b6-9254-452b-a567-902b195807a7', '唐', '["此寶從來二八傳，吉年吉月入爐安。","千朝火候依時節，必定芽成汞已乾。","（按：《龍虎元旨》末云：「東嶽董師元於貞元五年受之於羅浮山隱士青霞子，貞元十九年傳受劍州司馬張陶，開成三年京師傳族弟汾，成長契五年傳成君。","」）。"]', '["此寶從来二八傳，吉年吉月入爐安。","千朝火候依时節，必定芽成汞已乾。","（按：《龙虎元旨》末云：「东嶽董師元於貞元五年受之於羅浮山隐士青霞子，貞元十九年傳受劍州司马張陶，开成三年京師傳族弟汾，成长契五年傳成君。","」）。"]', '诗', 'shi', '', NULL, '龍虎元旨歌 七 青霞子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cabad79-7f22-461c-a9e9-8a0371c9704c', '雲門山', '云门山', '2ad8fbb1-bbd3-46b4-8746-38b56ef57319', '唐', '["十年遊罷古招提，路入雲門峻似梯。","秀氣漸分秦望嶺，寒身猶入若耶溪。","天開霽色澄千里，稻熟秋香互萬畦。","多少靈蹤待窮覽，却愁回馭日平西。","（見《古今圖書集成·山川典》卷一一四《雲門山部》）。"]', '["十年游罷古招提，路入云门峻似梯。","秀氣漸分秦望嶺，寒身猶入若耶溪。","天开霽色澄千里，稻熟秋香互万畦。","多少靈蹤待窮覽，却愁回馭日平西。","（见《古今圖书集成·山川典》卷一一四《云门山部》）。"]', '诗', 'shi', '', NULL, '雲門山 秦系 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4785da05-0eac-4ab6-a47e-49b2a110bf53', '送常州司士崔千里（題擬）', '送常州司士崔千里（題擬）', '0398551f-d51f-4897-962a-86b2c053e72d', '唐', '["官屈須推命，時危莫厭貧。","城樓近江水，潮退看垂輪。","（《千唐誌齋藏誌》九八三頁崔恕撰《唐故登仕郎常州司士參軍襲武城縣開國伯崔府君墓誌銘》引。","此則承陶先生告知。","）。"]', '["官屈須推命，时危莫厭貧。","城楼近江水，潮退看垂輪。","（《千唐誌斋藏誌》九八三頁崔恕撰《唐故登仕郎常州司士參軍襲武城縣开国伯崔府君墓誌銘》引。","此則承陶先生告知。","）。"]', '诗', 'shi', '', NULL, '送常州司士崔千里（題擬） 姚明敭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e76db489-1a13-42ce-a521-3ae91209bbac', '開元觀陪杜大夫中元日觀樂', '开元观陪杜大夫中元日观乐', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["（按：《全唐詩》卷二七○收此詩，第八句缺一字。","《古今歲時雜詠》卷二八錄此詩不缺，此句作「好風油幕動高煙」。","）空。"]', '["（按：《全唐诗》卷二七○收此诗，第八句缺一字。","《古今歲时杂詠》卷二八錄此诗不缺，此句作「好风油幕动高煙」。","）空。"]', '诗', 'shi', '', NULL, '開元觀陪杜大夫中元日觀樂 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1c633ce-3c74-4594-9169-e0cf7a24ed55', '運斤賦附歌', '運斤賦附歌', '6d801f0c-9153-4c84-baac-3f24c4622d24', '唐', '["彼二子兮以藝相崇，得一理兮其心則同。","運斤在手誠可懼，堅立不動神之雄。","（見《文苑英華》卷一○一）。"]', '["彼二子兮以藝相崇，得一理兮其心則同。","運斤在手誠可懼，堅立不动神之雄。","（见《文苑英华》卷一○一）。"]', '诗', 'shi', '', NULL, '運斤賦附歌 席夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c94a0340-f429-4218-ac9a-84f1f3323fe8', '怒李京兆（題擬）', '怒李京兆（題擬）', 'c0c09739-8065-41de-bad7-12f491269bec', '唐', '["近日兼放髭鬚白，猶向人前作背面。","（見《大唐傳載》）。"]', '["近日兼放髭鬚白，猶向人前作背面。","（见《大唐傳載》）。"]', '诗', 'shi', '', NULL, '怒李京兆（題擬） 裴延齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a92607ca-6a92-49ef-9afb-11aaa881e5f8', '劍詩', '劍诗', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["太平時節無人看，雪刃閒封滿匣塵。","（見《吟窗雜錄》卷十四《詩中旨格》）（按：《吟窗雜錄》本作者名作「處綸」，茲依《詩學指南》卷四改正。","《全唐詩》卷八四九收作處默詩，疑誤。","）。"]', '["太平时節無人看，雪刃閒封满匣塵。","（见《吟窗杂錄》卷十四《诗中旨格》）（按：《吟窗杂錄》本作者名作「处綸」，茲依《诗学指南》卷四改正。","《全唐诗》卷八四九收作处默诗，疑誤。","）。"]', '诗', 'shi', '', NULL, '劍詩 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60b061a4-d07e-4cbb-a5f3-1f5f4be92ed6', '竇五判官罷舉赴商州辟書袖文相訪書懷話舊因抒鄙懷（按：此詩見《竇氏聯珠集》，下署「重表兄太府卿賜紫金魚袋韋渠牟」。《全唐詩》卷三一四收本詩，題作《贈竇五判官》，刪略過甚，今爲補原題，詩不重錄。）', '竇五判官罷舉赴商州辟书袖文相訪书懷話旧因抒鄙懷（按：此诗见《竇氏聯珠集》，下署「重表兄太府卿賜紫金鱼袋韋渠牟」。《全唐诗》卷三一四收本诗，題作《贈竇五判官》，刪略過甚，今爲補原題，诗不重錄。）', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '竇五判官罷舉赴商州辟書袖文相訪書懷話舊因抒鄙懷（按：此詩見《竇氏聯珠集》，下署「重表兄太府卿賜紫金魚袋韋渠牟」。《全唐詩》卷三一四收本詩，題作《贈竇五判官》，刪略過甚，今爲補原題，詩不重錄。） 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b779dbde-1303-4f61-a021-d9a933db31d5', '句', '句', '56dfa9ec-715c-4f18-bc5f-fa0f11c2dc13', '唐', '["人人來問此中妙，懷素自云初不知。","（見明汪珂玉《汪氏珊瑚網法書題跋》卷二《藏真草書清淨經》附劉世昌跋引）（按：《全唐詩》卷八○八收懷素詩二首，傳云：「懷素，京兆人，從玄奘法師出家，上元三年，詔住西太原寺，尋歸西京。","以草書名。","」此傳實將同名之另一僧事跡誤入。","玄奘法嗣懷素，事跡詳《開元釋教錄》卷九，《宋高僧傳》卷十四，精於四分律，未聞其能詩善書。","所收二詩，皆以草書名世之長沙僧懷素作。","《題張僧繇醉僧圖》，出《圖畫見聞志》卷五：「又僧繇曾作《醉僧圖》傳於世，長沙僧懷素有詩云〖略。","〗」又米芾《書史》云：「懷素草書『祝融高座對寒峰』綠絹帖兩行，此字最佳，石紫微常刻石。","」所引一句，即《寄衡嶽僧》之首句。","《沅湘耆舊集》卷十收二詩歸長沙草書僧，是。","）。"]', '["人人来问此中妙，懷素自云初不知。","（见明汪珂玉《汪氏珊瑚網法书題跋》卷二《藏真草书清淨經》附劉世昌跋引）（按：《全唐诗》卷八○八收懷素诗二首，傳云：「懷素，京兆人，從玄奘法師出家，上元三年，詔住西太原寺，尋归西京。","以草书名。","」此傳實將同名之另一僧事跡誤入。","玄奘法嗣懷素，事跡詳《开元釋教錄》卷九，《宋高僧傳》卷十四，精於四分律，未闻其能诗善书。","所收二诗，皆以草书名世之长沙僧懷素作。","《題張僧繇醉僧圖》，出《圖畫见闻志》卷五：「又僧繇曾作《醉僧圖》傳於世，长沙僧懷素有诗云〖略。","〗」又米芾《书史》云：「懷素草书『祝融高座对寒峰』綠絹帖兩行，此字最佳，石紫微常刻石。","」所引一句，即《寄衡嶽僧》之首句。","《沅湘耆旧集》卷十收二诗归长沙草书僧，是。","）。"]', '诗', 'shi', '', NULL, '句 懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c60bd6fd-e54f-4f4b-95a0-cdd86bc9a5e2', '五言答李師尚', '五言答李師尚', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["雅篇忽見遺，婉□開緘發。","惠風搖精思，瓊蕋疑花□。","（下缺）（見《四部叢刊》本《皎然集》卷一）（按：《皎然集》錄此詩四句後，尚有「空門青山月」至「來稅丘中轍」共七句。","檢《全唐詩》卷八一五，此七句爲《酬李司直縱諸公冬日遊妙喜寺題照昱二上人房寄長城潘丞述》一詩之末七句。","可知原本在《五言答李師尚》前四行後，適有缺頁或缺行，刊刻者不審，遂將二詩合成一篇，今爲析出。","）。"]', '["雅篇忽见遺，婉□开緘發。","惠风搖精思，瓊蕋疑花□。","（下缺）（见《四部叢刊》本《皎然集》卷一）（按：《皎然集》錄此诗四句後，尚有「空门青山月」至「来稅丘中轍」共七句。","檢《全唐诗》卷八一五，此七句爲《酬李司直縱諸公冬日游妙喜寺題照昱二上人房寄长城潘丞述》一诗之末七句。","可知原本在《五言答李師尚》前四行後，適有缺頁或缺行，刊刻者不審，遂將二诗合成一篇，今爲析出。","）。"]', '诗', 'shi', '', NULL, '五言答李師尚 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad34e0e9-d29c-4106-a809-2b0fd00a7760', '三言重擬五雜俎', '三言重擬五杂俎', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["五雜俎，篋中線。","往復還，雙飛燕。","不得已，長門怨。","（晝。","下缺。","見同書卷十。","）（按：原詩應爲與顏真卿等聯句，今僅存皎然之作。","又按：《全唐詩》卷七九四聯句《秋日潘述自長城至霅上……》第十句皎然詩缺一字。","明刻本《吳興藝文補》卷四三錄此詩不缺，此句爲「懽敍難兼遂」。","）。"]', '["五杂俎，篋中線。","往复還，雙飞燕。","不得已，长门怨。","（晝。","下缺。","见同书卷十。","）（按：原诗應爲與顏真卿等聯句，今僅存皎然之作。","又按：《全唐诗》卷七九四聯句《秋日潘述自长城至霅上……》第十句皎然诗缺一字。","明刻本《吳兴藝文補》卷四三錄此诗不缺，此句爲「懽敍难兼遂」。","）。"]', '诗', 'shi', '', NULL, '三言重擬五雜俎 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d8721b3-3012-4abc-afaf-ed8279cf4f13', '句', '句', '6e5ca658-7b1b-4377-9ef0-2e0c9ddd41d8', '唐', '["行坐誦佛書。","（見齊己《白蓮集》卷九《過陸鴻漸舊居》自注引）。"]', '["行坐誦佛书。","（见齊己《白蓮集》卷九《過陸鴻漸旧居》自注引）。"]', '诗', 'shi', '', NULL, '句 陸羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c06d4d14-42a8-4c2e-83d5-f56c282c1374', '與耿湋聯句', '與耿湋聯句', '6e5ca658-7b1b-4377-9ef0-2e0c9ddd41d8', '唐', '["城裏攜籠萬壑前。","（羽。","下闕。","見席刻本《耿湋詩集》）。"]', '["城裏携籠万壑前。","（羽。","下闕。","见席刻本《耿湋诗集》）。"]', '诗', 'shi', '', NULL, '與耿湋聯句 陸羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d533ffc4-b725-4653-89e3-ce26721c8e0c', '入南澗', '入南澗', 'a52b447f-36c8-436f-90e5-86d85173e845', '唐', '["殘芳𦶜蘭馥，照水何花紅。"]', '["殘芳𦶜蘭馥，照水何花紅。"]', '诗', 'shi', '', NULL, '入南澗 鮑君徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14288bb1-77c2-48ad-9fa5-966e9578e6f2', '閑[宵]（霄）望月', '闲[宵]（霄）望月', 'a52b447f-36c8-436f-90e5-86d85173e845', '唐', '["轉扇來清風，援琴飛白雪。"]', '["轉扇来清风，援琴飞白雪。"]', '诗', 'shi', '', NULL, '閑[宵]（霄）望月 鮑君徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('575198d9-2117-4ef5-967f-f5a920da59a5', '晚眺', '晚眺', 'a52b447f-36c8-436f-90e5-86d85173e845', '唐', '["遠樹擁川斷，晴雲抱日流。","（均見《吟窗雜錄》卷三十《古今才婦》）。"]', '["远樹擁川斷，晴云抱日流。","（均见《吟窗杂錄》卷三十《古今才婦》）。"]', '诗', 'shi', '', NULL, '晚眺 鮑君徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e32a0167-27b0-4bbc-9083-0fbcad864550', '寶應初征史朝義過虢州題僧寺壁（題擬）', '寶應初征史朝義過虢州題僧寺壁（題擬）', '78e90648-c287-4e4f-a6f3-58a818b0b0e5', '唐', '["高僧居淨域，客子戀皇宮。","試訪毘耶室，旋（《大典》作「施」）遊方丈中。","禪林吹梵響，忍草散香風。","妙說三元（《大典》作「玄」）義，能談不二宗。","色空雙已滅，內外兩緣同。","識盡無生理，乃覺出凡（《大典》作「梵」，《金文最》作「樊」）籠。","（見光緒二年刊高錦榮纂《靈寶縣志》卷八《藝文》下。","又見《金文最》卷七一許安仁大定十六年撰《御題寺重即唐德宗詩碑》（徐俊告）、《永樂大典》卷一三八二三引《洛陽志》〖張忱石告〗）（按：《永樂大典》引《洛陽志》：「御題寺，寺在靈寶南里。","唐寶應元年，德宗以皇子爲天下兵馬元帥，統兵征史朝義過）（之，題詩壁間。","厥後十七年即位，寺僧玄覺詣長安求寺額，詔以御題名之。","」其後又錄無名氏詩云：「解鞍投宿得禪宮，識破浮生萬境空。","夜靜稍□簷外雨，朝來知是葉間風。","」此詩未詳何代何人所作，姑附此。","清畢沅《中州金石記》卷五：「御題寺唐德宗詩碣，大定十六年立，許安仁記幷書，在御碑寺。","額正書云：『御題寺唐德宗天章碑。","』下爲五律詩一首。","知年月人名者，據黃叔璥《中州金石攷》也。","」今按：《縣志》錄此詩原題作《題御碑寺》，然寺名因德宗此詩而得名，詩題顯爲後人追補。","今重爲擬題。","黃叔璥書未見。","碑記，《縣志》亦未收。","有關史事，兩《唐書》、《通鑑》所記甚詳，不具錄。","）。"]', '["高僧居淨域，客子戀皇宮。","試訪毘耶室，旋（《大典》作「施」）游方丈中。","禪林吹梵响，忍草散香风。","妙说三元（《大典》作「玄」）義，能談不二宗。","色空雙已滅，內外兩緣同。","識尽無生理，乃覺出凡（《大典》作「梵」，《金文最》作「樊」）籠。","（见光緒二年刊高錦榮纂《靈寶縣志》卷八《藝文》下。","又见《金文最》卷七一許安仁大定十六年撰《御題寺重即唐德宗诗碑》（徐俊告）、《永乐大典》卷一三八二三引《洛陽志》〖張忱石告〗）（按：《永乐大典》引《洛陽志》：「御題寺，寺在靈寶南里。","唐寶應元年，德宗以皇子爲天下兵马元帥，統兵征史朝義過）（之，題诗壁间。","厥後十七年即位，寺僧玄覺詣长安求寺額，詔以御題名之。","」其後又錄無名氏诗云：「解鞍投宿得禪宮，識破浮生万境空。","夜静稍□簷外雨，朝来知是葉间风。","」此诗未詳何代何人所作，姑附此。","清畢沅《中州金石記》卷五：「御題寺唐德宗诗碣，大定十六年立，許安仁記幷书，在御碑寺。","額正书云：『御題寺唐德宗天章碑。","』下爲五律诗一首。","知年月人名者，據黄叔璥《中州金石攷》也。","」今按：《縣志》錄此诗原題作《題御碑寺》，然寺名因德宗此诗而得名，诗題显爲後人追補。","今重爲擬題。","黄叔璥书未见。","碑記，《縣志》亦未收。","有关史事，兩《唐书》、《通鑑》所記甚詳，不具錄。","）。"]', '诗', 'shi', '', NULL, '寶應初征史朝義過虢州題僧寺壁（題擬） 德宗皇帝李适 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ac0e1c4-88b1-4786-ac99-ba56a69709cf', '贈何遐', '贈何遐', '52ee5f84-9adc-4c08-841d-99d06eee67aa', '唐', '["腰間寶劍七星文，掌上彎弓掛六鈞。","箭發雲中雙鴈落，始知秦地有將軍。","（見《輿地紀勝》卷一四五《簡州》）（按：《全唐詩》卷三一四收此詩，有缺文，今重錄。","）。"]', '["腰间寶劍七星文，掌上彎弓掛六鈞。","箭發云中雙鴈落，始知秦地有將軍。","（见《輿地紀勝》卷一四五《簡州》）（按：《全唐诗》卷三一四收此诗，有缺文，今重錄。","）。"]', '诗', 'shi', '', NULL, '贈何遐 韋臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0b5cc2f-f6ca-435a-b733-6ff323ea50dd', '靈巖述舊', '靈巖述旧', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["不到靈巖又二年，重來風景尚依然。","層巒迥出青霄外，倦鳥歸飛夕照邊。","坐愛雲林泉石好，行尋煖谷野橋連。","同遊不覺天將晚，暫借僧房一榻眠。","（見嘉靖《略陽縣志》卷六、光緒三十年重刊譚瑀《略陽縣志》卷四）。"]', '["不到靈巖又二年，重来风景尚依然。","層巒迥出青霄外，倦鸟归飞夕照邊。","坐愛云林泉石好，行尋煖谷野橋連。","同游不覺天將晚，暫借僧房一榻眠。","（见嘉靖《略陽縣志》卷六、光緒三十年重刊譚瑀《略陽縣志》卷四）。"]', '诗', 'shi', '', NULL, '靈巖述舊 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab6b212b-6f3c-4df1-a370-5723501ea483', '登汾上閣', '登汾上閣', 'b80535c5-afc8-455d-8621-c52f45487c10', '唐', '["汾樓秋水濶，宛似到閶門。","惆悵江湖思，惟將南客論。","（見《歐陽行周文集》卷九《陪太原鄭行軍中丞登汾上閣中丞詩曰汾樓秋水濶宛似到閶門惆悵江湖思惟將南客論南客即儋也輒書即事上答》）（按：《全唐詩》卷七八三收此詩於鄭中丞名下，今考定爲鄭儋作。","）。"]', '["汾楼秋水濶，宛似到閶门。","惆悵江湖思，惟將南客論。","（见《歐陽行周文集》卷九《陪太原鄭行軍中丞登汾上閣中丞诗曰汾楼秋水濶宛似到閶门惆悵江湖思惟將南客論南客即儋也輒书即事上答》）（按：《全唐诗》卷七八三收此诗於鄭中丞名下，今考定爲鄭儋作。","）。"]', '诗', 'shi', '', NULL, '登汾上閣 鄭儋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e403ec58-d2d0-4405-bf61-00019503e976', '江南春 一', '江南春 一', '2717562e-af42-40c5-bf30-c9df09585c30', '唐', '["江南正月春花早，梅花柳花夾長道。"]', '["江南正月春花早，梅花柳花夾长道。"]', '诗', 'shi', '', NULL, '江南春 一 許稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f904dc01-63de-491e-a253-4ed43051d6b5', '江南春 二', '江南春 二', '2717562e-af42-40c5-bf30-c9df09585c30', '唐', '["江南二月春光半，杏白桃紅香蘂散。"]', '["江南二月春光半，杏白桃紅香蘂散。"]', '诗', 'shi', '', NULL, '江南春 二 許稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c848c7c-12eb-47f9-92da-66aede6fb334', '江南春 三', '江南春 三', '2717562e-af42-40c5-bf30-c9df09585c30', '唐', '["江南三月春光暮，蝴蝶閑飛遶深圃。","（見《吟窗雜錄》卷二九《歷代吟譜》）。"]', '["江南三月春光暮，蝴蝶闲飞遶深圃。","（见《吟窗杂錄》卷二九《歷代吟譜》）。"]', '诗', 'shi', '', NULL, '江南春 三 許稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c419dd67-145c-4df5-aa0c-a2b0243b765f', '龍池（題擬）', '龙池（題擬）', '929e432f-efdf-465c-9231-3585d2f44926', '唐', '["爰有寒泉碧玉泓，天淵千古湛澄清。","（見影天一閣藏《正德青州府志》卷六）。"]', '["爰有寒泉碧玉泓，天淵千古湛澄清。","（见影天一閣藏《正德青州府志》卷六）。"]', '诗', 'shi', '', NULL, '龍池（題擬） 張崇傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a17b9e67-e646-4f2f-8524-33fd876523e9', '遊雲門', '游云门', 'ef1aeae9-6212-4459-87f2-f096f8e14e05', '唐', '["長松落落勝天台，佛殿經牕半嶺開。","郭裏鐘聲山裏去，上方流水下方來。","（見《會稽掇英總集》卷六）。"]', '["长松落落勝天台，佛殿經牕半嶺开。","郭裏鐘声山裏去，上方流水下方来。","（见《會稽掇英總集》卷六）。"]', '诗', 'shi', '', NULL, '遊雲門 崔子向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59b31220-8df4-4d10-9738-b3267f85da80', '寄勸俗兄弟二首 一', '寄勸俗兄弟二首 一', 'aedc6ceb-be35-4d30-ade3-bc8a5c500d39', '唐', '["同氣連枝本自榮，些些言語莫傷情。"]', '["同氣連枝本自榮，些些言語莫傷情。"]', '诗', 'shi', '', NULL, '寄勸俗兄弟二首 一 法照 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23909c3e-2783-4dc6-8d7d-587b24caa7bd', '寄勸俗兄弟二首 二', '寄勸俗兄弟二首 二', 'aedc6ceb-be35-4d30-ade3-bc8a5c500d39', '唐', '["兄弟同居忍便安，莫因毫末起爭端。","眼前生子又兄弟，留與兒孫作樣看。","（見影清光緒抄本張鵬翼修《洋縣志》卷七）。"]', '["兄弟同居忍便安，莫因毫末起爭端。","眼前生子又兄弟，留與兒孫作樣看。","（见影清光緒抄本張鵬翼修《洋縣志》卷七）。"]', '诗', 'shi', '', NULL, '寄勸俗兄弟二首 二 法照 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c1f4880-4438-4ed5-8aca-e26aef5f92be', '示門人頌', '示门人頌', '555475af-bf40-4f91-b352-633235213866', '唐', '["紅螺山子近邊夷，度得之流半是奚。","共語問醻都不會，可憐祇解那斯祁。","（見《五燈會元》卷三）。"]', '["紅螺山子近邊夷，度得之流半是奚。","共語问醻都不會，可怜祇解那斯祁。","（见《五灯會元》卷三）。"]', '诗', 'shi', '', NULL, '示門人頌 紅螺山和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d690fba1-7da0-4bc0-8a73-e5e26c71df33', '湘妃廟', '湘妃廟', 'a6234b1b-a192-473e-98ba-753daf76e535', '唐', '["代變時遷事跡存，見來誰不暗消魂。","上程此日湘江過，依舊修篁有舊痕。","（見《永樂大典》卷五七六九，中華書局影印本第六十冊。","）（按：《永樂大典》署「御史周謂」作。","《周君墓誌銘》云：「拜監察御史，董選補於南方。","南方吏理清而風俗阜，抑君是賴，復命其勞，轉殿中侍御史。","」詩或即渭此次南行時作。","「謂」爲「渭」之誤。","）。"]', '["代变时遷事跡存，见来誰不暗消魂。","上程此日湘江過，依旧修篁有旧痕。","（见《永乐大典》卷五七六九，中华书局影印本第六十冊。","）（按：《永乐大典》署「御史周謂」作。","《周君墓誌銘》云：「拜監察御史，董選補於南方。","南方吏理清而风俗阜，抑君是賴，复命其勞，轉殿中侍御史。","」诗或即渭此次南行时作。","「謂」爲「渭」之誤。","）。"]', '诗', 'shi', '', NULL, '湘妃廟 周渭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a11ce1c-3c17-4e06-ae10-d776d611a750', '', '', 'b06f9048-ef96-4854-ac62-e233c7a29b3a', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 陳詡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0febf41b-c8b5-432c-8d8f-2b6364c49fd6', '新雷', '新雷', 'b06f9048-ef96-4854-ac62-e233c7a29b3a', '唐', '["一聲離碧海，萬里發芽生。","（見《吟窗雜錄》卷十四《詩中旨格》引）。"]', '["一声離碧海，万里發芽生。","（见《吟窗杂錄》卷十四《诗中旨格》引）。"]', '诗', 'shi', '', NULL, '新雷 陳詡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7e522cd-3392-4a9b-a7a8-ec41174ffe06', '紫玉見南山賦附歌', '紫玉见南山賦附歌', 'fd08332f-e359-4c6f-a07d-7847ac26cd20', '唐', '["歸大素兮遠蠻屏，有瑞玉兮見霄嶺。","浮紫氣於雲際，混清輝於水影。","庶南山之不騫，期我皇之惟永。","（見《文苑英華》卷八六）。"]', '["归大素兮远蠻屏，有瑞玉兮见霄嶺。","浮紫氣於云際，混清輝於水影。","庶南山之不騫，期我皇之惟永。","（见《文苑英华》卷八六）。"]', '诗', 'shi', '', NULL, '紫玉見南山賦附歌 李覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60f5d7e4-2bea-4785-8cdd-16e1bf83ae65', '七言宿西臺江寄別南間寺一首', '七言宿西台江寄別南间寺一首', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["曾寄中天第一峰，新辭石室與巖松。","歸舟獨宿寒江上，夜半遙聽雲外鐘。"]', '["曾寄中天第一峰，新辞石室與巖松。","归舟独宿寒江上，夜半遙听云外鐘。"]', '诗', 'shi', '', NULL, '七言宿西臺江寄別南間寺一首 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45dde79a-bada-41dc-8bf4-d79517e57b6a', '五言宿妙喜寺贈遠公一首', '五言宿妙喜寺贈远公一首', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["空學西天客，冥然生意長。","夏高雲納愁近壇涼（此聯抄本原缺二字）。","月半生空處，孤燈宿上方。","欲離夕字想，何法御心王。","。"]', '["空学西天客，冥然生意长。","夏高云納愁近壇涼（此聯抄本原缺二字）。","月半生空处，孤灯宿上方。","欲離夕字想，何法御心王。","。"]', '诗', 'shi', '', NULL, '五言宿妙喜寺贈遠公一首 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5aff7b4-009b-4cb2-bb2f-195917324a45', '五言秋夜南間寺江尚院翫月一首', '五言秋夜南间寺江尚院翫月一首', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["圓月吐青[□]，蕭寥天宇寬。","凝光與空[□]，虛寂兩無端。","露重草衣濕，[□□]竹泉寒。","欲持高潔意，長此共林巒。","（均見日本藏唐抄本《唐詩卷》）。"]', '["圓月吐青[□]，蕭寥天宇寬。","凝光與空[□]，虛寂兩無端。","露重草衣濕，[□□]竹泉寒。","欲持高潔意，长此共林巒。","（均见日本藏唐抄本《唐诗卷》）。"]', '诗', 'shi', '', NULL, '五言秋夜南間寺江尚院翫月一首 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0254bcd5-b7b9-43c3-9a6c-b2a8f8aba5a1', '送最澄闍梨還日本詩', '送最澄闍梨還日本诗', '909951c4-7f8d-4f75-8039-a981a732a929', '唐', '["海東國主尊台教，遣僧來聽《妙法華》。","歸來香風滿衣裓，講堂日出映朝霞。","（見日本比睿山無量院沙門慈本〖一七九四--一八六八〗在文久二年〖一八六二〗撰《天台霞標》第四篇第一卷。","轉錄自《中國哲學史研究》一九八五年第一期刊日本戶崎哲彥撰《留傳日本的有關陸質的史料及若干考證》。","此篇承束景南先生告知。","）（按：慈本於詩下注云：「此詩未知出於何書。","慈本獲之希烈宿稱鈔書中也。","原本海作汝，妙作於，慈本依義改之。","或曰：此詩載在《禪宗日工集》，又改數字載之《本朝高僧傳》某傳也。","」戶崎氏考證此詩又見於《空華老師日用工夫略集》卷一，第二句作「故遣僧來聽《法華》」。","約在公元一三○○年前後即傳爲陸質詩。","但吳顗等九人送最澄詩，皆爲五言律詩，唯此首爲七言古絕，「因此，該詩疑爲後人假托之作，或以意採錄。","」）。"]', '["海东国主尊台教，遣僧来听《妙法华》。","归来香风满衣裓，講堂日出映朝霞。","（见日本比睿山無量院沙门慈本〖一七九四--一八六八〗在文久二年〖一八六二〗撰《天台霞標》第四篇第一卷。","轉錄自《中国哲学史研究》一九八五年第一期刊日本戶崎哲彥撰《留傳日本的有关陸質的史料及若干考證》。","此篇承束景南先生告知。","）（按：慈本於诗下注云：「此诗未知出於何书。","慈本獲之希烈宿稱鈔书中也。","原本海作汝，妙作於，慈本依義改之。","或曰：此诗載在《禪宗日工集》，又改數字載之《本朝高僧傳》某傳也。","」戶崎氏考證此诗又见於《空华老師日用工夫略集》卷一，第二句作「故遣僧来听《法华》」。","約在公元一三○○年前後即傳爲陸質诗。","但吳顗等九人送最澄诗，皆爲五言律诗，唯此首爲七言古絕，「因此，該诗疑爲後人假托之作，或以意採錄。","」）。"]', '诗', 'shi', '', NULL, '送最澄闍梨還日本詩 陸質 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c6c47b1-bd77-4576-a71f-7ee86a3fff63', '答復禮禪師《真妄偈》（題擬）', '答复禮禪師《真妄偈》（題擬）', '6e45e4f3-fd4a-48f0-a86e-7de393edb9f9', '唐', '["迷真妄念生，悟真妄即止。","能迷非常迷，安得長相似。","從來未曾悟，故說妄無始。","知妄本自真，方是恒妙理。","分別心未忘，何由出生死。","（《林間錄》卷上）。"]', '["迷真妄念生，悟真妄即止。","能迷非常迷，安得长相似。","從来未曾悟，故说妄無始。","知妄本自真，方是恒妙理。","分別心未忘，何由出生死。","（《林间錄》卷上）。"]', '诗', 'shi', '', NULL, '答復禮禪師《真妄偈》（題擬） 澄觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aafef9ef-57d1-4cda-ad11-ff3702caaba0', '台州相送詩一首（送最澄上人還日本國敍）', '台州相送诗一首（送最澄上人還日本国敍）', 'a8fa2bda-6139-4556-80a0-e0329fbe7150', '唐', '["重譯越滄溟，來求觀行經。","問鄉朝指日，尋路夜看星。","得法心念喜，乘杯體自寧。","扶桑一念到，風水豈勞形？","（見最澄《顯戒論緣起》卷上，轉錄自張步雲《唐代逸詩輯存》。","參《東南文化》一九九○年六期周琦等錄文。","）。"]', '["重譯越滄溟，来求观行經。","问乡朝指日，尋路夜看星。","得法心念喜，乘杯體自寧。","扶桑一念到，风水豈勞形？","（见最澄《显戒論緣起》卷上，轉錄自張步云《唐代逸诗輯存》。","參《东南文化》一九九○年六期周琦等錄文。","）。"]', '诗', 'shi', '', NULL, '台州相送詩一首（送最澄上人還日本國敍） 吳顗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91843347-96cb-46f3-b526-b1d87e79c103', '送最澄上人還日本國', '送最澄上人還日本国', '61b02ba1-ed9e-44b8-95be-5033350906f8', '唐', '["往歲來求請，新年受法歸。","衆香隨貝葉，一雨潤禪衣。","素舸輕翻浪，征帆背落暉。","遙知到本國，相見道流稀。","（同前）。"]', '["往歲来求請，新年受法归。","衆香隨貝葉，一雨潤禪衣。","素舸轻翻浪，征帆背落暉。","遙知到本国，相见道流稀。","（同前）。"]', '诗', 'shi', '', NULL, '送最澄上人還日本國 孟光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1afc5ff-f303-4d15-870e-99de1f49bafa', '送最澄上人還日本國', '送最澄上人還日本国', '709e54e1-aa5c-4c5d-9848-b764908639a9', '唐', '["萬里求文教，王春愴別離。","未（日本甲本注：「未，應作來。","」）傳不住相，歸集祖行詩。","舉筆論蕃意，焚香問漢儀。","莫言滄海濶，杯度自應知。","（同前）（按：此詩原署「台州臨縣令毛渙」，台州有臨海縣，無臨縣，「臨縣」應即指臨海縣，「臨」下脫去「海」字。","）。"]', '["万里求文教，王春愴別離。","未（日本甲本注：「未，應作来。","」）傳不住相，归集祖行诗。","舉笔論蕃意，焚香问漢儀。","莫言滄海濶，杯度自應知。","（同前）（按：此诗原署「台州臨縣令毛渙」，台州有臨海縣，無臨縣，「臨縣」應即指臨海縣，「臨」下脫去「海」字。","）。"]', '诗', 'shi', '', NULL, '送最澄上人還日本國 毛渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3149cf05-af6f-4c05-9538-255b6bc22784', '送最澄上人還日本國', '送最澄上人還日本国', '692150bb-ba7f-4b19-9e4f-98e923fb3bdb', '唐', '["一葉來自東，路在滄溟中。","遠思日邊國，却逐波上國。","問法言語異，傳經文字同。","何當至本處，定作玄門宗。","（同前）。"]', '["一葉来自东，路在滄溟中。","远思日邊国，却逐波上国。","问法言語異，傳經文字同。","何當至本处，定作玄门宗。","（同前）。"]', '诗', 'shi', '', NULL, '送最澄上人還日本國 崔謩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82e86161-3f75-42f7-86bb-283985a79f0b', '送最澄上人還日本國', '送最澄上人還日本国', '9269051c-b262-4324-8d97-fa1c689f5beb', '唐', '["家與扶桑近，煙波望不窮。","來求貝葉偈，遠過海龍宮。","流水隨歸處，征帆遠向東。","相思渺無畔，應使夢魂通。","（同前）。"]', '["家與扶桑近，煙波望不窮。","来求貝葉偈，远過海龙宮。","流水隨归处，征帆远向东。","相思渺無畔，應使梦魂通。","（同前）。"]', '诗', 'shi', '', NULL, '送最澄上人還日本國 全濟時 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f58e6e7a-1998-4db8-bd97-608e204cc37c', '', '', '6e0a260f-fe90-4e59-95ee-8d7505c0f649', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 行滿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa78827f-c1ae-477d-8930-62fc0883ffc8', '送最澄上人還日本國', '送最澄上人還日本国', '6e0a260f-fe90-4e59-95ee-8d7505c0f649', '唐', '["異域鄉音別，觀心法性同。","來時求半偈，去罷悟真空。","貝葉翻經疏，歸程大海東。","何當到本國，繼踵大師風。","（同前）。"]', '["異域乡音別，观心法性同。","来时求半偈，去罷悟真空。","貝葉翻經疏，归程大海东。","何當到本国，繼踵大師风。","（同前）。"]', '诗', 'shi', '', NULL, '送最澄上人還日本國 行滿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42ea5e37-6239-47a9-bb00-acd22768969a', '送最澄上人還日本國', '送最澄上人還日本国', '2902ebd9-8e06-4a4d-9e9a-34a682a198e0', '唐', '["道高心轉實，德重意唯堅。","不懼洪波遠，中華訪法緣。","精勤同忍可，廣學等彌天。","歸到扶桑國，迎人擁海壖。","（日本甲本注：「壖，應作煙。","」同前）。"]', '["道高心轉實，德重意唯堅。","不懼洪波远，中华訪法緣。","精勤同忍可，廣学等彌天。","归到扶桑国，迎人擁海壖。","（日本甲本注：「壖，應作煙。","」同前）。"]', '诗', 'shi', '', NULL, '送最澄上人還日本國 許蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('868fe0f5-f452-43a0-a612-4de91d3fe24a', '送最澄上人還日本國', '送最澄上人還日本国', '7c942a9f-eb4f-4394-93e2-2225d98ccf37', '唐', '["劫（疑「却」）返扶桑路，還乘舊葉船。","上潮看浸日，翻浪欲陷（日本甲本注：「陷，應作滔。","」）天。","求宿寧逾日（日本甲本注：「日，疑月。","」），雲行詎隔年？","遠將乾竺法，歸去化生緣。","（同前）。"]', '["劫（疑「却」）返扶桑路，還乘旧葉船。","上潮看浸日，翻浪欲陷（日本甲本注：「陷，應作滔。","」）天。","求宿寧逾日（日本甲本注：「日，疑月。","」），云行詎隔年？","远將乾竺法，归去化生緣。","（同前）。"]', '诗', 'shi', '', NULL, '送最澄上人還日本國 幻夢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe41047-6d3a-4949-be25-456ef1a7b286', '送最澄上人還日本國', '送最澄上人還日本国', 'f63d53e8-ae55-45dc-9df4-234e370cd2a9', '唐', '["求獲真乘妙，言歸倍有情。","玄關心地得，鄉思日邊生。","作梵慈雲布，浮杯漲海清。","看看達彼岸，長老散華迎。","（同前）（按：自吳顗以下九人詩，均轉引自張步雲《唐代逸詩輯存》。","）。"]', '["求獲真乘妙，言归倍有情。","玄关心地得，乡思日邊生。","作梵慈云布，浮杯漲海清。","看看達彼岸，长老散华迎。","（同前）（按：自吳顗以下九人诗，均轉引自張步云《唐代逸诗輯存》。","）。"]', '诗', 'shi', '', NULL, '送最澄上人還日本國 林暈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0e3c601-7eb9-417c-a52c-01924612fa16', '扣舷歌 一', '扣舷歌 一', '39fac445-4a95-4ea6-b4f5-b4309108843b', '唐', '["早潮初上海門開，漠漠彤雲雪作堆。","一百六峰都掩盡，不知何處有僧來。"]', '["早潮初上海门开，漠漠彤云雪作堆。","一百六峰都掩尽，不知何处有僧来。"]', '诗', 'shi', '', NULL, '扣舷歌 一 黃子野 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0be3234-43f3-4276-8e3c-3a7a68788a4f', '扣舷歌 二', '扣舷歌 二', '39fac445-4a95-4ea6-b4f5-b4309108843b', '唐', '["幾日江頭醉不醒，滿天風雪臥滄溟。","定知酒伴無尋處，門外松濤坐獨聽。","（《堅瓠壬集》卷一引明徐𤊹《榕陰新檢》。","以上二詩承張靖龍同志錄示。","）。"]', '["幾日江头醉不醒，满天风雪臥滄溟。","定知酒伴無尋处，门外松濤坐独听。","（《堅瓠壬集》卷一引明徐𤊹《榕陰新檢》。","以上二诗承張靖龙同志錄示。","）。"]', '诗', 'shi', '', NULL, '扣舷歌 二 黃子野 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c0c941d-5413-4963-bd28-809c04b6287b', '詩偈 一', '诗偈 一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["楞伽寶山高，四面無行路。","惟有達道人，乘空到彼處。","羅漢若悟空，擲錫騰空去。","緣覺若悟空，醒見三生事。","菩薩若悟空，十方同一處。","諸佛若悟空，妙理空中住。","空理真法身，法身即常住。","佛身祇這是，迷人自不悟。","一切若不空，苦厄從何度。"]', '["楞伽寶山高，四面無行路。","惟有達道人，乘空到彼处。","羅漢若悟空，擲錫腾空去。","緣覺若悟空，醒见三生事。","菩薩若悟空，十方同一处。","諸佛若悟空，妙理空中住。","空理真法身，法身即常住。","佛身祇這是，迷人自不悟。","一切若不空，苦厄從何度。"]', '诗', 'shi', '', NULL, '詩偈 一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('397fc01c-88de-4acc-99b3-8e071769d380', '詩偈 二', '诗偈 二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["大海濶三千，巨深五六萬。","余特七尺軀，入裏飲一頓。","當時枯竭盡，龍王自出現。","大閱經藏門，請爲說一徧。","依如說無法，龍王悟知見。","賣君髻中珠，隱在如來殿。","戴將軍陳頭，賊降不敢戰。","世上有仁人，得永離貧賤。","不貪有爲身，當見如來面。"]', '["大海濶三千，巨深五六万。","余特七尺軀，入裏饮一頓。","當时枯竭尽，龙王自出現。","大閱經藏门，請爲说一徧。","依如说無法，龙王悟知见。","賣君髻中珠，隐在如来殿。","戴將軍陳头，賊降不敢戰。","世上有仁人，得永離貧賤。","不貪有爲身，當见如来面。"]', '诗', 'shi', '', NULL, '詩偈 二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4180447d-6449-43a0-9d27-6d4c42ea11c4', '詩偈 三', '诗偈 三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["日輪漸漸短，光陰一何促。","身如水上沫，命似當風燭。","常須慎四虵，持心捨三毒。","相見論脩道，更莫著婬慾。","婬慾暫時情，長劫入地獄。","縱令得出來，異形人不識。","或時成四足，或是總無足。","可惜好人身，變作醜頭畜。","今是預報知，行行須努力。"]', '["日輪漸漸短，光陰一何促。","身如水上沫，命似當风燭。","常須慎四虵，持心捨三毒。","相见論脩道，更莫著婬慾。","婬慾暫时情，长劫入地獄。","縱令得出来，異形人不識。","或时成四足，或是總無足。","可惜好人身，变作醜头畜。","今是預報知，行行須努力。"]', '诗', 'shi', '', NULL, '詩偈 三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7182685e-6433-4ca7-a29e-81fe5e4209de', '詩偈 四', '诗偈 四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["余家久住山，早已離城市。","草屋有三間，一間長丈二。","一間安葛五，一間塵六四。","余家自內房，終日閒無事。","昨因黑月二十五，初夜飲酒醉，兩人相渾雜，種種調言氣。","余家不奈煩，放火燒屋積。","葛五成灰燼，塵六無一二。","有物蕩淨盡，惟餘空閑地。","自身赤裸裸，體上無衣被。","更莫憂盜賊，逍遙安樂睡。","一等被火燒，同行不同利。"]', '["余家久住山，早已離城市。","草屋有三间，一间长丈二。","一间安葛五，一间塵六四。","余家自內房，終日閒無事。","昨因黑月二十五，初夜饮酒醉，兩人相渾杂，種種調言氣。","余家不奈煩，放火燒屋積。","葛五成灰燼，塵六無一二。","有物蕩淨尽，惟餘空闲地。","自身赤裸裸，體上無衣被。","更莫憂盜賊，逍遙安乐睡。","一等被火燒，同行不同利。"]', '诗', 'shi', '', NULL, '詩偈 四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b5fcad0-b3ab-431c-856a-04adbe05b5d0', '詩偈 五', '诗偈 五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["出家捨煩惱，煩惱還同住。","癡心覓福田，騃意承救度。","十二因緣管，無繇免來去。","依智不依識，依義不依語。","佛心一子地，蠢動皆男女。","平等如虛空，善惡俱無取。","既不造天堂，誰受三塗苦。","有無盡無餘，乘空能自度。","神作如來身，智作如來庫。","涌出波羅蜜，流通正道路。","渾身加身佛，迷人自不悟。"]', '["出家捨煩惱，煩惱還同住。","癡心覓福田，騃意承救度。","十二因緣管，無繇免来去。","依智不依識，依義不依語。","佛心一子地，蠢动皆男女。","平等如虛空，善惡俱無取。","既不造天堂，誰受三塗苦。","有無尽無餘，乘空能自度。","神作如来身，智作如来庫。","涌出波羅蜜，流通正道路。","渾身加身佛，迷人自不悟。"]', '诗', 'shi', '', NULL, '詩偈 五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35954355-314d-4d67-90e3-a614ae682d96', '詩偈 六', '诗偈 六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["八十隨形好，相有三十二。","四諦及三乘，同一無生智。","名爲一合相，非是人同類。","凡夫共佛同，一體無有異。","若論心與境，懸隔不相似。","凡夫惟妄想，攀緣徧天地。","常懷三毒心，損他將自利。","佛心常慈悲，善惡無有二。","蠢動諸衆生，心同一子地。","六識空無生，六塵將布施。","意根成妙覺，七識平等智。"]', '["八十隨形好，相有三十二。","四諦及三乘，同一無生智。","名爲一合相，非是人同類。","凡夫共佛同，一體無有異。","若論心與境，懸隔不相似。","凡夫惟妄想，攀緣徧天地。","常懷三毒心，損他將自利。","佛心常慈悲，善惡無有二。","蠢动諸衆生，心同一子地。","六識空無生，六塵將布施。","意根成妙覺，七識平等智。"]', '诗', 'shi', '', NULL, '詩偈 六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a11b33f-2fa1-4364-826c-fe6e9d5ce188', '詩偈 七', '诗偈 七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["富兒空毛行，貧兒把他物。","被物牽入廛，買賣不得出。","覺暮便歸舍，黃昏黑漆漆。","所求不稱意，合家加啾唧。","自無般若性，乏欠波羅蜜。","把繩入草裏，自繫百年畢。","實是可憐許，冥冥不見日。","富兒雖空手，家中甚富溢。","自有無盡藏，不假外緣物。","周流用不窮，要者從理出。"]', '["富兒空毛行，貧兒把他物。","被物牽入廛，買賣不得出。","覺暮便归舍，黄昏黑漆漆。","所求不稱意，合家加啾唧。","自無般若性，乏欠波羅蜜。","把繩入草裏，自繫百年畢。","實是可怜許，冥冥不见日。","富兒雖空手，家中甚富溢。","自有無尽藏，不假外緣物。","周流用不窮，要者從理出。"]', '诗', 'shi', '', NULL, '詩偈 七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('950eeec2-9fab-4157-a919-92e399629ad3', '詩偈 八', '诗偈 八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["古時不異今，今時不異古。","生事日日滅，有所不能作。","世上乏錢財，守空無貨賂。","理詩日日新，朽宅時時故。","聞船未破漏，愛河須早渡。","出過三江口，逍遙神自悟。","損之又損之，俄成貝多樹。","臨行途路難，無船可相渡。","業老見閻公，沒你分疎處。","若見優曇花，處處無疑慮。"]', '["古时不異今，今时不異古。","生事日日滅，有所不能作。","世上乏錢財，守空無貨賂。","理诗日日新，朽宅时时故。","闻船未破漏，愛河須早渡。","出過三江口，逍遙神自悟。","損之又損之，俄成貝多樹。","臨行途路难，無船可相渡。","業老见閻公，沒你分疎处。","若见優曇花，处处無疑慮。"]', '诗', 'shi', '', NULL, '詩偈 八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('899584ea-3d52-48d6-ae4b-30046377fd3f', '詩偈 九', '诗偈 九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["世上蠢蠢者，相見只論錢，張三五百貫，李四有幾千，趙大折却本，五六太迍邅。","口常談三業，心中慾火然。","癡狼咬肚熱，貪鬼撮頭牽。","有脚復有足，開眼常睡眠。","羅剎同心腹，何日見青天。","青天不可見，地獄結因緣。"]', '["世上蠢蠢者，相见只論錢，張三五百貫，李四有幾千，趙大折却本，五六太迍邅。","口常談三業，心中慾火然。","癡狼咬肚熱，貪鬼撮头牽。","有脚复有足，开眼常睡眠。","羅剎同心腹，何日见青天。","青天不可见，地獄結因緣。"]', '诗', 'shi', '', NULL, '詩偈 九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('946da0ca-bd4b-4d58-bf49-7aeb71491e93', '詩偈 十', '诗偈 十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["故宅守真妻，不好求外色。","真妻生男女，長大同榮辱。","外色有男女，長成愛作賊。","有妻累我來，牽我入牢獄。","我亦早識渠，誘引入吾室。","內外總團圓，同飡一鉢食。","食飽斷虛妄，無相即無福。","若論真寂理，同歸無所得。"]', '["故宅守真妻，不好求外色。","真妻生男女，长大同榮辱。","外色有男女，长成愛作賊。","有妻累我来，牽我入牢獄。","我亦早識渠，誘引入吾室。","內外總團圓，同飡一鉢食。","食飽斷虛妄，無相即無福。","若論真寂理，同归無所得。"]', '诗', 'shi', '', NULL, '詩偈 十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33a92fca-11f3-4a8b-86cf-3f794c087b37', '詩偈 十一', '诗偈 十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["昔日在有時，常被有人欺，一相（《宗鏡錄》卷四八作「總總」）生分別，見聞多是非。","已後入無時（《宗鏡錄》作「後向無中坐」），又被無人欺，一向看心坐，冥冥無所知。","有無俱是執，何處是無爲？有無同一體，諸相盡皆（《宗鏡錄》作「皆盡」）離。","心同虛空故，虛空是我師（《宗鏡錄》作「無所依」）。","若論無相理，惟我（《宗鏡錄》作「有」）父王知。"]', '["昔日在有时，常被有人欺，一相（《宗镜錄》卷四八作「總總」）生分別，见闻多是非。","已後入無时（《宗镜錄》作「後向無中坐」），又被無人欺，一向看心坐，冥冥無所知。","有無俱是執，何处是無爲？有無同一體，諸相尽皆（《宗镜錄》作「皆尽」）離。","心同虛空故，虛空是我師（《宗镜錄》作「無所依」）。","若論無相理，惟我（《宗镜錄》作「有」）父王知。"]', '诗', 'shi', '', NULL, '詩偈 十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ee23cdd-1fa8-43ed-82a1-ab266260ce07', '詩偈 十二', '诗偈 十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["老來無氣力，房舍不能修。","基頹柱根朽，椽梠脫差抽。","泥塗零落盡，四壁空颼颼。","舉頭看梁柱，星星見白頭。","慧雲降法雨，智水沃心流。","家中空豁豁，屋倒亦何憂。","山莊草菴破，余歸大宅遊。","生生不揀處，隨類說無求。"]', '["老来無氣力，房舍不能修。","基頹柱根朽，椽梠脫差抽。","泥塗零落尽，四壁空颼颼。","舉头看梁柱，星星见白头。","慧云降法雨，智水沃心流。","家中空豁豁，屋倒亦何憂。","山莊草菴破，余归大宅游。","生生不揀处，隨類说無求。"]', '诗', 'shi', '', NULL, '詩偈 十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd9397a0-bfe4-437c-a3f3-e9125a6d3812', '詩偈 十三', '诗偈 十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["人有五般花，花蘭（一本云「花爛」）變成香。","氤氳滿故宅，供養本爺娘。","有人見不識，報道十月桑。","外塵一念愛，合成五色囊。","囊中起三柱，柱上有千梁。","梁變成地獄，地獄作天堂。","緣箇一羣賊，自作自消亡。","縱令存草命，何時還故鄉？","文字說定慧，定慧是爺娘。","何不依理智，逐色在他鄉。","早須歸大宅，孝順見爺娘。"]', '["人有五般花，花蘭（一本云「花爛」）变成香。","氤氳满故宅，供養本爺娘。","有人见不識，報道十月桑。","外塵一念愛，合成五色囊。","囊中起三柱，柱上有千梁。","梁变成地獄，地獄作天堂。","緣箇一羣賊，自作自消亡。","縱令存草命，何时還故乡？","文字说定慧，定慧是爺娘。","何不依理智，逐色在他乡。","早須归大宅，孝順见爺娘。"]', '诗', 'shi', '', NULL, '詩偈 十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3407b4bc-9422-4cae-90eb-65ffa6874f7b', '詩偈 十四', '诗偈 十四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["爺娘聞子來，端坐見咍咍。","我所有寶藏，分付鑰匙開。","非論窮子富，舉國免三災。","如意用無盡，更不受胞胎。","逍遙無障礙，終日見如來。","。"]', '["爺娘闻子来，端坐见咍咍。","我所有寶藏，分付鑰匙开。","非論窮子富，舉国免三災。","如意用無尽，更不受胞胎。","逍遙無障礙，終日见如来。","。"]', '诗', 'shi', '', NULL, '詩偈 十四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('568ae776-67df-4abb-8c89-1904aec8390d', '詩偈 十五', '诗偈 十五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["如來愍諸子，平等無高下。","諸子自愚癡，所以難教化。","直心是道場，子心轉姦詐。","遣子淨三業，轉愛論俗話。","遣子內脩真，向外轉尋假。","遣子學無相，捻他有相把。","無諍最第一，論義成相駡。"]', '["如来愍諸子，平等無高下。","諸子自愚癡，所以难教化。","直心是道場，子心轉姦詐。","遣子淨三業，轉愛論俗話。","遣子內脩真，向外轉尋假。","遣子学無相，捻他有相把。","無諍最第一，論義成相駡。"]', '诗', 'shi', '', NULL, '詩偈 十五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3cf7a03-7069-4508-a79f-13ba3935fcb3', '詩偈 十六', '诗偈 十六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["無貪勝布施，無癡勝坐禪。","無瞋勝持戒，無念勝求緣。","盡見（《祖堂集》卷十五作「現」）凡夫事，夜來安樂眠。","寒時向火坐，火本實（《祖堂集》作「寔本」）無烟。","不忌（《祖堂集》作「怕」）黑闇女，不求功德天。","任運生方便，皆同般若船。","若能如是學，功德實無邊。"]', '["無貪勝布施，無癡勝坐禪。","無瞋勝持戒，無念勝求緣。","尽见（《祖堂集》卷十五作「現」）凡夫事，夜来安乐眠。","寒时向火坐，火本實（《祖堂集》作「寔本」）無烟。","不忌（《祖堂集》作「怕」）黑闇女，不求功德天。","任運生方便，皆同般若船。","若能如是学，功德實無邊。"]', '诗', 'shi', '', NULL, '詩偈 十六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a4c8387-a4f9-4657-a29a-0e5014606eb1', '詩偈 十七', '诗偈 十七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["十方同一等，此是真如寺。","裏有無量壽，本來無名字。","凡夫不入理，心緣世上事。","乞錢買瓦木，蓋他虛空地。","却被六賊驅，背却真如智。","終日受艱辛，妄想圖名利。","如此學道人，累劫終不至。"]', '["十方同一等，此是真如寺。","裏有無量壽，本来無名字。","凡夫不入理，心緣世上事。","乞錢買瓦木，蓋他虛空地。","却被六賊驱，背却真如智。","終日受艱辛，妄想圖名利。","如此学道人，累劫終不至。"]', '诗', 'shi', '', NULL, '詩偈 十七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fd77afa-03de-459a-aafb-a2a65aea65f3', '詩偈 十八', '诗偈 十八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["無有報龐大，空空無處坐。","家內空空空，空空無有貨。","日在空裏行，日沒空裏臥。","空坐空吟詩，詩空空相和。","莫怪純用空，空是諸佛座。","世人不別寶，空即是實貨。","若嫌無有空，自是諸佛定。"]', '["無有報龐大，空空無处坐。","家內空空空，空空無有貨。","日在空裏行，日沒空裏臥。","空坐空吟诗，诗空空相和。","莫怪純用空，空是諸佛座。","世人不別寶，空即是實貨。","若嫌無有空，自是諸佛定。"]', '诗', 'shi', '', NULL, '詩偈 十八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddbc240d-a017-46f5-b0d5-4650be8b7743', '詩偈 十九', '诗偈 十九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["有人有所知，有事有是非。","聞道無相理，心執不生疑。","五歲更不長，祇作阿孩兒。","將拳口裏咬，百年不肯離。","假花雖端正，究竟不充飢。","都緣癡孩子，不識是權宜。","如來無相理，有作盡皆非。"]', '["有人有所知，有事有是非。","闻道無相理，心執不生疑。","五歲更不长，祇作阿孩兒。","將拳口裏咬，百年不肯離。","假花雖端正，究竟不充飢。","都緣癡孩子，不識是權宜。","如来無相理，有作尽皆非。"]', '诗', 'shi', '', NULL, '詩偈 十九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c74a4f7-eedb-4e9d-a764-b91566a6233c', '詩偈 二十', '诗偈 二十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["合瞋不須假，合喜不須喜。","喜即婬慾生，瞋即毒蛇起。","毒蛇起猛火，婬慾成貪鬼。","猛火和貪鬼，癡狼咬心底。","妄想如恆沙，煩惱無遮止。","無明黑漆漆，渴來飲鹹水。","終日緣事走，不肯入空理。"]', '["合瞋不須假，合喜不須喜。","喜即婬慾生，瞋即毒蛇起。","毒蛇起猛火，婬慾成貪鬼。","猛火和貪鬼，癡狼咬心底。","妄想如恆沙，煩惱無遮止。","無明黑漆漆，渴来饮鹹水。","終日緣事走，不肯入空理。"]', '诗', 'shi', '', NULL, '詩偈 二十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cffd4a47-f5e1-49a6-89ac-ec51d5e33589', '詩偈 二十一', '诗偈 二十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["我見好畜生，知是嘍羅漢。","枉法取人錢，誇道能計算。","得即渾家用，受苦沒人伴。","有力任他騎，棒鞭脊上楦。","觜上著{金革}頭，口中銜鐵片。","項領被磨穿，鼻孔芒繩絆。","自種還自收，佛也不能斷。"]', '["我见好畜生，知是嘍羅漢。","枉法取人錢，誇道能計算。","得即渾家用，受苦沒人伴。","有力任他騎，棒鞭脊上楦。","觜上著{金革}头，口中銜鐵片。","項領被磨穿，鼻孔芒繩絆。","自種還自收，佛也不能斷。"]', '诗', 'shi', '', NULL, '詩偈 二十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99ea5df9-a8ff-4361-9a0a-1f2c0fed595e', '詩偈 二十二', '诗偈 二十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["癡兒無智慧，自嫌阿爺醜。","阿娘生得身，嫌孃無面首。","拋却親爺孃，外邊逐色走。","六親相將作，尋常不開口。","恆遊十二月，月月飲欲酒。","夜夜不曾醒，醉吐飼猪狗。","如此惡男子，緣事不了手。"]', '["癡兒無智慧，自嫌阿爺醜。","阿娘生得身，嫌孃無面首。","拋却親爺孃，外邊逐色走。","六親相將作，尋常不开口。","恆游十二月，月月饮欲酒。","夜夜不曾醒，醉吐飼猪狗。","如此惡男子，緣事不了手。"]', '诗', 'shi', '', NULL, '詩偈 二十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e372f312-0cfe-4e70-a349-224cfcfd7696', '詩偈 二十三', '诗偈 二十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["余有一寶劍，非是世間鐵。","成來更不磨，晶晶白如雪。","氣衝浮雲散，光照三千徹。","吼作獅子聲，百獸皆腦裂。","外國盡歸降，衆生悉磨滅。","滅已復還生，還生作金鐍。","帶將處處行，樂者即爲說。"]', '["余有一寶劍，非是世间鐵。","成来更不磨，晶晶白如雪。","氣衝浮云散，光照三千徹。","吼作獅子声，百獸皆腦裂。","外国尽归降，衆生悉磨滅。","滅已复還生，還生作金鐍。","带將处处行，乐者即爲说。"]', '诗', 'shi', '', NULL, '詩偈 二十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ba5549-8d1a-4ec1-a9a6-97256fe6c294', '詩偈 二十四', '诗偈 二十四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["知余轉般若，見余轉金剛，合掌恭敬了，不動見空王。","亦勝身命施，亦勝坐天堂，亦勝五臺供，亦勝求西方。","於住而無住，其福不可量。","有爲如夢幻，無相契真常。"]', '["知余轉般若，见余轉金剛，合掌恭敬了，不动见空王。","亦勝身命施，亦勝坐天堂，亦勝五台供，亦勝求西方。","於住而無住，其福不可量。","有爲如梦幻，無相契真常。"]', '诗', 'shi', '', NULL, '詩偈 二十四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afe1ae6b-4552-4872-a661-69cc3a2b3e2d', '詩偈 二十五', '诗偈 二十五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["如來大慈悲，廣演波羅蜜。","了知三界苦，殷勤勸君出。","得之不肯修，寔是頑皮物。","他是已成佛，汝是當成佛。","當成自不成，是誰之過失？","已後累劫苦，莫尤過去佛。"]', '["如来大慈悲，廣演波羅蜜。","了知三界苦，殷勤勸君出。","得之不肯修，寔是頑皮物。","他是已成佛，汝是當成佛。","當成自不成，是誰之過失？","已後累劫苦，莫尤過去佛。"]', '诗', 'shi', '', NULL, '詩偈 二十五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0f06566-7569-4224-a14a-bdc47438a25a', '詩偈 二十六', '诗偈 二十六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["誰家郎君子，開眼造地獄。","枉法取人錢，養那一羣賊。","饒伊家戶大，業成出不得。","除非輪迴滿，換形償他力。","看君騎底驢，總是如此色。","無事被鞭杖，有理說不得。"]', '["誰家郎君子，开眼造地獄。","枉法取人錢，養那一羣賊。","饒伊家戶大，業成出不得。","除非輪迴满，換形償他力。","看君騎底驢，總是如此色。","無事被鞭杖，有理说不得。"]', '诗', 'shi', '', NULL, '詩偈 二十六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5104436-6de6-4cd0-83b3-4e7d68f38e94', '詩偈 二十七', '诗偈 二十七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["愚人打瓮破，求人望錮護。","惡法得錢財，布施擬補處。","物色不相當，此事無煩做。","縱然有少福，那得地獄去。","罪福當頭行，何時相值遇。","自本猶折却，安得有利路。"]', '["愚人打瓮破，求人望錮護。","惡法得錢財，布施擬補处。","物色不相當，此事無煩做。","縱然有少福，那得地獄去。","罪福當头行，何时相值遇。","自本猶折却，安得有利路。"]', '诗', 'shi', '', NULL, '詩偈 二十七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f9d984a-b9a2-4494-9f97-0cb0dca21300', '詩偈 二十八', '诗偈 二十八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["先須持五戒，方始得人身。","有財將布施，身即不窮貧。","若行十善業，聞道得天人。","天人生滅福，來去如車輪。","有爲接梵世，不及一毫真。","更欲談玄妙，慮恐法王瞋。"]', '["先須持五戒，方始得人身。","有財將布施，身即不窮貧。","若行十善業，闻道得天人。","天人生滅福，来去如车輪。","有爲接梵世，不及一毫真。","更欲談玄妙，慮恐法王瞋。"]', '诗', 'shi', '', NULL, '詩偈 二十八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6631753f-ac71-4163-87de-77bd3e596cb7', '詩偈 二十九', '诗偈 二十九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["一皮較一皮，孫子不如兒。","坐禪勝讀經，讀經勝有爲。","尋文不識理，棄母養阿姨。","阿姨是色身，阿孃是法體。","色身是文字，法入無爲理。","文字有生滅，無相宛然爾。"]', '["一皮較一皮，孫子不如兒。","坐禪勝读經，读經勝有爲。","尋文不識理，棄母養阿姨。","阿姨是色身，阿孃是法體。","色身是文字，法入無爲理。","文字有生滅，無相宛然爾。"]', '诗', 'shi', '', NULL, '詩偈 二十九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d166ac5-d6d2-4f7d-bf66-7b7281f5b9e2', '詩偈 三十', '诗偈 三十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["佛教本無妄，句句須論實。","尅己饒益他，俗所謂陰騭。","遮莫是天王，饒君宰相侄。","世間有貴賤，業力還同一。","語汝富貴人，貧兒莫欺屈。","習重業力成，翻覆難得出。"]', '["佛教本無妄，句句須論實。","尅己饒益他，俗所謂陰騭。","遮莫是天王，饒君宰相侄。","世间有貴賤，業力還同一。","語汝富貴人，貧兒莫欺屈。","習重業力成，翻覆难得出。"]', '诗', 'shi', '', NULL, '詩偈 三十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2811d110-7061-4c6e-8cab-0e6f42b8351d', '詩偈 三十一', '诗偈 三十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["自恨己身癡，有事無人知。","橫展兩脚睡，至曉不尋思。","諸佛爲我爺，我是世尊兒。","兒今已長大，替父爲導師。","父子同宅住，寸步不相離。","法身無相貌，世人那得知。"]', '["自恨己身癡，有事無人知。","橫展兩脚睡，至晓不尋思。","諸佛爲我爺，我是世尊兒。","兒今已长大，替父爲導師。","父子同宅住，寸步不相離。","法身無相貌，世人那得知。"]', '诗', 'shi', '', NULL, '詩偈 三十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4181d421-024d-4f92-bfab-7c9a2fffe6be', '詩偈 三十二', '诗偈 三十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["此箇一羣賊，生生欺主人。","即今識汝也，不共汝相親。","你若不伏我，我則處處說。","教人總識汝，遣汝行路絕。","你若能伏我，我亦不分別。","共汝同一身，永離於生滅。"]', '["此箇一羣賊，生生欺主人。","即今識汝也，不共汝相親。","你若不伏我，我則处处说。","教人總識汝，遣汝行路絕。","你若能伏我，我亦不分別。","共汝同一身，永離於生滅。"]', '诗', 'shi', '', NULL, '詩偈 三十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5866bcad-d87f-4aa5-937a-2edb5264d967', '詩偈 三十三', '诗偈 三十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["世人重珍寶，我則不如然。","名聞即知足，富貴心不緣。","唯樂簞瓢飲，無求澡鏡銓。","饑食西山稻，渴飲本源泉。","寒披無相服，熱來松下眠。","知身無究竟，任運了殘年。"]', '["世人重珍寶，我則不如然。","名闻即知足，富貴心不緣。","唯乐簞瓢饮，無求澡镜銓。","饑食西山稻，渴饮本源泉。","寒披無相服，熱来松下眠。","知身無究竟，任運了殘年。"]', '诗', 'shi', '', NULL, '詩偈 三十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bb4c7c9-4258-4a01-8d46-ec86d72176f9', '詩偈 三十四', '诗偈 三十四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["霧重日難出，雲厚月朦朧。","有心求覓佛，晝夜用心功。","見夢言將實，聞真耳却聾。","羣賊當路坐，道理若爲通。","見性若玲瓏，多求說處通。","取他凡聖語，到頭渾是空。"]', '["霧重日难出，云厚月朦朧。","有心求覓佛，晝夜用心功。","见梦言將實，闻真耳却聾。","羣賊當路坐，道理若爲通。","见性若玲瓏，多求说处通。","取他凡聖語，到头渾是空。"]', '诗', 'shi', '', NULL, '詩偈 三十四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dad3ccae-4765-4037-8ce5-3037f345ee8c', '詩偈 三十五', '诗偈 三十五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["云何爲人演，離相說如如，心鏡俱空靜，無實亦無虛。","心通常嘿用，出世入無餘。","梵釋咸恭敬，菩薩亦同居。","語是凡夫語，理合釋迦書。","若能如是學，不枉用功夫。"]', '["云何爲人演，離相说如如，心镜俱空静，無實亦無虛。","心通常嘿用，出世入無餘。","梵釋咸恭敬，菩薩亦同居。","語是凡夫語，理合釋迦书。","若能如是学，不枉用功夫。"]', '诗', 'shi', '', NULL, '詩偈 三十五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa154c97-350a-42cd-a3cc-82c64e470ca7', '詩偈 三十六', '诗偈 三十六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["寅朝飲稀粥，飯後兩束薪，貨得二升米，支我有餘身。","身無飢火逼，安余無相神。","神安佛土淨，內外絕埃塵。","無間說般若，豁達啟關津。","火燒家計盡，全成無事人。"]', '["寅朝饮稀粥，飯後兩束薪，貨得二升米，支我有餘身。","身無飢火逼，安余無相神。","神安佛土淨，內外絕埃塵。","無间说般若，豁達啟关津。","火燒家計尽，全成無事人。"]', '诗', 'shi', '', NULL, '詩偈 三十六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a69d787-54ed-41dc-814d-38a47421df38', '詩偈 三十七', '诗偈 三十七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["圓鏡朗如日，湧出無礙智。","梵語波羅蜜，唐家無量義。","說者說無相，離者離文字。","但說無上道，利他還自利。","若能入理行，不動到如地。","緣事常區區，不如展脚睡。"]', '["圓镜朗如日，湧出無礙智。","梵語波羅蜜，唐家無量義。","说者说無相，離者離文字。","但说無上道，利他還自利。","若能入理行，不动到如地。","緣事常區區，不如展脚睡。"]', '诗', 'shi', '', NULL, '詩偈 三十七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2d68198-68da-4b40-9582-a237ebb721bc', '詩偈 三十八', '诗偈 三十八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["我觀三界有，有人披草舍。","虵鼠同穴住，白日恆如夜。","鳩鴿爲親情，羅剎同心話。","五狗常嘷吠，思之令人怕。","我觀總是幻，虛空名亦假。","放牛喫草菴，三生同一化。"]', '["我观三界有，有人披草舍。","虵鼠同穴住，白日恆如夜。","鳩鴿爲親情，羅剎同心話。","五狗常嘷吠，思之令人怕。","我观總是幻，虛空名亦假。","放牛喫草菴，三生同一化。"]', '诗', 'shi', '', NULL, '詩偈 三十八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24c7a43e-b522-4040-9b7d-60afdd516aa1', '詩偈 三十九', '诗偈 三十九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["如來一真智，徧滿娑婆界。","殷勤說方便，有人自不解。","無處不生心，有處多貪愛。","心王作黑業，教他口懺悔。","口懺心不改，心口相違背。","不服無心藥，病根總不差。","著相求菩提，不免還他債。"]', '["如来一真智，徧满娑婆界。","殷勤说方便，有人自不解。","無处不生心，有处多貪愛。","心王作黑業，教他口懺悔。","口懺心不改，心口相違背。","不服無心藥，病根總不差。","著相求菩提，不免還他債。"]', '诗', 'shi', '', NULL, '詩偈 三十九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cd70c0c-f9c3-41ed-89be-a09f6173050d', '詩偈 四十', '诗偈 四十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["香山有栴檀，寶山無伊蘭。","金山照毛頭，毛頭百億寬。","淨心空室坐，妙德四方安。","空生知內外，相事付阿難。","如能達此理，無處即泥洹。"]', '["香山有栴檀，寶山無伊蘭。","金山照毛头，毛头百億寬。","淨心空室坐，妙德四方安。","空生知內外，相事付阿难。","如能達此理，無处即泥洹。"]', '诗', 'shi', '', NULL, '詩偈 四十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b9a7992-7c2d-44f6-8c71-cfdf782bf973', '詩偈 四十一', '诗偈 四十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["若能相用語，教君一箇訣。","捻取三毒箭，一時總抝折。","田地成四空，五狗牙總缺。","色藴自消亡，六賊俱磨滅。","閻羅成法王，羅剎成菩薩。","勿論己一身，舉國一時悅。"]', '["若能相用語，教君一箇訣。","捻取三毒箭，一时總抝折。","田地成四空，五狗牙總缺。","色藴自消亡，六賊俱磨滅。","閻羅成法王，羅剎成菩薩。","勿論己一身，舉国一时悅。"]', '诗', 'shi', '', NULL, '詩偈 四十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1371323f-a390-420b-aeea-6f7375b27e65', '詩偈 四十二', '诗偈 四十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["達人知是幻，縱損心亦如。","諸天不免難，況復此閻浮。","須尋無上理，莫更苦踟躕。","衣食纔方足，不用積盈餘。","少欲有湼槃，知足非凡夫。","當來無地獄，現在出三塗。"]', '["達人知是幻，縱損心亦如。","諸天不免难，況复此閻浮。","須尋無上理，莫更苦踟躕。","衣食纔方足，不用積盈餘。","少欲有湼槃，知足非凡夫。","當来無地獄，現在出三塗。"]', '诗', 'shi', '', NULL, '詩偈 四十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c676b8-8101-4a09-8f5c-702fe5ad8114', '詩偈 四十三', '诗偈 四十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["外若絕攀緣，歡喜常現前。","本來何所得，吉祥自現形。","空生成長老，燃燈常照明。","彌勒是同學，釋迦是長兄。","神通次第坐，無勞問姓名。","名相有差別，法身同一形。"]', '["外若絕攀緣，歡喜常現前。","本来何所得，吉祥自現形。","空生成长老，燃灯常照明。","彌勒是同学，釋迦是长兄。","神通次第坐，無勞问姓名。","名相有差別，法身同一形。"]', '诗', 'shi', '', NULL, '詩偈 四十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba64eb0a-7f1b-4abf-8f83-1cf18820e157', '詩偈 四十四', '诗偈 四十四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["大乘一等義，本自無遮閉。","凡夫著相求，心生有執滯。","無心爲真宗，空寂爲本體。","無問亦無說，常照勿使廢。","佛子行道已，更莫愁來去。"]', '["大乘一等義，本自無遮閉。","凡夫著相求，心生有執滯。","無心爲真宗，空寂爲本體。","無问亦無说，常照勿使廢。","佛子行道已，更莫愁来去。"]', '诗', 'shi', '', NULL, '詩偈 四十四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f9be6f8-1efd-476b-8f6e-e0d2762df9f6', '詩偈 四十五', '诗偈 四十五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["無念清涼寺，藴空真五臺。","對鏡心無垢，當情心死灰。","妙理於中現，優曇空裏開。","無求真法眼，離相見如來。","若能如是學，不動出三災。"]', '["無念清涼寺，藴空真五台。","对镜心無垢，當情心死灰。","妙理於中現，優曇空裏开。","無求真法眼，離相见如来。","若能如是学，不动出三災。"]', '诗', 'shi', '', NULL, '詩偈 四十五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad16f785-ab02-4e21-af62-be994d49b9e3', '詩偈 四十六', '诗偈 四十六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["常聞阿閦佛，擬向東方討。","今日審思維，不動自然到。","語汝守門奴，何須苦煩燥。","我奏父王知，與汝改名號。","破却有爲功，顯示無爲道。"]', '["常闻阿閦佛，擬向东方討。","今日審思維，不动自然到。","語汝守门奴，何須苦煩燥。","我奏父王知，與汝改名號。","破却有爲功，显示無爲道。"]', '诗', 'shi', '', NULL, '詩偈 四十六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8449f17a-f0a9-4170-b179-b000bb31c2ae', '詩偈 四十七', '诗偈 四十七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["識樂衆生樂，緣繩枉（《宗鏡錄》卷四十作「妄」）走作。","智樂菩薩樂，無繩亦無縛。","若有發心者，直須學無作。","莫道怕落空，得空亦不惡。","見鑛不別（《宗鏡錄》作「識」）金，入鑛（《宗鏡錄》作「爐」）方知錯。"]', '["識乐衆生乐，緣繩枉（《宗镜錄》卷四十作「妄」）走作。","智乐菩薩乐，無繩亦無縛。","若有發心者，直須学無作。","莫道怕落空，得空亦不惡。","见鑛不別（《宗镜錄》作「識」）金，入鑛（《宗镜錄》作「爐」）方知錯。"]', '诗', 'shi', '', NULL, '詩偈 四十七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eda10fad-7d11-4403-910e-79c9f02a3fe1', '詩偈 四十八', '诗偈 四十八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["苦痛役身心，勞神覓官職。","暫得色毛披，拍按作瞋色。","口口打奴兵，聲聲遣拔肋。","聞道送王老，曲亦變成直。","縱令有理道，分疎亦不得。"]', '["苦痛役身心，勞神覓官職。","暫得色毛披，拍按作瞋色。","口口打奴兵，声声遣拔肋。","闻道送王老，曲亦变成直。","縱令有理道，分疎亦不得。"]', '诗', 'shi', '', NULL, '詩偈 四十八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9beb919c-1f3b-4d3a-823c-057c3436a2d4', '詩偈 四十九', '诗偈 四十九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["家長自飲酒，舉家一時醉。","失火燒故宅，運水沃空地。","水火當頭發，三災一時起。","空中鳩鴿舞，騾來助放屁。","因中無好花，結果亦天理。"]', '["家长自饮酒，舉家一时醉。","失火燒故宅，運水沃空地。","水火當头發，三災一时起。","空中鳩鴿舞，騾来助放屁。","因中無好花，結果亦天理。"]', '诗', 'shi', '', NULL, '詩偈 四十九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59c80ca0-a7d1-4891-abdb-39c7fbaa1c71', '詩偈 五十', '诗偈 五十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["學道迷路人，實是可憐許。","被賊妄牽纏，惡緣取次與。","有法遍娑婆，開眼看佛語。","洗舌讀經典，和經弄蛇鼠。","動念三界成，迷失當時路。"]', '["学道迷路人，實是可怜許。","被賊妄牽纏，惡緣取次與。","有法遍娑婆，开眼看佛語。","洗舌读經典，和經弄蛇鼠。","动念三界成，迷失當时路。"]', '诗', 'shi', '', NULL, '詩偈 五十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4753f403-bb60-47ba-91db-d73433571966', '詩偈 五十一', '诗偈 五十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["身現凡夫事，內照自分明。","三千大千界，滿中諸衆生。","剎那造有業，了了總知情。","納安芥子裏，稱爲無相經。","常持人不識，念時無色聲。"]', '["身現凡夫事，內照自分明。","三千大千界，满中諸衆生。","剎那造有業，了了總知情。","納安芥子裏，稱爲無相經。","常持人不識，念时無色声。"]', '诗', 'shi', '', NULL, '詩偈 五十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('219b42b7-afce-4da8-b7a4-3892836bde78', '詩偈 五十二', '诗偈 五十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["學佛作夢事，不須論地獄。","天堂總越却，六識爲僮僕。","心心無所住，處處塵不著。","五道絕人行，無心是極樂。","空裏見優曇，衆生作橋彴。"]', '["学佛作梦事，不須論地獄。","天堂總越却，六識爲僮僕。","心心無所住，处处塵不著。","五道絕人行，無心是極乐。","空裏见優曇，衆生作橋彴。"]', '诗', 'shi', '', NULL, '詩偈 五十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cb8a4fa-bb80-48ba-98bb-4c540fa08102', '詩偈 五十三', '诗偈 五十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["欲得速成佛，祇學無生忍。","非常省心力，當時煩惱盡。","七寶藏門開，智慧無窮盡。","廣演波羅蜜，無心可鄙吝。","祇恐着有人，愚癡自不信。"]', '["欲得速成佛，祇学無生忍。","非常省心力，當时煩惱尽。","七寶藏门开，智慧無窮尽。","廣演波羅蜜，無心可鄙吝。","祇恐着有人，愚癡自不信。"]', '诗', 'shi', '', NULL, '詩偈 五十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c81b32-6f8d-4888-b29e-7a7e9f69c02b', '詩偈 五十四', '诗偈 五十四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["世人皮上黠，心裏沒頭癡。","他貪目前利，焉知已後非。","謾胡欺得漢，誇道手脚遲。","走向見閻老，倒拖研米槌。","恐君不覺悟，今日報君知。"]', '["世人皮上黠，心裏沒头癡。","他貪目前利，焉知已後非。","謾胡欺得漢，誇道手脚遲。","走向见閻老，倒拖研米槌。","恐君不覺悟，今日報君知。"]', '诗', 'shi', '', NULL, '詩偈 五十四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d833482-d3ea-4598-ae1d-52309e82131c', '詩偈 五十五', '诗偈 五十五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["中人樂寂靜，下士好威儀。","菩薩心無礙，同凡凡不知。","佛是無相體，何須有相持。","但令心了事，遮莫外人疑。","如人渴飲水，冷暖心自知。"]', '["中人乐寂静，下士好威儀。","菩薩心無礙，同凡凡不知。","佛是無相體，何須有相持。","但令心了事，遮莫外人疑。","如人渴饮水，冷暖心自知。"]', '诗', 'shi', '', NULL, '詩偈 五十五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd593ced-287f-4939-8ef2-93b5cfc180c0', '詩偈 五十六', '诗偈 五十六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["識若不受塵，心亦不顛狂。","妙智作心師，名爲破有王。","須臾證六度，動用五種香。","此即真極樂，亦是真西方。","釋迦無量壽，同居此道場。"]', '["識若不受塵，心亦不顛狂。","妙智作心師，名爲破有王。","須臾證六度，动用五種香。","此即真極乐，亦是真西方。","釋迦無量壽，同居此道場。"]', '诗', 'shi', '', NULL, '詩偈 五十六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d3d83c1-4e01-4ccc-8ea1-63e1470c2544', '詩偈 五十七', '诗偈 五十七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["俗務不廢作，內秘貪心學。","世上假名聞，超然總莫着。","息念三界空，無求出五濁。","法報皆圓滿，意根成正覺。","若能如此修，輪王亦不博。"]', '["俗務不廢作，內秘貪心学。","世上假名闻，超然總莫着。","息念三界空，無求出五濁。","法報皆圓满，意根成正覺。","若能如此修，輪王亦不博。"]', '诗', 'shi', '', NULL, '詩偈 五十七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1fc0a3a-856a-4ab7-9760-d79131fef1dd', '詩偈 五十八', '诗偈 五十八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["五藴若實有，則合有色形。","五藴若實無，則合無形聲。","祇爲假名字，所以妄來停。","若了名相空，事盡總惺惺。","心王無障礙，擺撥三界行。"]', '["五藴若實有，則合有色形。","五藴若實無，則合無形声。","祇爲假名字，所以妄来停。","若了名相空，事尽總惺惺。","心王無障礙，擺撥三界行。"]', '诗', 'shi', '', NULL, '詩偈 五十八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('495acdfe-378b-45e9-8013-e5cad98f4243', '詩偈 五十九', '诗偈 五十九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["我是凡夫身，樂說真如理。","爲性不慳貪，常行平等施。","凡夫事有爲，佛智超生死。","作佛作凡夫，一切自繇你。"]', '["我是凡夫身，乐说真如理。","爲性不慳貪，常行平等施。","凡夫事有爲，佛智超生死。","作佛作凡夫，一切自繇你。"]', '诗', 'shi', '', NULL, '詩偈 五十九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ff35a58-70ea-4b02-a33e-286aa2b056b9', '詩偈 六十', '诗偈 六十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["耳聞無相理，眼空不受色。","鼻嗅無相香，舌嘗無相食。","身着無相衣，竟隨無相得。","心靜越諸天，神清見彌勒。","十方同一乘，無心記南北。"]', '["耳闻無相理，眼空不受色。","鼻嗅無相香，舌嘗無相食。","身着無相衣，竟隨無相得。","心静越諸天，神清见彌勒。","十方同一乘，無心記南北。"]', '诗', 'shi', '', NULL, '詩偈 六十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b4fee40-25c5-44aa-b552-900f4446616a', '詩偈 六十一', '诗偈 六十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["慈悲說斯法，現疾爲衆生。","純陀獻後供，妙德亦同行。","名相有差別，法身同一形。","化身千萬億，方便立空名。","不須執有法，圓通最大精。"]', '["慈悲说斯法，現疾爲衆生。","純陀獻後供，妙德亦同行。","名相有差別，法身同一形。","化身千万億，方便立空名。","不須執有法，圓通最大精。"]', '诗', 'shi', '', NULL, '詩偈 六十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('823259a5-c1d1-4b24-aa0f-761c1e5a24c5', '詩偈 六十二', '诗偈 六十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["欲得真成佛，無心於萬物。","心如鏡亦如，真智從如出。","定慧等莊嚴，廣演波羅蜜。","流通十方界，諸有不能疾。","報汝學道人，祇麼便成佛。"]', '["欲得真成佛，無心於万物。","心如镜亦如，真智從如出。","定慧等莊嚴，廣演波羅蜜。","流通十方界，諸有不能疾。","報汝学道人，祇麼便成佛。"]', '诗', 'shi', '', NULL, '詩偈 六十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c12507e9-4ceb-4844-be5f-f9dc0b14853d', '詩偈 六十三', '诗偈 六十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["讀（《祖堂集》作「奉」）經須解義，解義始（《宗鏡錄》卷三三作「即」）修行。","若能依義學（《祖堂集》作「了義教」），即入湼槃城。","讀經（前引二書均作「如其」）不解義，多見不如盲。","緣（《宗鏡錄》作「尋」）文廣占地，心中（前引二書均作「牛」）不肯耕。"]', '["读（《祖堂集》作「奉」）經須解義，解義始（《宗镜錄》卷三三作「即」）修行。","若能依義学（《祖堂集》作「了義教」），即入湼槃城。","读經（前引二书均作「如其」）不解義，多见不如盲。","緣（《宗镜錄》作「尋」）文廣占地，心中（前引二书均作「牛」）不肯耕。"]', '诗', 'shi', '', NULL, '詩偈 六十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab0c30b6-db11-4107-8bac-88568b16ab50', '詩偈 六十四', '诗偈 六十四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["有人道不得，是伊心王黑。","不能自了事，埋藏一羣賊。","羣賊多貪癡，緣事說是非。","心王被賊使，劫劫無出期。","見花不識樹，果熟始應知。"]', '["有人道不得，是伊心王黑。","不能自了事，埋藏一羣賊。","羣賊多貪癡，緣事说是非。","心王被賊使，劫劫無出期。","见花不識樹，果熟始應知。"]', '诗', 'shi', '', NULL, '詩偈 六十四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cd4bfea-25ce-4fc8-a14b-299f31ae6f13', '詩偈 六十五', '诗偈 六十五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["君家住聚落，余自居山谷。","山空無有物，聚落百種有。","有者喫飯食，無者空張口。","口空肚亦空，還將空喫有。","有盡物歸空，同體無前後。"]', '["君家住聚落，余自居山谷。","山空無有物，聚落百種有。","有者喫飯食，無者空張口。","口空肚亦空，還將空喫有。","有尽物归空，同體無前後。"]', '诗', 'shi', '', NULL, '詩偈 六十五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73eb8066-aff5-44a3-a4ca-766ffb223f77', '詩偈 六十六', '诗偈 六十六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["諸佛與衆生，元來同一家。","不識親尊長，外面認假爺。","優曇不肯摘，專採葫蘆花。","葫蘆花未落，常被三五枷。","如斯之等類，輪轉劫恆沙。"]', '["諸佛與衆生，元来同一家。","不識親尊长，外面認假爺。","優曇不肯摘，專採葫蘆花。","葫蘆花未落，常被三五枷。","如斯之等類，輪轉劫恆沙。"]', '诗', 'shi', '', NULL, '詩偈 六十六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9205713e-1087-476a-9626-ec799374abd3', '詩偈 六十七', '诗偈 六十七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["余爲田舍翁，世上最貧窮。","家中無一物，啟口說空空。","舊時惡知識，總度作師僧。","和合一處坐，常教聽大乘。","食時與持鉢，惟我一人供。"]', '["余爲田舍翁，世上最貧窮。","家中無一物，啟口说空空。","旧时惡知識，總度作師僧。","和合一处坐，常教听大乘。","食时與持鉢，惟我一人供。"]', '诗', 'shi', '', NULL, '詩偈 六十七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2c7518d-2ab8-4683-82cf-856a1889e7a3', '詩偈 六十八', '诗偈 六十八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["平等無有二，終日同宅住。","世人不了妄，心生外緣取。","取得外相佛，樂却變成苦。","苦即諸法生，大海從何渡。","爲報知音者，好好看道路。"]', '["平等無有二，終日同宅住。","世人不了妄，心生外緣取。","取得外相佛，乐却变成苦。","苦即諸法生，大海從何渡。","爲報知音者，好好看道路。"]', '诗', 'shi', '', NULL, '詩偈 六十八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d4af41b-4e90-4196-b8e2-8c829e9b2ba7', '詩偈 六十九', '诗偈 六十九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["故宅有寶珠，却向田野求。","這箇一羣賊，賺你徒悠悠。","泥上搽粧粉，壁上塗渾油。","愚人見夢事，讚歎道能修。","臘月三十日，元無一物收。","。"]', '["故宅有寶珠，却向田野求。","這箇一羣賊，賺你徒悠悠。","泥上搽粧粉，壁上塗渾油。","愚人见梦事，讚歎道能修。","臘月三十日，元無一物收。","。"]', '诗', 'shi', '', NULL, '詩偈 六十九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd3dd74a-7c96-44c8-9fb7-4705e9ffb005', '詩偈 七十', '诗偈 七十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["山中失却心，任運騰騰語。","語即說空空，空中無虵鼠。","有心波浪起，無心是淨土。","淨土生真佛，佛還傳佛語。","佛能度衆生，衆生是佛母。"]', '["山中失却心，任運腾腾語。","語即说空空，空中無虵鼠。","有心波浪起，無心是淨土。","淨土生真佛，佛還傳佛語。","佛能度衆生，衆生是佛母。"]', '诗', 'shi', '', NULL, '詩偈 七十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c95a4cd0-16e3-4d08-89b1-a09638b4b6a2', '詩偈 七十一', '诗偈 七十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["心王不能了，何不依真智。","一吼百獸伏，盡見無生理。","無生理甚寬，無心無可看。","非內外中間，非生死湼槃。","諸法無住處，遨遊神自安。"]', '["心王不能了，何不依真智。","一吼百獸伏，尽见無生理。","無生理甚寬，無心無可看。","非內外中间，非生死湼槃。","諸法無住处，遨游神自安。"]', '诗', 'shi', '', NULL, '詩偈 七十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('400f0e09-800f-47e3-98f5-0f8dfd4e459f', '詩偈 七十二', '诗偈 七十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["外求非是寶，無念自家珍。","心外求佛法，總是倒行人。","般若名尚假，豈可更依文。","有相皆虛妄，無形實是真。"]', '["外求非是寶，無念自家珍。","心外求佛法，總是倒行人。","般若名尚假，豈可更依文。","有相皆虛妄，無形實是真。"]', '诗', 'shi', '', NULL, '詩偈 七十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('055c8991-9a19-49d4-ae76-38c3b0474da2', '詩偈 七十三', '诗偈 七十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["意根無自性，萬法本來虛。","外塵都不有，三界自然無。","五藴今何在，盡總入無餘。","河沙過去佛，並在一毛如。"]', '["意根無自性，万法本来虛。","外塵都不有，三界自然無。","五藴今何在，尽總入無餘。","河沙過去佛，並在一毛如。"]', '诗', 'shi', '', NULL, '詩偈 七十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b9de435-6d71-4ca1-b8e1-7f95879ef46f', '詩偈 七十四', '诗偈 七十四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["人有一卷經，無相亦（《祖堂集》卷十五作「復」）無名。","無人能（《祖堂集》作「解」）轉讀，有我不能聽。","如能轉讀得，入理契無生。","非論菩薩道，佛亦不勞（《祖堂集》作「要」）成。"]', '["人有一卷經，無相亦（《祖堂集》卷十五作「复」）無名。","無人能（《祖堂集》作「解」）轉读，有我不能听。","如能轉读得，入理契無生。","非論菩薩道，佛亦不勞（《祖堂集》作「要」）成。"]', '诗', 'shi', '', NULL, '詩偈 七十四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f3900c5-d2bd-44e5-92ba-991842d28245', '詩偈 七十五', '诗偈 七十五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["阿爺當殿坐，子向前頭立。","父子同宅住，小魔不敢入。","時開無盡藏，貧者相供給。","得之永不窮，免得生憂悒。"]', '["阿爺當殿坐，子向前头立。","父子同宅住，小魔不敢入。","时开無尽藏，貧者相供給。","得之永不窮，免得生憂悒。"]', '诗', 'shi', '', NULL, '詩偈 七十五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87e108e1-9e77-4522-ac09-e8de83d37174', '詩偈 七十六', '诗偈 七十六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["欲得真醍醐，三毒須去除。","嗅無酥酪氣，自見如意珠。","劫火燒不然，泛海浪中浮。","昔日強索者，今日作他奴。"]', '["欲得真醍醐，三毒須去除。","嗅無酥酪氣，自见如意珠。","劫火燒不然，泛海浪中浮。","昔日強索者，今日作他奴。"]', '诗', 'shi', '', NULL, '詩偈 七十六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac22fef-e31f-4179-9bd2-1fb3bb6aa3da', '詩偈 七十七', '诗偈 七十七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["報汝尋真理，偷生佯不聞。","及其身命卒，心口便紛紜。","我命不能與，將錢別僱人。","爲讀如來教，救護我精神。","。"]', '["報汝尋真理，偷生佯不闻。","及其身命卒，心口便紛紜。","我命不能與，將錢別僱人。","爲读如来教，救護我精神。","。"]', '诗', 'shi', '', NULL, '詩偈 七十七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d919a18-abb9-4e18-a883-96a261c30f38', '詩偈 七十八', '诗偈 七十八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["城內數萬戶，不奈我恆一。","時時師子吼，禽獸俱皆卒。","教作羅睺羅，無蹤持戒律。","但知入理坐，日頭骨咄出。"]', '["城內數万戶，不奈我恆一。","时时師子吼，禽獸俱皆卒。","教作羅睺羅，無蹤持戒律。","但知入理坐，日头骨咄出。"]', '诗', 'shi', '', NULL, '詩偈 七十八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb174e31-7c54-42b0-a655-504d68495766', '詩偈 七十九', '诗偈 七十九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["衆生多品類，諸佛祇一般。","庶人見天子，知隔幾重關。","若有過人策，欲見亦不難。","策中契聖理，坐取國家官。"]', '["衆生多品類，諸佛祇一般。","庶人见天子，知隔幾重关。","若有過人策，欲见亦不难。","策中契聖理，坐取国家官。"]', '诗', 'shi', '', NULL, '詩偈 七十九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69d3d8ca-0a20-40f2-a1eb-a92747a6ddff', '詩偈 八十', '诗偈 八十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["智度本來如，衆生病盡除。","又度作護法，一切入無餘。","過去恆沙佛，皆同此一途。","如能達此理，凡夫非凡夫。"]', '["智度本来如，衆生病尽除。","又度作護法，一切入無餘。","過去恆沙佛，皆同此一途。","如能達此理，凡夫非凡夫。"]', '诗', 'shi', '', NULL, '詩偈 八十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9206b51f-871e-48ae-8526-a05b7bf3cb02', '詩偈 八十一', '诗偈 八十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["四大本無情，清虛無色聲。","達人悟空理，知法本無生。","諸佛常現前，妙德亦同行。","無無無障礙，心牛不肯耕。"]', '["四大本無情，清虛無色声。","達人悟空理，知法本無生。","諸佛常現前，妙德亦同行。","無無無障礙，心牛不肯耕。"]', '诗', 'shi', '', NULL, '詩偈 八十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17fb9fe5-d195-4c8d-a026-54b724a0dbbf', '詩偈 八十二', '诗偈 八十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["塵六門前喚，無情呼不入。","二彼總空空，自然唇不濕。","從此絕因緣，葛五隨緣出。","惟有空寂舍，圓八同金七。"]', '["塵六门前喚，無情呼不入。","二彼總空空，自然唇不濕。","從此絕因緣，葛五隨緣出。","惟有空寂舍，圓八同金七。"]', '诗', 'shi', '', NULL, '詩偈 八十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea172efb-05c1-4a03-9984-c449785fb183', '詩偈 八十三', '诗偈 八十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["入理如箭射，尋文轉相背。","直道不肯行，識路成迷退。","心王不了事，公臣生執礙。","爲此一羣賊，生死如踏碓。"]', '["入理如箭射，尋文轉相背。","直道不肯行，識路成迷退。","心王不了事，公臣生執礙。","爲此一羣賊，生死如踏碓。"]', '诗', 'shi', '', NULL, '詩偈 八十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('104a2a78-76ca-4878-b39f-beeafa2ce492', '詩偈 八十四', '诗偈 八十四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["覺他欲打你，着脚即須抽。","已後再相見，他羞我不羞。","忍辱第一道，歷劫無冤讎。","此是無生縣，不屬湼槃洲。"]', '["覺他欲打你，着脚即須抽。","已後再相见，他羞我不羞。","忍辱第一道，歷劫無冤讎。","此是無生縣，不屬湼槃洲。"]', '诗', 'shi', '', NULL, '詩偈 八十四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6aaf393-ab8c-4500-8624-07f8f5e3771f', '詩偈 八十五', '诗偈 八十五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["駡他無便宜，在應却得穩。","無瞋神自安，駡他還自損。","忍得有法利，駡他還折本。","瞋喜同一如，循世不悶悶。","。"]', '["駡他無便宜，在應却得穩。","無瞋神自安，駡他還自損。","忍得有法利，駡他還折本。","瞋喜同一如，循世不悶悶。","。"]', '诗', 'shi', '', NULL, '詩偈 八十五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1da4492f-4dd7-45c8-adca-6a69c26b0f63', '詩偈 八十六', '诗偈 八十六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["識業人稀少，迷途者衆多。","苦中生樂想，無喜強絃歌。","不飲尋常醉，昏昏溺愛河。","含笑造殃咎，後苦莫由他。"]', '["識業人稀少，迷途者衆多。","苦中生乐想，無喜強絃歌。","不饮尋常醉，昏昏溺愛河。","含笑造殃咎，後苦莫由他。"]', '诗', 'shi', '', NULL, '詩偈 八十六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b8ec10a-ab8c-4c1e-890f-4a074bf51305', '詩偈 八十七', '诗偈 八十七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["耳聞他駡詈，心知口莫對。","惡亦不須嫌，好亦不須愛。","豁達無關津，虛空無罣礙。","此真不動物，亦名觀自在。"]', '["耳闻他駡詈，心知口莫对。","惡亦不須嫌，好亦不須愛。","豁達無关津，虛空無罣礙。","此真不动物，亦名观自在。"]', '诗', 'shi', '', NULL, '詩偈 八十七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50a7f74f-1e82-40da-973a-1fb9b868453c', '詩偈 八十八', '诗偈 八十八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["仰手是天堂，覆手是地獄。","地獄與天堂，我心都不屬。","化城猶不止，豈況諸天福。","一切都不求，曠然無所得。"]', '["仰手是天堂，覆手是地獄。","地獄與天堂，我心都不屬。","化城猶不止，豈況諸天福。","一切都不求，曠然無所得。"]', '诗', 'shi', '', NULL, '詩偈 八十八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a49f16f-d299-4615-a733-cbff588fe117', '詩偈 八十九', '诗偈 八十九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["佛有一等慈，有人心不知。","一切皆平等，貧富總憐伊。","富者你莫貪，貧者你莫癡。","無貪心自靜，無癡意莫思。"]', '["佛有一等慈，有人心不知。","一切皆平等，貧富總怜伊。","富者你莫貪，貧者你莫癡。","無貪心自静，無癡意莫思。"]', '诗', 'shi', '', NULL, '詩偈 八十九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b473d4c-73c1-4656-879b-080ce3a3aad5', '詩偈 九十', '诗偈 九十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["白衣不執相，真理從空生。","祇爲心無礙，智慧出縱橫。","唯論師子吼。","不許野干鳴。","菩提稱最妙，猶呵是假名。"]', '["白衣不執相，真理從空生。","祇爲心無礙，智慧出縱橫。","唯論師子吼。","不許野干鳴。","菩提稱最妙，猶呵是假名。"]', '诗', 'shi', '', NULL, '詩偈 九十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a0472fe-d8e7-4441-8ae6-f82c521913e1', '詩偈 九十一', '诗偈 九十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["從根誅則絕，從根修則滅。","若能雙株斷，三乘盡超越。","此非凡夫言，妙吉分明說。","如來所療治，一差不復發。"]', '["從根誅則絕，從根修則滅。","若能雙株斷，三乘尽超越。","此非凡夫言，妙吉分明说。","如来所療治，一差不复發。"]', '诗', 'shi', '', NULL, '詩偈 九十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d108e6f-ec8e-48a2-94d1-2b622bf288c2', '詩偈 九十二', '诗偈 九十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["久種善根深，同塵塵不侵。","非關塵不染，自是我無心。","無心心不起，超三越十地。","究竟真如果，到頭祇箇是。"]', '["久種善根深，同塵塵不侵。","非关塵不染，自是我無心。","無心心不起，超三越十地。","究竟真如果，到头祇箇是。"]', '诗', 'shi', '', NULL, '詩偈 九十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49331de3-b518-472b-948e-5c369616169c', '詩偈 九十三', '诗偈 九十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["凡夫智量狹，妄說有難易。","離相如虛空，盡契諸佛智。","戒相如虛空，迷人自作持。","病根不肯拔，執是弄花枝。","。"]', '["凡夫智量狹，妄说有难易。","離相如虛空，尽契諸佛智。","戒相如虛空，迷人自作持。","病根不肯拔，執是弄花枝。","。"]', '诗', 'shi', '', NULL, '詩偈 九十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91dbb533-2b40-4bf3-abaf-7e61d885fea9', '詩偈 九十四', '诗偈 九十四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["牽牛駕空車，共入無爲宅。","無爲宅甚寬，衆生却嫌窄。","十方同一空，何曾有間隔。","有法入不得，無心是度厄。"]', '["牽牛駕空车，共入無爲宅。","無爲宅甚寬，衆生却嫌窄。","十方同一空，何曾有间隔。","有法入不得，無心是度厄。"]', '诗', 'shi', '', NULL, '詩偈 九十四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8868536-0a31-4c54-aaae-fc3aceec7cbc', '詩偈 九十五', '诗偈 九十五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["世間最上事，唯有修道強。","若悟無生理，三界自消亡。","藴空妙德現，無念是清涼。","此即迷陀土，何處覓西方。"]', '["世间最上事，唯有修道強。","若悟無生理，三界自消亡。","藴空妙德現，無念是清涼。","此即迷陀土，何处覓西方。"]', '诗', 'shi', '', NULL, '詩偈 九十五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c647114f-f9b4-48af-bbd6-2fb2a47149c6', '詩偈 九十六', '诗偈 九十六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["寶珠內衣裏，繫來無量時。","遇六惡知識，又常假慈悲。","牽我飲欲酒，醉臥都不知。","情盡酒復醒，自見本道師。"]', '["寶珠內衣裏，繫来無量时。","遇六惡知識，又常假慈悲。","牽我饮欲酒，醉臥都不知。","情尽酒复醒，自见本道師。"]', '诗', 'shi', '', NULL, '詩偈 九十六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c23beef4-0279-4941-a2ad-4d7a285f3f85', '詩偈 九十七', '诗偈 九十七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["世人重珍寶（《宗鏡錄》卷十五作「但重金」），我貴（《宗鏡錄》作「愛」）剎那靜。","金多亂人心，靜見真如性。","性空法亦空（《宗鏡錄》作「性通法亦通」），十八絕（《宗鏡錄》作「斷」）行蹤。","但自心無礙。","何愁神（《宗鏡錄》作「聲」）不通。","（《法藏碎金錄》卷四、卷五錄前四句）。"]', '["世人重珍寶（《宗镜錄》卷十五作「但重金」），我貴（《宗镜錄》作「愛」）剎那静。","金多亂人心，静见真如性。","性空法亦空（《宗镜錄》作「性通法亦通」），十八絕（《宗镜錄》作「斷」）行蹤。","但自心無礙。","何愁神（《宗镜錄》作「声」）不通。","（《法藏碎金錄》卷四、卷五錄前四句）。"]', '诗', 'shi', '', NULL, '詩偈 九十七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d1c4e2f-4b57-49f2-8d74-a8eafca96810', '詩偈 九十八', '诗偈 九十八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["端坐求如法，如法轉相違。","拋法無心取，始自却來歸。","無求出三界，有念則成癡。","求佛覓解脫，不是丈夫兒。"]', '["端坐求如法，如法轉相違。","拋法無心取，始自却来归。","無求出三界，有念則成癡。","求佛覓解脫，不是丈夫兒。"]', '诗', 'shi', '', NULL, '詩偈 九十八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a3d7319-1f7c-46b9-a75d-5db7a9f466af', '詩偈 九十九', '诗偈 九十九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["惡心滿三界，口即念彌陀。","心口相違背，羣賊轉轉多。","一塵起萬境，倐忽徧婆娑。","色聲求（《宗鏡錄》卷十五作「取」）佛道，結果盡成魔。"]', '["惡心满三界，口即念彌陀。","心口相違背，羣賊轉轉多。","一塵起万境，倐忽徧婆娑。","色声求（《宗镜錄》卷十五作「取」）佛道，結果尽成魔。"]', '诗', 'shi', '', NULL, '詩偈 九十九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('601592b7-4d7b-4b26-bef9-553569149bed', '詩偈 一○○', '诗偈 一○○', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["佛亦不離心，心亦不離佛。","心寂即菩提，心然即有物。","物即變成魔，無即無諸佛。","若能如是用，十八從何出。"]', '["佛亦不離心，心亦不離佛。","心寂即菩提，心然即有物。","物即变成魔，無即無諸佛。","若能如是用，十八從何出。"]', '诗', 'shi', '', NULL, '詩偈 一○○ 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaa08c03-450b-42f5-8bea-6d86ff6cb892', '詩偈 一○一', '诗偈 一○一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["羊車誘下愚，鹿車載中夫。","大乘爲上士，鵬巢鶴不居。","鷦鷯住蚊睫，居士咄盲驢。","若論質利帝，畢竟一乘無。"]', '["羊车誘下愚，鹿车載中夫。","大乘爲上士，鵬巢鹤不居。","鷦鷯住蚊睫，居士咄盲驢。","若論質利帝，畢竟一乘無。"]', '诗', 'shi', '', NULL, '詩偈 一○一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('797bc41e-8cf4-47a4-9711-1edec2401bf9', '詩偈 一○二', '诗偈 一○二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["有（《祖堂集》卷十五作「世」）人嫌龐老，龐老不嫌他（《祖庭事苑》卷二作「它」）。","開門待知識，知識不來過。","心如具三學，塵識不相和（《祖堂集》無此二句）。","一丸療萬（《祖堂集》作「百」）病，不假藥方多。"]', '["有（《祖堂集》卷十五作「世」）人嫌龐老，龐老不嫌他（《祖庭事苑》卷二作「它」）。","开门待知識，知識不来過。","心如具三学，塵識不相和（《祖堂集》無此二句）。","一丸療万（《祖堂集》作「百」）病，不假藥方多。"]', '诗', 'shi', '', NULL, '詩偈 一○二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('003da74c-847d-4369-9df6-959a50e4ad29', '詩偈 一○三', '诗偈 一○三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["淼淼長江水，周而還復始。","昏昏三界人，輪迴亦如此。","輪迴改形貌，長江色不異。","改貌勞神識，終須到佛地。"]', '["淼淼长江水，周而還复始。","昏昏三界人，輪迴亦如此。","輪迴改形貌，长江色不異。","改貌勞神識，終須到佛地。"]', '诗', 'shi', '', NULL, '詩偈 一○三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f49b4dc6-44fe-4857-9fba-2766e107b8da', '詩偈 一○四', '诗偈 一○四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["睡來展脚睡，悟理起題詩。","詩中無別意，唯勸破貪癡。","貪瞋癡若盡，便是世尊兒。","無煩問師匠，心王應自知。"]', '["睡来展脚睡，悟理起題诗。","诗中無別意，唯勸破貪癡。","貪瞋癡若尽，便是世尊兒。","無煩问師匠，心王應自知。"]', '诗', 'shi', '', NULL, '詩偈 一○四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9b6153f-d7c7-45ce-8337-bdc54e3a8792', '詩偈 一○五', '诗偈 一○五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["世人重名利，余心總不然。","束薪貨升米，清水鐵鐺煎。","覺熟捻鐺下，將身近畔邊。","時時拋入口，腹飽肚無言。"]', '["世人重名利，余心總不然。","束薪貨升米，清水鐵鐺煎。","覺熟捻鐺下，將身近畔邊。","时时拋入口，腹飽肚無言。"]', '诗', 'shi', '', NULL, '詩偈 一○五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcc95438-9507-4d1b-988f-179a1af3b570', '詩偈 一○六', '诗偈 一○六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["行學非真道，徒勞神與軀。","千里尋月影（《宗鏡錄》卷四一作「千生尋水月」），終是枉工夫。","不悟緣聲色，當今學者疎。","但看起滅處，此箇是真如。"]', '["行学非真道，徒勞神與軀。","千里尋月影（《宗镜錄》卷四一作「千生尋水月」），終是枉工夫。","不悟緣声色，當今学者疎。","但看起滅处，此箇是真如。"]', '诗', 'shi', '', NULL, '詩偈 一○六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1380ffc-6db3-45f7-bfef-02de716aaf0f', '詩偈 一○七', '诗偈 一○七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["教君殺賊法，不用苦多方。","慧劍當心刺，心亡法亦亡。","心亡極樂國，法亡即西方。","賊爲象馬用，神自作空王。"]', '["教君殺賊法，不用苦多方。","慧劍當心刺，心亡法亦亡。","心亡極乐国，法亡即西方。","賊爲象马用，神自作空王。"]', '诗', 'shi', '', NULL, '詩偈 一○七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1771a49-7401-4c43-8f59-ab233981ebb6', '詩偈 一○八', '诗偈 一○八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["不用苦多聞，看他彼上人。","百憶及日用，元在一毛塵（《宗鏡錄》卷十八作「纂在一毛鱗」）。","心但寂無相，即出無明津。","若能如是學，幾許省精神。"]', '["不用苦多闻，看他彼上人。","百憶及日用，元在一毛塵（《宗镜錄》卷十八作「纂在一毛鱗」）。","心但寂無相，即出無明津。","若能如是学，幾許省精神。"]', '诗', 'shi', '', NULL, '詩偈 一○八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fa3b36d-0e03-4cd1-981f-b32dcd9bad97', '詩偈 一○九', '诗偈 一○九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["慚愧好心王，生在蓮華堂。","恆持般若劍，終日帶浮囊。","常懷第一義，外國賴恩光。","五百長者子，相隨歸故鄉。"]', '["慚愧好心王，生在蓮华堂。","恆持般若劍，終日带浮囊。","常懷第一義，外国賴恩光。","五百长者子，相隨归故乡。"]', '诗', 'shi', '', NULL, '詩偈 一○九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d39522b1-1887-43cf-a3e0-9b06131dfb43', '詩偈 一一○', '诗偈 一一○', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["慚愧好意根，無自亦無他。","無自身無垢，無他塵不加。","常居清靜地，知有不能過。","舊時惡知識，總見阿彌陀。"]', '["慚愧好意根，無自亦無他。","無自身無垢，無他塵不加。","常居清静地，知有不能過。","旧时惡知識，總见阿彌陀。"]', '诗', 'shi', '', NULL, '詩偈 一一○ 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('278baac5-5978-4af0-9b0b-791ef42ddf3a', '詩偈 一一一', '诗偈 一一一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["慚愧好舌根，常開大道門。","世間三有事，實是不能論。","相逢唯說道，更莫敍寒溫。","了知世相假，俗理也徒煩。"]', '["慚愧好舌根，常开大道门。","世间三有事，實是不能論。","相逢唯说道，更莫敍寒溫。","了知世相假，俗理也徒煩。"]', '诗', 'shi', '', NULL, '詩偈 一一一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45a8e9e7-ea51-4ae1-b3cc-76fbeeb33506', '詩偈 一一二', '诗偈 一一二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["慚愧一雙耳，常思解脫聲。","若論俗語話，實是不能聽。","聞財耳不納，聞色心不生。","不受有無語，何慮不惺惺。"]', '["慚愧一雙耳，常思解脫声。","若論俗語話，實是不能听。","闻財耳不納，闻色心不生。","不受有無語，何慮不惺惺。"]', '诗', 'shi', '', NULL, '詩偈 一一二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcc34ac0-7396-407a-95e9-8e761872e7bb', '詩偈 一一三', '诗偈 一一三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["慚愧一雙眼，曾見數般人。","端正亦不愛，醜陋亦不瞋，當頭異國色，何須妄起塵。","低頭自形相，都無一處真。","身心如幻化，滿眼沒怨親。"]', '["慚愧一雙眼，曾见數般人。","端正亦不愛，醜陋亦不瞋，當头異国色，何須妄起塵。","低头自形相，都無一处真。","身心如幻化，满眼沒怨親。"]', '诗', 'shi', '', NULL, '詩偈 一一三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8908c7cd-3959-40b7-b480-1c22276c023d', '詩偈 一一四', '诗偈 一一四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["慚愧一軀身，梵號波羅柰。","被賊一羣使，尋常不自在。","亦名爲枯井，亦名爲韛袋。","亦名朽故宅，亦名幻三昧。","佛駡作死屍，乘屍渡大海。","大海元無水，死屍非是船。","熟看世上事，總是假因緣。","若了身心相，空裏任橫眠。","具此六慚愧，實是不求天。","（以上一百十四首均見咸豐元年刊于頔編《龐居士語錄》卷中）。"]', '["慚愧一軀身，梵號波羅柰。","被賊一羣使，尋常不自在。","亦名爲枯井，亦名爲韛袋。","亦名朽故宅，亦名幻三昧。","佛駡作死屍，乘屍渡大海。","大海元無水，死屍非是船。","熟看世上事，總是假因緣。","若了身心相，空裏任橫眠。","具此六慚愧，實是不求天。","（以上一百十四首均见咸豐元年刊于頔編《龐居士語錄》卷中）。"]', '诗', 'shi', '', NULL, '詩偈 一一四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('366aad62-d63f-4f40-b5ce-4334ddcc536f', '詩偈 一', '诗偈 一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["一時復一時，步步向前移。","無常有限分，早晚即不知。","古人一交語，預辦沒貧兒。","聞小須修道，莫待衰老時。","邂逅符到來，賺你更無疑。","勸君不肯聽，三塗真可悲。"]', '["一时复一时，步步向前移。","無常有限分，早晚即不知。","古人一交語，預辦沒貧兒。","闻小須修道，莫待衰老时。","邂逅符到来，賺你更無疑。","勸君不肯听，三塗真可悲。"]', '诗', 'shi', '', NULL, '詩偈 一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d373ed45-0516-428c-9e07-684c68e3a3ae', '詩偈 二', '诗偈 二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["一日復一日，百年漸漸畢。","急急除妄想，無念成真佛。","更莫苦攀緣，窺他世上物。","忽然無常至，累劫出不得。"]', '["一日复一日，百年漸漸畢。","急急除妄想，無念成真佛。","更莫苦攀緣，窺他世上物。","忽然無常至，累劫出不得。"]', '诗', 'shi', '', NULL, '詩偈 二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b483e2fe-1768-4ebf-8a76-b5e8e8de8a07', '詩偈 三', '诗偈 三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["一宿復一宿，光陰漸漸促。","報你心王道，依智莫依識。","依智見真佛，依識入地獄。","若淪六趣中，受苦無時足。"]', '["一宿复一宿，光陰漸漸促。","報你心王道，依智莫依識。","依智见真佛，依識入地獄。","若淪六趣中，受苦無时足。"]', '诗', 'shi', '', NULL, '詩偈 三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('424917aa-3cd2-4ecb-afbe-2e99fc89b821', '詩偈 四', '诗偈 四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["一年復一年，務在且遷延。","皮皺緣肉減，髮白髓枯乾。","毛孔通風過，骨消椽梠寬。","水微不耐熱，火少不耐寒。","幻身如聚沫，四大亦非堅。","更被癡狼使，無明曉夜煎。","惟知念水草，心神被物纏。","云何不懺悔，便道捨財錢。","外頭遮曲語，望得免前愆。","地獄應無事，準擬得生天。","世間有這屬，冥道不如然。","除非不作業，當拔罪根源。","根空塵不實，內外絕因緣。","積罪如山岳，慧火一時燃。","須臾變灰燼，永劫更無煙。","。"]', '["一年复一年，務在且遷延。","皮皺緣肉減，髮白髓枯乾。","毛孔通风過，骨消椽梠寬。","水微不耐熱，火少不耐寒。","幻身如聚沫，四大亦非堅。","更被癡狼使，無明晓夜煎。","惟知念水草，心神被物纏。","云何不懺悔，便道捨財錢。","外头遮曲語，望得免前愆。","地獄應無事，準擬得生天。","世间有這屬，冥道不如然。","除非不作業，當拔罪根源。","根空塵不實，內外絕因緣。","積罪如山岳，慧火一时燃。","須臾变灰燼，永劫更無煙。","。"]', '诗', 'shi', '', NULL, '詩偈 四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2fe22e2-6d88-4f00-9900-c1c77edfa8d2', '詩偈 五', '诗偈 五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["迷時三界有，悟即出囂纏。","心無六入迹，清淨達本源。","地獄成淨土，招手別諸天。","報語三塗宅，共你更無緣。","非論早與晚，悟理即無邊。"]', '["迷时三界有，悟即出囂纏。","心無六入迹，清淨達本源。","地獄成淨土，招手別諸天。","報語三塗宅，共你更無緣。","非論早與晚，悟理即無邊。"]', '诗', 'shi', '', NULL, '詩偈 五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e050389b-8222-4a30-8296-70c92908073e', '詩偈 六', '诗偈 六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["心如即是坐，境如即是禪。","如如都不動，大道無中邊。","若能如是達，所謂火中蓮。"]', '["心如即是坐，境如即是禪。","如如都不动，大道無中邊。","若能如是達，所謂火中蓮。"]', '诗', 'shi', '', NULL, '詩偈 六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1d6d9b4-a023-4c83-916a-d296a64047d4', '詩偈 七', '诗偈 七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["無求乃法眼，有念却成魔。","無求復無念，即是阿彌陀。","真如共菩薩，總祇較無多。"]', '["無求乃法眼，有念却成魔。","無求复無念，即是阿彌陀。","真如共菩薩，總祇較無多。"]', '诗', 'shi', '', NULL, '詩偈 七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31d67755-44db-4858-84b2-cd2d4db10094', '詩偈 八', '诗偈 八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["鍊盡三山鐵，鎔銷五嶽銅。","林枯鳥自散，海竭絕魚龍。","無師破戒行，有法盡皆空。"]', '["鍊尽三山鐵，鎔銷五嶽銅。","林枯鸟自散，海竭絕鱼龙。","無師破戒行，有法尽皆空。"]', '诗', 'shi', '', NULL, '詩偈 八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c70d1e8-0b91-493d-949c-b78468f5c97b', '詩偈 九', '诗偈 九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["菩薩無煩惱，衆生愛皺眉。","無惱緣無賊，皺眉被賊欺。","不須問師匠，心王應自知。"]', '["菩薩無煩惱，衆生愛皺眉。","無惱緣無賊，皺眉被賊欺。","不須问師匠，心王應自知。"]', '诗', 'shi', '', NULL, '詩偈 九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42af3a9f-89fa-484f-ac92-836c69ef018d', '詩偈 十', '诗偈 十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["凡夫龢著事，不免三界輪。","與說無生理，閉耳佯不聞。"]', '["凡夫龢著事，不免三界輪。","與说無生理，閉耳佯不闻。"]', '诗', 'shi', '', NULL, '詩偈 十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5af128bb-0046-41d3-9ecc-0b6b4744ede9', '詩偈 十一', '诗偈 十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["壁畫枉用色，不如脫空佛。","住法比無住，陰中對白日。","不信有無言，看取波羅蜜。"]', '["壁畫枉用色，不如脫空佛。","住法比無住，陰中对白日。","不信有無言，看取波羅蜜。"]', '诗', 'shi', '', NULL, '詩偈 十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76e3f78b-5b01-44cc-956a-093c1d473ce9', '詩偈 十二', '诗偈 十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["見時如不見，聞時如不聞。","喜時如不喜，瞋時如不瞋。","一切盡歸如，自然無我人。"]', '["见时如不见，闻时如不闻。","喜时如不喜，瞋时如不瞋。","一切尽归如，自然無我人。"]', '诗', 'shi', '', NULL, '詩偈 十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dad0079-4312-4134-9e6c-026fd7a53997', '詩偈 十三', '诗偈 十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["齋須實相齋，戒須實相戒。","有相持齋戒，到頭歸敗壞。","敗壞屬無常，從何免三界。"]', '["斋須實相斋，戒須實相戒。","有相持斋戒，到头归敗壞。","敗壞屬無常，從何免三界。"]', '诗', 'shi', '', NULL, '詩偈 十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90879c14-d694-4c92-ab8b-e8ddab87163e', '詩偈 十四', '诗偈 十四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["心王不了事，遮莫向名山。","縱令見佛像，實以不相關。","猿猴見水月，捉月始知難。"]', '["心王不了事，遮莫向名山。","縱令见佛像，實以不相关。","猿猴见水月，捉月始知难。"]', '诗', 'shi', '', NULL, '詩偈 十四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8b72e6e-b8a9-460f-8843-745217feb4f8', '詩偈 十五', '诗偈 十五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["緣事求解脫，累劫無出期。","直須入理性，成佛更無疑。","雖然不受記，見是世尊兒。"]', '["緣事求解脫，累劫無出期。","直須入理性，成佛更無疑。","雖然不受記，见是世尊兒。"]', '诗', 'shi', '', NULL, '詩偈 十五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fb01c8a-e129-44c3-9329-58146b3f097e', '詩偈 十六', '诗偈 十六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["佛遣滅生滅，生滅長相隨。","不學大人相，却作小孫兒。","持心更覓佛，豈不是愚癡。"]', '["佛遣滅生滅，生滅长相隨。","不学大人相，却作小孫兒。","持心更覓佛，豈不是愚癡。"]', '诗', 'shi', '', NULL, '詩偈 十六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00f3ce69-f667-4152-8b8e-174e1cb1d391', '詩偈 十七', '诗偈 十七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["無事被他駡，佯佯耳不聞。","舌亦不須動，心亦不須瞋。","關津無障礙，即是出纏人。"]', '["無事被他駡，佯佯耳不闻。","舌亦不須动，心亦不須瞋。","关津無障礙，即是出纏人。"]', '诗', 'shi', '', NULL, '詩偈 十七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ca8d9e-6721-4057-b5d7-7c6f0667c256', '詩偈 十八', '诗偈 十八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["真如本無相，所得是凡流。","昔時爲父子，長大出外遊。","今日相遇見，父少子白頭。"]', '["真如本無相，所得是凡流。","昔时爲父子，长大出外游。","今日相遇见，父少子白头。"]', '诗', 'shi', '', NULL, '詩偈 十八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62bed559-9eb9-4503-bf0c-e42f32f32c9e', '詩偈 十九', '诗偈 十九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["一生解縛鈍，渾身納裏眠。","心中無意識，耳無繩索牽。","心本無繫縛，同塵亦無喧。","。"]', '["一生解縛鈍，渾身納裏眠。","心中無意識，耳無繩索牽。","心本無繫縛，同塵亦無喧。","。"]', '诗', 'shi', '', NULL, '詩偈 十九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcbaa0b6-a669-4fc9-b934-96b4673a7ebc', '詩偈 二十', '诗偈 二十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["欲得真解脫，持刀且殺牛。","牛死人亦亡，佛亦不須求。","全身空裏坐，即度死生流。"]', '["欲得真解脫，持刀且殺牛。","牛死人亦亡，佛亦不須求。","全身空裏坐，即度死生流。"]', '诗', 'shi', '', NULL, '詩偈 二十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06ffe225-a66b-4be7-a0df-ce35bfe4ba6f', '詩偈 二十一', '诗偈 二十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["貪瞋不肯捨，徒勞讀釋經（《祖堂集》卷十五作「書」）。"]', '["貪瞋不肯捨，徒勞读釋經（《祖堂集》卷十五作「书」）。"]', '诗', 'shi', '', NULL, '詩偈 二十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f72756c8-e93a-480b-b7c6-663b8214cba8', '詩偈 二十二', '诗偈 二十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["取空是取（《祖堂集》作「空是」）色，取色色無常。","色空非我有，端坐見家鄉。"]', '["取空是取（《祖堂集》作「空是」）色，取色色無常。","色空非我有，端坐见家乡。"]', '诗', 'shi', '', NULL, '詩偈 二十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('097cb97c-db74-437a-a9f5-ba29851959fb', '詩偈 二十三', '诗偈 二十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["經體本無名，受持無色聲。","心依無相理，真是《金剛經》。"]', '["經體本無名，受持無色声。","心依無相理，真是《金剛經》。"]', '诗', 'shi', '', NULL, '詩偈 二十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0da6fee5-acae-4f32-be1e-4f6e4371dd1b', '詩偈 二十四', '诗偈 二十四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["孫兒正啼哭，母言來與金。","捻他黃葉把，便是正聲音。"]', '["孫兒正啼哭，母言来與金。","捻他黄葉把，便是正声音。"]', '诗', 'shi', '', NULL, '詩偈 二十四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63b6be45-ead4-432c-9bf1-6c2d9e6fde2a', '詩偈 二十五', '诗偈 二十五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["別淚成河海，骨如毘富山。","祇緣塵識法，所以遣心然。"]', '["別泪成河海，骨如毘富山。","祇緣塵識法，所以遣心然。"]', '诗', 'shi', '', NULL, '詩偈 二十五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8c138e8-f6a8-42c3-a6ca-cb118874d0dc', '詩偈 二十六', '诗偈 二十六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["前人若有事，我猶佯不知。","何況他無問，讒舌強卑卑。"]', '["前人若有事，我猶佯不知。","何況他無问，讒舌強卑卑。"]', '诗', 'shi', '', NULL, '詩偈 二十六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b24b02f3-6c8e-45a7-b7f7-71e26e6f4b38', '詩偈 二十七', '诗偈 二十七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["勸君師子吼，莫學野干鳴。","若能香象起，感得鳳凰迎。"]', '["勸君師子吼，莫学野干鳴。","若能香象起，感得鳳凰迎。"]', '诗', 'shi', '', NULL, '詩偈 二十七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17414b67-540e-4dee-9c2d-5888199c6fee', '詩偈 二十八', '诗偈 二十八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["一種學事業，亦來登選場。","祇緣口義錯，落第在他鄉。"]', '["一種学事業，亦来登選場。","祇緣口義錯，落第在他乡。"]', '诗', 'shi', '', NULL, '詩偈 二十八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72385150-92ff-467b-bf5b-a1b02bb98321', '詩偈 二十九', '诗偈 二十九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["心王不了事，却被六賊使。","共賊作火下，無由出生死。"]', '["心王不了事，却被六賊使。","共賊作火下，無由出生死。"]', '诗', 'shi', '', NULL, '詩偈 二十九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b7e1dc8-cf43-4b8e-b709-944480d8596b', '詩偈 三十', '诗偈 三十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["別人終不賤，別寶終不貪。","祇今擔鐵漢，不肯博金銀。"]', '["別人終不賤，別寶終不貪。","祇今擔鐵漢，不肯博金銀。"]', '诗', 'shi', '', NULL, '詩偈 三十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9650da0a-99e8-47f9-9952-7c22a74ee96a', '詩偈 三十一', '诗偈 三十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["有男不肯婚，有女不肯嫁（《景德傳燈錄》卷八錄二句皆無「肯」字）。","父子自團欒（《景德傳燈錄》作「大家團欒頭」），共說無生話。"]', '["有男不肯婚，有女不肯嫁（《景德傳灯錄》卷八錄二句皆無「肯」字）。","父子自團欒（《景德傳灯錄》作「大家團欒头」），共说無生話。"]', '诗', 'shi', '', NULL, '詩偈 三十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e830604a-d49a-470f-a609-b7e0d24d238b', '詩偈 三十二', '诗偈 三十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["四性同一舍，三身同一室。","一切惡知識，總見彌陀佛。"]', '["四性同一舍，三身同一室。","一切惡知識，總见彌陀佛。"]', '诗', 'shi', '', NULL, '詩偈 三十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfad49c8-5c92-4b6b-82f6-7a5e3c64968c', '詩偈 三十三', '诗偈 三十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["教君一箇法，有事無處避。","若能如理修，存本却有利。"]', '["教君一箇法，有事無处避。","若能如理修，存本却有利。"]', '诗', 'shi', '', NULL, '詩偈 三十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('316d3ef0-6e9e-44f3-b161-74dab02bf1df', '詩偈 三十四', '诗偈 三十四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["道是無爲道，修人自有爲。","假即無頭數，真中實是稀。","。"]', '["道是無爲道，修人自有爲。","假即無头數，真中實是稀。","。"]', '诗', 'shi', '', NULL, '詩偈 三十四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30bdda3e-8d33-4ba9-9694-0723a9799289', '詩偈 三十五', '诗偈 三十五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["無求勝禮佛，知足勝持齋。","本自無薪火，何勞更拾柴。"]', '["無求勝禮佛，知足勝持斋。","本自無薪火，何勞更拾柴。"]', '诗', 'shi', '', NULL, '詩偈 三十五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2be39c21-bec1-49b4-a50d-852025d8a5bd', '詩偈 三十六', '诗偈 三十六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["說事滿天下，入理實無多。","常被有爲縛，何日見彌陀。"]', '["说事满天下，入理實無多。","常被有爲縛，何日见彌陀。"]', '诗', 'shi', '', NULL, '詩偈 三十六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73993a3c-d2c6-4ad1-a41e-df8c7dcb20c3', '詩偈 三十七', '诗偈 三十七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["起時惟法起，行時共佛行。","騰騰三界內，諸法自無生。"]', '["起时惟法起，行时共佛行。","腾腾三界內，諸法自無生。"]', '诗', 'shi', '', NULL, '詩偈 三十七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41bc542d-aed1-4ab4-8f73-829e7331ef81', '詩偈 三十八', '诗偈 三十八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["大海淼無涯，衆生自著枷。","無求出妙德，心生勞算沙。"]', '["大海淼無涯，衆生自著枷。","無求出妙德，心生勞算沙。"]', '诗', 'shi', '', NULL, '詩偈 三十八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6486f4b-1b43-474e-8ad9-72cfbf38ef57', '詩偈 三十九', '诗偈 三十九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["一念心清淨，處處蓮花開。","一華一淨土，一土一如來。"]', '["一念心清淨，处处蓮花开。","一华一淨土，一土一如来。"]', '诗', 'shi', '', NULL, '詩偈 三十九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a605187e-2144-43b8-bed2-05984694a7af', '詩偈 四十', '诗偈 四十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["大唐三百六十州，我暫放閒乘興遊。","瞬息之間知事盡，若論入理更深幽。","共外知識呷清水，總是妄想無骨頭。","却歸東西山道去，不捨因緣騎牯牛。","後望青山平似掌，前瞻漢水水東流。","試問西域那提子，遺法慇懃無所求。","自入大海歸火宅，不覺乘空失却牛。","有人見我歸東土，我本元居西海頭。","來去自然無障礙，出入生死有何憂。"]', '["大唐三百六十州，我暫放閒乘兴游。","瞬息之间知事尽，若論入理更深幽。","共外知識呷清水，總是妄想無骨头。","却归东西山道去，不捨因緣騎牯牛。","後望青山平似掌，前瞻漢水水东流。","試问西域那提子，遺法慇懃無所求。","自入大海归火宅，不覺乘空失却牛。","有人见我归东土，我本元居西海头。","来去自然無障礙，出入生死有何憂。"]', '诗', 'shi', '', NULL, '詩偈 四十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9da582b-e09e-4038-9c61-63bed624019f', '詩偈 四十一', '诗偈 四十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["無思無念是真空，妙德法身自見中。","應機接物契真智，十方世界總流通。","通達無我無人法，人法不見有行蹤。","神識自然無罣礙，廓周沙界等虛空。","不假坐禪持戒律，超然解脫豈勞功。","（按：《全唐詩》卷八一○收末四句爲一首，未完。","）。"]', '["無思無念是真空，妙德法身自见中。","應機接物契真智，十方世界總流通。","通達無我無人法，人法不见有行蹤。","神識自然無罣礙，廓周沙界等虛空。","不假坐禪持戒律，超然解脫豈勞功。","（按：《全唐诗》卷八一○收末四句爲一首，未完。","）。"]', '诗', 'shi', '', NULL, '詩偈 四十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d16a723-24a2-4c9d-a34c-65adba6d4dca', '詩偈 四十二', '诗偈 四十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["菩提般若名相假，湼槃真如亦是虛。","欲得心神真解脫，一切名相本來無。","十方世界風塵淨，州州縣縣絕艱虞。","王道蕩蕩無偏黨，舉國衆生同一如。","不動干戈安萬姓，法王合掌髻中珠。"]', '["菩提般若名相假，湼槃真如亦是虛。","欲得心神真解脫，一切名相本来無。","十方世界风塵淨，州州縣縣絕艱虞。","王道蕩蕩無偏黨，舉国衆生同一如。","不动干戈安万姓，法王合掌髻中珠。"]', '诗', 'shi', '', NULL, '詩偈 四十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3904159-73da-4669-83c4-bc3ddd71d1fb', '詩偈 四十三', '诗偈 四十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["空中自見清涼月，一光普照婆娑徹。","此光湛然無去來，不增不減無生滅。","爾是妙德現真身，剎那不起恆沙劫。","無邊無盡如虛空，虛空無邊不可說。","。"]', '["空中自见清涼月，一光普照婆娑徹。","此光湛然無去来，不增不減無生滅。","爾是妙德現真身，剎那不起恆沙劫。","無邊無尽如虛空，虛空無邊不可说。","。"]', '诗', 'shi', '', NULL, '詩偈 四十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('825ce624-d5c9-4599-aa11-f497cd4a7f3a', '詩偈 四十四', '诗偈 四十四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["但自無心於萬物，何妨萬物常圍遶。","鐵牛不怕師子吼，恰似木人見花鳥。","木人本體自無情，花鳥逢人亦不驚。","心境如如祇箇（《緇門警訓》卷九作「遮」）是，何慮菩提道不成。"]', '["但自無心於万物，何妨万物常圍遶。","鐵牛不怕師子吼，恰似木人见花鸟。","木人本體自無情，花鸟逢人亦不驚。","心境如如祇箇（《緇门警訓》卷九作「遮」）是，何慮菩提道不成。"]', '诗', 'shi', '', NULL, '詩偈 四十四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9e32e1a-1a69-4623-8592-937e868f2749', '詩偈 四十五', '诗偈 四十五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["清靜無爲無識塵，不捨內身妙法身。","祇爲衆生有漏習，權止草菴轉法輪。","法輪常轉而人見，優曇時時一出現。","無相真空妙法身，歷劫恆沙不遷變。"]', '["清静無爲無識塵，不捨內身妙法身。","祇爲衆生有漏習，權止草菴轉法輪。","法輪常轉而人见，優曇时时一出現。","無相真空妙法身，歷劫恆沙不遷变。"]', '诗', 'shi', '', NULL, '詩偈 四十五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3f68972-29fe-4c0a-8fc5-f26c745cbf05', '詩偈 四十六', '诗偈 四十六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["莫求佛兮莫求人，但自心裏莫貪瞋。","貪瞋癡病前頓盡，便是如來的的親。","內無垢兮外無塵，中間豁達無關津。","神無障礙居三界，恰是琉璃處日輪。"]', '["莫求佛兮莫求人，但自心裏莫貪瞋。","貪瞋癡病前頓尽，便是如来的的親。","內無垢兮外無塵，中间豁達無关津。","神無障礙居三界，恰是琉璃处日輪。"]', '诗', 'shi', '', NULL, '詩偈 四十六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5a53560-6563-47e0-a98a-c6f79bbb9d4e', '詩偈 四十七', '诗偈 四十七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["心王若解依真智，一切有無俱遣棄。","身隨世流心不流，夜來眼睡心不睡。","天堂地獄總無情，任運幽玄到此地。"]', '["心王若解依真智，一切有無俱遣棄。","身隨世流心不流，夜来眼睡心不睡。","天堂地獄總無情，任運幽玄到此地。"]', '诗', 'shi', '', NULL, '詩偈 四十七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a8bb4df-756a-4232-b849-589fb4a174fe', '詩偈 四十八', '诗偈 四十八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["報汝世人莫癡憨，暫時權住此草菴。","無想衣食飽暖後，世間有物不須貪。","此身幻化如燈焰，須臾不覺即頭南。"]', '["報汝世人莫癡憨，暫时權住此草菴。","無想衣食飽暖後，世间有物不須貪。","此身幻化如灯焰，須臾不覺即头南。"]', '诗', 'shi', '', NULL, '詩偈 四十八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c4274be-698b-4cc0-999e-ef8ec58e8c1a', '詩偈 四十九', '诗偈 四十九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["一切有求枉用功，想念真成著色空。","差之亳釐失千里，有生劫劫道難通。","癡心望出三界外，不知元在鐵圍中。"]', '["一切有求枉用功，想念真成著色空。","差之亳釐失千里，有生劫劫道难通。","癡心望出三界外，不知元在鐵圍中。"]', '诗', 'shi', '', NULL, '詩偈 四十九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7883a6a-e78b-4a23-8e6e-af5919632e52', '詩偈 五十', '诗偈 五十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["二十部經兼戒律，執相依文常受持。","生生獲得有爲果，隨在三界無出期。","若能離相真入理，理中無念亦無思。"]', '["二十部經兼戒律，執相依文常受持。","生生獲得有爲果，隨在三界無出期。","若能離相真入理，理中無念亦無思。"]', '诗', 'shi', '', NULL, '詩偈 五十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e9222f7-9fd0-4b4f-9d98-31b29920b8c3', '詩偈 五十一', '诗偈 五十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["貝多葉裏優曇華，萬象皆如同一家。","歡喜摘花不見菓，吉祥採菓不觀華。","緣之本來元不識，法王呵之如稻麻。","。"]', '["貝多葉裏優曇华，万象皆如同一家。","歡喜摘花不见菓，吉祥採菓不观华。","緣之本来元不識，法王呵之如稻麻。","。"]', '诗', 'shi', '', NULL, '詩偈 五十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b147a01-f2d1-4467-b025-d6ac102ac8e1', '詩偈 五十二', '诗偈 五十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["田舍老翁如聚落，眼耳鼻舌俱失却。","內外尋訪覓無蹤，舊時住處空寂寞。","卻歸堂上問空王，總在此間學無作。"]', '["田舍老翁如聚落，眼耳鼻舌俱失却。","內外尋訪覓無蹤，旧时住处空寂寞。","卻归堂上问空王，總在此间学無作。"]', '诗', 'shi', '', NULL, '詩偈 五十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ab7bba0-3965-4f7d-adba-224faae94496', '詩偈 五十三', '诗偈 五十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["黃葉飄零化作塵，本來非妄亦非真。","有情故宅含秋色，無名君子湛然春。"]', '["黄葉飄零化作塵，本来非妄亦非真。","有情故宅含秋色，無名君子湛然春。"]', '诗', 'shi', '', NULL, '詩偈 五十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa93a8bc-11c4-4d72-b9a4-d9a8a1e00110', '詩偈 五十四', '诗偈 五十四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["迷時愛欲心如火，心開悟理火成灰。","灰火本來同一體，當知妄盡即如來。"]', '["迷时愛欲心如火，心开悟理火成灰。","灰火本来同一體，當知妄尽即如来。"]', '诗', 'shi', '', NULL, '詩偈 五十四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75a85a26-201a-4fe3-aa8c-5685e10fb8ff', '詩偈 五十五', '诗偈 五十五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["真爲家貧無一物，此語總是空裏出。","出語還須歸本源，不敢違他過去佛。"]', '["真爲家貧無一物，此語總是空裏出。","出語還須归本源，不敢違他過去佛。"]', '诗', 'shi', '', NULL, '詩偈 五十五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('582ac73a-84ea-4189-9ad0-8a93f3d33574', '詩偈 五十六', '诗偈 五十六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["父子相守空山坐，無相如如寄有間。","世人見靜元無靜，看似閑時亦不閑。"]', '["父子相守空山坐，無相如如寄有间。","世人见静元無静，看似闲时亦不闲。"]', '诗', 'shi', '', NULL, '詩偈 五十六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fbe63a0-17e3-41c2-9746-4f65023a5944', '詩偈 五十七', '诗偈 五十七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["八萬四千同一理，事相差別立異名。","十二圍陀及疏論，慇懃三六不須生。"]', '["八万四千同一理，事相差別立異名。","十二圍陀及疏論，慇懃三六不須生。"]', '诗', 'shi', '', NULL, '詩偈 五十七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac200f4b-fc78-44be-9f85-139577b11e30', '詩偈 五十八', '诗偈 五十八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["十方國土皆吾宅，長者大門常日開。","有識名人守院外，無心入理見如來。"]', '["十方国土皆吾宅，长者大门常日开。","有識名人守院外，無心入理见如来。"]', '诗', 'shi', '', NULL, '詩偈 五十八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87d25f02-a7e4-4e65-9369-d5989ed74bae', '詩偈 五十九', '诗偈 五十九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["世人愛假不愛真，世人憐富却憎貧。","唯敬三塗八不淨，背却如來妙色身。"]', '["世人愛假不愛真，世人怜富却憎貧。","唯敬三塗八不淨，背却如来妙色身。"]', '诗', 'shi', '', NULL, '詩偈 五十九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21e0bf33-3bb3-4fcc-889f-49dccc9b41a3', '詩偈 六十', '诗偈 六十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["更無別路超生死，前佛後佛同一般。","舒即周流十方剎，歛時還在一毛端。"]', '["更無別路超生死，前佛後佛同一般。","舒即周流十方剎，歛时還在一毛端。"]', '诗', 'shi', '', NULL, '詩偈 六十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('562ce661-3585-4c4c-9c31-d6f8a029dff1', '詩偈 六十一', '诗偈 六十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["唯有一門無鑰匙，伸縮低昂說是非。","但能宣得無生理，善巧方便亦從伊。"]', '["唯有一门無鑰匙，伸縮低昂说是非。","但能宣得無生理，善巧方便亦從伊。"]', '诗', 'shi', '', NULL, '詩偈 六十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb88de30-051d-486a-b48f-49bf166425f5', '詩偈 六十二', '诗偈 六十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["二乘皆曰不堪任，上士之人智慧深。","欲得神通等居士，無過無物總無心。"]', '["二乘皆曰不堪任，上士之人智慧深。","欲得神通等居士，無過無物總無心。"]', '诗', 'shi', '', NULL, '詩偈 六十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afbbfec8-a3aa-4ea6-9949-506d2f98d226', '雜句 一', '杂句 一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["行路易，行路易，內外中間依本智。","本智無情法不生，無生即是入正理。","非色非心放一光，空裏優曇顯心地。","名爲智，智爲尊，心智通同達本源，萬物同歸不二門。","有非有兮理常存，無非無兮無有根，未來諸佛亦如是，現在還同古世尊。","三世俱皆無別道，佛佛相授至今傳。","。"]', '["行路易，行路易，內外中间依本智。","本智無情法不生，無生即是入正理。","非色非心放一光，空裏優曇显心地。","名爲智，智爲尊，心智通同達本源，万物同归不二门。","有非有兮理常存，無非無兮無有根，未来諸佛亦如是，現在還同古世尊。","三世俱皆無別道，佛佛相授至今傳。","。"]', '诗', 'shi', '', NULL, '雜句 一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a7734bf-7571-4e44-b9c7-b7e3bb0c90ff', '雜句 二', '杂句 二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["外無他兮內無自，不動干戈契佛智。","通達佛道行非道，不捨凡夫有爲事。","有爲名相盡空華，無名無相出生死。"]', '["外無他兮內無自，不动干戈契佛智。","通達佛道行非道，不捨凡夫有爲事。","有爲名相尽空华，無名無相出生死。"]', '诗', 'shi', '', NULL, '雜句 二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17b699d1-0593-4a4d-842c-043bfd9d8dbd', '雜句 三', '杂句 三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["余有一大衣，非是世間絹。","衆色染不著，晶晶如素練。","裁時不用刀，縫時不用線。","常持不離身，有人自不見。","三千世間遮寒暑，無情有情悉覆遍，如來持得此大衣，披了直入空王殿。"]', '["余有一大衣，非是世间絹。","衆色染不著，晶晶如素練。","裁时不用刀，縫时不用線。","常持不離身，有人自不见。","三千世间遮寒暑，無情有情悉覆遍，如来持得此大衣，披了直入空王殿。"]', '诗', 'shi', '', NULL, '雜句 三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0d323b6-8196-4433-98c2-aac9e1bcde83', '雜句 四', '杂句 四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["思思低思思，自歎一雙眉。","向他勝地坐，萬事總不知。","六識若似眉，即得不思議。","六識若嫌眉，論時沒腦癡。","伊若去却眉，即被世人欺。","饒你六識嘍囉漢，總成乞索兒。"]', '["思思低思思，自歎一雙眉。","向他勝地坐，万事總不知。","六識若似眉，即得不思議。","六識若嫌眉，論时沒腦癡。","伊若去却眉，即被世人欺。","饒你六識嘍囉漢，總成乞索兒。"]', '诗', 'shi', '', NULL, '雜句 四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecb8e458-a72e-4151-b601-945cc07e15b4', '雜句 五', '杂句 五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["出一屋，入一屋，來來去去教他哭。","來去祇爲貪瞋癡，於今悟罷須知足。","知足常須達本源，去却昔時惡知識。","惡知識，將伊作，手力法施無前後，共護無生國。"]', '["出一屋，入一屋，来来去去教他哭。","来去祇爲貪瞋癡，於今悟罷須知足。","知足常須達本源，去却昔时惡知識。","惡知識，將伊作，手力法施無前後，共護無生国。"]', '诗', 'shi', '', NULL, '雜句 五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('023ccd56-348e-4749-80b6-6e5af25ca435', '雜句 六', '杂句 六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["無事失却心，走向門前覓。","借問舊知識，寂絕無蹤跡。","却歸堂上審思看，改却衆生稱心安。","不能出外求知識，自向家中入湼槃。","大丈夫，昔日有，今日無，家計破除盡，贖得一羣奴。","奴婢有六人，一人有六口。","六六三十六，常隨我前後。","我亦不拘伊，伊亦不敢走。","若道菩提難，菩提亦不難。","少欲知足毛頭寬，遠離財色神自安。","分明了見三塗苦，世上名聞不相關。"]', '["無事失却心，走向门前覓。","借问旧知識，寂絕無蹤跡。","却归堂上審思看，改却衆生稱心安。","不能出外求知識，自向家中入湼槃。","大丈夫，昔日有，今日無，家計破除尽，贖得一羣奴。","奴婢有六人，一人有六口。","六六三十六，常隨我前後。","我亦不拘伊，伊亦不敢走。","若道菩提难，菩提亦不难。","少欲知足毛头寬，远離財色神自安。","分明了见三塗苦，世上名闻不相关。"]', '诗', 'shi', '', NULL, '雜句 六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae4d4e0d-049b-4b2b-b90a-cd0b029e3e82', '雜句 七', '杂句 七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["難復難，持心離欲貪湼槃。","一向他方求淨土，若論實行不相關。","枉用功夫來去苦，畢竟到頭空色還。"]', '["难复难，持心離欲貪湼槃。","一向他方求淨土，若論實行不相关。","枉用功夫来去苦，畢竟到头空色還。"]', '诗', 'shi', '', NULL, '雜句 七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b258fee5-22d5-48ac-a6cb-3ab0c0886985', '雜句 八', '杂句 八', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["易復易，即此五陰成（《祖堂集》卷十五作「藴有」）真智。","十方世界一乘同，無相法身豈有二。","若捨煩惱覓（《五燈會元》卷三作「入」）菩提，不知何方有佛地。"]', '["易复易，即此五陰成（《祖堂集》卷十五作「藴有」）真智。","十方世界一乘同，無相法身豈有二。","若捨煩惱覓（《五灯會元》卷三作「入」）菩提，不知何方有佛地。"]', '诗', 'shi', '', NULL, '雜句 八 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96716f27-b724-43cc-8eb4-1a3b1f7d3068', '雜句 九', '杂句 九', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["正中正，心王如如六根瑩。","六塵空，六識淨，六六三十六，同歸大圓鏡。","。"]', '["正中正，心王如如六根瑩。","六塵空，六識淨，六六三十六，同归大圓镜。","。"]', '诗', 'shi', '', NULL, '雜句 九 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65a901bd-0526-4aba-bdf8-a69134a100b6', '雜句 十', '杂句 十', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["阿難貝多葉，持來數千劫。","匕寶藏中付迦葉，分爲十二部，析作三乘法。"]', '["阿难貝多葉，持来數千劫。","匕寶藏中付迦葉，分爲十二部，析作三乘法。"]', '诗', 'shi', '', NULL, '雜句 十 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e0d6ca0-a2c7-4cd2-a952-4e8ca708ac09', '雜句 十一', '杂句 十一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["非故亦非新，應化隨緣百億身。","若有真如一合相，一億還同一聚塵。"]', '["非故亦非新，應化隨緣百億身。","若有真如一合相，一億還同一聚塵。"]', '诗', 'shi', '', NULL, '雜句 十一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7de524cb-ac3b-4e47-b082-476b4767047e', '雜句 十二', '杂句 十二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["珠從藏中現，顯赫呈光輝。","昔日逃走爲窮子，今日還家作富兒。"]', '["珠從藏中現，显赫呈光輝。","昔日逃走爲窮子，今日還家作富兒。"]', '诗', 'shi', '', NULL, '雜句 十二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('297ecd3a-3198-42af-b31b-f76248d54e86', '雜句 十三', '杂句 十三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["心依真智，理逐心行，理智無礙，心亦無生。","迷即有我，悟即無情。","通達大智，諸法不成。","五神無主，六國安寧。","七死弗受，八鏡圓明。","隨宜善化，總合佛經。","過即已過，更莫再尋。","現在不住，念念勿侵。","未來未至，亦莫預斟。","既無三世，心同佛心。","依空默用，即是行深。","無有少法，觸目平任。","無戒可持，無垢可淨。","洞達虛心，法無壽命。","若能如是，圓通究竟。","（以上七十五首皆見《龐居士語錄》卷下）。"]', '["心依真智，理逐心行，理智無礙，心亦無生。","迷即有我，悟即無情。","通達大智，諸法不成。","五神無主，六国安寧。","七死弗受，八镜圓明。","隨宜善化，總合佛經。","過即已過，更莫再尋。","現在不住，念念勿侵。","未来未至，亦莫預斟。","既無三世，心同佛心。","依空默用，即是行深。","無有少法，觸目平任。","無戒可持，無垢可淨。","洞達虛心，法無壽命。","若能如是，圓通究竟。","（以上七十五首皆见《龐居士語錄》卷下）。"]', '诗', 'shi', '', NULL, '雜句 十三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('203b2569-bf7e-4eff-8c68-9fe1354362ec', '居士見僧講金剛經至無我無人居士問云既無我無人是誰講誰聽座主無語迺與頌曰', '居士见僧講金剛經至無我無人居士问云既無我無人是誰講誰听座主無語迺與頌曰', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["無我復無人，作麽有疎親。","勸師（《景德傳燈錄》卷八作「君」）休歷坐，不是（《景德傳燈錄》作「似」）直求真。","金剛般若性，外絕一纖塵。","我聞並信受，總是假名陳。","（同前書卷上）。"]', '["無我复無人，作麽有疎親。","勸師（《景德傳灯錄》卷八作「君」）休歷坐，不是（《景德傳灯錄》作「似」）直求真。","金剛般若性，外絕一纖塵。","我闻並信受，總是假名陳。","（同前书卷上）。"]', '诗', 'shi', '', NULL, '居士見僧講金剛經至無我無人居士問云既無我無人是誰講誰聽座主無語迺與頌曰 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0667faa0-8c67-4529-b8f5-9b23deebdcba', '與谷隱道者頌', '與谷隐道者頌', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["焰火無魚下底鉤，覓魚無處笑君愁。","可憐谷隱孜禪伯，被唾如今見亦羞。","（同前）按：《全唐詩》卷八一○收此首，缺題，今重錄。"]', '["焰火無鱼下底鉤，覓鱼無处笑君愁。","可怜谷隐孜禪伯，被唾如今见亦羞。","（同前）按：《全唐诗》卷八一○收此首，缺題，今重錄。"]', '诗', 'shi', '', NULL, '與谷隱道者頌 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8672133-dca7-400f-9f90-0d841156eeab', '詩偈 一', '诗偈 一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["須彌頹，五嶽崩，大海竭，十方空。","乾坤尚納毛頭裏，日月猶潛毫相中。","此是西國那提子，示寂不起現神通。","妙德啓口問不二，忘言入理顯真宗。","（見吳越釋延壽《宗鏡錄》卷二三）。"]', '["須彌頹，五嶽崩，大海竭，十方空。","乾坤尚納毛头裏，日月猶潛毫相中。","此是西国那提子，示寂不起現神通。","妙德啓口问不二，忘言入理显真宗。","（见吳越釋延壽《宗镜錄》卷二三）。"]', '诗', 'shi', '', NULL, '詩偈 一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac65b26f-999f-4386-9265-fe838895ae7c', '詩偈 二', '诗偈 二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["居士元無病，方丈現有疾。","唯憂二乘者，緣事不得出。","所以訶穢食，純說波羅蜜。","上方一盂飯，氣滿於七日。","不假日月光，心王照斯室。","文殊問不二，忘言功自畢。","過去即如然，現在還同一。","若能達此理，無求總成佛。","（見前書卷二五）。"]', '["居士元無病，方丈現有疾。","唯憂二乘者，緣事不得出。","所以訶穢食，純说波羅蜜。","上方一盂飯，氣满於七日。","不假日月光，心王照斯室。","文殊问不二，忘言功自畢。","過去即如然，現在還同一。","若能達此理，無求總成佛。","（见前书卷二五）。"]', '诗', 'shi', '', NULL, '詩偈 二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ce312df-17a2-4b28-944a-c98edc0e5920', '詩偈 三', '诗偈 三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["心如境亦如，無實亦無虛。","有亦不管，無亦不居（《五燈會元》作「拘」）。","不事賢聖，了事凡夫。"]', '["心如境亦如，無實亦無虛。","有亦不管，無亦不居（《五灯會元》作「拘」）。","不事賢聖，了事凡夫。"]', '诗', 'shi', '', NULL, '詩偈 三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ece3bb7-c816-455e-ba76-7b07bcc229e9', '詩偈 四', '诗偈 四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["心若如，神自虛。","不服藥，病自除。","病既除，自見蓮華如意珠。","無勞事，莫駈駈。","智者觀財色，了知如（《語錄》作「是」）幻虛。","衣食支身命，相勸學如如。","時至移庵去，無物可盈餘。","（以上二首均見影印本日本花園大學圖書館藏高麗覆刻本南唐招慶寺靜筠二僧著《祖堂集》卷十五）（按：《龐居士語錄》卷中以後六句爲一首，似未全。","）。"]', '["心若如，神自虛。","不服藥，病自除。","病既除，自见蓮华如意珠。","無勞事，莫駈駈。","智者观財色，了知如（《語錄》作「是」）幻虛。","衣食支身命，相勸学如如。","时至移庵去，無物可盈餘。","（以上二首均见影印本日本花园大学圖书館藏高丽覆刻本南唐招慶寺静筠二僧著《祖堂集》卷十五）（按：《龐居士語錄》卷中以後六句爲一首，似未全。","）。"]', '诗', 'shi', '', NULL, '詩偈 四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad065703-6e60-4d96-9356-1921853f5db4', '詩偈 五', '诗偈 五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["事上說佛國，此去十萬里。","大海渺無邊，動即黑風起。","往者雖千萬，達者無一二。","忽遇本來人，不在陰陽里。","（見日本《大正新修大藏經》第四八冊吳越釋延壽撰《萬善同歸集》卷上）。"]', '["事上说佛国，此去十万里。","大海渺無邊，动即黑风起。","往者雖千万，達者無一二。","忽遇本来人，不在陰陽里。","（见日本《大正新修大藏經》第四八冊吳越釋延壽撰《万善同归集》卷上）。"]', '诗', 'shi', '', NULL, '詩偈 五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ee4c7e6-ea49-492c-9663-5f063289f666', '詩偈 六', '诗偈 六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["護身須是殺，殺盡始安居。","會得箇中意，鐵船水上浮。","（《五燈會元》卷三）。"]', '["護身須是殺，殺尽始安居。","會得箇中意，鐵船水上浮。","（《五灯會元》卷三）。"]', '诗', 'shi', '', NULL, '詩偈 六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d98757e-196d-4cba-a5b7-f3bd74077f45', '詩偈 七', '诗偈 七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["窮廝煎，餓廝吵，父子不同途，大家相脫卯。","萬頃湘江洗不清，無生曲調何時了。","（見《大正新修大藏經》四七冊宋《虛堂和尚語錄》卷十引）（按：《祖堂集》卷十五《龐居士傳》云：「平生樂道偈頌，可三百餘首，廣行於世。","皆以言符至理，句闡玄猷，爲儒彥之珠金，乃緇流之篋寶。","」）（〖1〗《景德傳燈錄》卷八本傳云：「有詩偈三百餘篇傳於世。","」〖2〗《新唐書》卷五九《藝文志》三著錄龐藴《詩偈》三卷，注云：「字道玄，衡州衡陽人，貞元初人。","三百餘篇。","」〖3〗無名子《龐居士語錄詩頌序》云：「其餘玄談道頌，流傳人間，頗多散軼。","今姑以所聞成編，釐爲二卷，永示將來，庶警後學。","」）。"]', '["窮廝煎，餓廝吵，父子不同途，大家相脫卯。","万頃湘江洗不清，無生曲調何时了。","（见《大正新修大藏經》四七冊宋《虛堂和尚語錄》卷十引）（按：《祖堂集》卷十五《龐居士傳》云：「平生乐道偈頌，可三百餘首，廣行於世。","皆以言符至理，句闡玄猷，爲儒彥之珠金，乃緇流之篋寶。","」）（〖1〗《景德傳灯錄》卷八本傳云：「有诗偈三百餘篇傳於世。","」〖2〗《新唐书》卷五九《藝文志》三著錄龐藴《诗偈》三卷，注云：「字道玄，衡州衡陽人，貞元初人。","三百餘篇。","」〖3〗無名子《龐居士語錄诗頌序》云：「其餘玄談道頌，流傳人间，頗多散軼。","今姑以所闻成編，釐爲二卷，永示將来，庶警後学。","」）。"]', '诗', 'shi', '', NULL, '詩偈 七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a751fe18-a193-41c6-9867-0967e6ba2774', '謁贈何國子監司籍堅', '謁贈何国子監司籍堅', 'b7d646d3-2fcb-4bb1-8b5b-d9bb1277758b', '唐', '["久仰高明抱樸忠，倏傳馬首向城東。","錦袍光射三千里，汗史功高百二雄。","童稚候門烹雀舌，黎老植杖盼菊松。","皇天應欲逸家輔，故遣盤桓醉碧筒。","（見光緒三年刊許清源纂《道州志》卷十一）。"]', '["久仰高明抱樸忠，倏傳马首向城东。","錦袍光射三千里，汗史功高百二雄。","童稚候门烹雀舌，黎老植杖盼菊松。","皇天應欲逸家輔，故遣盤桓醉碧筒。","（见光緒三年刊許清源纂《道州志》卷十一）。"]', '诗', 'shi', '', NULL, '謁贈何國子監司籍堅 陽城 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e84b9f55-c903-4bf2-914e-e6f3761f40bd', '次韻答陽刺史城', '次韻答陽刺史城', 'b4e9a3e8-c458-4c5c-8781-70b212348898', '唐', '["素履衡門秉直忠，挂冠金闕回江東。","戢羽應知非健翮，守雌或可謂知雄。","午夜鳴琴餐玄露，深山弄月友赤松。","多感君侯歡導引，臨流遣興醉碧筒。"]', '["素履衡门秉直忠，挂冠金闕回江东。","戢羽應知非健翮，守雌或可謂知雄。","午夜鳴琴餐玄露，深山弄月友赤松。","多感君侯歡導引，臨流遣兴醉碧筒。"]', '诗', 'shi', '', NULL, '次韻答陽刺史城 何堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a7f6d13-0699-4d1e-92f0-9d03410aa692', '除授太學國子監司籍之職因賦', '除授太学国子監司籍之職因賦', 'b4e9a3e8-c458-4c5c-8781-70b212348898', '唐', '["九重天子重英豪，御殿傳恩賜綠袍。","樂道直欲學商尹，致君恒切佐唐堯。","瓊林日照宮花燦，金榜風搖姓字高。","幸荷召頒入太學，相期聯步覲天朝。","（見同前書卷十一）。"]', '["九重天子重英豪，御殿傳恩賜綠袍。","乐道直欲学商尹，致君恒切佐唐堯。","瓊林日照宮花燦，金榜风搖姓字高。","幸荷召頒入太学，相期聯步覲天朝。","（见同前书卷十一）。"]', '诗', 'shi', '', NULL, '除授太學國子監司籍之職因賦 何堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd95ade7-8a73-4cad-a66e-6f608409a7b9', '漁父詞', '漁父词', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["新婦磯邊月明，女兒浦口潮平，沙頭鷺宿魚驚。","（見宋曾慥《樂府雅詞》卷中徐俯詞跋引、吳曾《能改齋漫錄》卷十六《水光山色漁父家風》引徐師川云引）（按：《全唐詩》卷二六七據《野客叢書》卷二一所錄，僅存前二句，今重錄。","）。"]', '["新婦磯邊月明，女兒浦口潮平，沙头鷺宿鱼驚。","（见宋曾慥《乐府雅词》卷中徐俯词跋引、吳曾《能改斋漫錄》卷十六《水光山色漁父家风》引徐師川云引）（按：《全唐诗》卷二六七據《野客叢书》卷二一所錄，僅存前二句，今重錄。","）。"]', '诗', 'shi', '', NULL, '漁父詞 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acef2d2d-cbcc-441c-8163-e1669a19b202', '題梨花睡鴨圖', '題梨花睡鴨圖', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["昔年家住太湖西，常過吳興罨畫溪。","水閣筠簾春似海，梨花影裏睡鳧鷖。","（見《吳興藝文志補》卷四四）。"]', '["昔年家住太湖西，常過吳兴罨畫溪。","水閣筠簾春似海，梨花影裏睡鳧鷖。","（见《吳兴藝文志補》卷四四）。"]', '诗', 'shi', '', NULL, '題梨花睡鴨圖 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de0b8a80-6ec4-44a2-bffb-d9f014d34a57', '委羽山', '委羽山', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["昔人乘鶴玉京遊，翮遺仙洞何悠悠。","我來尋覓空彝猶，煙霞萬壑明清秋。","何當騎麟翳鳳登瀛洲，倏忽能消萬古愁。","（見《古今圖書集成·山川典》卷一二○《委羽山部》）。"]', '["昔人乘鹤玉京游，翮遺仙洞何悠悠。","我来尋覓空彝猶，煙霞万壑明清秋。","何當騎麟翳鳳登瀛洲，倏忽能消万古愁。","（见《古今圖书集成·山川典》卷一二○《委羽山部》）。"]', '诗', 'shi', '', NULL, '委羽山 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3f45c6f-2929-4bd5-86b3-aef6979d311b', '贈顧況詩', '贈顧況诗', '86fde0ad-4690-4aa7-bdf4-ad98954bab44', '唐', '["辟彊東晉日，竹樹有名園。","年代更多主，池塘復裔孫。","（見宋朱長文《吳郡圖經續紀》卷下）（〖1〗《吳郡圖經續記》：「辟彊園，唐時猶在。","顧況嘗假以居。","郡守贈詩曰〖略〗。","」郡守姓名不詳。","）。"]', '["辟彊东晉日，竹樹有名园。","年代更多主，池塘复裔孫。","（见宋朱长文《吳郡圖經續紀》卷下）（〖1〗《吳郡圖經續記》：「辟彊园，唐时猶在。","顧況嘗假以居。","郡守贈诗曰〖略〗。","」郡守姓名不詳。","）。"]', '诗', 'shi', '', NULL, '贈顧況詩 蘇州刺史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdea7c94-9609-44b7-8bc6-a4f38b2d3bea', '問如滿禪師 一', '问如满禪師 一', '62e42ce2-662b-4669-bbc2-0071129c8c2e', '唐', '[]', '[]', '诗', 'shi', '', NULL, '問如滿禪師 一 順宗皇帝李誦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09650c65-e86e-487d-a9a3-40d093e1c22f', '問如滿禪師 二', '问如满禪師 二', '62e42ce2-662b-4669-bbc2-0071129c8c2e', '唐', '["佛向王宮生，滅向雙林滅。","住世四十九，又言無法說。","山河及大海，天地及日月。","時至皆歸盡，誰言不生滅？","疑情猶若斯，智者善分別。","（《景德傳燈錄》卷六）。"]', '["佛向王宮生，滅向雙林滅。","住世四十九，又言無法说。","山河及大海，天地及日月。","时至皆归尽，誰言不生滅？","疑情猶若斯，智者善分別。","（《景德傳灯錄》卷六）。"]', '诗', 'shi', '', NULL, '問如滿禪師 二 順宗皇帝李誦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90279a2d-3bdf-4b90-afa3-8800ee9f50e3', '', '', '5fde4753-3a90-4944-9c28-bc687fe7290f', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 如滿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('857ff0e0-111e-4aaa-8f8c-07fe00c6f198', '答順宗皇帝問 一', '答順宗皇帝问 一', '5fde4753-3a90-4944-9c28-bc687fe7290f', '唐', '["佛從無爲來，滅向無爲去。","法身等虛空，常住無心處。","有念歸無念，有住歸無住。","來爲衆生來，去爲衆生去。","清淨真如海，湛然體常住。","智者善思惟，更勿生疑慮。"]', '["佛從無爲来，滅向無爲去。","法身等虛空，常住無心处。","有念归無念，有住归無住。","来爲衆生来，去爲衆生去。","清淨真如海，湛然體常住。","智者善思惟，更勿生疑慮。"]', '诗', 'shi', '', NULL, '答順宗皇帝問 一 如滿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a408e27-755e-4962-a412-412205f11060', '答順宗皇帝問 二', '答順宗皇帝问 二', '5fde4753-3a90-4944-9c28-bc687fe7290f', '唐', '["佛體本無爲，迷情妄分別。","法身等虛空，未曾有生滅。","有緣佛出世，無緣佛入滅。","處處化衆生，猶如水中月。","非常亦非滅。","生亦未曾生，滅亦未曾滅。","了見無心處，自然無法說。","（同前）。"]', '["佛體本無爲，迷情妄分別。","法身等虛空，未曾有生滅。","有緣佛出世，無緣佛入滅。","处处化衆生，猶如水中月。","非常亦非滅。","生亦未曾生，滅亦未曾滅。","了见無心处，自然無法说。","（同前）。"]', '诗', 'shi', '', NULL, '答順宗皇帝問 二 如滿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b273ac38-3a54-4667-a82f-b21233ec2ba1', '山莊早春連雨即事', '山莊早春連雨即事', '2ea957d6-e9a0-4f5c-a98b-48ac55840abd', '唐', '["崇朝竟日雨{風衰}{風衰}（疑），萬物萌牙春（疑）水災。","白屋世情輕席戶，青山老大厭莓苔。","常時楊柳煙中綻，今歲花枝雪未開。","節往始知陽氣晚，和風不借後亭梅。"]', '["崇朝竟日雨{风衰}{风衰}（疑），万物萌牙春（疑）水災。","白屋世情轻席戶，青山老大厭莓苔。","常时楊柳煙中綻，今歲花枝雪未开。","節往始知陽氣晚，和风不借後亭梅。"]', '诗', 'shi', '', NULL, '山莊早春連雨即事 朱千乘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8fd8b82-4a57-46b4-a5e1-e2911191060f', '早春霽後山莊即事', '早春霽後山莊即事', '2ea957d6-e9a0-4f5c-a98b-48ac55840abd', '唐', '["插槿未成籬，啼鶯早已知。","日長春霽後，風暖柳煙宜。","席戶門斜掩，漁舟釣直垂。","久將松竹比，寧懼歲寒移。","上藥幽前圃，繁花壓小枝。","素琴延翫月，清渭酌臨池。","守道安貧（疑）老，專經數欲奇。","若爲裁二鬢，羞向鏡中窺。","（日本藏唐抄本《新撰類林抄》卷四）。"]', '["插槿未成籬，啼鶯早已知。","日长春霽後，风暖柳煙宜。","席戶门斜掩，漁舟釣直垂。","久將松竹比，寧懼歲寒移。","上藥幽前圃，繁花壓小枝。","素琴延翫月，清渭酌臨池。","守道安貧（疑）老，專經數欲奇。","若爲裁二鬢，羞向镜中窺。","（日本藏唐抄本《新撰類林抄》卷四）。"]', '诗', 'shi', '', NULL, '早春霽後山莊即事 朱千乘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05b650af-52e3-45d0-8ea6-db4f22db5531', '送日本國三藏空海上人朝宗我唐兼貢方物而歸海東詩（幷序）', '送日本国三藏空海上人朝宗我唐兼貢方物而归海东诗（幷序）', '2ea957d6-e9a0-4f5c-a98b-48ac55840abd', '唐', '["古貌宛休公，談真說苦空。","應傳六祖後，遠化島夷中。","去歲朝秦闕，今春赴海東。","威儀易舊體，文字冠儒宗。","留學幽微旨，雲關護法崇。","凌波無際礙，振錫路何窮。","水宿鳴金磬，雲行侍玉童。","承恩見明主，偏沐僧家風。","（收入《弘法大師正傳》，見《弘法大師全集》第七卷）。"]', '["古貌宛休公，談真说苦空。","應傳六祖後，远化島夷中。","去歲朝秦闕，今春赴海东。","威儀易旧體，文字冠儒宗。","留学幽微旨，云关護法崇。","凌波無際礙，振錫路何窮。","水宿鳴金磬，云行侍玉童。","承恩见明主，偏沐僧家风。","（收入《弘法大師正傳》，见《弘法大師全集》第七卷）。"]', '诗', 'shi', '', NULL, '送日本國三藏空海上人朝宗我唐兼貢方物而歸海東詩（幷序） 朱千乘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76ce33cc-916b-4a82-a441-d8e74cbb6334', '送空海上人朝謁後歸日本', '送空海上人朝謁後归日本', '7007621b-dc8d-47ff-8eb0-c9b230fe4f70', '唐', '["禪客祖州來，中華謁帝回。","騰空猶振錫，過海來浮杯。","佛法逢人授，天書到國開。","歸程數萬里，歸國信悠哉。","（同前）。"]', '["禪客祖州来，中华謁帝回。","腾空猶振錫，過海来浮杯。","佛法逢人授，天书到国开。","归程數万里，归国信悠哉。","（同前）。"]', '诗', 'shi', '', NULL, '送空海上人朝謁後歸日本 朱少端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94e09911-749c-4013-bb41-fe1254cbc98d', '奉送日本國使空海上人橘秀才朝獻後却還', '奉送日本国使空海上人橘秀才朝獻後却還', '76e11fda-2163-450c-8778-052121dd34ac', '唐', '["異國桑門客，乘杯望斗星。","來朝漢天子，歸譯竺乾經。","萬里洪濤白，三春孤島青。","到宮方奏對，圖像列王庭。","（同前）。"]', '["異国桑门客，乘杯望斗星。","来朝漢天子，归譯竺乾經。","万里洪濤白，三春孤島青。","到宮方奏对，圖像列王庭。","（同前）。"]', '诗', 'shi', '', NULL, '奉送日本國使空海上人橘秀才朝獻後却還 曇靖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32204a07-f044-4a5e-9b7c-3225b224de83', '奉送日本國使空海上人橘秀才朝獻後却還', '奉送日本国使空海上人橘秀才朝獻後却還', 'c73756e5-fd01-4463-9748-c01550f3f1d8', '唐', '["禪居一海間，鄉路祖州東。","到國宣周禮，朝天得僧風。","山冥魚梵遠，日正蜃樓空。","人至非徐福，何由寄信通。","（同前）。"]', '["禪居一海间，乡路祖州东。","到国宣周禮，朝天得僧风。","山冥鱼梵远，日正蜃楼空。","人至非徐福，何由寄信通。","（同前）。"]', '诗', 'shi', '', NULL, '奉送日本國使空海上人橘秀才朝獻後却還 鴻漸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('960525be-a6bc-463f-94b4-34785e2b16e9', '奉送日本國使空海上人橘秀才朝獻後却還', '奉送日本国使空海上人橘秀才朝獻後却還', '74b50210-72b0-43e0-8fc9-77144a957500', '唐', '["承化來中國，朝天是外臣。","異才誰作侶，孤嶼自爲鄰。","鴈塔歸殊域，鯨波涉巨津。","他年續僧史，更載一賢人。","（同前）（按：朱千乘等五人送空海歸國詩五首，均錄自張步雲《唐代逸詩輯存》。","）。"]', '["承化来中国，朝天是外臣。","異才誰作侶，孤嶼自爲鄰。","鴈塔归殊域，鯨波涉巨津。","他年續僧史，更載一賢人。","（同前）（按：朱千乘等五人送空海归国诗五首，均錄自張步云《唐代逸诗輯存》。","）。"]', '诗', 'shi', '', NULL, '奉送日本國使空海上人橘秀才朝獻後却還 鄭壬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fd9b2f6-c5c5-4e56-94e1-701de35f8965', '贈釋空海歌', '贈釋空海歌', 'dfe43a0f-2c53-4569-a6e6-b3d598e75f07', '唐', '["說四句，演毗尼，凡夫聽者盡歸依。","天假吾師多伎術，就中草聖最狂逸，不可得，難再見。","（見日僧真濟《遍照發揮性靈集序》，見《日本古典文學大系》七一冊空海《性靈集》卷首）（按：《全唐詩逸》卷中錄此詩，缺末二句，今重錄。","）。"]', '["说四句，演毗尼，凡夫听者尽归依。","天假吾師多伎術，就中草聖最狂逸，不可得，难再见。","（见日僧真濟《遍照發揮性靈集序》，见《日本古典文学大系》七一冊空海《性靈集》卷首）（按：《全唐诗逸》卷中錄此诗，缺末二句，今重錄。","）。"]', '诗', 'shi', '', NULL, '贈釋空海歌 胡伯崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c1e468d-3c2a-4c22-b7cb-9173015020ae', '奉贈葉□郎新湖詩', '奉贈葉□郎新湖诗', '2011632a-8808-4229-97e5-c15abb6251b8', '唐', '["賞眺新湖趣，澄漪寫物華。","采蘋經綠溆，垂釣倚枯槎。","水動魚驚鳥，風搖蝶□花。","宛然登興處，寧羨武陵家。","（光緒《上虞縣志》卷三七《金石》）。"]', '["賞眺新湖趣，澄漪寫物华。","采蘋經綠溆，垂釣倚枯槎。","水动鱼驚鸟，风搖蝶□花。","宛然登兴处，寧羨武陵家。","（光緒《上虞縣志》卷三七《金石》）。"]', '诗', 'shi', '', NULL, '奉贈葉□郎新湖詩 余鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7bdab8b-ce63-4557-8d3c-064626ac893d', '奉贈葉□郎新湖詩', '奉贈葉□郎新湖诗', '55f1e112-d799-43ce-ab37-2a9b6c5eabaf', '唐', '["平湖近闢千□□，物色如今滿面新。","風擺野花香撲撲，水澄絲柳影鱗鱗。","高低菡萏分紅蘂，出沒鵁鶄間白蘋。","迴首更看南北岸，不知何處不宜人。","（以上二首，均爲陶敏先生錄示。","）。"]', '["平湖近闢千□□，物色如今满面新。","风擺野花香撲撲，水澄絲柳影鱗鱗。","高低菡萏分紅蘂，出沒鵁鶄间白蘋。","迴首更看南北岸，不知何处不宜人。","（以上二首，均爲陶敏先生錄示。","）。"]', '诗', 'shi', '', NULL, '奉贈葉□郎新湖詩 汪仲陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae72bfb9-b960-4aa7-9329-cd2d84552b5c', '善卷祠', '善卷祠', '020dc06b-a017-46e9-ba5e-aa42d33692ab', '唐', '["子長愛奇故不收，況乃著論非許由。","先生蹤跡重埋沒，引舜作證應點頭。","天下大器尚不欲，萬古虛名豈願留？","江北漫空山不靜，說著高風簪可投。","（同治《武陵縣志》卷四八。","本詩爲陶敏先生錄示，小傳亦從陶說。","）。"]', '["子长愛奇故不收，況乃著論非許由。","先生蹤跡重埋沒，引舜作證應点头。","天下大器尚不欲，万古虛名豈願留？","江北漫空山不静，说著高风簪可投。","（同治《武陵縣志》卷四八。","本诗爲陶敏先生錄示，小傳亦從陶说。","）。"]', '诗', 'shi', '', NULL, '善卷祠 薛巽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17d10833-7bf6-46fe-ad63-a70d4437ad3c', '金燈', '金灯', 'a5076ed1-98cc-4fb4-b669-e046fe554cf3', '唐', '["疎莖秋擁翠，幽豔夕添紅。","有月長燈在，無煙燼火同。","香濃初受露，勢庳不知風。","應笑金臺上，先隨曉漏終。","（見令狐楚《御覽詩》）（按：《全唐詩》卷五六三誤收於盧溵下，今移正。","）。"]', '["疎莖秋擁翠，幽豔夕添紅。","有月长灯在，無煙燼火同。","香濃初受露，勢庳不知风。","應笑金台上，先隨晓漏終。","（见令狐楚《御覽诗》）（按：《全唐诗》卷五六三誤收於盧溵下，今移正。","）。"]', '诗', 'shi', '', NULL, '金燈 盧殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c3d970d-b8be-4600-844a-e0cda299e596', '秋懷', '秋懷', '30962e62-340a-456f-8510-c4457ef6b594', '唐', '["野濶平收潦水香，園林恰似鄭公鄉。","懶雲未許寒風卷，落葉從他零露傷。","夜靜猿聲添客淚，朝聞雁字引詩狂。","生涯不共秋光老，濁酒丹經一釣航。","（見同治十三年刊《直隸澧州志》卷二五）。"]', '["野濶平收潦水香，园林恰似鄭公乡。","懶云未許寒风卷，落葉從他零露傷。","夜静猿声添客泪，朝闻雁字引诗狂。","生涯不共秋光老，濁酒丹經一釣航。","（见同治十三年刊《直隸澧州志》卷二五）。"]', '诗', 'shi', '', NULL, '秋懷 段弘古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d2cf0f0-f99f-4347-adf2-e432061f1e05', '孤竹', '孤竹', '30962e62-340a-456f-8510-c4457ef6b594', '唐', '["亭亭骨屹短墻顛，搖曳空明漾素妍。","帶雨微添寒鶴淚，淩霜不受野雲憐。","老松立地同高節，芳草何心弔[謫]（滴）仙。","抱此孤根滋九畹，青山一道送流泉。","（見道光刊本鄧顯鶴輯《沅湘耆舊集》卷二）。"]', '["亭亭骨屹短墻顛，搖曳空明漾素妍。","带雨微添寒鹤泪，淩霜不受野云怜。","老松立地同高節，芳草何心弔[謫]（滴）仙。","抱此孤根滋九畹，青山一道送流泉。","（见道光刊本鄧显鹤輯《沅湘耆旧集》卷二）。"]', '诗', 'shi', '', NULL, '孤竹 段弘古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bae868b-4a1c-4b45-b6e9-fa28dbb6acd1', '登石傘峰', '登石傘峰', '00aacb4c-8658-452c-b6e6-19376f3519ec', '唐', '["作鎮得良牧，撫戎慙匪仁。","每觀龔黃化，煦物如陽春。","政簡似多暇，遊從邀衆賓。","鳴騶鏡水畔，捨櫂耶溪津。","偶茲逢勝境，頓覺離囂塵。","丞相築室在，季方結廬新。","登臨經絕頂，矚眺怡心神。","金章照玉傘，龍節陵松鱗。","笙歌入中流，聲角聞城闉。","更吟瓊瑤篇，願言書諸紳。","（見《會稽掇英總集》卷四）。"]', '["作鎮得良牧，撫戎慙匪仁。","每观龔黄化，煦物如陽春。","政簡似多暇，游從邀衆賓。","鳴騶镜水畔，捨櫂耶溪津。","偶茲逢勝境，頓覺離囂塵。","丞相築室在，季方結廬新。","登臨經絕頂，矚眺怡心神。","金章照玉傘，龙節陵松鱗。","笙歌入中流，声角闻城闉。","更吟瓊瑤篇，願言书諸紳。","（见《會稽掇英總集》卷四）。"]', '诗', 'shi', '', NULL, '登石傘峰 王承鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e03ca858-c25a-4658-8f53-16252bec7227', '登石傘峰', '登石傘峰', 'ed4ef74d-d073-4e3b-80bf-96385d9cd05f', '唐', '["能以郡中暇，不遺塵外蹤。","嘯儔得鴛鴦，探策入雲松。","緣徑歷空際，望崖來劍峰。","況當會天人，復此陳歌鐘。","賤子固多癖，偶茲安一峰。","步林欣有適，築室幸可容。","寧期樵牧處，忽與軒蓋逢。","仰荷高興屬，俯慙危磴重。","攀幽破巖靄，踐滑觸苔封。","秋景山光動，寒叢菊艷濃。","賞心愜觴酌，逸韻陶襟胸。","仍叨勒名字，永紀今所從。","（見《會稽掇英總集》卷四）。"]', '["能以郡中暇，不遺塵外蹤。","嘯儔得鴛鴦，探策入云松。","緣徑歷空際，望崖来劍峰。","況當會天人，复此陳歌鐘。","賤子固多癖，偶茲安一峰。","步林欣有適，築室幸可容。","寧期樵牧处，忽與軒蓋逢。","仰荷高兴屬，俯慙危磴重。","攀幽破巖靄，踐滑觸苔封。","秋景山光动，寒叢菊艷濃。","賞心愜觴酌，逸韻陶襟胸。","仍叨勒名字，永紀今所從。","（见《會稽掇英總集》卷四）。"]', '诗', 'shi', '', NULL, '登石傘峰 齊推 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('723daec8-8774-4106-b8f7-86e80a18282d', '', '', '1add005c-05cc-404a-a368-1d191864867a', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 路黃中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec456771-0cc3-4ecf-82ab-f454a1f015e1', '登石傘峰', '登石傘峰', '1add005c-05cc-404a-a368-1d191864867a', '唐', '["總戎詣幽勝，天使相追隨。","躋山玉笥號，到峰石傘奇。","接武白雲表，放情玄月時。","恬曠薄沆瀣，峻極超崦嵫。","平視羲和轡，俯觀朝夕池。","巖中復何揖，坐位多所宜。","鬱烈桂香眇，寅緣霞彩披。","孤光逗綺翼，獨秀分瓊枝。","靈氣達心久，華容招目移。","遂忘日云暮，登降不知疲。","眷言丘壑士，養節松竹滋。","感激旌蓋顧，干以獻貞詞。","（見《會稽掇英總集》卷四）。"]', '["總戎詣幽勝，天使相追隨。","躋山玉笥號，到峰石傘奇。","接武白云表，放情玄月时。","恬曠薄沆瀣，峻極超崦嵫。","平視羲和轡，俯观朝夕池。","巖中复何揖，坐位多所宜。","鬱烈桂香眇，寅緣霞彩披。","孤光逗綺翼，独秀分瓊枝。","靈氣達心久，华容招目移。","遂忘日云暮，登降不知疲。","眷言丘壑士，養節松竹滋。","感激旌蓋顧，干以獻貞词。","（见《會稽掇英總集》卷四）。"]', '诗', 'shi', '', NULL, '登石傘峰 路黃中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5e635a0-7d08-44d6-9bc9-579016600b32', '正月十五夜翫月詩 一', '正月十五夜翫月诗 一', '7522f6a6-f353-4dcd-a334-1334ef84b6df', '唐', '["風淒城上樓。"]', '["风淒城上楼。"]', '诗', 'shi', '', NULL, '正月十五夜翫月詩 一 范傳正 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('117ec536-0192-43f7-8531-0f545ccc7fa3', '正月十五夜翫月詩 二', '正月十五夜翫月诗 二', '7522f6a6-f353-4dcd-a334-1334ef84b6df', '唐', '["月滿庾公樓。"]', '["月满庾公楼。"]', '诗', 'shi', '', NULL, '正月十五夜翫月詩 二 范傳正 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09aaeabc-7d34-4a68-b733-9a7af309c2bb', '正月十五夜翫月詩 三', '正月十五夜翫月诗 三', '7522f6a6-f353-4dcd-a334-1334ef84b6df', '唐', '["夕照下西樓。","（均見《嘉泰吳興志》卷十三「明月樓」條）。"]', '["夕照下西楼。","（均见《嘉泰吳兴志》卷十三「明月楼」條）。"]', '诗', 'shi', '', NULL, '正月十五夜翫月詩 三 范傳正 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('696b87aa-48f4-4335-9bc2-861fe9b548b6', '雲居寺', '云居寺', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["玉峰山下雲居寺，六百年來選佛場。","滿地白雲關不住，石泉流出落花香。","（見光緒元年刊支恒春纂《松陽縣志》卷十一）。"]', '["玉峰山下云居寺，六百年来選佛場。","满地白云关不住，石泉流出落花香。","（见光緒元年刊支恒春纂《松陽縣志》卷十一）。"]', '诗', 'shi', '', NULL, '雲居寺 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff14212f-cf65-447c-a9ff-ff12378d9f02', '奉酬竇三中丞見贈', '奉酬竇三中丞见贈', 'fe7fa319-0e96-45a3-9ede-8fae67115d67', '唐', '["多幸嘗陪侍玉墀，俄驚負譴阻天涯。","今日相逢問榮悴，更嗟年輩颯然衰。","（見《竇氏聯珠集·竇羣》附）（按：竇羣詩題爲《贈劉大兄院長》，劉詩下署「金州員外司馬劉伯翁」。","岑仲勉先生《唐人行第錄》疑即兩《唐書》皆有傳之劉伯芻，然二書均未載伯芻貶金州事，尚無從定論。","今仍題作劉伯翁，俟考詳。","）。"]', '["多幸嘗陪侍玉墀，俄驚負譴阻天涯。","今日相逢问榮悴，更嗟年輩颯然衰。","（见《竇氏聯珠集·竇羣》附）（按：竇羣诗題爲《贈劉大兄院长》，劉诗下署「金州員外司马劉伯翁」。","岑仲勉先生《唐人行第錄》疑即兩《唐书》皆有傳之劉伯芻，然二书均未載伯芻貶金州事，尚無從定論。","今仍題作劉伯翁，俟考詳。","）。"]', '诗', 'shi', '', NULL, '奉酬竇三中丞見贈 劉伯翁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89152e41-bf8a-4870-83ee-bf2fe254390e', '雲門寺（《禪》作「歸雲門」）', '云门寺（《禪》作「归云门」）', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["湖邊歸鶴（《禪》作「雁」）唳寥泬，僧房半倚秦峰缺。","雲生幽石何逍遙，泉去疎林幾嗚咽。","天寒猛虎叫巖月（《禪》作「雪」），松下無人空有雪（《禪》作「月」）。","千年像教人不聞，燒（《禪》作「焚」）香獨爲鬼神說。","（見《會稽掇英總集》卷七，以《古今禪藻集》卷三相校）。"]', '["湖邊归鹤（《禪》作「雁」）唳寥泬，僧房半倚秦峰缺。","云生幽石何逍遙，泉去疎林幾嗚咽。","天寒猛虎叫巖月（《禪》作「雪」），松下無人空有雪（《禪》作「月」）。","千年像教人不闻，燒（《禪》作「焚」）香独爲鬼神说。","（见《會稽掇英總集》卷七，以《古今禪藻集》卷三相校）。"]', '诗', 'shi', '', NULL, '雲門寺（《禪》作「歸雲門」） 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a781aa2b-af14-4da2-bbd7-d617b96f9481', '謫汀州', '謫汀州', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["青蠅爲弔客，黃耳（《紀事》作「黃犬」）寄家書。","（見《劉賓客文集》卷十九《澈上人文集紀》、《唐詩紀事》卷七二）。"]', '["青蠅爲弔客，黄耳（《紀事》作「黄犬」）寄家书。","（见《劉賓客文集》卷十九《澈上人文集紀》、《唐诗紀事》卷七二）。"]', '诗', 'shi', '', NULL, '謫汀州 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('701754c3-baf0-406d-85a7-effe45f1c329', '過秦松嶺', '過秦松嶺', 'e2ce53e7-0bac-4cd8-b75e-60768b0821be', '唐', '["散髮長林下，松風入太清。","空山容暮色，落葉起秋聲。","世險江天窄，雲深草木平。","從茲歸故土，勿作失羣鳴。","（《閩詩錄甲集》卷一）。"]', '["散髮长林下，松风入太清。","空山容暮色，落葉起秋声。","世險江天窄，云深草木平。","從茲归故土，勿作失羣鳴。","（《閩诗錄甲集》卷一）。"]', '诗', 'shi', '', NULL, '過秦松嶺 林藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b40f55aa-a982-4d9e-bb7f-82aad8914f7a', '答顏太守', '答顏太守', 'e2ce53e7-0bac-4cd8-b75e-60768b0821be', '唐', '["物力孤窮甚，無由蔽草廬。","抱疴明盛世，丐食兵荒餘。","馬革藏身拙，鴟夷報主疎。","勉哉吾二子，太歲易消除。","（見《王氏刊唐人集》收《林邵州遺集》，注云：「見鄭王臣《莆風清籟集》。","」）。"]', '["物力孤窮甚，無由蔽草廬。","抱疴明盛世，丐食兵荒餘。","马革藏身拙，鴟夷報主疎。","勉哉吾二子，太歲易消除。","（见《王氏刊唐人集》收《林邵州遺集》，注云：「见鄭王臣《莆风清籟集》。","」）。"]', '诗', 'shi', '', NULL, '答顏太守 林藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c7a7fb3-ba6b-4079-8848-d82c80128a32', '長句贈微之（題擬）', '长句贈微之（題擬）', '591ee30a-a2a6-4d30-a5d1-6a17be2fd338', '唐', '["靈溪試爲訪金丹。","（見《元氏長慶集》卷十六《天壇上境》題注引）。"]', '["靈溪試爲訪金丹。","（见《元氏长慶集》卷十六《天壇上境》題注引）。"]', '诗', 'shi', '', NULL, '長句贈微之（題擬） 馬逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5da00cac-9544-442b-b14f-1231ed6f5075', '大滌山（題擬）', '大滌山（題擬）', '57b73308-199d-4dcd-83ab-5e73b5178c21', '唐', '["天壇絕頂山，髣髴翠微間。","跡久苔紋碎，雲根古木閒。","丹成人已去，鶴駕未曾還。","猶有簫吹響，時時下舊山。","（見《咸淳臨安志》卷二四）（按：《全唐詩補逸》卷十八據《洞霄詩集》收《天壇》，爲此詩之別本，然四十字中有二十八字不同，今重錄。","《咸淳臨安志》收《大滌洞》一首，首三句與《全唐詩補逸》不同，錄如次：「靈山實秀德，仙聖杳難親。","水溜空巖石，……」餘同，不錄。","）。"]', '["天壇絕頂山，髣髴翠微间。","跡久苔紋碎，云根古木閒。","丹成人已去，鹤駕未曾還。","猶有簫吹响，时时下旧山。","（见《咸淳臨安志》卷二四）（按：《全唐诗補逸》卷十八據《洞霄诗集》收《天壇》，爲此诗之別本，然四十字中有二十八字不同，今重錄。","《咸淳臨安志》收《大滌洞》一首，首三句與《全唐诗補逸》不同，錄如次：「靈山實秀德，仙聖杳难親。","水溜空巖石，……」餘同，不錄。","）。"]', '诗', 'shi', '', NULL, '大滌山（題擬） 白元鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaeb58f6-a5a0-48b4-8154-6b657f0597d4', '法堂', '法堂', '57b73308-199d-4dcd-83ab-5e73b5178c21', '唐', '["高蹤遺可繼，虛室即流塵。","越國曾封邑，蓬萊早會真。","餘風生戶牖，殘影照江濱。","化鶴年猶遠，空悲雲水親。","（影印本《詩淵》第三冊第一五六九頁）。"]', '["高蹤遺可繼，虛室即流塵。","越国曾封邑，蓬萊早會真。","餘风生戶牖，殘影照江濱。","化鹤年猶远，空悲云水親。","（影印本《诗淵》第三冊第一五六九頁）。"]', '诗', 'shi', '', NULL, '法堂 白元鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c52c91e2-80c0-4550-927f-dc048b50e762', '新池', '新池', '57b73308-199d-4dcd-83ab-5e73b5178c21', '唐', '["昔嘗遊勝境，今喜盡幽蹤。","丹滿鏡潭色，雲疏錦磧容。","響中聞細溜，波裏見喬松。","唯廣花源賞，人間不可逢。","（同前第二○四三頁）。"]', '["昔嘗游勝境，今喜尽幽蹤。","丹满镜潭色，云疏錦磧容。","响中闻細溜，波裏见喬松。","唯廣花源賞，人间不可逢。","（同前第二○四三頁）。"]', '诗', 'shi', '', NULL, '新池 白元鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c0b3f6c-d811-4171-b86f-01ad77f20e62', '瀑布', '瀑布', '57b73308-199d-4dcd-83ab-5e73b5178c21', '唐', '["太極生柔德，雄姿不可名。","淩空虹永掛，瀉澗布長成。","映日添霞色，當風振浪聲。","潺潺雲水下，已得滌幽情。","（同前第二一八○頁）（按：《全唐詩補逸》卷十八收白詩，有《講堂》、《瀑布》、《新池》諸詩，但內容均不同。","）。"]', '["太極生柔德，雄姿不可名。","淩空虹永掛，瀉澗布长成。","映日添霞色，當风振浪声。","潺潺云水下，已得滌幽情。","（同前第二一八○頁）（按：《全唐诗補逸》卷十八收白诗，有《講堂》、《瀑布》、《新池》諸诗，但內容均不同。","）。"]', '诗', 'shi', '', NULL, '瀑布 白元鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dccf1672-c359-4746-b9ee-fd10bcdbc203', '偈', '偈', '4d860609-2a1b-441f-b3c7-e08cbfb29859', '唐', '["獨絃琴子爲君彈，松栢長青不怕（《宋高僧傳》作「怯」）寒。","金鑛相和性自別，任向君前試取看。","（見《祖堂集》卷十五、《宋高僧傳》卷二一）。"]', '["独絃琴子爲君彈，松栢长青不怕（《宋高僧傳》作「怯」）寒。","金鑛相和性自別，任向君前試取看。","（见《祖堂集》卷十五、《宋高僧傳》卷二一）。"]', '诗', 'shi', '', NULL, '偈 隱峯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d1b452c-66cd-4e4e-96c3-570f07597d33', '臨化示偈（題擬）', '臨化示偈（題擬）', '8d3b3393-ce95-4b6f-9956-c9cf9e29b792', '唐', '["八十年來辨東西（《五燈會元》作「西東」），如今不要白頭公（《五燈會元》作「翁」）。","非長非短非大小，還與諸人性相同。","無來無去兼無住，了却本來自性空。","（見《祖堂集》卷十五、《五燈會元》卷三）。"]', '["八十年来辨东西（《五灯會元》作「西东」），如今不要白头公（《五灯會元》作「翁」）。","非长非短非大小，還與諸人性相同。","無来無去兼無住，了却本来自性空。","（见《祖堂集》卷十五、《五灯會元》卷三）。"]', '诗', 'shi', '', NULL, '臨化示偈（題擬） 無了 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75cf76a5-c159-49d3-9689-07635475fce7', '讚馬氏子', '讚马氏子', '9e257a93-a3c8-4035-b4fc-48c1ee755065', '唐', '["豐姿窈窕鬢欲斜，賺煞郎君念法華。","一把骨頭挑去後，不知明月落誰家。","（見《全閩詩話》卷十二引《感應傳》）。"]', '["豐姿窈窕鬢欲斜，賺煞郎君念法华。","一把骨头挑去後，不知明月落誰家。","（见《全閩诗話》卷十二引《感應傳》）。"]', '诗', 'shi', '', NULL, '讚馬氏子 粲和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c84ef65e-df87-4fe7-9273-d58b7f6ff528', '零陵寺井欄讚', '零陵寺井欄讚', 'f6d7cf6a-f3cc-42a9-9c16-870e0c94399a', '唐', '["此是南山石，將來造井欄。","流傳千萬代，各結佛家緣。","盡意修功德，應無朽壞年。","同霑勝福者，超于彌勒前。","（《江蘇金石志》卷五、《寶鐵齋金石文字跋尾》卷上、《靈芬館詩話》卷六）。"]', '["此是南山石，將来造井欄。","流傳千万代，各結佛家緣。","尽意修功德，應無朽壞年。","同霑勝福者，超于彌勒前。","（《江蘇金石志》卷五、《寶鐵斋金石文字跋尾》卷上、《靈芬館诗話》卷六）。"]', '诗', 'shi', '', NULL, '零陵寺井欄讚 郭通 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d08a0431-1d8c-482e-a279-1b4db9ef2c7f', '夜', '夜', '34dd0de2-8d07-46a8-b8cc-0c6be57b71cb', '唐', '["久絕白雲信，愁心如水長。","蛩鳴萬戶月，鴉步一溪霜。","不識紅塵險，安知皓首狂。","擣衣中夜望，今古事尋常。","（《莆風清籟集》卷一）。"]', '["久絕白云信，愁心如水长。","蛩鳴万戶月，鴉步一溪霜。","不識紅塵險，安知皓首狂。","擣衣中夜望，今古事尋常。","（《莆风清籟集》卷一）。"]', '诗', 'shi', '', NULL, '夜 林藻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c43298a-fdba-4617-9e8e-d149526ac25a', '晚泊鄞陽', '晚泊鄞陽', '34dd0de2-8d07-46a8-b8cc-0c6be57b71cb', '唐', '["孤帆高樓鄞陽城，萬頃清流一應聲。","青鬢初隨衰草謝，白雲還傍故山行。","夢中美酒酬枚乘，江上秋風屬屈平。","愧我一生潦倒甚，全無佳句答長庚。","（同前）。"]', '["孤帆高楼鄞陽城，万頃清流一應声。","青鬢初隨衰草謝，白云還傍故山行。","梦中美酒酬枚乘，江上秋风屬屈平。","愧我一生潦倒甚，全無佳句答长庚。","（同前）。"]', '诗', 'shi', '', NULL, '晚泊鄞陽 林藻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8098d8ef-7329-4cdc-ba0e-afc1baf9343f', '爲樵', '爲樵', '34dd0de2-8d07-46a8-b8cc-0c6be57b71cb', '唐', '["致政慚輕舉，爲樵亦易窮。","文章還古道，禮數逐秋風。","獨鶴千松下，萬航一水中。","最憐當路草，衰敗與人同。","（《莆風清籟集》卷六十）。"]', '["致政慚轻舉，爲樵亦易窮。","文章還古道，禮數逐秋风。","独鹤千松下，万航一水中。","最怜當路草，衰敗與人同。","（《莆风清籟集》卷六十）。"]', '诗', 'shi', '', NULL, '爲樵 林藻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0bfa33c-dca3-4f70-8ce6-8c6f78759376', '題桂林七星巖棲霞洞詩（題擬）', '題桂林七星巖棲霞洞诗（題擬）', 'c67ed179-4df9-40b4-9bb1-092ae7e0befe', '唐', '["石古苔痕厚，巖深日影悠。","參禪因久坐，老佛總無愁。","（見桂林市文物管理局編《桂林石刻》第一冊）（按：《桂林石刻》編者注：「右摩崖在七星巖口，高一尺五寸，寬九寸，徑一寸五分。","原石已毀，據舊搨本校錄。","」詩末署「釋懷信書」。","同書又載《南溪山元巖磨崖題名》云：「懷信、覺救、惟則、惟亮、無等、無業，元和十二年九同遊。","業記。","」今據以確定作者之時代。","《宋高僧傳》卷十九有《唐揚州西靈塔寺懷信傳》，爲會昌間人。","時代雖相接，然無從證明即此詩作者，故不取。","）。"]', '["石古苔痕厚，巖深日影悠。","參禪因久坐，老佛總無愁。","（见桂林市文物管理局編《桂林石刻》第一冊）（按：《桂林石刻》編者注：「右摩崖在七星巖口，高一尺五寸，寬九寸，徑一寸五分。","原石已毀，據旧搨本校錄。","」诗末署「釋懷信书」。","同书又載《南溪山元巖磨崖題名》云：「懷信、覺救、惟則、惟亮、無等、無業，元和十二年九同游。","業記。","」今據以確定作者之时代。","《宋高僧傳》卷十九有《唐揚州西靈塔寺懷信傳》，爲會昌间人。","时代雖相接，然無從證明即此诗作者，故不取。","）。"]', '诗', 'shi', '', NULL, '題桂林七星巖棲霞洞詩（題擬） 懷信 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13ef86ad-f91d-4cd8-b9dd-9fc9ea7f5a13', '石塘路有懷院中諸公', '石塘路有懷院中諸公', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["迴合千峰裏，晴光似畫圖。","征車隨反照，候吏暎寒蕪。","石瀨侵行徑，溪雲拂路隅。","未酬知己分，寧敢學潛夫。","。"]', '["迴合千峰裏，晴光似畫圖。","征车隨反照，候吏暎寒蕪。","石瀨侵行徑，溪云拂路隅。","未酬知己分，寧敢学潛夫。","。"]', '诗', 'shi', '', NULL, '石塘路有懷院中諸公 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92104bfa-69cf-4f80-b450-211ee30081b4', '曉發桐廬', '晓發桐廬', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["客路去漫漫，桐溪上水灘。","扣船乘曉月，欹枕聽迴灘。","煙重江楓濕，沙平宿鷺寒。","閑吟試一望，疑在畫屏看。","（均見《四部叢刊》本《權載之文集》卷六）。"]', '["客路去漫漫，桐溪上水灘。","扣船乘晓月，欹枕听迴灘。","煙重江楓濕，沙平宿鷺寒。","闲吟試一望，疑在畫屏看。","（均见《四部叢刊》本《權載之文集》卷六）。"]', '诗', 'shi', '', NULL, '曉發桐廬 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('388fbdfc-ca06-4c12-9798-74b48d02c4d6', '越州觀察使差人問師以禪住持依律住持師以偈答', '越州观察使差人问師以禪住持依律住持師以偈答', '209806b3-a4a1-4d35-8ad7-daef0074fb77', '唐', '["寂寂不持律，滔滔不坐禪。","儼茶兩三垸，意在钁頭邊。","（見《祖堂集》卷十五）。"]', '["寂寂不持律，滔滔不坐禪。","儼茶兩三垸，意在钁头邊。","（见《祖堂集》卷十五）。"]', '诗', 'shi', '', NULL, '越州觀察使差人問師以禪住持依律住持師以偈答 靈默 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c3a9493-2be2-4fcc-92c2-83726b3e5241', '牧護歌', '牧護歌', '4132cdeb-6a47-48d2-ac8c-1e9eb2f2233b', '唐', '["聽說衲僧牧護，任運逍遙無住。","一條百納瓶盂，便是生涯調度。","爲求至理參尋，不憚寒暑辛苦。","還曾四海周遊，山水風雲滿肚。","內除戒律精嚴，不學威儀行步。","三乘笑我無能，我笑三乘謾做。","智人權立階梯，大道本無迷悟。","達者不假修治，不在能言能語。","披麻目視雲霄，遮莫王侯不顧。","道人本體如然，不是知佛去處。","生也猶如著衫，死也還同脫袴。","生也無喜無憂，八風豈能驚怖。","外相猶似癡人，肚裏非常峭措。","活計原無一錢，敢與君王鬬富。","愚人擺手憎嫌，智者點頭相許。","那知傀儡牽抽，歌舞盡由行主。","一言爲報諸人，打破畫瓶歸去。","（《景德傳燈錄》卷三十）（按：此詩原署云：「蘇溪和尚，即五洩小師也。","」）。"]', '["听说衲僧牧護，任運逍遙無住。","一條百納瓶盂，便是生涯調度。","爲求至理參尋，不憚寒暑辛苦。","還曾四海周游，山水风云满肚。","內除戒律精嚴，不学威儀行步。","三乘笑我無能，我笑三乘謾做。","智人權立階梯，大道本無迷悟。","達者不假修治，不在能言能語。","披麻目視云霄，遮莫王侯不顧。","道人本體如然，不是知佛去处。","生也猶如著衫，死也還同脫袴。","生也無喜無憂，八风豈能驚怖。","外相猶似癡人，肚裏非常峭措。","活計原無一錢，敢與君王鬬富。","愚人擺手憎嫌，智者点头相許。","那知傀儡牽抽，歌舞尽由行主。","一言爲報諸人，打破畫瓶归去。","（《景德傳灯錄》卷三十）（按：此诗原署云：「蘇溪和尚，即五洩小師也。","」）。"]', '诗', 'shi', '', NULL, '牧護歌 蘇溪和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5c09fcc-4307-43c3-affb-c171d8368dd0', '坐禪銘', '坐禪銘', 'e0987086-57d5-4b5c-8a94-36868ce5d22d', '唐', '["參禪學道幾般樣，要在當人能擇上。","莫只忘形與死心，此箇難醫病最深。","直須坐究探淵源，此道古今天下傳。","正坐端然如泰山，巍巍不要守空閑。","直須提起吹毛利，要剖西來第一義。","瞠却眼兮剔起眉，反覆看渠渠是誰。","還如捉賊須見贓，不怕賊理深處藏。","有智捉獲剎那頃，無智經年不見影。","深嗟兀坐常如死，千年萬歲只如此。","若將此等當禪宗，拈花微笑喪家風。","黑山下坐死水浸，大地漫漫如何禁。","若是鐵眼銅睛漢，把手心頭能自判。","直須著到悟爲期，哮吼一聲獅子兒。","君不見磨磚作鏡喻有由，車不行兮在打牛。","又不見巖前湛水萬丈清，沈沈寂寂杳無聲。","一朝魚龍來攪動，波翻浪湧真堪重。","譬如靜坐不用工，何年及第悟心空？","急下手兮高著眼，管取今生教了辦。","若還默默恣如愚，知君未解作工夫。","抖擻精神著意看，無形無影悟不難。","此是十分真用意，勇猛丈夫却須記。","切莫聽道不須參，古聖孜孜爲指南。","雖然舊閣閑田地，一度贏來得也未。","要識坐禪不動尊，風行草偃悉皆論。","而今四海清如鏡，頭頭物物皆吾聽。","長短方圓只自知，從來絲髮不曾移。","若問坐禪成底事，日出東方夜落西。","（《緇門警訓》卷二）。"]', '["參禪学道幾般樣，要在當人能擇上。","莫只忘形與死心，此箇难醫病最深。","直須坐究探淵源，此道古今天下傳。","正坐端然如泰山，巍巍不要守空闲。","直須提起吹毛利，要剖西来第一義。","瞠却眼兮剔起眉，反覆看渠渠是誰。","還如捉賊須见贓，不怕賊理深处藏。","有智捉獲剎那頃，無智經年不见影。","深嗟兀坐常如死，千年万歲只如此。","若將此等當禪宗，拈花微笑喪家风。","黑山下坐死水浸，大地漫漫如何禁。","若是鐵眼銅睛漢，把手心头能自判。","直須著到悟爲期，哮吼一声獅子兒。","君不见磨磚作镜喻有由，车不行兮在打牛。","又不见巖前湛水万丈清，沈沈寂寂杳無声。","一朝鱼龙来攪动，波翻浪湧真堪重。","譬如静坐不用工，何年及第悟心空？","急下手兮高著眼，管取今生教了辦。","若還默默恣如愚，知君未解作工夫。","抖擻精神著意看，無形無影悟不难。","此是十分真用意，勇猛丈夫却須記。","切莫听道不須參，古聖孜孜爲指南。","雖然旧閣闲田地，一度贏来得也未。","要識坐禪不动尊，风行草偃悉皆論。","而今四海清如镜，头头物物皆吾听。","长短方圓只自知，從来絲髮不曾移。","若问坐禪成底事，日出东方夜落西。","（《緇门警訓》卷二）。"]', '诗', 'shi', '', NULL, '坐禪銘 大義 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad966410-467f-4374-9aea-512c36703ac1', '頌', '頌', 'e0987086-57d5-4b5c-8a94-36868ce5d22d', '唐', '["直下識玄旨，羅紋結角是。","不識玄旨人，徒勞逐所示。","䲺䲺鳥，守空池，魚從脚下過，䲺䲺總不知。","（見《祖堂集》卷十五）。"]', '["直下識玄旨，羅紋結角是。","不識玄旨人，徒勞逐所示。","䲺䲺鸟，守空池，鱼從脚下過，䲺䲺總不知。","（见《祖堂集》卷十五）。"]', '诗', 'shi', '', NULL, '頌 大義 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5097365-c21b-438c-b8fb-649dfc843ba8', '偈', '偈', 'b6aaff99-5e7e-4835-a95a-3c26a10796c3', '唐', '["三千里路禮師顏，師已歸真塔已關。","鬼神哭泣嗟無主，空山只見水潺湲。","（見《江西詩徵》卷八七）。"]', '["三千里路禮師顏，師已归真塔已关。","鬼神哭泣嗟無主，空山只见水潺湲。","（见《江西诗徵》卷八七）。"]', '诗', 'shi', '', NULL, '偈 新羅僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df70a211-0607-416b-a5f8-5548a892431f', '催妝詩', '催妝诗', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["舜耕餘草木，禹鑿舊山川。","（見《說郛》卷三二高懌《羣居解頤》、卷六五宋無和子《善謔集》、《古今說海》本陸游《避暑漫抄》引《解頤》）。"]', '["舜耕餘草木，禹鑿旧山川。","（见《说郛》卷三二高懌《羣居解頤》、卷六五宋無和子《善謔集》、《古今说海》本陸游《避暑漫抄》引《解頤》）。"]', '诗', 'shi', '', NULL, '催妝詩 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdde7968-530e-4272-aaba-9cc10bd0b131', '弄珠吟', '弄珠吟', 'c97edbb1-a5ec-412d-939f-11c22163a1da', '唐', '["落落明珠耀百千，森蘿萬像鏡中懸。","光透三千越大千，四生六類一靈源。","凡聖聞珠誰不羨，瞥起心求渾不見。","對面看珠不識珠，尋珠逐物當時變。","千般萬般況珠喻，珠離百非超四句。","只這珠生是不生，非爲無生珠始住。","如意珠，大圓鏡，亦有人中（《宗》作「中人」）喚作性。","分身百億我珠分，無始本淨如今淨。","日用真珠是佛陀，何勞逐物浪波波。","隱現則（《宗》作「即」）今無二相，對面看珠識得摩（《宗》作「麽」）。","（見《祖堂集》卷十四，《宗鏡錄》卷十一收末九句）。"]', '["落落明珠耀百千，森蘿万像镜中懸。","光透三千越大千，四生六類一靈源。","凡聖闻珠誰不羨，瞥起心求渾不见。","对面看珠不識珠，尋珠逐物當时变。","千般万般況珠喻，珠離百非超四句。","只這珠生是不生，非爲無生珠始住。","如意珠，大圓镜，亦有人中（《宗》作「中人」）喚作性。","分身百億我珠分，無始本淨如今淨。","日用真珠是佛陀，何勞逐物浪波波。","隐現則（《宗》作「即」）今無二相，对面看珠識得摩（《宗》作「麽」）。","（见《祖堂集》卷十四，《宗镜錄》卷十一收末九句）。"]', '诗', 'shi', '', NULL, '弄珠吟 慧藏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b4a5ffd-678e-45f4-94ea-37603690e60f', '', '', '70e505fd-b8f7-487e-b36b-2e1c198b750f', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 米嶺和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ef71ad9-28ff-4a01-a13d-715a489a2272', '遺偈', '遺偈', '70e505fd-b8f7-487e-b36b-2e1c198b750f', '唐', '["祖祖不思議，不許常住世。","大衆審思惟，畢竟祇這是。","（《景德傳燈錄》卷八、《五燈會元》卷三）。"]', '["祖祖不思議，不許常住世。","大衆審思惟，畢竟祇這是。","（《景德傳灯錄》卷八、《五灯會元》卷三）。"]', '诗', 'shi', '', NULL, '遺偈 米嶺和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('482c4ed8-01c9-432a-bd5f-51485cdd223a', '冶山二十詠（幷序） 天泉池', '冶山二十詠（幷序） 天泉池', 'eda8859e-9966-4023-a1b9-50d617792769', '唐', '["魚鱗息枯池，廣之使涵泳。","疏鑿得蒙泉，澄明覩明鏡。","（《淳熙三山志》卷一）（按：《淳熙三山志》云：「唐元和八年，刺史裴次元于其〖指冶山〗南闢爲毬場，即山爲亭，作詩題于其壁。","」次錄其序之大略，幷云二十首的詩題是：《望京山》、《觀海亭》、《雙檜嶺》、《登山路》、《天泉池》、《翫琴臺》、《筯竹巖》、《枇杷川》、《荻蘆崗》、《桃花塢》、《芳茗原》、《山陰亭》、《含清洞》、《紅蕉坪》、《越壑橋》、《獨秀峰》、《篔簹坳》、《八角亭》、《椒盤石》、《白土谷》。","詩各一章，章六句。","今存者惟《淳熙三山志》所錄之《天泉池》四句及《望京樓》二句，後者已收入《全唐詩》卷四六六。","《淳熙三山志》另錄馮審所作記。","）。"]', '["鱼鱗息枯池，廣之使涵泳。","疏鑿得蒙泉，澄明覩明镜。","（《淳熙三山志》卷一）（按：《淳熙三山志》云：「唐元和八年，刺史裴次元于其〖指冶山〗南闢爲毬場，即山爲亭，作诗題于其壁。","」次錄其序之大略，幷云二十首的诗題是：《望京山》、《观海亭》、《雙檜嶺》、《登山路》、《天泉池》、《翫琴台》、《筯竹巖》、《枇杷川》、《荻蘆崗》、《桃花塢》、《芳茗原》、《山陰亭》、《含清洞》、《紅蕉坪》、《越壑橋》、《独秀峰》、《篔簹坳》、《八角亭》、《椒盤石》、《白土谷》。","诗各一章，章六句。","今存者惟《淳熙三山志》所錄之《天泉池》四句及《望京楼》二句，後者已收入《全唐诗》卷四六六。","《淳熙三山志》另錄馮審所作記。","）。"]', '诗', 'shi', '', NULL, '冶山二十詠（幷序） 天泉池 裴次元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5a33b6e-86e7-4550-b63f-58fe096ed97b', '', '', '798a8425-088f-47b0-b8f1-44ef6fc92372', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 李直方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68480a0c-827d-466e-ae02-c05e048d58e6', '句', '句', '798a8425-088f-47b0-b8f1-44ef6fc92372', '唐', '["峴山依舊遠，漢水遶城流。","（見《輿地紀勝》卷八二《襄陽府》）。"]', '["峴山依旧远，漢水遶城流。","（见《輿地紀勝》卷八二《襄陽府》）。"]', '诗', 'shi', '', NULL, '句 李直方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de40ad3f-6a45-41d1-ba7c-266f0f0b447f', '壺公山', '壺公山', 'a496f5b7-7e38-4645-95b7-a4c1f9e6244d', '唐', '["雙旌牧清源，吟看壺公翠。","（見黃滔《黃御史公集》卷四《壺公山》詩注、《輿地紀勝》卷一三五、《莆陽比事》卷一、《記纂淵海》卷十）。"]', '["雙旌牧清源，吟看壺公翠。","（见黄滔《黄御史公集》卷四《壺公山》诗注、《輿地紀勝》卷一三五、《莆陽比事》卷一、《記纂淵海》卷十）。"]', '诗', 'shi', '', NULL, '壺公山 潘存實 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63986f07-a554-460e-8021-a8cc32f62f6e', '九日夜', '九日夜', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["燈下竹煙看更碧，月間花色不分紅。","（《千載佳句》卷上《天象部·夜》）。"]', '["灯下竹煙看更碧，月间花色不分紅。","（《千載佳句》卷上《天象部·夜》）。"]', '诗', 'shi', '', NULL, '九日夜 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a93ea851-c7ad-49b4-9b3f-c3751ac8bc78', '答問附歌', '答问附歌', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["堯舜之修兮，禹益之憂兮，能者任而愚者休兮。","蹮蹮蓬藋，樂吾（一作「夫」）囚兮，文墨之彬彬（一本作「申申」），足以申吾愁兮。","已乎已乎，曷之求乎！（見《柳河東集》卷十五）。"]', '["堯舜之修兮，禹益之憂兮，能者任而愚者休兮。","蹮蹮蓬藋，乐吾（一作「夫」）囚兮，文墨之彬彬（一本作「申申」），足以申吾愁兮。","已乎已乎，曷之求乎！（见《柳河东集》卷十五）。"]', '诗', 'shi', '', NULL, '答問附歌 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7356ac5-7155-426c-9c77-b2d58924e4e3', '送賈山人南遊歌（幷序）', '送賈山人南游歌（幷序）', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["充乎其居，或以匱己之虛，（一作「或躓其塗，匱乎己之虛」。","蜀本云：「或以」字下疑脫「兩」字）。","或盈其廬。","孰匱孰充，爲泰爲窮，君子烏乎取以寧其躬！若君者之於道而已爾，世孰知其從容耶！（見《柳河東集》卷二五）。"]', '["充乎其居，或以匱己之虛，（一作「或躓其塗，匱乎己之虛」。","蜀本云：「或以」字下疑脫「兩」字）。","或盈其廬。","孰匱孰充，爲泰爲窮，君子烏乎取以寧其躬！若君者之於道而已爾，世孰知其從容耶！（见《柳河东集》卷二五）。"]', '诗', 'shi', '', NULL, '送賈山人南遊歌（幷序） 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('292023d3-faf8-494b-a865-91bd027b2f3b', '送元暠師詩（幷序）', '送元暠師诗（幷序）', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["侯門辭必服，忍位取悲增。","去魯心猶在，從周力未能。","家山餘五柳，人世遍千燈。","莫讓金錢施，無生道自弘。","（中華書局校點本《柳宗元集》附錄《外集補遺》錄自宋乾道永州本《柳柳州外集》）。"]', '["侯门辞必服，忍位取悲增。","去魯心猶在，從周力未能。","家山餘五柳，人世遍千灯。","莫讓金錢施，無生道自弘。","（中华书局校点本《柳宗元集》附錄《外集補遺》錄自宋乾道永州本《柳柳州外集》）。"]', '诗', 'shi', '', NULL, '送元暠師詩（幷序） 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e08606f6-74f2-4291-a196-2893bc523ea7', '秋懷', '秋懷', '74ec0f85-5580-4ec3-a008-602655cee7d5', '唐', '["嫋嫋芙蓉枝，灼灼當秋好。","嚴霜一以冽，日夜色枯槁。","詎惟華葉衰，柯條不自保。","斬刈同束薪，秋江迹如掃。","時事多推移，江流去浩浩。","（見民國二十年戴鴻熙纂《湯溪縣志》卷十九）。"]', '["嫋嫋芙蓉枝，灼灼當秋好。","嚴霜一以冽，日夜色枯槁。","詎惟华葉衰，柯條不自保。","斬刈同束薪，秋江迹如掃。","时事多推移，江流去浩浩。","（见民国二十年戴鴻熙纂《湯溪縣志》卷十九）。"]', '诗', 'shi', '', NULL, '秋懷 滕倪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebd40ecb-2d6b-4a13-ac99-f8aebf258686', '月桂', '月桂', '73e7ca05-f35a-4db2-b9bb-a79ed4cdc7bd', '唐', '["片月轉洪濛，扶疎萬古同。","根非生下土，葉不墜西風。","每向圓時足，還隨缺處空。","影令羣木外，香滿一輪[中]（木）。","未種丹霄日，應虛白兔宮。","何時得羽化，細得問元宮。","（見《古今合璧事類備要前集》卷一）。"]', '["片月轉洪濛，扶疎万古同。","根非生下土，葉不墜西风。","每向圓时足，還隨缺处空。","影令羣木外，香满一輪[中]（木）。","未種丹霄日，應虛白兔宮。","何时得羽化，細得问元宮。","（见《古今合璧事類備要前集》卷一）。"]', '诗', 'shi', '', NULL, '月桂 李正封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43cb6959-228d-4f35-8cc3-4a3a92eb083f', '句', '句', '73e7ca05-f35a-4db2-b9bb-a79ed4cdc7bd', '唐', '["三月後方有，百花中更無。","（見《錦繡萬花谷前集》卷七）。"]', '["三月後方有，百花中更無。","（见《錦繡万花谷前集》卷七）。"]', '诗', 'shi', '', NULL, '句 李正封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10ee82aa-b836-44bf-b577-6c43299964d7', '欲歸山留別韓潮州愈偈', '欲归山留別韓潮州愈偈', 'a19102f1-d826-4bde-8d37-a58ce0e52331', '唐', '["辭君莫恠歸山早，爲憶松蘿對月宮。","臺殿不將金鏁閉，來時自有白雲封。","（見《祖堂集》卷五）。"]', '["辞君莫恠归山早，爲憶松蘿对月宮。","台殿不將金鏁閉，来时自有白云封。","（见《祖堂集》卷五）。"]', '诗', 'shi', '', NULL, '欲歸山留別韓潮州愈偈 大顛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8409991-fa99-41ad-ac97-d310c699c4e0', '洗鉢潭', '洗鉢潭', '293b58bd-4a17-4fd7-87d6-24f4aa30769b', '唐', '["潭水澄初地，長爲洗鉢供。","已能降虎豹，不問攬魚龍。","濺沫溪莎碧，疏流石瀨重。","此中清淨理，繼跡有禪宗。"]', '["潭水澄初地，长爲洗鉢供。","已能降虎豹，不问攬鱼龙。","濺沫溪莎碧，疏流石瀨重。","此中清淨理，繼跡有禪宗。"]', '诗', 'shi', '', NULL, '洗鉢潭 邢允中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7516bc7a-17ad-49a1-9758-5f58a3e75680', '駐錫峯', '駐錫峯', '293b58bd-4a17-4fd7-87d6-24f4aa30769b', '唐', '["高峯常駐錫，靈異見當年。","卓立驚沙界，光輝動梵天。","鶴飛青靄外，龍護赤嵐邊。","丈室仍相對，重來果夙緣。","（見董慶酉《四明詩幹》卷中。","邢允中詩承張靖龍同志錄示）。"]', '["高峯常駐錫，靈異见當年。","卓立驚沙界，光輝动梵天。","鹤飞青靄外，龙護赤嵐邊。","丈室仍相对，重来果夙緣。","（见董慶酉《四明诗幹》卷中。","邢允中诗承張靖龙同志錄示）。"]', '诗', 'shi', '', NULL, '駐錫峯 邢允中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dabd1488-a0f5-4607-bfc1-3abbccea5536', '禹廟神座頃服金紫苹自到鎮申牒禮司重加袞冕今因祈雨偶成八韻', '禹廟神座頃服金紫苹自到鎮申牒禮司重加袞冕今因祈雨偶成八韻', '73bed79b-f3a2-4185-981c-d6d76d366e0e', '唐', '["玉座新規盛，金章舊制非。","列城初執禮，清廟重垂衣。","不覩千箱詠，翻愁五稼微。","祇將蘋藻潔，寧在餼牢肥。","徙市行應謬，焚巫事亦違，至誠期必感，昭報意猶希。","海日明朱檻，谿煙濕畫旗。","迴瞻郡城路，未欲背山歸。","（《會稽掇英總集》卷八）（〖1〗《歐陽文忠公文集》卷一四二《集古錄跋尾》卷九《唐薛苹唱和詩》〖大和中〗云：「右薛苹唱和詩，其間馮宿、馮定、李紳皆唐顯人，靈澈以詩名後世，皆人所想見者，然詩皆不及苹，豈唱者得於自然，和者牽於強作耶！」〖2〗《寶刻叢編》卷十三引歐陽棐《集古錄目》云：「《唐禹廟詩》，唐浙東觀察使越州刺史薛苹詩，不著書人名氏。","苹初至鎮，易禹廟金紫服以冠冕，後因祈雨，作此詩，其和者鹽鐵轉運崔述等凡十七首。","」按：岑仲勉先生《貞石證史·薛苹唱和詩即禹廟詩》對此詩考證甚詳，可參看。","惟訂歐陽修云「大和中」刻石爲誤，實未察《集古錄跋尾》著錄年歲，爲刻石時間而非寫作時間，爲小疵耳。","）。"]', '["玉座新規盛，金章旧制非。","列城初執禮，清廟重垂衣。","不覩千箱詠，翻愁五稼微。","祇將蘋藻潔，寧在餼牢肥。","徙市行應謬，焚巫事亦違，至誠期必感，昭報意猶希。","海日明朱檻，谿煙濕畫旗。","迴瞻郡城路，未欲背山归。","（《會稽掇英總集》卷八）（〖1〗《歐陽文忠公文集》卷一四二《集古錄跋尾》卷九《唐薛苹唱和诗》〖大和中〗云：「右薛苹唱和诗，其间馮宿、馮定、李紳皆唐显人，靈澈以诗名後世，皆人所想见者，然诗皆不及苹，豈唱者得於自然，和者牽於強作耶！」〖2〗《寶刻叢編》卷十三引歐陽棐《集古錄目》云：「《唐禹廟诗》，唐浙东观察使越州刺史薛苹诗，不著书人名氏。","苹初至鎮，易禹廟金紫服以冠冕，後因祈雨，作此诗，其和者鹽鐵轉運崔述等凡十七首。","」按：岑仲勉先生《貞石證史·薛苹唱和诗即禹廟诗》对此诗考證甚詳，可參看。","惟訂歐陽修云「大和中」刻石爲誤，實未察《集古錄跋尾》著錄年歲，爲刻石时间而非寫作时间，爲小疵耳。","）。"]', '诗', 'shi', '', NULL, '禹廟神座頃服金紫苹自到鎮申牒禮司重加袞冕今因祈雨偶成八韻 薛苹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('037f89ed-b9ed-4a75-acce-90a4edb6e3ca', '謁禹廟', '謁禹廟', '4b3fbce1-81d3-4766-ade2-db5323499154', '唐', '["（按：崔詞疑即與薛苹同題禹廟十七人之一。","）惟舜禪功始，惟堯錫命初。","九州方奠畫，萬壑遂橫疏。","受籙嘗開洞，過門不下車。","諸侯會玉帛，滄海薦圖書。","玄默將遺世，崇高亦厭居。","耘田自有鳥，濬澤豈爲魚。","家及三王嗣，殷囚百代如。","靈容肅清宇，袞服閉荒墟。","棗徑愁雲暮，松扉撤祭餘。","叨榮陵寢邑，懷古益躊躇。","（見《會稽掇英總集》卷八）。"]', '["（按：崔词疑即與薛苹同題禹廟十七人之一。","）惟舜禪功始，惟堯錫命初。","九州方奠畫，万壑遂橫疏。","受籙嘗开洞，過门不下车。","諸侯會玉帛，滄海薦圖书。","玄默將遺世，崇高亦厭居。","耘田自有鸟，濬澤豈爲鱼。","家及三王嗣，殷囚百代如。","靈容肅清宇，袞服閉荒墟。","棗徑愁云暮，松扉撤祭餘。","叨榮陵寢邑，懷古益躊躇。","（见《會稽掇英總集》卷八）。"]', '诗', 'shi', '', NULL, '謁禹廟 崔詞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91c0b434-e230-4e51-9c9d-dc053eb31edd', '歷山', '歷山', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["（按：《全唐詩》卷三三二收此二句，缺題，今重錄。","）風泉（《歷代詩話續編》本《詩人主客圖》作「前」）留古顏（《全唐詩》作「韻」），笙磬想遺音。","（見汲古閣本《唐詩紀事》卷四三引《詩人主客圖》）。"]', '["（按：《全唐诗》卷三三二收此二句，缺題，今重錄。","）风泉（《歷代诗話續編》本《诗人主客圖》作「前」）留古顏（《全唐诗》作「韻」），笙磬想遺音。","（见汲古閣本《唐诗紀事》卷四三引《诗人主客圖》）。"]', '诗', 'shi', '', NULL, '歷山 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7f1f1f8-4c02-453e-9220-9b45248901c5', '', '', '64c36659-b4b6-4815-94dd-30f1fbf9070f', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 崔備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54b05242-72c3-4a04-b005-41e992ee0a94', '寄羊士諤永寧里居（題擬）', '寄羊士諤永寧里居（題擬）', '64c36659-b4b6-4815-94dd-30f1fbf9070f', '唐', '["圖書鎖塵閣，符節守山城。","（見江標影宋書棚本《羊士諤詩集》收《酬禮部崔員外備獨永寧里弊居見寄來詩云圖書鎖塵閣符節守山城》）。"]', '["圖书鎖塵閣，符節守山城。","（见江標影宋书棚本《羊士諤诗集》收《酬禮部崔員外備独永寧里弊居见寄来诗云圖书鎖塵閣符節守山城》）。"]', '诗', 'shi', '', NULL, '寄羊士諤永寧里居（題擬） 崔備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('947ff270-e244-4b3a-acdf-e4a5fd1a684c', '放少師行脚時頌', '放少師行脚时頌', '83110c08-7c40-4159-a85d-debfdebbc217', '唐', '["放汝南行入大津，碧潭深處養金鱗。","等閑莫與凡魚伴，直透龍門便出身。"]', '["放汝南行入大津，碧潭深处養金鱗。","等闲莫與凡鱼伴，直透龙门便出身。"]', '诗', 'shi', '', NULL, '放少師行脚時頌 自在 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e633eae-203f-42c1-9dc8-033d9ebbd81f', '三個不歸頌', '三個不归頌', '83110c08-7c40-4159-a85d-debfdebbc217', '唐', '["（按：《全唐詩續補遺》據《鑑誡錄》卷十《高僧諭》條，錄伏牛上人《三傷頌》三首，擬傳云「王蜀時高僧」。","今檢《宋高僧傳》卷十一《唐洛京伏牛山自在傳》云：「所著《三傷歌》，辭理俱美，警發迷蒙，有益於代。","」後接述王蜀乾德間人引此歌事。","《三傷歌》即《三傷頌》，可知三詩皆元和間自在作，王蜀時另無伏牛上人其人。","）。"]', '["（按：《全唐诗續補遺》據《鑑誡錄》卷十《高僧諭》條，錄伏牛上人《三傷頌》三首，擬傳云「王蜀时高僧」。","今檢《宋高僧傳》卷十一《唐洛京伏牛山自在傳》云：「所著《三傷歌》，辞理俱美，警發迷蒙，有益於代。","」後接述王蜀乾德间人引此歌事。","《三傷歌》即《三傷頌》，可知三诗皆元和间自在作，王蜀时另無伏牛上人其人。","）。"]', '诗', 'shi', '', NULL, '三個不歸頌 自在 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20b23aca-bd46-4911-ae61-0f788b1dd8c4', '三個不歸頌 一', '三個不归頌 一', '83110c08-7c40-4159-a85d-debfdebbc217', '唐', '["割愛慈親異俗迷，如雲似鶴更高飛。","五湖四海隨緣去，到處爲家一不歸。"]', '["割愛慈親異俗迷，如云似鹤更高飞。","五湖四海隨緣去，到处爲家一不归。"]', '诗', 'shi', '', NULL, '三個不歸頌 一 自在 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab30411-e9d3-4c1d-9849-970b41162bb6', '三個不歸頌 二', '三個不归頌 二', '83110c08-7c40-4159-a85d-debfdebbc217', '唐', '["苦節勞形守法威，幸逢知識決玄微。","慧燈初照昏衢朗，唯報自親二不歸。"]', '["苦節勞形守法威，幸逢知識決玄微。","慧灯初照昏衢朗，唯報自親二不归。"]', '诗', 'shi', '', NULL, '三個不歸頌 二 自在 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fa3f6c1-8505-4d1f-b9fd-1408e3dfc127', '三個不歸頌 三', '三個不归頌 三', '83110c08-7c40-4159-a85d-debfdebbc217', '唐', '["峭壁幽嵒往復希，片雲孤月每相依。","經行宴坐閑無事，樂道逍遙三不歸。","（以上四首均見《祖堂集》卷十五）。"]', '["峭壁幽嵒往复希，片云孤月每相依。","經行宴坐闲無事，乐道逍遙三不归。","（以上四首均见《祖堂集》卷十五）。"]', '诗', 'shi', '', NULL, '三個不歸頌 三 自在 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d18e506f-1860-4d82-a2e9-dd491f2274b7', '答伏牛和尚（題擬）', '答伏牛和尚（題擬）', '144c75b4-97c8-4e2d-a257-e53b076a74af', '唐', '["魚龍未變志常存，變了還教海氣渾。","兩眼不曾窺小水，一心專擬透龍門。","千迴下網終難繫，萬度垂鉤誓不天。","待我一朝鱗甲備，解將雲雨灑乾坤。","（見《祖堂集》卷十五）。"]', '["鱼龙未变志常存，变了還教海氣渾。","兩眼不曾窺小水，一心專擬透龙门。","千迴下網終难繫，万度垂鉤誓不天。","待我一朝鱗甲備，解將云雨灑乾坤。","（见《祖堂集》卷十五）。"]', '诗', 'shi', '', NULL, '答伏牛和尚（題擬） 伏牛小師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cec0bab7-7728-463f-b791-9a20912843cf', '句', '句', 'e9ee4ce0-4692-4371-b3c2-cfb79893599e', '唐', '["越羅巴錦不勝春。","（見《分門纂類唐宋時賢千家詩選》卷十六聞人詳正《集句》引）（按：《宋詩紀事》卷六九引作張曙）。"]', '["越羅巴錦不勝春。","（见《分门纂類唐宋时賢千家诗選》卷十六闻人詳正《集句》引）（按：《宋诗紀事》卷六九引作張曙）。"]', '诗', 'shi', '', NULL, '句 張署 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e7c0c24-04ad-47c8-bb67-cec9f788c84d', '同竇羣雪中寓直（題擬）', '同竇羣雪中寓直（題擬）', '0cde2000-4260-40af-9c3a-70b68695f0c7', '唐', '["耿耿風雪暮，直廬未掩扉。","詠蘭幽助興，儷玉粲相輝。","氣勁琴韻切，夜深鑪火微。","雖殊江海遠，即此戀彤闈。","（見《竇氏聯珠集》。","題下原署「吏部員外郎韋貫之」）。"]', '["耿耿风雪暮，直廬未掩扉。","詠蘭幽助兴，儷玉粲相輝。","氣勁琴韻切，夜深鑪火微。","雖殊江海远，即此戀彤闈。","（见《竇氏聯珠集》。","題下原署「吏部員外郎韋貫之」）。"]', '诗', 'shi', '', NULL, '同竇羣雪中寓直（題擬） 韋貫之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81230142-adb7-4004-a6f0-9e79c58e2588', '顏魯公挽歌詞', '顏魯公挽歌词', '33a350ae-8c9e-403a-9034-8e784839348e', '唐', '["殺身終不恨，歸喪遂如生。","（《唐語林》卷六）（按：《唐語林》原稱柳常侍作，此從周勛初先生《唐語林校證》說。","據周考，此段文字出自韋絢《戎幕閑談》。","）。"]', '["殺身終不恨，归喪遂如生。","（《唐語林》卷六）（按：《唐語林》原稱柳常侍作，此從周勛初先生《唐語林校證》说。","據周考，此段文字出自韋絢《戎幕闲談》。","）。"]', '诗', 'shi', '', NULL, '顏魯公挽歌詞 柳登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14cdd9ca-176b-4083-8dff-23a976815d88', '沙堤葬母', '沙堤葬母', 'b14bdd6a-aa71-485d-86c5-b3d62244e646', '唐', '["守堤三年念生緣，種樹爲陰出世恩。","劃石寄言相矚付，一重孫付一重孫。","（《閩詩錄甲集》卷四）。"]', '["守堤三年念生緣，種樹爲陰出世恩。","劃石寄言相矚付，一重孫付一重孫。","（《閩诗錄甲集》卷四）。"]', '诗', 'shi', '', NULL, '沙堤葬母 李頭陀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76d232e6-4b8a-4bad-8e25-c2f23fc2af1f', '孤寂吟', '孤寂吟', 'f290551c-82a9-4df3-90ed-27b413b472cb', '唐', '["時人見余守孤寂，爲言一生無所益。","余則閑吟孤寂章，始知光陰不虛擲。","不棄光陰須努力，此言雖說人不識。","識者同爲一路行，豈可顛墜緣榛棘。","榛棘茫茫何是邊，只爲終朝盡衆喧。","衆喧不覺無涯際，哀哉真實不虛傳。","傳之響之只不聞，猶如燈燭合盂盆。","共知總有光明在，看時未免暗昏昏。","昏昏不覺一生了，斯類塵沙比不少。","直似潭中吞鈎魚，何異空中盪羅鳥。","此患由來實是長，四維上下遠茫茫。","倏忽之間迷病死，塵勞難脫哭愴愴。","愴愴哀怨終無益，只爲將身居痛室。","到此之時悔何及，雲泥未可訪孤寂。","孤寂宇宙窮爲良，長吟高臥一閑堂。","不慮寒風吹落葉，豈愁霜草遍遭霜。","但看松竹歲寒心，四時不變流清音。","春夏暫爲羣木暎，秋冬方見鬱高林。","故知世相有剛柔，何必將心清濁流。","二時麁糖隨緣過，一身遮莫布毛裘。","隨風逐浪住東西，豈愁地迮與天低（此字原寫作「{伭右上爲一}」）。","時人未解將爲錯，余則了然自不迷。","不迷須有不迷心，看時淺淺用時深。","此个真珠若採得，豈同樵夫負黃金。","黃金烹練轉爲真（《宗鏡錄》卷二十引作「新」），明（同前書作「此」）珠含光未示人。","了即毛端滴（《宗鏡錄》作「吞」）巨海，始知大地一微塵。","塵滴存乎未免{僭右下爲心}，莫棄這邊留那邊。","直似長空搜鳥跡，始得玄中又更玄。","舉一例諸足可知，何用諵諵說引詞。","只見餓夫來取飽，未聞漿逐渴人死。","多人說道道不行，他家未悟詐頭明。","三寸利刀開曠路，萬株榛棘擁身生。","塵滓茫茫都不知，空將辯口瀉玄微。","此物那堪爲大用，千生萬刦作貧兒。","聊書孤寂事還深，鍾期能聽[伯]（白）牙琴。","道者知音指其掌，方貴名爲孤寂吟。"]', '["时人见余守孤寂，爲言一生無所益。","余則闲吟孤寂章，始知光陰不虛擲。","不棄光陰須努力，此言雖说人不識。","識者同爲一路行，豈可顛墜緣榛棘。","榛棘茫茫何是邊，只爲終朝尽衆喧。","衆喧不覺無涯際，哀哉真實不虛傳。","傳之响之只不闻，猶如灯燭合盂盆。","共知總有光明在，看时未免暗昏昏。","昏昏不覺一生了，斯類塵沙比不少。","直似潭中吞鈎鱼，何異空中盪羅鸟。","此患由来實是长，四維上下远茫茫。","倏忽之间迷病死，塵勞难脫哭愴愴。","愴愴哀怨終無益，只爲將身居痛室。","到此之时悔何及，云泥未可訪孤寂。","孤寂宇宙窮爲良，长吟高臥一闲堂。","不慮寒风吹落葉，豈愁霜草遍遭霜。","但看松竹歲寒心，四时不变流清音。","春夏暫爲羣木暎，秋冬方见鬱高林。","故知世相有剛柔，何必將心清濁流。","二时麁糖隨緣過，一身遮莫布毛裘。","隨风逐浪住东西，豈愁地迮與天低（此字原寫作「{伭右上爲一}」）。","时人未解將爲錯，余則了然自不迷。","不迷須有不迷心，看时淺淺用时深。","此个真珠若採得，豈同樵夫負黄金。","黄金烹練轉爲真（《宗镜錄》卷二十引作「新」），明（同前书作「此」）珠含光未示人。","了即毛端滴（《宗镜錄》作「吞」）巨海，始知大地一微塵。","塵滴存乎未免{僭右下爲心}，莫棄這邊留那邊。","直似长空搜鸟跡，始得玄中又更玄。","舉一例諸足可知，何用諵諵说引词。","只见餓夫来取飽，未闻漿逐渴人死。","多人说道道不行，他家未悟詐头明。","三寸利刀开曠路，万株榛棘擁身生。","塵滓茫茫都不知，空將辯口瀉玄微。","此物那堪爲大用，千生万刦作貧兒。","聊书孤寂事還深，鍾期能听[伯]（白）牙琴。","道者知音指其掌，方貴名爲孤寂吟。"]', '诗', 'shi', '', NULL, '孤寂吟 天然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58021e79-d3c8-436d-aba2-a8f00bf90683', '翫珠吟', '翫珠吟', 'f290551c-82a9-4df3-90ed-27b413b472cb', '唐', '["識得衣中寶，無明醉（伯作「酒」）自惺（《燈錄》、《通載》、伯作「醒」）。","百骸俱（《燈錄》、《宗鏡錄》作「雖」）潰散（伯作「悔盡」），一物鎮長靈。","知（《通載》作「智」）境渾非體（伯作「智劍揮非體」），尋（伯、《燈錄》、《通載》作「神」）珠不定（伯作「見」）形。","悟即（伯、《燈錄》、《通載》作「則」）三身佛，迷疑萬卷經。","在心心豈（《燈錄》、《通載》、伯作「可」）測，居（《燈錄》、《通載》作「歷」）耳耳難聽。","罔像先天地，淵玄（《燈錄》、《通載》作「玄泉」，伯作「懸泉」）出杳冥（伯作「名」）。","本剛非鍛（伯作「斷」）鍊，元淨（《燈錄》、《通載》作「鏡」）莫澄停（伯作「亭」、《燈錄》、《通載》作「渟」）。","盤泊（《通載》作「礴」）逾（伯作「轉」，《燈錄》、《通載》作「輪」）朝日，玲瓏（伯作「鈴鑨」）暎曉星。","瑞光流不滅，真澄（伯作「氣」）濁還清（《燈錄》、《通載》作「真氣觸還生」）。","鑒照崆峒（伯作「空洞」）寂，勞（《燈錄》、《通載》、伯作「羅」）籠法界明。","剉（《燈錄》作「挫」，伯作「春」）凡功不滅（伯作「狹」），超聖果非盈。","龍女心親獻，虵（《燈錄》、《通載》作「闍」）王口自傾（伯作「經」，《燈錄》、《通載》作「呈」）。","護鵝人却活，黃雀義（《燈錄》、《通載》作「意」）猶輕。","解語非關舌，能言不是聲。","絕邊彌瀚（《燈錄》、《通載》作「汗」）漫，三（《燈錄》、《通載》作「無」）際等空平。","演教非爲教（《燈錄》、《通載》作「說」），聞名不（《燈錄》作「勿」，《通載》作「忽」）認名。","（伯無以上四句）。","二（伯、《通載》、《燈錄》作「兩」）邊俱不（《通載》作「莫」）立（伯作「守」），中道不須行。","見月休看（《燈錄》、《通載》作「觀」）指（伯作「紙」），歸（伯作「知」，《燈錄》、《通載》作「還」）家罷問程（伯作「逞」）。","識心豈測（《燈錄》作「心則」，伯、《通載》作「心即」）佛，何佛更堪成。","（按：《景德傳燈錄》卷三十收丹霞和尚《翫珠吟二首》，此爲其二。","另伯三五九七卷、《佛祖歷代通載》卷十六亦收此詩。","異文並注出。","《宗鏡錄》卷四十收「百骸雖潰散，一物鎮長靈」二句，題作《般若吟》，不注作者名。","）。"]', '["識得衣中寶，無明醉（伯作「酒」）自惺（《灯錄》、《通載》、伯作「醒」）。","百骸俱（《灯錄》、《宗镜錄》作「雖」）潰散（伯作「悔尽」），一物鎮长靈。","知（《通載》作「智」）境渾非體（伯作「智劍揮非體」），尋（伯、《灯錄》、《通載》作「神」）珠不定（伯作「见」）形。","悟即（伯、《灯錄》、《通載》作「則」）三身佛，迷疑万卷經。","在心心豈（《灯錄》、《通載》、伯作「可」）測，居（《灯錄》、《通載》作「歷」）耳耳难听。","罔像先天地，淵玄（《灯錄》、《通載》作「玄泉」，伯作「懸泉」）出杳冥（伯作「名」）。","本剛非鍛（伯作「斷」）鍊，元淨（《灯錄》、《通載》作「镜」）莫澄停（伯作「亭」、《灯錄》、《通載》作「渟」）。","盤泊（《通載》作「礴」）逾（伯作「轉」，《灯錄》、《通載》作「輪」）朝日，玲瓏（伯作「鈴鑨」）暎晓星。","瑞光流不滅，真澄（伯作「氣」）濁還清（《灯錄》、《通載》作「真氣觸還生」）。","鑒照崆峒（伯作「空洞」）寂，勞（《灯錄》、《通載》、伯作「羅」）籠法界明。","剉（《灯錄》作「挫」，伯作「春」）凡功不滅（伯作「狹」），超聖果非盈。","龙女心親獻，虵（《灯錄》、《通載》作「闍」）王口自傾（伯作「經」，《灯錄》、《通載》作「呈」）。","護鵝人却活，黄雀義（《灯錄》、《通載》作「意」）猶轻。","解語非关舌，能言不是声。","絕邊彌瀚（《灯錄》、《通載》作「汗」）漫，三（《灯錄》、《通載》作「無」）際等空平。","演教非爲教（《灯錄》、《通載》作「说」），闻名不（《灯錄》作「勿」，《通載》作「忽」）認名。","（伯無以上四句）。","二（伯、《通載》、《灯錄》作「兩」）邊俱不（《通載》作「莫」）立（伯作「守」），中道不須行。","见月休看（《灯錄》、《通載》作「观」）指（伯作「紙」），归（伯作「知」，《灯錄》、《通載》作「還」）家罷问程（伯作「逞」）。","識心豈測（《灯錄》作「心則」，伯、《通載》作「心即」）佛，何佛更堪成。","（按：《景德傳灯錄》卷三十收丹霞和尚《翫珠吟二首》，此爲其二。","另伯三五九七卷、《佛祖歷代通載》卷十六亦收此诗。","異文並注出。","《宗镜錄》卷四十收「百骸雖潰散，一物鎮长靈」二句，題作《般若吟》，不注作者名。","）。"]', '诗', 'shi', '', NULL, '翫珠吟 天然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66d5d596-8f34-4d15-a60e-72257f7b1784', '又頌', '又頌', 'f290551c-82a9-4df3-90ed-27b413b472cb', '唐', '["丹霞有一寶，藏之歲月久。","從來人不識，余自獨防守。","山河無隔碍，光明處處透。","體寂常湛然，瑩澈無塵垢。","世間採取人，顛狂逐路走。","余則爲渠說，撫掌笑破口。","忽遇解空人，放曠在林藪。","相逢不擎出，舉意便知有。"]', '["丹霞有一寶，藏之歲月久。","從来人不識，余自独防守。","山河無隔碍，光明处处透。","體寂常湛然，瑩澈無塵垢。","世间採取人，顛狂逐路走。","余則爲渠说，撫掌笑破口。","忽遇解空人，放曠在林藪。","相逢不擎出，舉意便知有。"]', '诗', 'shi', '', NULL, '又頌 天然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86006ae3-a6e8-41eb-9a0c-b4d7fdd2608f', '驪龍珠吟', '驪龙珠吟', 'f290551c-82a9-4df3-90ed-27b413b472cb', '唐', '["驪龍珠，驪龍珠，光明𪹥（疑即「燦」字）爛與人殊。","十方世界無求處，縱然求得亦非珠。","珠本有，不昇沉，時人不識外追尋。","行盡天涯自疲寂，不如體取自家心。","莫求覓，損功夫，轉求轉滅轉元無。","恰如渴鹿趁陽燄，又似狂人在道途。","須自體，了分明，了得不用更磨瑩。","深知不是人間得，非論六類及生靈。","虛用意，損精神，不如閑處絕纖塵。","停心息意珠常在，莫向途中別問人。","自迷失，珠元在，此个驪龍終不改。","雖然埋在五陰山，自是時人生懈怠。","不識珠，每拋擲，却向驪龍前作客。","不知身是主人公，棄却驪龍別處覓。","認取寶，自家珍，此珠元是本來人。","拈得翫弄無窮盡，始覺驪龍本不貧。","若能曉了驪珠後，只這驪珠在我身。"]', '["驪龙珠，驪龙珠，光明𪹥（疑即「燦」字）爛與人殊。","十方世界無求处，縱然求得亦非珠。","珠本有，不昇沉，时人不識外追尋。","行尽天涯自疲寂，不如體取自家心。","莫求覓，損功夫，轉求轉滅轉元無。","恰如渴鹿趁陽燄，又似狂人在道途。","須自體，了分明，了得不用更磨瑩。","深知不是人间得，非論六類及生靈。","虛用意，損精神，不如闲处絕纖塵。","停心息意珠常在，莫向途中別问人。","自迷失，珠元在，此个驪龙終不改。","雖然埋在五陰山，自是时人生懈怠。","不識珠，每拋擲，却向驪龙前作客。","不知身是主人公，棄却驪龙別处覓。","認取寶，自家珍，此珠元是本来人。","拈得翫弄無窮尽，始覺驪龙本不貧。","若能晓了驪珠後，只這驪珠在我身。"]', '诗', 'shi', '', NULL, '驪龍珠吟 天然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b43a41b-825f-45d9-963d-d40c99cdd83b', '弄珠吟（《景德傳燈錄》卷三十作《翫珠吟二首》之一）', '弄珠吟（《景德傳灯錄》卷三十作《翫珠吟二首》之一）', 'f290551c-82a9-4df3-90ed-27b413b472cb', '唐', '["般若神（《燈錄》作「靈」）珠妙難測，法性海中親認得。","隱現時游五藴山（《燈錄》作「隱顯常游五藴中」），內外光明大神力。","此珠無狀非大小，晝夜圓明悉能照。","（《燈錄》作「此珠非大亦非小，晝夜光明皆悉照」。","）用時無處復無蹤（《燈錄》作「覓時無物又無蹤」），行住（《燈錄》作「起坐」）相隨常了了。","先聖相傳相指授，信此珠人世希有。","智者號明不離珠，迷人將珠不識走。","（以上四句，《傳燈錄》作「黃帝曾遊于赤水，爭聽爭求都不遂。","罔像無心却得珠，能見能聞是虛僞。","」）吾師權指喻摩尼，採人無數入（《燈錄》作「溺」）春池。","爭拈瓦礫將爲寶，智者安然而得之。","言下非近亦非遠（《燈錄》作「森羅萬象光中現」），體用如如轉無轉。","萬機珠對（《燈錄》作「消遣」）寸心中，一切時中巧方便。","皇帝曾遊於赤水，視聽爭求都不遂。","罔像無心却得珠，能見能聞是虛僞。","非自心，非因緣，妙中之妙玄中玄。","森羅萬像光中現，尋之不見有根源。","（《燈錄》無以上九句）燒六賊（《宗鏡錄》卷七六「賊」下有「兮」字），爍四（《燈錄》作「衆」）魔，能摧我山（《宗鏡錄》作「摧我山兮」）竭愛（《燈錄》作「我」）河。","龍女靈山親獻佛，貧兒衣裏幾（《宗鏡錄》作「枉」，《燈錄》作「下任」）蹉{趷右下爲也}。","亦非性，亦非心（《燈錄》二「非」字皆作「名」），非性非心超古今。","體絕名言名不得（《燈錄》作「全體明時明不得」），權時題作《弄珠吟》。","（以上皆見影印日本花園大學圖書館藏高麗覆刻本南唐招慶寺靜筠二僧著《祖堂集》卷四）。"]', '["般若神（《灯錄》作「靈」）珠妙难測，法性海中親認得。","隐現时游五藴山（《灯錄》作「隐显常游五藴中」），內外光明大神力。","此珠無狀非大小，晝夜圓明悉能照。","（《灯錄》作「此珠非大亦非小，晝夜光明皆悉照」。","）用时無处复無蹤（《灯錄》作「覓时無物又無蹤」），行住（《灯錄》作「起坐」）相隨常了了。","先聖相傳相指授，信此珠人世希有。","智者號明不離珠，迷人將珠不識走。","（以上四句，《傳灯錄》作「黄帝曾游于赤水，爭听爭求都不遂。","罔像無心却得珠，能见能闻是虛僞。","」）吾師權指喻摩尼，採人無數入（《灯錄》作「溺」）春池。","爭拈瓦礫將爲寶，智者安然而得之。","言下非近亦非远（《灯錄》作「森羅万象光中現」），體用如如轉無轉。","万機珠对（《灯錄》作「消遣」）寸心中，一切时中巧方便。","皇帝曾游於赤水，視听爭求都不遂。","罔像無心却得珠，能见能闻是虛僞。","非自心，非因緣，妙中之妙玄中玄。","森羅万像光中現，尋之不见有根源。","（《灯錄》無以上九句）燒六賊（《宗镜錄》卷七六「賊」下有「兮」字），爍四（《灯錄》作「衆」）魔，能摧我山（《宗镜錄》作「摧我山兮」）竭愛（《灯錄》作「我」）河。","龙女靈山親獻佛，貧兒衣裏幾（《宗镜錄》作「枉」，《灯錄》作「下任」）蹉{趷右下爲也}。","亦非性，亦非心（《灯錄》二「非」字皆作「名」），非性非心超古今。","體絕名言名不得（《灯錄》作「全體明时明不得」），權时題作《弄珠吟》。","（以上皆见影印日本花园大学圖书館藏高丽覆刻本南唐招慶寺静筠二僧著《祖堂集》卷四）。"]', '诗', 'shi', '', NULL, '弄珠吟（《景德傳燈錄》卷三十作《翫珠吟二首》之一） 天然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3adcc3ac-7ed9-4bf8-afc9-478b09a3edf4', '過施水庵', '過施水庵', '9aaa4717-9faa-4d72-ab1f-aa78831e1b2e', '唐', '["勝地開闌若，幽尋信短筇。","僧貧祇施水，客至但聞鐘。","講坐天花滿，香臺翠靄重。","何當謝塵紱，白社此相從。","（見明李培等萬曆十四年修《秀水縣志》卷八、《檇李詩繫》卷三七）。"]', '["勝地开闌若，幽尋信短筇。","僧貧祇施水，客至但闻鐘。","講坐天花满，香台翠靄重。","何當謝塵紱，白社此相從。","（见明李培等万曆十四年修《秀水縣志》卷八、《檇李诗繫》卷三七）。"]', '诗', 'shi', '', NULL, '過施水庵 李諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9e6826e-db80-4654-95d4-3ee2876b079a', '白烏呈瑞賦附歌', '白烏呈瑞賦附歌', 'bd272f87-8332-47ff-b1f6-849e80d96d8f', '唐', '["素德式昭兮何寫奕，玄質從化兮爲潔白。","符仁孝兮叶佳冊，見祥瑞兮流聖澤。","（見《文苑英華》卷八九）。"]', '["素德式昭兮何寫奕，玄質從化兮爲潔白。","符仁孝兮叶佳冊，见祥瑞兮流聖澤。","（见《文苑英华》卷八九）。"]', '诗', 'shi', '', NULL, '白烏呈瑞賦附歌 孟簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f27adc0-0d2c-4bb7-b917-3c9225be6cc1', '謁禹廟', '謁禹廟', 'bd272f87-8332-47ff-b1f6-849e80d96d8f', '唐', '["九土昔淪墊，八方抱殷憂。","哲王受《洪範》，羣物承天休。","源委有所在，勤勞會東州。","稽山何峻極，清廟居上頭。","律度非外事，辛壬寧少留。","歌謠自不去，覆載將何求？","靈長表遠績，經啓蒙宏猷。","孰敢備佐命，天吳與陽侯。","玄功餘玉帛，茂實結松楸。","蓋影庇風雨，湖光搖冕旒。","質明簫鼓作，通昔禮容脩。","騂牢設舊物，洿水配庶羞。","深沈本建極，傲很亦思柔。","陰怪尚奔走，靈徒如獻酬。","怳疑仙駕動，靜見宿雲收。","竹樹依積潤，菰蒲託清流。","謬茲領百越，忽復歷三秋。","丹懇諒可薦，庶幾無年尤。","（見《會稽掇英總集》卷八）。"]', '["九土昔淪墊，八方抱殷憂。","哲王受《洪範》，羣物承天休。","源委有所在，勤勞會东州。","稽山何峻極，清廟居上头。","律度非外事，辛壬寧少留。","歌謠自不去，覆載將何求？","靈长表远績，經啓蒙宏猷。","孰敢備佐命，天吳與陽侯。","玄功餘玉帛，茂實結松楸。","蓋影庇风雨，湖光搖冕旒。","質明簫鼓作，通昔禮容脩。","騂牢設旧物，洿水配庶羞。","深沈本建極，傲很亦思柔。","陰怪尚奔走，靈徒如獻酬。","怳疑仙駕动，静见宿云收。","竹樹依積潤，菰蒲託清流。","謬茲領百越，忽复歷三秋。","丹懇諒可薦，庶幾無年尤。","（见《會稽掇英總集》卷八）。"]', '诗', 'shi', '', NULL, '謁禹廟 孟簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cf3bb3d-b449-49ed-9400-61f9629c7eef', '臨蒸諸葛亮宅（題擬）', '臨蒸諸葛亮宅（題擬）', '06ccb9a6-28c7-4727-a61a-7d729109d8e7', '唐', '["始有諸葛翁，柯亭寄翠靄。","（見《輿地紀勝》卷五五《衡州》）。"]', '["始有諸葛翁，柯亭寄翠靄。","（见《輿地紀勝》卷五五《衡州》）。"]', '诗', 'shi', '', NULL, '臨蒸諸葛亮宅（題擬） 蔣防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('606ed089-ce9f-459b-a513-bb4fc2e52cbf', '太常寺觀舞聖壽樂', '太常寺观舞聖壽乐', 'ee376a3a-cb54-40c6-a654-4c803efe1472', '唐', '["舞字傳新慶，人文邁舊章。","冲融和氣洽，悠遠聖功長。","盛德流無外，時時樂未央。","日華增顧眄，風物助低昂。","翥鳳方齊首，高鴻忽繼行。","雲門與茲曲，同是奉陶唐。","（《文苑英華》卷一八四）（按：《全唐詩》卷七八一誤以作者爲徐元鼎，無事跡，今改正重錄。","）。"]', '["舞字傳新慶，人文邁旧章。","冲融和氣洽，悠远聖功长。","盛德流無外，时时乐未央。","日华增顧眄，风物助低昂。","翥鳳方齊首，高鴻忽繼行。","云门與茲曲，同是奉陶唐。","（《文苑英华》卷一八四）（按：《全唐诗》卷七八一誤以作者爲徐元鼎，無事跡，今改正重錄。","）。"]', '诗', 'shi', '', NULL, '太常寺觀舞聖壽樂 徐元弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc507994-aa97-4958-b4d0-d2eccc6be598', '登石傘峰（幷序）', '登石傘峰（幷序）', '08ea146e-6496-414c-815f-acb18535b4cb', '唐', '["賢相昔未遇，耶溪藏臥龍。","宛然東山居，已韻西林鐘。","仲氏亦遐曠，爾來習高蹤。","楊公偶閒暇，中貴同遊從。","曲渚擁騶馭，迴潭轉艨艟。","既登寅緣岸，遂踐岧嶤峰。","徑側縈巨石，磴危攀茂松。","傘開自羅列，笥閉誰箴封？","迥立霄漢表，俯看嚴嶂重。","遠村暮杳杳，秋海晴溶溶。","染翰紀勝絕，飛觴暢心胸。","仍聞待新月，歸櫂何從容。","（見《會稽掇英總集》卷四）。"]', '["賢相昔未遇，耶溪藏臥龙。","宛然东山居，已韻西林鐘。","仲氏亦遐曠，爾来習高蹤。","楊公偶閒暇，中貴同游從。","曲渚擁騶馭，迴潭轉艨艟。","既登寅緣岸，遂踐岧嶤峰。","徑側縈巨石，磴危攀茂松。","傘开自羅列，笥閉誰箴封？","迥立霄漢表，俯看嚴嶂重。","远村暮杳杳，秋海晴溶溶。","染翰紀勝絕，飞觴暢心胸。","仍闻待新月，归櫂何從容。","（见《會稽掇英總集》卷四）。"]', '诗', 'shi', '', NULL, '登石傘峰（幷序） 陳諫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fafcd344-a74f-4b79-84c0-15d3d6f51fb9', '題京兆大興善寺釋南素院', '題京兆大兴善寺釋南素院', '458c4ad4-3159-4d36-8549-93e603a5ddf5', '唐', '["三萬蓮經三十春，半生不踏院門塵。","（見《宋高僧傳》卷二五。","又見《酉陽雜俎續集》卷五）（按：《全唐詩》卷八五一錄二句，僅題作《逸句》，作者亦缺事跡，今重錄。","）。"]', '["三万蓮經三十春，半生不踏院门塵。","（见《宋高僧傳》卷二五。","又见《酉陽杂俎續集》卷五）（按：《全唐诗》卷八五一錄二句，僅題作《逸句》，作者亦缺事跡，今重錄。","）。"]', '诗', 'shi', '', NULL, '題京兆大興善寺釋南素院 玄幽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('400be168-382c-43da-a86b-aeedce8d038c', '送李愿歸盤谷歌', '送李愿归盤谷歌', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["盤之中，維子之宮；盤之土，維子之稼；盤之泉，可濯可沿；盤之阻，誰爭子所！窈而深，廓其有容；繚而曲，如往而復。","嗟盤之樂兮樂且無央，虎豹遠跡兮蛟龍遁藏，鬼神守護兮呵禁不祥，飲且食兮壽而康，無不足兮奚所望！膏吾車兮秣吾馬，從子於盤兮終吾生以徜徉！（《四部叢刊》影元刻本《朱文公校昌黎先生集》卷十九《送李愿歸盤谷序》附此歌）。"]', '["盤之中，維子之宮；盤之土，維子之稼；盤之泉，可濯可沿；盤之阻，誰爭子所！窈而深，廓其有容；繚而曲，如往而复。","嗟盤之乐兮乐且無央，虎豹远跡兮蛟龙遁藏，鬼神守護兮呵禁不祥，饮且食兮壽而康，無不足兮奚所望！膏吾车兮秣吾马，從子於盤兮終吾生以徜徉！（《四部叢刊》影元刻本《朱文公校昌黎先生集》卷十九《送李愿归盤谷序》附此歌）。"]', '诗', 'shi', '', NULL, '送李愿歸盤谷歌 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b56c9ed7-af9b-4f63-bf6e-d694ea59d337', '袁氏先廟碑附詩', '袁氏先廟碑附诗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["袁自陳分，初尚蹇連（方云：作「連連」）。","越秦造漢，博士發論。","司徒任德，忍不錮人。","收功厥後，五公重尊。","晉氏于南，來處華下。","鴻臚、孝侯，用適操捨。","南州勤治，取最不懈。","當陽耽經，唯義之畏。","石州烈烈，學專春秋。","懿哉咸寧，不名一休。","趨難避成，與時泛浮。","是生孝子，天子之宰，出把（或作「祀」、或作「持」）將符，羣（或作「郡」）州承楷。","數（或作「教」）以立廟，祿以備器。","由曾及考，同堂異置。","栢版松楹，其筵（或作「業」）肆肆。","維袁之廟，孝孫之爲。","順勢即宜，以諏以龜。","以平其巇，屋牆持持。","孝孫來享，來拜廟庭。","陟堂進室，親登籩鉶。","肩臑胉骼，其樽玄清。","降登受胙，于慶爾（方作「示」，非是）成。","維曾維祖，維考之施。","于汝孝嗣，以報以祗。","凡我有今，非本曷思。","刻詩牲繫（或作「繫牲」），維以告之。","（同前書卷二七）。"]', '["袁自陳分，初尚蹇連（方云：作「連連」）。","越秦造漢，博士發論。","司徒任德，忍不錮人。","收功厥後，五公重尊。","晉氏于南，来处华下。","鴻臚、孝侯，用適操捨。","南州勤治，取最不懈。","當陽耽經，唯義之畏。","石州烈烈，学專春秋。","懿哉咸寧，不名一休。","趨难避成，與时泛浮。","是生孝子，天子之宰，出把（或作「祀」、或作「持」）將符，羣（或作「郡」）州承楷。","數（或作「教」）以立廟，祿以備器。","由曾及考，同堂異置。","栢版松楹，其筵（或作「業」）肆肆。","維袁之廟，孝孫之爲。","順勢即宜，以諏以龟。","以平其巇，屋牆持持。","孝孫来享，来拜廟庭。","陟堂進室，親登籩鉶。","肩臑胉骼，其樽玄清。","降登受胙，于慶爾（方作「示」，非是）成。","維曾維祖，維考之施。","于汝孝嗣，以報以祗。","凡我有今，非本曷思。","刻诗牲繫（或作「繫牲」），維以告之。","（同前书卷二七）。"]', '诗', 'shi', '', NULL, '袁氏先廟碑附詩 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a49feac-2823-4bf7-93df-0a13b028f497', '南海神廟碑附詩', '南海神廟碑附诗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["南海陰（或作「之」）墟，祝融之宅，即祀于旁。","帝命南伯：「吏惰不躬，正自令公，明用享錫，右（《唐文粹》作「祐」）我家邦。","」惟明天子，惟慎厥使，我公在官，神人致喜。","海嶺之陬，既足既濡，胡不均弘，俾執事樞。","公行勿遲，公無遽歸。","匪我私公，神人具依。","（同前書卷三一，校以《唐文粹》卷五十所錄示）（〖1〗清陸耀遹《金石續編》卷七據石刻錄此碑，題作《南海廣利王碑》，云碑在廣州府，元和十五陳諫書。","按：就常理言，碑末所附韻文或稱銘，或稱頌，稱詩者較少見。","然韓愈性好奇，碑末附詩，不止一見。","碑文云：「咸願刻廟石以著厥美而繫以詩。","乃作詩曰〖略〗。","」各本《韓集》、清人所錄石刻、《文苑英華》卷八七九、《唐文粹》等所載碑文，均作詩而不作銘，故仍錄出之。","）。"]', '["南海陰（或作「之」）墟，祝融之宅，即祀于旁。","帝命南伯：「吏惰不躬，正自令公，明用享錫，右（《唐文粹》作「祐」）我家邦。","」惟明天子，惟慎厥使，我公在官，神人致喜。","海嶺之陬，既足既濡，胡不均弘，俾執事樞。","公行勿遲，公無遽归。","匪我私公，神人具依。","（同前书卷三一，校以《唐文粹》卷五十所錄示）（〖1〗清陸耀遹《金石續編》卷七據石刻錄此碑，題作《南海廣利王碑》，云碑在廣州府，元和十五陳諫书。","按：就常理言，碑末所附韻文或稱銘，或稱頌，稱诗者較少见。","然韓愈性好奇，碑末附诗，不止一见。","碑文云：「咸願刻廟石以著厥美而繫以诗。","乃作诗曰〖略〗。","」各本《韓集》、清人所錄石刻、《文苑英华》卷八七九、《唐文粹》等所載碑文，均作诗而不作銘，故仍錄出之。","）。"]', '诗', 'shi', '', NULL, '南海神廟碑附詩 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bcbe334-71c8-42da-92b0-502ea0941261', '處州孔子廟碑附詩', '处州孔子廟碑附诗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["惟此廟學，鄴侯所作。","厥初庳下，神不以宇。","生（《唐文粹》作「先」）師所處，亦窘寒暑。","乃新斯宮，神降其獻。","講讀有常，不誡用勸。","揭揭元[哲]（誓），有師之尊。","羣聖嚴嚴，大法以存。","像圖孔肖，咸在斯堂。","以瞻以儀，俾不[或]（惑）忘。","後之君子，無廢成美。","琢詞碑石，以贊攸始。","（同前書卷三一。","據《唐文粹》卷五一校改）。"]', '["惟此廟学，鄴侯所作。","厥初庳下，神不以宇。","生（《唐文粹》作「先」）師所处，亦窘寒暑。","乃新斯宮，神降其獻。","講读有常，不誡用勸。","揭揭元[哲]（誓），有師之尊。","羣聖嚴嚴，大法以存。","像圖孔肖，咸在斯堂。","以瞻以儀，俾不[或]（惑）忘。","後之君子，無廢成美。","琢词碑石，以贊攸始。","（同前书卷三一。","據《唐文粹》卷五一校改）。"]', '诗', 'shi', '', NULL, '處州孔子廟碑附詩 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaef090a-c731-44fb-8d03-829ed9237e25', '柳州羅池廟詩（題擬）', '柳州羅池廟诗（題擬）', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["荔子丹兮蕉黃（「蕉」下或有「葉」字，或有「子」字），雜肴蔬兮進侯堂。","侯之船兮兩旗，度中流兮風泊之，待侯不來兮不知我悲。","侯乘駒兮入廟，慰我民兮不嚬以笑。","鵝之山兮柳之水，桂樹團團兮白石齒齒。","侯朝出遊兮暮來歸，春與猿吟兮秋鶴與飛。","（《唐文粹》及歐陽修所見《韓集》均作「秋與鶴飛」。","《集古錄跋尾》卷八錄碑文作「秋鶴與飛」，歐疑碑文有誤。","沈括《夢溪筆談》卷十四以爲此用《楚辭》相錯成文格，今從其說。","）北方之人兮爲侯是非，千秋萬歲兮侯無我違。","福我兮壽我，驅厲鬼兮山之左。","下無濕兮高無乾，秔稌充羨兮蛇蛟結蟠。","我民報事兮無怠其始，自今兮欽于世世。","（同前書卷三一、《唐文粹》卷五二《柳州羅池廟碑》附）（〖1〗《柳州羅池廟碑》云：「三年孟秋辛卯，侯降于州之後堂，歐陽翼等見而拜之。","其夕，夢翼而告之曰：『館我於羅池。","』其日景辰，廟成，大祭。","過客李儀醉酒，慢侮堂上，得疾，扶出廟門即死。","明年春，魏忠、歐陽翼使謝寧來京師，請書其事于石。","余謂柳侯生能澤其民，死能驚動禍福之，以食其土，可謂靈也已。","作迎享送神詩遺柳民，俾歌以祀焉而幷刻之。","……其詞曰〖詞略〗。","」《湖南通志·金石》六著錄嘉定刻此碑，題作《唐羅池廟享神詞碑》，附魏紹芳跋此爲享神詩。","《唐詩別裁集》卷七收入。","朱東潤師主編《中國歷代文學作品選》中編第一冊收此詩，題作《柳州羅池廟詩》，解題云：「此廟建成後，韓愈爲撰《柳州羅池廟碑》，詩就附在碑文的後面。","詩效《楚辭·九歌》體，作爲祭祀中迎神、送神時歌唱之用。","」）。"]', '["荔子丹兮蕉黄（「蕉」下或有「葉」字，或有「子」字），杂肴蔬兮進侯堂。","侯之船兮兩旗，度中流兮风泊之，待侯不来兮不知我悲。","侯乘駒兮入廟，慰我民兮不嚬以笑。","鵝之山兮柳之水，桂樹團團兮白石齒齒。","侯朝出游兮暮来归，春與猿吟兮秋鹤與飞。","（《唐文粹》及歐陽修所见《韓集》均作「秋與鹤飞」。","《集古錄跋尾》卷八錄碑文作「秋鹤與飞」，歐疑碑文有誤。","沈括《梦溪笔談》卷十四以爲此用《楚辞》相錯成文格，今從其说。","）北方之人兮爲侯是非，千秋万歲兮侯無我違。","福我兮壽我，驱厲鬼兮山之左。","下無濕兮高無乾，秔稌充羨兮蛇蛟結蟠。","我民報事兮無怠其始，自今兮欽于世世。","（同前书卷三一、《唐文粹》卷五二《柳州羅池廟碑》附）（〖1〗《柳州羅池廟碑》云：「三年孟秋辛卯，侯降于州之後堂，歐陽翼等见而拜之。","其夕，梦翼而告之曰：『館我於羅池。","』其日景辰，廟成，大祭。","過客李儀醉酒，慢侮堂上，得疾，扶出廟门即死。","明年春，魏忠、歐陽翼使謝寧来京師，請书其事于石。","余謂柳侯生能澤其民，死能驚动禍福之，以食其土，可謂靈也已。","作迎享送神诗遺柳民，俾歌以祀焉而幷刻之。","……其词曰〖词略〗。","」《湖南通志·金石》六著錄嘉定刻此碑，題作《唐羅池廟享神词碑》，附魏紹芳跋此爲享神诗。","《唐诗別裁集》卷七收入。","朱东潤師主編《中国歷代文学作品選》中編第一冊收此诗，題作《柳州羅池廟诗》，解題云：「此廟建成後，韓愈爲撰《柳州羅池廟碑》，诗就附在碑文的後面。","诗效《楚辞·九歌》體，作爲祭祀中迎神、送神时歌唱之用。","」）。"]', '诗', 'shi', '', NULL, '柳州羅池廟詩（題擬） 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ccdef67-d539-4b6c-b7e7-1da6645d9de0', '唐故江南西道觀察使中大夫洪州刺史兼御史中丞上柱國賜紫金魚袋贈左散騎常侍太原王公神道碑銘附詩', '唐故江南西道观察使中大夫洪州刺史兼御史中丞上柱国賜紫金鱼袋贈左散騎常侍太原王公神道碑銘附诗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["生人之治，本乎斯文。","有事其末，而忘其源，切近昧陋，道由是堙。","有志其本，而泥古陳，當用而迂，乖戾不伸。","較是二者，其過也均。","其美王公，志儒之本，達士之經。","秩秩而積，涵涵而停。","韡爲華英（一作「英華」），不矜不盈。","孰播其馨？孰發其明？介然而居，士友以傾。","敷文帝階，擢列侍從，以忠遠名，有直有諷。","辨遏堅（或作「聖」）懇，巨邪不用。","秀出班行，乃動帝目。","帝省竭心，恩顧日渥。","翔于郎署，鶱于禁密。","發帝之令，簡古而蔚。","不比于權，以直友冤，敲撼挫揠，竟遭斥奔。","久淹于外，歷守大藩。","所至極思，必悉利病，萎枯以膏，燠暍（或作「暘」）以醒，坦之敞之，必絕其徑，浚之詠之，使安其泳。","帝思其文，復命掌誥。","公潛謂人：「此職宜少，豈無凋郡，庸以自效。","」上藉（或作「籍」）其實，俾統于洪。","逋滯攸除，姦訛革風，祛蔽于目，釋負于躬。","方乎（或作「平」）所部，禁絕浮屠。","風雨順易，秔稻盈疇。","人得其所（或作「饒」），乃恬乃謳（或作「謠」）。","化成有代，思以息勞。","虛位而竢，奄忽（方作「勿隨」）滔滔。","維德維績，志于斯石，日遠彌高。","（同前書卷三一）（按：王公爲王仲舒。","碑文末云：「既以公之德刻而藏之墓矣，子初又請詩以揭之。","」稱詩而不稱銘，故錄出。","）。"]', '["生人之治，本乎斯文。","有事其末，而忘其源，切近昧陋，道由是堙。","有志其本，而泥古陳，當用而迂，乖戾不伸。","較是二者，其過也均。","其美王公，志儒之本，達士之經。","秩秩而積，涵涵而停。","韡爲华英（一作「英华」），不矜不盈。","孰播其馨？孰發其明？介然而居，士友以傾。","敷文帝階，擢列侍從，以忠远名，有直有諷。","辨遏堅（或作「聖」）懇，巨邪不用。","秀出班行，乃动帝目。","帝省竭心，恩顧日渥。","翔于郎署，鶱于禁密。","發帝之令，簡古而蔚。","不比于權，以直友冤，敲撼挫揠，竟遭斥奔。","久淹于外，歷守大藩。","所至極思，必悉利病，萎枯以膏，燠暍（或作「暘」）以醒，坦之敞之，必絕其徑，浚之詠之，使安其泳。","帝思其文，复命掌誥。","公潛謂人：「此職宜少，豈無凋郡，庸以自效。","」上藉（或作「籍」）其實，俾統于洪。","逋滯攸除，姦訛革风，祛蔽于目，釋負于躬。","方乎（或作「平」）所部，禁絕浮屠。","风雨順易，秔稻盈疇。","人得其所（或作「饒」），乃恬乃謳（或作「謠」）。","化成有代，思以息勞。","虛位而竢，奄忽（方作「勿隨」）滔滔。","維德維績，志于斯石，日远彌高。","（同前书卷三一）（按：王公爲王仲舒。","碑文末云：「既以公之德刻而藏之墓矣，子初又請诗以揭之。","」稱诗而不稱銘，故錄出。","）。"]', '诗', 'shi', '', NULL, '唐故江南西道觀察使中大夫洪州刺史兼御史中丞上柱國賜紫金魚袋贈左散騎常侍太原王公神道碑銘附詩 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21184d89-cfe5-43f2-8535-a7c03af1f87d', '曹成王碑附詩', '曹成王碑附诗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["太支十三，曹於弟季。","或亡或微，曹始就事。","曹之祖王，畏塞絕遷。","零王黎公，不聞僅存。","子父易封，三王守名。","延延百載，以有成王。","成王之作，一自其躬。","文被明章，武薦畯功。","蘇枯弱彊，齦其姦猖。","以報於宗，以昭於王。","王亦有子，處王之所，唯舊之視，蹶蹶陛陛。","實取實似，刻詩其碑，爲示無止。","（同前書卷二八）（按：碑云：「乃序而詩之。","」）。"]', '["太支十三，曹於弟季。","或亡或微，曹始就事。","曹之祖王，畏塞絕遷。","零王黎公，不闻僅存。","子父易封，三王守名。","延延百載，以有成王。","成王之作，一自其躬。","文被明章，武薦畯功。","蘇枯弱彊，齦其姦猖。","以報於宗，以昭於王。","王亦有子，处王之所，唯旧之視，蹶蹶陛陛。","實取實似，刻诗其碑，爲示無止。","（同前书卷二八）（按：碑云：「乃序而诗之。","」）。"]', '诗', 'shi', '', NULL, '曹成王碑附詩 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2984e222-5b2e-4fdc-b3b4-1b68d9f5c0d7', '遊祝融峯', '游祝融峯', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["祝融萬丈拔地起，欲見不見輕烟裏。","山翁愛山不肯歸，愛山醉眠山根底。","山童尋着不敢驚，沉吟爲怕山翁嗔。","夢迴抖擻下山去，一徑蘿月松風清。","（嘉靖《衡山府志》卷二。","陶敏先生錄示此詩，幷云：「此詩風格不類韓詩，疑僞，姑錄以存疑。","」）。"]', '["祝融万丈拔地起，欲见不见轻烟裏。","山翁愛山不肯归，愛山醉眠山根底。","山童尋着不敢驚，沉吟爲怕山翁嗔。","梦迴抖擻下山去，一徑蘿月松风清。","（嘉靖《衡山府志》卷二。","陶敏先生錄示此诗，幷云：「此诗风格不類韓诗，疑僞，姑錄以存疑。","」）。"]', '诗', 'shi', '', NULL, '遊祝融峯 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1455f0de-369f-46f1-8903-9b0fbca47b93', '題西白澗', '題西白澗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["太行之下清且淺，一水盤桓紆山轉。","千峰萬壑不可數，異草幽花幾曾見。","波中白日隱出明，風翻不動浮雲輕。","翠巒玉女下雙鶴，笑倚秋練開新晴。","又疑武陵溪上原，桃花溪盡空潺湲。","幽泉間復逗嵒側，噴珠潄玉相交喧。","羣猿見之走絕壁，緣峰虛梯弗勞力。","鳴禽迴面背人飛，爲是從來不相識。","杖藜因貪仰面看，礙石牽蘿錯移屐。","路窮屈曲疑欲回，迤邐屏開一重碧。","殘樽遇坐酒即傾，旋摘山菓都無名。","題詩且欲盡佳句，能歌翻詠仙難成。","天門幽深十里西，無奈落日催人歸。","誰能可屬天宮事，爲我乞取須臾期。","上天無梯日不顧，牢落歸來壇未暮。","閉門下馬一衾寒，夢想魂馳在何處。","（見《古今圖書集成·山川典》卷四八《太行山部》、乾隆廿四年刊蕭應植纂《濟源縣志》卷十六）。"]', '["太行之下清且淺，一水盤桓紆山轉。","千峰万壑不可數，異草幽花幾曾见。","波中白日隐出明，风翻不动浮云轻。","翠巒玉女下雙鹤，笑倚秋練开新晴。","又疑武陵溪上原，桃花溪尽空潺湲。","幽泉间复逗嵒側，噴珠潄玉相交喧。","羣猿见之走絕壁，緣峰虛梯弗勞力。","鳴禽迴面背人飞，爲是從来不相識。","杖藜因貪仰面看，礙石牽蘿錯移屐。","路窮屈曲疑欲回，迤邐屏开一重碧。","殘樽遇坐酒即傾，旋摘山菓都無名。","題诗且欲尽佳句，能歌翻詠仙难成。","天门幽深十里西，無奈落日催人归。","誰能可屬天宮事，爲我乞取須臾期。","上天無梯日不顧，牢落归来壇未暮。","閉门下马一衾寒，梦想魂驰在何处。","（见《古今圖书集成·山川典》卷四八《太行山部》、乾隆廿四年刊蕭應植纂《濟源縣志》卷十六）。"]', '诗', 'shi', '', NULL, '題西白澗 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('972e5ce7-adee-475e-9d7c-d50e7c85b2a9', '別韓湘（附存）', '別韓湘（附存）', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["未爲世用古來多，如子雄文世孰過。","好待功成身退後，却抽身去臥煙蘿。","（見《青瑣高議別集》卷四）（按：此詩似出後人僞託。","然韓湘仙事，始於唐時，此詩爲唐人或宋人作，今已無從辨明，姑錄存於此。","）。"]', '["未爲世用古来多，如子雄文世孰過。","好待功成身退後，却抽身去臥煙蘿。","（见《青瑣高議別集》卷四）（按：此诗似出後人僞託。","然韓湘仙事，始於唐时，此诗爲唐人或宋人作，今已無從辨明，姑錄存於此。","）。"]', '诗', 'shi', '', NULL, '別韓湘（附存） 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8cdc1b0-af9a-4fa7-af69-43814d12e1c3', '題遊息洞（題擬）', '題游息洞（題擬）', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["所樂非吾獨，人人共此情。","往來三伏裏，試酌一泓清。","（見民國廿七年刊朱汝珍纂《陽山縣志》卷十七《金石》）（按：《陽山縣志》錄《陸志》云：「右詩字大一寸五分，在遊息洞口石壁。","」）。"]', '["所乐非吾独，人人共此情。","往来三伏裏，試酌一泓清。","（见民国廿七年刊朱汝珍纂《陽山縣志》卷十七《金石》）（按：《陽山縣志》錄《陸志》云：「右诗字大一寸五分，在游息洞口石壁。","」）。"]', '诗', 'shi', '', NULL, '題遊息洞（題擬） 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7896449d-b347-4fee-ac6e-6d1a3ad1d1eb', '歌行一首', '歌行一首', '269a0b6c-a628-456f-9417-84850abfc8aa', '唐', '["古人重義不重金，曲高和寡勿（《宗鏡錄》、《偈頌》作「無」）知音。","今時志（《宗鏡錄》、《偈頌》作「學」）士還如此，語默動用跡難尋。","所嗟世上歧路者，終日崎嶇狂（《宗鏡錄》、《偈頌》作「枉」）用心。","平坦旃檀不肯收，要須登險（《宗鏡錄》作「陟」）訪椿林。","窮子捨父遠逃逝，却於本舍絕知音。","貧女宅中無價寶，却將秤賣他人（《宗鏡錄》、《偈頌》作「小秤買他」）金。","心無相，用還（《偈頌》作「能」）深，無常境界不能侵。","運用能隨高與下，靈光且（《偈頌》作「元」）不是浮沉。","無相無（《偈頌》、《宗鏡錄》無此字）心能運曜，應聲應色隨方照。","雖在方而不在方，任運高低總能妙。","亦（《偈頌》、《宗鏡錄》作「尋」）無頭，復無尾，靈（《偈頌》、《宗鏡錄》作「焰」）光運運從何起？","只今起者便是心（《偈頌》、《宗鏡錄》作「祇者如今全是心」），心用明時更何你（《偈頌》、《宗鏡錄》作「心用明心心復爾」）。","不居方，無（一作「何」）處覓，運用無蹤復無跡。","識取如今明覓（《偈頌》作「密」）人，終朝莫慢（《偈頌》作「漫」，《宗鏡錄》作「謾」）別求的。","懃（《宗鏡錄》作「勸」）心學，近藂林，莫將病眼認花針。","說教本窮無相理，廣讀元來不識心。","了（《偈頌》、《宗鏡錄》作「識」）取心，識（《偈頌》、《宗鏡錄》作「了」）取境，了心識境（《偈頌》、《宗鏡錄》作「識心了境」）禪河淨。","但（《宗鏡錄》作「若」，《偈頌》作「知」）能了境便識心，萬法都如闥婆影。","勸且學，莫爲師，不用登高向下窺。","平源不用金剛鑽，劍刃之中錯下錐。","向前來，莫人我，山僧有曲無人和。","了空無相即法師（《偈頌》作「了境心空即法王」），不用綾羅將作幡（《偈頌》作「爲播」）。","可中了，大希奇，大人幽邃不思議。","（《偈頌》三句作「大幽邃，不思議，可中學得大希奇」）。","自家壞（《偈頌》作「懷」）却真寶藏，終日從人乞布衣。","取境界，妄情生，只如水面（《偈頌》作「上」）一波成。","但能當境無情計（《偈頌》作「繫」），還同水面本地平。","應大軀，應小軀，運用只隨如（《偈頌》作「如隨」）意珠。","被（《偈頌》作「披」）毛戴角形雖異，能應之心（《偈頌》作「應物之情」）體不殊。","應眼時，若千日，萬像不能逃影質。","凡夫只是未曾觀，那得自輕而退屈。","應耳時，若幽谷，大小音聲無不足。","什（《偈頌》作「十」）方鍾鼓一時鳴，靈光運運常相續。","應意時，絕分別，照燭森羅長（《偈頌》作「恒」）不歇。","透過山河石壁間，要且照時常寂滅。","境自虛，不須畏，終朝照燭無形（《偈頌》作「元無」）對。","設使（《偈頌》作「爾」）任持浮幻身，運用都無舌身意。","（南唐靜筠二僧《祖堂集》卷十四，宋子昇、本如《禪門諸祖師偈頌》卷上之下，另《宗鏡錄》卷九〖作古德歌〗、卷十八、卷四四、卷九八收此歌部分文字。","）。"]', '["古人重義不重金，曲高和寡勿（《宗镜錄》、《偈頌》作「無」）知音。","今时志（《宗镜錄》、《偈頌》作「学」）士還如此，語默动用跡难尋。","所嗟世上歧路者，終日崎嶇狂（《宗镜錄》、《偈頌》作「枉」）用心。","平坦旃檀不肯收，要須登險（《宗镜錄》作「陟」）訪椿林。","窮子捨父远逃逝，却於本舍絕知音。","貧女宅中無價寶，却將秤賣他人（《宗镜錄》、《偈頌》作「小秤買他」）金。","心無相，用還（《偈頌》作「能」）深，無常境界不能侵。","運用能隨高與下，靈光且（《偈頌》作「元」）不是浮沉。","無相無（《偈頌》、《宗镜錄》無此字）心能運曜，應声應色隨方照。","雖在方而不在方，任運高低總能妙。","亦（《偈頌》、《宗镜錄》作「尋」）無头，复無尾，靈（《偈頌》、《宗镜錄》作「焰」）光運運從何起？","只今起者便是心（《偈頌》、《宗镜錄》作「祇者如今全是心」），心用明时更何你（《偈頌》、《宗镜錄》作「心用明心心复爾」）。","不居方，無（一作「何」）处覓，運用無蹤复無跡。","識取如今明覓（《偈頌》作「密」）人，終朝莫慢（《偈頌》作「漫」，《宗镜錄》作「謾」）別求的。","懃（《宗镜錄》作「勸」）心学，近藂林，莫將病眼認花針。","说教本窮無相理，廣读元来不識心。","了（《偈頌》、《宗镜錄》作「識」）取心，識（《偈頌》、《宗镜錄》作「了」）取境，了心識境（《偈頌》、《宗镜錄》作「識心了境」）禪河淨。","但（《宗镜錄》作「若」，《偈頌》作「知」）能了境便識心，万法都如闥婆影。","勸且学，莫爲師，不用登高向下窺。","平源不用金剛鑽，劍刃之中錯下錐。","向前来，莫人我，山僧有曲無人和。","了空無相即法師（《偈頌》作「了境心空即法王」），不用綾羅將作幡（《偈頌》作「爲播」）。","可中了，大希奇，大人幽邃不思議。","（《偈頌》三句作「大幽邃，不思議，可中学得大希奇」）。","自家壞（《偈頌》作「懷」）却真寶藏，終日從人乞布衣。","取境界，妄情生，只如水面（《偈頌》作「上」）一波成。","但能當境無情計（《偈頌》作「繫」），還同水面本地平。","應大軀，應小軀，運用只隨如（《偈頌》作「如隨」）意珠。","被（《偈頌》作「披」）毛戴角形雖異，能應之心（《偈頌》作「應物之情」）體不殊。","應眼时，若千日，万像不能逃影質。","凡夫只是未曾观，那得自轻而退屈。","應耳时，若幽谷，大小音声無不足。","什（《偈頌》作「十」）方鍾鼓一时鳴，靈光運運常相續。","應意时，絕分別，照燭森羅长（《偈頌》作「恒」）不歇。","透過山河石壁间，要且照时常寂滅。","境自虛，不須畏，終朝照燭無形（《偈頌》作「元無」）对。","設使（《偈頌》作「爾」）任持浮幻身，運用都無舌身意。","（南唐静筠二僧《祖堂集》卷十四，宋子昇、本如《禪门諸祖師偈頌》卷上之下，另《宗镜錄》卷九〖作古德歌〗、卷十八、卷四四、卷九八收此歌部分文字。","）。"]', '诗', 'shi', '', NULL, '歌行一首 法藏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a82dd98f-215e-44db-aa6f-9a32caed5b6f', '濾水羅賦附歌', '濾水羅賦附歌', '91c99d86-18e2-4a3b-8c41-dc305f1aea30', '唐', '["玉巵無當兮安可擬，風飄有聲兮不足比。","惟濾羅之用也大哉，故去此而取彼。","（見《文苑英華》卷一一○）。"]', '["玉巵無當兮安可擬，风飄有声兮不足比。","惟濾羅之用也大哉，故去此而取彼。","（见《文苑英华》卷一一○）。"]', '诗', 'shi', '', NULL, '濾水羅賦附歌 白行簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a432674b-f1fd-434d-9b87-c6916ae4c8a2', '見杭州烏窠和尚後作（題擬）', '见杭州烏窠和尚後作（題擬）', '91c99d86-18e2-4a3b-8c41-dc305f1aea30', '唐', '["白頭居士對禪師，正是楞嚴三昧時。","一物也無百味足，恒沙能有幾人知？","（見《祖堂集》卷三）。"]', '["白头居士对禪師，正是楞嚴三昧时。","一物也無百味足，恒沙能有幾人知？","（见《祖堂集》卷三）。"]', '诗', 'shi', '', NULL, '見杭州烏窠和尚後作（題擬） 白行簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d6e4be2-4076-4992-910d-2e548f625d92', '登石傘峰', '登石傘峰', '65608818-21e0-419b-ac29-5f1330a96ab5', '唐', '["威鳳昔未起，茲山嘉氣深。","逶迤抱川阜，蘿蔦方沈沈。","龍節稍巖徑，星軒伴幽尋。","嘗聞謝公事，今嘉昭曠心。","絕頂上巍峨，秋晨好登臨。","蘆洲辨微色，天籟聞虛吟。","支策睇歸湖，舒情凝遠岑。","徘徊繞靈傘，登坐延芳襟。","溪路鏁重扃，松門交翠陰。","貞姿在空谷，瑞色仍棲林。","晚靄覆迴汀，輕橈環碧潯。","探奇幸陪唱，願繼咸池音。","（見《會稽掇英總集》卷四）。"]', '["威鳳昔未起，茲山嘉氣深。","逶迤抱川阜，蘿蔦方沈沈。","龙節稍巖徑，星軒伴幽尋。","嘗闻謝公事，今嘉昭曠心。","絕頂上巍峨，秋晨好登臨。","蘆洲辨微色，天籟闻虛吟。","支策睇归湖，舒情凝远岑。","徘徊繞靈傘，登坐延芳襟。","溪路鏁重扃，松门交翠陰。","貞姿在空谷，瑞色仍棲林。","晚靄覆迴汀，轻橈环碧潯。","探奇幸陪唱，願繼咸池音。","（见《會稽掇英總集》卷四）。"]', '诗', 'shi', '', NULL, '登石傘峰 衛中行 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4634aecd-e198-4b0a-b020-2997508f0083', '贈白使君樂天（題擬）', '贈白使君乐天（題擬）', '85cf0e20-6246-4cec-ba41-75091a40eac1', '唐', '["聞有餘霞千萬首，何妨一句乞閒人。","（見《白氏長慶集》卷二四《答次休上人》題注引）。"]', '["闻有餘霞千万首，何妨一句乞閒人。","（见《白氏长慶集》卷二四《答次休上人》題注引）。"]', '诗', 'shi', '', NULL, '贈白使君樂天（題擬） 次休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('611ec8dd-6e4f-47a6-8bf2-f0f730bd2fa7', '及第後返閉戶窮（下缺）', '及第後返閉戶窮（下缺）', '5c998943-09fd-4d2b-9b57-ecaeb8f1c8fc', '唐', '["爲學心雖滿，知君如掩扉。","（見《吟窗雜錄》卷四四）。"]', '["爲学心雖满，知君如掩扉。","（见《吟窗杂錄》卷四四）。"]', '诗', 'shi', '', NULL, '及第後返閉戶窮（下缺） 歐陽袞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d0b3e5b-a67c-4bb0-bfd2-40ec3e22c2de', '范忠韓喜得劉先生詩', '范忠韓喜得劉先生诗', 'f52adb40-7de0-4f9f-b193-532e2afff0a6', '唐', '["玉尺沈埋久，得之銘篆深。","指磨露正色，扣擊吐哀音。","（《後村詩話續集》卷二引《劉叉集》）。"]', '["玉尺沈埋久，得之銘篆深。","指磨露正色，扣擊吐哀音。","（《後村诗話續集》卷二引《劉叉集》）。"]', '诗', 'shi', '', NULL, '范忠韓喜得劉先生詩 劉叉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6f64e69-ee41-4c39-838d-fe417f154e39', '暑中即事', '暑中即事', 'c0065f11-f869-431f-9c20-2faed799e79d', '唐', '["雲起松關作遠山，一庭細草未曾刪。","吏書抱去琴聲靜，驄使何須采下艱。","（《莆風清籟集》卷五七）。"]', '["云起松关作远山，一庭細草未曾刪。","吏书抱去琴声静，驄使何須采下艱。","（《莆风清籟集》卷五七）。"]', '诗', 'shi', '', NULL, '暑中即事 孔仲良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11a6acf6-d766-443e-b86e-64b94f3fa8dd', '', '', '893f5c23-a93a-41c4-a1c4-523e420c1ff3', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 薛昌朝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d31f92e5-c5fc-4401-bf9e-c01611d8495c', '紫閣', '紫閣', '893f5c23-a93a-41c4-a1c4-523e420c1ff3', '唐', '["閣下寒溪漲碧湍，閣前蒼翠數峯環。","危梯續蹬穿松外，細竹分泉落石間（卷九作「前」）。","好鳥啁啾爭喚客，亂雲開合巧藏山。","獨來應爲禪僧笑，少有人能伴我閑。","（《類編長安志》卷三、卷九）。"]', '["閣下寒溪漲碧湍，閣前蒼翠數峯环。","危梯續蹬穿松外，細竹分泉落石间（卷九作「前」）。","好鸟啁啾爭喚客，亂云开合巧藏山。","独来應爲禪僧笑，少有人能伴我闲。","（《類編长安志》卷三、卷九）。"]', '诗', 'shi', '', NULL, '紫閣 薛昌朝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a5e4dbc-93c9-44dc-9652-ed00d4830e2c', '同觀察使張公仲方大和元年夏禱雨歸至聖泉寺作（題擬）', '同观察使張公仲方大和元年夏禱雨归至聖泉寺作（題擬）', '8e723e0f-c194-4a44-9640-3d38501e844f', '唐', '["雨隨青嶂合，雲拂畫旗來。","（見《淳熙三山志》卷八、《閩都記》卷十一）（〖1〗《淳熙三山志》云：「今詩牌在聖泉。","」同作者爲張仲方、李貽孫、彭城三人，《全唐詩》僅收仲方詩。","）。"]', '["雨隨青嶂合，云拂畫旗来。","（见《淳熙三山志》卷八、《閩都記》卷十一）（〖1〗《淳熙三山志》云：「今诗牌在聖泉。","」同作者爲張仲方、李貽孫、彭城三人，《全唐诗》僅收仲方诗。","）。"]', '诗', 'shi', '', NULL, '同觀察使張公仲方大和元年夏禱雨歸至聖泉寺作（題擬） 李敬彝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c803a9b4-3e34-49cd-848d-841bee579ff1', '同觀察使張公仲方大和元年夏禱雨歸至聖泉寺作', '同观察使張公仲方大和元年夏禱雨归至聖泉寺作', '4592d406-aa5d-4d28-bf3b-443f4e430471', '唐', '["雲陰隨雨度，桂馥逐風來。","（同前）。"]', '["云陰隨雨度，桂馥逐风来。","（同前）。"]', '诗', 'shi', '', NULL, '同觀察使張公仲方大和元年夏禱雨歸至聖泉寺作 彭城 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bead88f9-a9d4-4e54-a773-4a4589d9073a', '宿猿洞', '宿猿洞', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["萬屋人家雲閣下，一屏煙水石橋西。","（見《輿地紀勝》卷一二八《福州》）。"]', '["万屋人家云閣下，一屏煙水石橋西。","（见《輿地紀勝》卷一二八《福州》）。"]', '诗', 'shi', '', NULL, '宿猿洞 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da30a4ad-7ae6-4326-ab13-63d7eca80475', '題瀑布詩三首 一', '題瀑布诗三首 一', 'a52965e9-4bd0-4beb-b7fc-d511a6a12622', '唐', '["殷勤[對]綠醽，閑坐繞沙[汀]。","怪來喧語笑，一派落青屏。","（缺字據《永樂大典》補）。"]', '["殷勤[对]綠醽，闲坐繞沙[汀]。","怪来喧語笑，一派落青屏。","（缺字據《永乐大典》補）。"]', '诗', 'shi', '', NULL, '題瀑布詩三首 一 王師閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08ead037-48e5-4913-b677-cc242a81584f', '題瀑布詩三首 二', '題瀑布诗三首 二', 'a52965e9-4bd0-4beb-b7fc-d511a6a12622', '唐', '["嵌崆（《輿地紀勝》作「空」）石洞古，飄灑玉泉吐。","飛流勢不定，散作松間雨。"]', '["嵌崆（《輿地紀勝》作「空」）石洞古，飄灑玉泉吐。","飞流勢不定，散作松间雨。"]', '诗', 'shi', '', NULL, '題瀑布詩三首 二 王師閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f098f6e-dab8-46fe-b6bb-921342f9d9eb', '題瀑布詩三首 三', '題瀑布诗三首 三', 'a52965e9-4bd0-4beb-b7fc-d511a6a12622', '唐', '["清明雲日開，山路足莓苔。","瀑溜千尋落，乘閑一看來。","（見劉喜海《金石苑》卷二。","《輿地紀勝》卷一五七《資州》錄第二首。","張忱石先生告：《永樂大典》卷九七六六引《成都府志》錄第一首，今據以校補。","）（〖1〗《金石苑》云：「高約二尺，廣三尺六寸，十二行，行七字，字徑寸餘至二寸不等。","正書。","下端石殘缺。","」石刻題下署：「資□刺史王師閔。","」末署：「大和二年正月七日。","」〖2〗劉喜海跋云：「右詩刻在資州。","此西巖龍潭瀑布詩也，見王象之《碑目》。","王師閔爲資州刺史，史失載。","」〖3〗《輿地紀勝》云：「唐王師閔守資中，政有能聲。","嘗游西巖，留《瀑布詩》於石壁。","其一曰〖錄第二首，略〗。","」按：據《輿地紀勝》及《永樂大典》所錄詩，知石刻除稍有漫漶外，大致完整。","《金石苑》謂「下端石殘缺」，未允。","）。"]', '["清明云日开，山路足莓苔。","瀑溜千尋落，乘闲一看来。","（见劉喜海《金石苑》卷二。","《輿地紀勝》卷一五七《資州》錄第二首。","張忱石先生告：《永乐大典》卷九七六六引《成都府志》錄第一首，今據以校補。","）（〖1〗《金石苑》云：「高約二尺，廣三尺六寸，十二行，行七字，字徑寸餘至二寸不等。","正书。","下端石殘缺。","」石刻題下署：「資□刺史王師閔。","」末署：「大和二年正月七日。","」〖2〗劉喜海跋云：「右诗刻在資州。","此西巖龙潭瀑布诗也，见王象之《碑目》。","王師閔爲資州刺史，史失載。","」〖3〗《輿地紀勝》云：「唐王師閔守資中，政有能声。","嘗游西巖，留《瀑布诗》於石壁。","其一曰〖錄第二首，略〗。","」按：據《輿地紀勝》及《永乐大典》所錄诗，知石刻除稍有漫漶外，大致完整。","《金石苑》謂「下端石殘缺」，未允。","）。"]', '诗', 'shi', '', NULL, '題瀑布詩三首 三 王師閔 shi');
